const LECTURES = {"1":"<!DOCTYPE html>\r\n<html lang=\"ko\">\r\n<head>\r\n<meta charset=\"utf-8\">\r\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\r\n<title>1회차 — AI 에이전트 시대: 전문가의 태도와 트렌드 지도</title>\r\n<link rel=\"preconnect\" href=\"https://cdnjs.cloudflare.com\">\r\n<link rel=\"stylesheet\" href=\"https://cdnjs.cloudflare.com/ajax/libs/highlight.js/11.9.0/styles/github.min.css\">\r\n<style>\r\n:root{\r\n  --bg:#fafaf6; --panel:#ffffff; --ink:#1b1e24; --ink-soft:#5a6069; --ink-faint:#8b919b;\r\n  --line:#e7e6df; --line-soft:#f0efe9;\r\n  --teal:#127c71; --teal-d:#0c5249; --teal-bg:#e6f4f1;\r\n  --amber:#b9722a; --amber-bg:#fbf1e4;\r\n  --red:#c0392b; --red-bg:#fbe9e7;\r\n  --code-bg:#f6f6f0;\r\n  --mono:ui-monospace,\"SF Mono\",\"Cascadia Code\",\"JetBrains Mono\",Consolas,monospace;\r\n  --sans:-apple-system,BlinkMacSystemFont,\"Pretendard\",\"Apple SD Gothic Neo\",\"Segoe UI\",\"Malgun Gothic\",sans-serif;\r\n  --rad:12px;\r\n}\r\n*{box-sizing:border-box}\r\nhtml{scroll-behavior:smooth}\r\n@media (prefers-reduced-motion:reduce){html{scroll-behavior:auto}}\r\nbody{margin:0;background:var(--bg);color:var(--ink);font-family:var(--sans);\r\n  font-size:16px;line-height:1.72;-webkit-font-smoothing:antialiased}\r\n\r\n/* layout */\r\n.shell{display:grid;grid-template-columns:300px minmax(0,1fr);max-width:1240px;margin:0 auto}\r\n.print-toc{display:none}\r\n.side{position:sticky;top:0;align-self:start;height:100vh;overflow-y:auto;\r\n  padding:30px 22px 60px;border-right:1px solid var(--line)}\r\n.main{min-width:0;padding:46px 60px 120px;max-width:880px}\r\n\r\n/* sidebar */\r\n.brand{font-family:var(--mono);font-size:11px;letter-spacing:.14em;text-transform:uppercase;\r\n  color:var(--teal);margin-bottom:6px}\r\n.brand-t{font-weight:700;font-size:17px;line-height:1.35;margin:0 0 4px}\r\n.brand-s{font-size:12.5px;color:var(--ink-faint);margin:0 0 24px;line-height:1.5}\r\nnav a{display:block;text-decoration:none;color:var(--ink-soft);border-left:2px solid transparent;\r\n  padding:3px 0 3px 12px;font-size:13.5px;transition:color .15s,border-color .15s}\r\nnav a:hover{color:var(--ink)}\r\nnav a.nav-h1{margin-top:16px;font-weight:700;color:var(--ink);font-size:13px;\r\n  font-family:var(--mono);letter-spacing:.02em}\r\nnav a.nav-h2{font-size:13px}\r\nnav a.active{color:var(--teal-d);border-left-color:var(--teal);font-weight:600}\r\n\r\n/* headings */\r\nh1.modhead{font-size:13px;font-family:var(--mono);letter-spacing:.06em;text-transform:uppercase;\r\n  color:var(--teal);margin:72px 0 0;padding-top:28px;border-top:2px solid var(--ink);\r\n  font-weight:700}\r\nh1.modhead::after{content:attr(data-full);display:block;font-family:var(--sans);\r\n  font-size:30px;letter-spacing:-.01em;text-transform:none;color:var(--ink);\r\n  margin-top:8px;font-weight:750;line-height:1.2}\r\nh1.modhead{font-size:0}            /* hide raw, show via ::after */\r\nh1.modhead.intro{font-size:13px}\r\nh2{font-size:21px;font-weight:720;letter-spacing:-.01em;margin:46px 0 14px;\r\n  padding-bottom:8px;border-bottom:1px solid var(--line)}\r\nh3{font-size:16.5px;font-weight:700;margin:32px 0 10px;color:var(--ink)}\r\nh2.starred,h3.starred{color:var(--teal-d)}\r\nh2.starred::before,h3.starred::before{content:\"★ \";color:var(--teal);font-size:.85em}\r\nh2.starred,h3.starred{}\r\n.main h1:first-of-type{margin-top:0}\r\n\r\np{margin:12px 0}\r\na{color:var(--teal-d)}\r\nstrong{font-weight:700;color:var(--ink)}\r\nul,ol{padding-left:22px;margin:12px 0}\r\nli{margin:5px 0}\r\nhr{border:none;border-top:1px solid var(--line);margin:40px 0}\r\n\r\n/* intro hero */\r\n.hero{background:linear-gradient(135deg,#0c5249,#127c71);color:#eafaf6;\r\n  border-radius:16px;padding:34px 36px;margin:0 0 14px}\r\n.hero .eyebrow{font-family:var(--mono);font-size:11px;letter-spacing:.16em;\r\n  text-transform:uppercase;color:#9fdfd2;margin-bottom:10px}\r\n.hero h1{font-size:32px;line-height:1.18;margin:0 0 12px;font-weight:780;letter-spacing:-.02em}\r\n.hero p{margin:0;color:#cfeee7;font-size:14.5px;line-height:1.6}\r\n\r\n/* tables */\r\ntable{width:100%;border-collapse:collapse;margin:18px 0;font-size:14px;\r\n  border:1px solid var(--line);border-radius:var(--rad);overflow:hidden}\r\nthead th{background:var(--teal-bg);color:var(--teal-d);text-align:left;\r\n  font-weight:700;padding:10px 13px;font-size:13px}\r\ntd{padding:10px 13px;border-top:1px solid var(--line-soft);vertical-align:top}\r\ntbody tr:nth-child(even){background:#fbfbf8}\r\n.tablescroll{overflow-x:auto}\r\n\r\n/* code */\r\n.codewrap{margin:16px 0;border:1px solid var(--line);border-radius:var(--rad);\r\n  overflow:hidden;background:var(--code-bg)}\r\n.codebar{display:flex;justify-content:space-between;align-items:center;\r\n  padding:7px 12px;background:#efeee7;border-bottom:1px solid var(--line)}\r\n.codelang{font-family:var(--mono);font-size:11px;letter-spacing:.08em;\r\n  text-transform:uppercase;color:var(--ink-faint);font-weight:600}\r\n.copybtn{font-family:var(--mono);font-size:11px;border:1px solid var(--line);\r\n  background:#fff;color:var(--ink-soft);padding:3px 11px;border-radius:6px;cursor:pointer;\r\n  transition:all .15s}\r\n.copybtn:hover{border-color:var(--teal);color:var(--teal-d)}\r\n.copybtn.ok{background:var(--teal);color:#fff;border-color:var(--teal)}\r\n.codewrap pre{margin:0;padding:0}\r\npre code,pre.hljs{display:block;padding:15px 16px;overflow-x:auto;\r\n  font-family:var(--mono);font-size:13px;line-height:1.6;background:var(--code-bg)!important}\r\n:not(pre)>code{font-family:var(--mono);font-size:.88em;background:#eeede6;\r\n  padding:1.5px 6px;border-radius:5px;color:var(--teal-d);white-space:nowrap}\r\n\r\n/* mermaid */\r\npre.mermaid{background:var(--panel);border:1px solid var(--line);border-radius:var(--rad);\r\n  padding:22px;margin:20px 0;text-align:center;overflow-x:auto;line-height:1.4}\r\n\r\n/* callouts */\r\n.callout{position:relative;margin:18px 0;padding:14px 18px 14px 18px;border-radius:10px;\r\n  border-left:4px solid var(--ink-faint);background:#f4f4ee;font-size:14.5px}\r\n.callout p{margin:8px 0}\r\n.callout p:first-of-type{margin-top:0}\r\n.callout p:last-child{margin-bottom:0}\r\n.callout-badge{display:inline-block;font-family:var(--mono);font-size:10.5px;\r\n  letter-spacing:.1em;text-transform:uppercase;font-weight:700;\r\n  padding:2px 9px;border-radius:20px;margin-bottom:8px}\r\n.callout-note{border-left-color:#9aa0a8;background:#f3f3ee}\r\n.callout-note .callout-badge{background:#e4e4dd;color:#5a6069}\r\n.callout-key{border-left-color:var(--teal);background:var(--teal-bg)}\r\n.callout-key .callout-badge{background:var(--teal);color:#fff}\r\n.callout-warn{border-left-color:var(--amber);background:var(--amber-bg)}\r\n.callout-warn .callout-badge{background:var(--amber);color:#fff}\r\n.callout-add{border-left-color:var(--teal-d);background:#e9f3f1}\r\n.callout-add .callout-badge{background:var(--teal-d);color:#fff}\r\n\r\n/* topbar (mobile) */\r\n.topbar{display:none}\r\n\r\n@media (max-width:880px){\r\n  .shell{grid-template-columns:1fr}\r\n  .side{position:fixed;z-index:40;top:0;left:0;width:84%;max-width:320px;height:100vh;\r\n    background:var(--panel);transform:translateX(-105%);transition:transform .25s;\r\n    box-shadow:0 0 40px rgba(0,0,0,.18)}\r\n  .side.open{transform:translateX(0)}\r\n  .main{padding:70px 22px 90px}\r\n  .topbar{display:flex;align-items:center;gap:12px;position:sticky;top:0;z-index:30;\r\n    background:rgba(250,250,246,.92);backdrop-filter:blur(8px);\r\n    padding:12px 18px;border-bottom:1px solid var(--line)}\r\n  .menubtn{font-family:var(--mono);font-size:13px;border:1px solid var(--line);\r\n    background:#fff;padding:6px 12px;border-radius:8px;cursor:pointer}\r\n  .topbar .tt{font-family:var(--mono);font-size:12px;color:var(--teal);letter-spacing:.05em}\r\n  .scrim{display:none;position:fixed;inset:0;background:rgba(0,0,0,.35);z-index:35}\r\n  .scrim.show{display:block}\r\n  h1.modhead::after{font-size:25px}\r\n  .hero h1{font-size:25px}\r\n  .main{max-width:100%}\r\n}\r\n\r\n/* ── 인쇄 / PDF 저장 (출력 시 목차 먼저 → 본문) ── */\r\n@media print{\r\n  @page{margin:14mm 12mm}\r\n  *{-webkit-print-color-adjust:exact;print-color-adjust:exact}\r\n  .topbar,.scrim,.menubtn,.copybtn{display:none!important}\r\n  .shell{display:block;max-width:none}\r\n  /* 화면용 사이드바는 인쇄에서 완전히 숨김 (변환 불안정 → 빈 페이지 방지) */\r\n  .side{display:none!important}\r\n  /* 인쇄 전용 목차: 본문 맨 앞 일반 블록으로 깔끔히 출력 후 페이지 넘김 */\r\n  .print-toc{display:block!important;break-after:page;page-break-after:always}\r\n  .print-toc .ptoc-title{font-size:19pt;font-weight:800;color:#0c5249;letter-spacing:-.01em;\r\n    margin:0 0 16px;padding-bottom:10px;border-bottom:2px solid #127c71}\r\n  .print-toc a{display:block;color:#1b1e24;text-decoration:none;padding:3px 0;font-size:11.5pt;border:none}\r\n  .print-toc a.nav-h1{margin-top:13px;font-weight:700;color:#0c5249;font-size:12.5pt}\r\n  .print-toc a.nav-h2{padding-left:16px;color:#3a3f47}\r\n  /* 본문 */\r\n  .main{padding:0;max-width:none}\r\n  body{font-size:10.5pt;line-height:1.5;background:#fff}\r\n  a{text-decoration:none;color:inherit}\r\n  .hero{break-inside:avoid;background:#fff!important;color:#1b1e24!important;\r\n    border:none;border-bottom:2px solid #127c71;border-radius:0;\r\n    padding:0 0 14px!important;margin:0 0 18px}\r\n  .hero .eyebrow{color:#127c71!important}\r\n  .hero h1{color:#0c5249!important}\r\n  .hero p{color:#444!important}\r\n  /* 주제 헤더가 페이지 맨 아래 외롭게 걸리지 않게만 (새 페이지 강제는 빼서 빈 페이지 방지) */\r\n  h1.modhead{break-after:avoid;page-break-after:avoid}\r\n  h2,h3{break-after:avoid;page-break-after:avoid}\r\n  /* 코드·콜아웃·표·다이어그램은 페이지 중간에서 잘리지 않게 */\r\n  .codewrap,.callout,pre.mermaid,.tablescroll,table{break-inside:avoid;page-break-inside:avoid}\r\n  pre code,pre.hljs{white-space:pre-wrap;word-break:break-word}\r\n  pre.mermaid{text-align:center;border:1px solid #ddd;padding:12px 8px;margin:14px auto}\r\n  pre.mermaid svg{max-width:100%!important;height:auto!important;\r\n    max-height:200mm!important;display:inline-block!important}\r\n  .codewrap{border-color:#ccc}\r\n}\r\n</style>\r\n</head>\r\n<body>\r\n<div class=\"topbar\">\r\n  <button class=\"menubtn\" id=\"menubtn\" aria-label=\"목차 열기\">☰ 목차</button>\r\n  <span class=\"tt\">강의노트 · 보강판</span>\r\n</div>\r\n<div class=\"scrim\" id=\"scrim\"></div>\r\n<div class=\"shell\">\r\n  <aside class=\"side\" id=\"side\">\r\n    <div class=\"brand\">강의노트 · 01회차</div>\r\n    <p class=\"brand-t\">1회차 — AI 에이전트 시대: 전문가의 태도와 트렌드 지도</p>\r\n    <p class=\"brand-s\">현장 강의 · 기술 보강판</p>\r\n    <nav id=\"nav\">\r\n<a class=\"nav-h1\" href=\"#ai\">오리엔테이션 — 이 시대의 AI 전문가는 누구인가</a>\r\n<a class=\"nav-h2\" href=\"#_1\">교과서가 없는 &quot;초학문의 시대&quot;</a>\r\n<a class=\"nav-h2\" href=\"#knowledge-attitude-\">knowledge보다 attitude — 더닝-크루거와 겸손</a>\r\n<a class=\"nav-h2\" href=\"#_2\">전문가의 좁은 스펙트럼, 그리고 &quot;틈 메우기&quot;</a>\r\n<a class=\"nav-h1\" href=\"#_3\">미시적 혁신 — 책상 위 문제부터 푼다</a>\r\n<a class=\"nav-h2\" href=\"#1\">워밍업 문제 ① — 교안 사이트에 접속하라</a>\r\n<a class=\"nav-h2\" href=\"#2\">워밍업 문제 ② — 압축파일에서 회의 일시 찾기</a>\r\n<a class=\"nav-h2\" href=\"#_4\">레고 블록 오케스트레이션</a>\r\n<a class=\"nav-h1\" href=\"#dx-ax\">DX와 AX — 내 언어로 다시 정의하기</a>\r\n<a class=\"nav-h1\" href=\"#8\">8주 학습 지도 — 무엇을 언제 배우나</a>\r\n<a class=\"nav-h1\" href=\"#ai-1\">AI 트렌드 지도 ① — 어디서 보고, 어떻게 따라잡나</a>\r\n<a class=\"nav-h2\" href=\"#_5\">모델 비교·순위 사이트</a>\r\n<a class=\"nav-h2\" href=\"#_6\">회사 공식 문서를 정독하라</a>\r\n<a class=\"nav-h2\" href=\"#_7\">지금 잘나가는 모델(빠르게 바뀜)</a>\r\n<a class=\"nav-h1\" href=\"#ai-2-llm\">AI 트렌드 지도 ② — LLM은 도대체 어떻게 작동하나</a>\r\n<a class=\"nav-h2\" href=\"#860\">비유: 뉴런 860억 개</a>\r\n<a class=\"nav-h2\" href=\"#_8\">파라미터 = 곱셈에 쓰는 &quot;가중치&quot;의 개수</a>\r\n<a class=\"nav-h2\" href=\"#querykeyvalue\">트랜스포머와 Query·Key·Value</a>\r\n<a class=\"nav-h2\" href=\"#_9\">파라미터 수와 토큰 수</a>\r\n<a class=\"nav-h1\" href=\"#aislm\">작은 모델의 시대 — 소버린 AI·온디바이스·SLM</a>\r\n<a class=\"nav-h2\" href=\"#ai_1\">소버린 AI의 핵심은 &quot;모델의 다양성&quot;</a>\r\n<a class=\"nav-h2\" href=\"#ai-slm\">온디바이스·엣지 AI와 SLM</a>\r\n<a class=\"nav-h2\" href=\"#hugging-face-ollama\">직접 해보기 — Hugging Face + Ollama</a>\r\n<a class=\"nav-h1\" href=\"#_10\">멀티모달과 워크플로우 — 결과만 보여준 것 채우기</a>\r\n<a class=\"nav-h1\" href=\"#_11\">프롬프트에서 컨텍스트·하네스로 — 용어 정리</a>\r\n<a class=\"nav-h2\" href=\"#ai_2\">메타 프롬프트 — &quot;AI에게 질문을 시켜라&quot;</a>\r\n<a class=\"nav-h2\" href=\"#_12\">컨텍스트 윈도우 / 컨텍스트 엔지니어링</a>\r\n<a class=\"nav-h2\" href=\"#_13\">스킬·하네스·규칙 파일</a>\r\n<a class=\"nav-h1\" href=\"#ai_3\">AI가 내 컴퓨터로 들어온다 — 통합 전략과 에이전트</a>\r\n<a class=\"nav-h2\" href=\"#_14\">회사별 통합(생태계) 전략</a>\r\n<a class=\"nav-h1\" href=\"#_15\">부록 — 용어 사전·환경설정·출처</a>\r\n<a class=\"nav-h2\" href=\"#_16\">용어 빠른 사전</a>\r\n<a class=\"nav-h2\" href=\"#_17\">환경설정 체크리스트(과제 예고)</a>\r\n<a class=\"nav-h2\" href=\"#_18\">검색으로 보강·정정한 출처</a>\r\n    </nav>\r\n  </aside>\r\n  <main class=\"main\" id=\"main\">\r\n<nav class=\"print-toc\">\r\n<div class=\"ptoc-title\">목차</div>\r\n<a class=\"nav-h1\" href=\"#ai\">오리엔테이션 — 이 시대의 AI 전문가는 누구인가</a>\r\n<a class=\"nav-h2\" href=\"#_1\">교과서가 없는 &quot;초학문의 시대&quot;</a>\r\n<a class=\"nav-h2\" href=\"#knowledge-attitude-\">knowledge보다 attitude — 더닝-크루거와 겸손</a>\r\n<a class=\"nav-h2\" href=\"#_2\">전문가의 좁은 스펙트럼, 그리고 &quot;틈 메우기&quot;</a>\r\n<a class=\"nav-h1\" href=\"#_3\">미시적 혁신 — 책상 위 문제부터 푼다</a>\r\n<a class=\"nav-h2\" href=\"#1\">워밍업 문제 ① — 교안 사이트에 접속하라</a>\r\n<a class=\"nav-h2\" href=\"#2\">워밍업 문제 ② — 압축파일에서 회의 일시 찾기</a>\r\n<a class=\"nav-h2\" href=\"#_4\">레고 블록 오케스트레이션</a>\r\n<a class=\"nav-h1\" href=\"#dx-ax\">DX와 AX — 내 언어로 다시 정의하기</a>\r\n<a class=\"nav-h1\" href=\"#8\">8주 학습 지도 — 무엇을 언제 배우나</a>\r\n<a class=\"nav-h1\" href=\"#ai-1\">AI 트렌드 지도 ① — 어디서 보고, 어떻게 따라잡나</a>\r\n<a class=\"nav-h2\" href=\"#_5\">모델 비교·순위 사이트</a>\r\n<a class=\"nav-h2\" href=\"#_6\">회사 공식 문서를 정독하라</a>\r\n<a class=\"nav-h2\" href=\"#_7\">지금 잘나가는 모델(빠르게 바뀜)</a>\r\n<a class=\"nav-h1\" href=\"#ai-2-llm\">AI 트렌드 지도 ② — LLM은 도대체 어떻게 작동하나</a>\r\n<a class=\"nav-h2\" href=\"#860\">비유: 뉴런 860억 개</a>\r\n<a class=\"nav-h2\" href=\"#_8\">파라미터 = 곱셈에 쓰는 &quot;가중치&quot;의 개수</a>\r\n<a class=\"nav-h2\" href=\"#querykeyvalue\">트랜스포머와 Query·Key·Value</a>\r\n<a class=\"nav-h2\" href=\"#_9\">파라미터 수와 토큰 수</a>\r\n<a class=\"nav-h1\" href=\"#aislm\">작은 모델의 시대 — 소버린 AI·온디바이스·SLM</a>\r\n<a class=\"nav-h2\" href=\"#ai_1\">소버린 AI의 핵심은 &quot;모델의 다양성&quot;</a>\r\n<a class=\"nav-h2\" href=\"#ai-slm\">온디바이스·엣지 AI와 SLM</a>\r\n<a class=\"nav-h2\" href=\"#hugging-face-ollama\">직접 해보기 — Hugging Face + Ollama</a>\r\n<a class=\"nav-h1\" href=\"#_10\">멀티모달과 워크플로우 — 결과만 보여준 것 채우기</a>\r\n<a class=\"nav-h1\" href=\"#_11\">프롬프트에서 컨텍스트·하네스로 — 용어 정리</a>\r\n<a class=\"nav-h2\" href=\"#ai_2\">메타 프롬프트 — &quot;AI에게 질문을 시켜라&quot;</a>\r\n<a class=\"nav-h2\" href=\"#_12\">컨텍스트 윈도우 / 컨텍스트 엔지니어링</a>\r\n<a class=\"nav-h2\" href=\"#_13\">스킬·하네스·규칙 파일</a>\r\n<a class=\"nav-h1\" href=\"#ai_3\">AI가 내 컴퓨터로 들어온다 — 통합 전략과 에이전트</a>\r\n<a class=\"nav-h2\" href=\"#_14\">회사별 통합(생태계) 전략</a>\r\n<a class=\"nav-h1\" href=\"#_15\">부록 — 용어 사전·환경설정·출처</a>\r\n<a class=\"nav-h2\" href=\"#_16\">용어 빠른 사전</a>\r\n<a class=\"nav-h2\" href=\"#_17\">환경설정 체크리스트(과제 예고)</a>\r\n<a class=\"nav-h2\" href=\"#_18\">검색으로 보강·정정한 출처</a>\r\n</nav>\r\n    <div class=\"hero\">\r\n      <div class=\"eyebrow\">Lecture Note · 기술 보강판</div>\r\n      <h1>1회차 — AI 에이전트 시대: 전문가의 태도와 트렌드 지도</h1>\r\n      <p>현장 강의를 기술적으로 보강한 학습 레퍼런스 — 강사의 의도는 살리고, 빠지거나 틀린 기술은 정확히 채웠습니다.</p>\r\n    </div>\r\n\r\n<p>이 강의 하나로 무엇을 할 수 있게 하려는가 →\r\n<strong>\"거대한 AX(수십억짜리 사업)가 아니라 내 책상 위 작은 문제부터 AI로 푸는 마인드셋을 잡고, 그걸 위해 머릿속에 'AI 트렌드 전체 지도'를 심는 것.\"</strong></p>\r\n<blockquote class=\"callout callout-key\"><span class=\"callout-badge\">핵심</span>\r\n<p>★ 1회차는 실습 회차가 아니라 <strong>오리엔테이션 + AI 트렌드 오버뷰 + 환경설정 예고</strong>다. 그래서 이 노트도 위계를 억지로 세우지 않고, 강의에 실제로 있던 <em>나란한 주제들</em>을 그대로 두되 하나의 태도로 꿰었다. 관통하는 태도는 딱 한 줄: <strong>\"지식·기술(how)보다 태도(attitude)가 먼저다. 다양한 도구를 겸손하게 모아서 오케스트레이션하라.\"</strong></p>\r\n<p><strong>보강 안내</strong> — 강사가 이름을 안 밝히고 넘어간 사이트·도구, 그리고 낡았거나 부정확한 수치는 웹 검색으로 확인해 본문에 녹이고 <code>(검색 보강)</code>으로 표시했다. 출처는 맨 끝 부록에 모았다.</p>\r\n</blockquote>\r\n<hr/>\r\n<h1 class=\"modhead\" data-full=\"오리엔테이션 — 이 시대의 AI 전문가는 누구인가\" id=\"ai\">오리엔테이션 — 이 시대의 AI 전문가는 누구인가</h1>\r\n<h2 id=\"_1\">교과서가 없는 \"초학문의 시대\"</h2>\r\n<p>강사(신성진, 한국데이터사이언티스트협회)가 처음 던진 화두는 <em>\"과연 이 시대의 AI 전문가는 누구인가\"</em>다. 핵심은 이거야.</p>\r\n<ul>\r\n<li><strong>교과서가 없다.</strong> ChatGPT 책을 사면 그 안에는 이미 한물간 모델이 기다리고 있다. GPT-4o로 배웠는데 현장은 5.5다. 기술이 책보다 빨리 바뀐다.</li>\r\n<li>그래서 <strong>FOMO</strong>(Fear Of Missing Out, 뒤처질까 봐 느끼는 불안)에 시달리거나, 반대로 \"여기까지만 알면 돼\" 하고 멈춰 선다. 둘 다 위험하다.</li>\r\n<li>공공(공직자)이 민간보다 AI 활용 역량이 <strong>오히려 높다</strong>는 게 강사의 현장 관찰이다. 외부망·OpenRouter·엔터프라이즈 API를 도입해 직원이 쓰게 하는 지자체가 많다.</li>\r\n</ul>\r\n<blockquote class=\"callout callout-key\"><span class=\"callout-badge\">핵심</span>\r\n<p>★ <strong>AI 전문가의 정의를 스스로 잡아라.</strong> 강사 본인도 \"나는 AI 전문가인가? 사실 아니다\"라고 말한다. 정답이 없으니 각자 정의를 내리고, 그 정의를 동료에게 전파할 수 있어야 한다는 게 이 과정의 출발점이다.</p>\r\n</blockquote>\r\n<h2 id=\"knowledge-attitude-\">knowledge보다 attitude — 더닝-크루거와 겸손</h2>\r\n<p>강사가 가장 길게 강조한 부분. 초보자가 꼭 기억할 그림이 하나 있다.</p>\r\n<p><strong>더닝-크루거 효과(Dunning–Kruger effect)</strong> — 조금 배운 사람일수록 자신을 과대평가한다는 심리 현상.</p>\r\n<div class=\"codewrap\"><div class=\"codebar\"><span class=\"codelang\">code</span><button class=\"copybtn\" type=\"button\">복사</button></div><pre class=\"mermaid\">flowchart LR\r\n  A[\"조금 배움\"] --&gt; B[\"우매함의 봉우리&lt;br/&gt;다 안다는 착각\"]\r\n  B --&gt; C[\"절망의 계곡&lt;br/&gt;모를수록 불안\"]\r\n  C --&gt; D[\"지속 가능한 전문가&lt;br/&gt;겸손 = 계속 배움\"]\r\n</pre></div>\r\n<blockquote class=\"callout callout-key\"><span class=\"callout-badge\">핵심</span>\r\n<p>★ 강사의 한 줄: <strong>\"절망의 계곡을 '겸손'으로 바꿔 읽어라.\"</strong> 진짜 전문가는 만족이 없고 늘 불안하다. 나보다 더 아는 사람, 내가 알던 게 부정당할 순간을 늘 대비하기 때문이다. 그래서 <code>knowledge</code>보다 <code>attitude</code>(세상·현상·문제를 다르게 보는 자세)가 먼저다.</p>\r\n</blockquote>\r\n<h2 id=\"_2\">전문가의 좁은 스펙트럼, 그리고 \"틈 메우기\"</h2>\r\n<p>한 사람이 소화하는 AI 영역은 좁다. 안드레이 카파시(Andrej Karpathy, \"바이브 코딩\"이라는 말을 만든 사람) 같은 대가도 전부는 못 다룬다. 그래서 좁은 전문가들이 모이면 반드시 <strong>틈</strong>이 생긴다. 틈을 메우는 방법은 두 가지다.</p>\r\n<div class=\"codewrap\"><div class=\"codebar\"><span class=\"codelang\">code</span><button class=\"copybtn\" type=\"button\">복사</button></div><pre class=\"mermaid\">flowchart LR\r\n  G[\"내 지식의 틈\"] --&gt; M1[\"① 내 원의 지름을 키운다&lt;br/&gt;= 스스로 더 배움\"]\r\n  G --&gt; M2[\"② 동료가 옆에서 메워준다&lt;br/&gt;= 다양성의 협업\"]\r\n</pre></div>\r\n<blockquote class=\"callout callout-add\"><span class=\"callout-badge\">보강</span>\r\n<p><strong>보강 — 용어 한 줄 정리.</strong> 강의에 등장한 카파시의 명언 <em>\"망치를 들고 있으면 모든 게 못으로 보인다\"</em> 는 도구 편식 경고다(2장에서 워밍업 문제로 다시 나온다). 그리고 <em>바이브 코딩(Vibe Coding)</em> 은 \"코드 문법을 몰라도 자연어로 AI에게 시켜서 프로그램을 만드는 방식\"을 뜻한다. 이 과정의 핵심 도구가 된다.</p>\r\n</blockquote>\r\n<hr/>\r\n<h1 class=\"modhead\" data-full=\"미시적 혁신 — 책상 위 문제부터 푼다\" id=\"_3\">미시적 혁신 — 책상 위 문제부터 푼다</h1>\r\n<p>강의 전체를 관통하는 실천 메시지. <strong>거대한 AX(AI Transformation, 수십·수백억짜리 전환사업)에 짓눌리지 말고, 2~5분짜리 작은 문제부터 AI로 풀라</strong>는 것.</p>\r\n<blockquote class=\"callout callout-warn\"><span class=\"callout-badge\">주의</span>\r\n<p>⚠ <strong>주의 — \"진격의 거인 콤플렉스\"를 경계하라.</strong> 강사 표현으로, \"몇십억 들여야 AI가 도입된다\"는 생각에 빠지면 정작 책상 위 작은 문제를 풀 에너지를 잃는다. AX로만 풀리는 문제는 없다. <strong>기존 레거시(legacy, 이미 쓰던 낡은) 워크플로우 + LLM</strong>을 어떻게 결합하느냐가 진짜 실력이다.</p>\r\n</blockquote>\r\n<h2 id=\"1\">워밍업 문제 ① — 교안 사이트에 접속하라</h2>\r\n<p>강사는 단톡방에 링크를 안 뿌리고, \"수단·방법 가리지 말고 알아서 접속하라\"는 문제를 냈다. 그 사이트(\"AI 챔피언 고급 과정 교안 편집기 = 워크벤치\")의 정체를 보강하면:</p>\r\n<div class=\"tablescroll\"><table>\r\n<thead>\r\n<tr>\r\n<th>구성 요소</th>\r\n<th>정체</th>\r\n<th>한 줄 설명</th>\r\n</tr>\r\n</thead>\r\n<tbody>\r\n<tr>\r\n<td><strong>HTML</strong></td>\r\n<td>브라우저에서 도는 화면 언어</td>\r\n<td>페이지의 뼈대. C드라이브의 .html 파일은 브라우저만 있으면 바로 열린다</td>\r\n</tr>\r\n<tr>\r\n<td><strong>Claude Sonnet</strong></td>\r\n<td>Anthropic의 LLM</td>\r\n<td>교안 내용을 생성·수정하는 두뇌</td>\r\n</tr>\r\n<tr>\r\n<td><strong>GitHub Pages</strong></td>\r\n<td>무료 정적 사이트 호스팅</td>\r\n<td>깃허브에 올린 HTML을 인터넷 주소로 띄워줌 (검색 보강)</td>\r\n</tr>\r\n<tr>\r\n<td><strong>Supabase</strong></td>\r\n<td>백엔드 데이터베이스(BaaS)</td>\r\n<td>'DB' 버튼을 누르면 교안이 여기 저장됐다 다시 불려옴 (검색 보강)</td>\r\n</tr>\r\n</tbody>\r\n</table></div>\r\n<blockquote class=\"callout callout-add\"><span class=\"callout-badge\">보강</span>\r\n<p><strong>보강</strong> — 비밀번호는 <code>2026</code>. 강사가 보여주려던 건 <em>\"사이트를 만든다\"</em> 가 아니라 <em>\"HTML 한 장 + LLM + 무료 호스팅 + 가벼운 DB만으로도 우리만의 협업 공간을 만들 수 있다\"</em> 는 감각이다. 이게 뒤에 나오는 \"HTML 하나로 파생되는 서비스\" 이야기와 이어진다.</p>\r\n</blockquote>\r\n<h2 id=\"2\">워밍업 문제 ② — 압축파일에서 회의 일시 찾기</h2>\r\n<p>노션에 올린 압축 파일(50개 문서) 안에서 \"인천광역시 규제혁신담당관이 회의한 일시\"를 찾는 문제. 누군가는 반디집으로 그냥 풀었고, 누군가는 Codex/ChatGPT에 통째로 맡겼다. <strong>정답은 하나가 아니다.</strong></p>\r\n<blockquote class=\"callout callout-warn\"><span class=\"callout-badge\">주의</span>\r\n<p>★ 이 문제의 진짜 메시지: <strong>도구에 매몰되지 마라.</strong> 반디집으로 30초면 풀 일을 굳이 Codex 띄워서 풀면 그게 \"망치 들면 다 못으로 보이는\" 함정이다. 동시에, 50개 중 어디 있는지 모를 때 <strong>AI로 빠르게 찾는 것</strong>도 미시적 혁신이다. 상황에 맞는 도구를 고르는 판단이 핵심.</p>\r\n</blockquote>\r\n<h2 id=\"_4\">레고 블록 오케스트레이션</h2>\r\n<p>도구(API, RSS, MCP, 플러그인, 스킬, 프롬프트, 첨부파일, Antigravity, Codex, Claude Code…)를 <strong>레고 블록</strong>처럼 모아서 조합하라는 비유. 블록 8개로 수억 개 형상을 만들 수 있듯, 회차마다 배우는 도구를 <em>난이도순 정복</em>이 아니라 <em>조합 가능한 부품</em>으로 쌓으라는 것.</p>\r\n<blockquote class=\"callout callout-add\"><span class=\"callout-badge\">보강</span>\r\n<p><strong>보강 — 낯선 도구 이름 빠른 사전</strong> (지금 다 이해할 필요 없음, \"이런 게 있구나\"면 충분)\r\n- <strong>API</strong>: 프로그램끼리 정보를 주고받는 약속. AI 모델도 API 키 하나로 불러 쓴다.\r\n- <strong>RSS</strong>: 사이트의 새 글을 자동으로 받아오는 표준 형식(뉴스/공고 수집에 유용).\r\n- <strong>MCP</strong> (Model Context Protocol): AI에게 외부 도구·데이터를 연결해주는 표준 규격.\r\n- <strong>Antigravity / Codex / Claude Code / opencode / Goose</strong>: 내 컴퓨터에서 일하는 코딩 에이전트들(10장에서 설명).</p>\r\n</blockquote>\r\n<hr/>\r\n<h1 class=\"modhead\" data-full=\"DX와 AX — 내 언어로 다시 정의하기\" id=\"dx-ax\">DX와 AX — 내 언어로 다시 정의하기</h1>\r\n<p>강사가 \"여러분은 거점 리더니까 동료에게 개념을 전파할 수 있어야 한다\"며 직접 정의한 부분. 외울 게 아니라 <strong>응급실 통증</strong> 비유로 이해하면 된다.</p>\r\n<div class=\"codewrap\"><div class=\"codebar\"><span class=\"codelang\">code</span><button class=\"copybtn\" type=\"button\">복사</button></div><pre class=\"mermaid\">flowchart LR\r\n  A[\"현상&lt;br/&gt;아파 죽겠다(암묵지)\"] --&gt; B[\"DX 디지털화&lt;br/&gt;10점 중 7점으로 정량화\"]\r\n  B --&gt; C[\"AX 전환&lt;br/&gt;더 세밀한 패턴 분석\"]\r\n  C --&gt; D[\"생성형 AI&lt;br/&gt;바늘로 찌르는 듯한 통증이&lt;br/&gt;5분 지속(비정형 표현까지)\"]\r\n</pre></div>\r\n<ul>\r\n<li><strong>DX (Digital Transformation)</strong>: 인간이 감각으로 아는 현상·암묵지를 <strong>컴퓨터가 알아먹게 정량화</strong>하는 모든 노력. 응급실의 \"통증 1~10점\"이 딱 그거다. 센서 발달 → 데이터 저장 → 패턴 인식(머신러닝·통계)으로 이어졌다.</li>\r\n<li><strong>AX (AI Transformation)</strong>: 그 정량 데이터를 <strong>더 디테일하게</strong> 분석하려는 흐름. 생성형 AI가 들어오면서 \"7점\" 같은 척도를 넘어 <em>\"바늘로 찌르는 듯한 통증\"</em> 같은 비정형 표현까지 다룰 수 있게 됐다.</li>\r\n</ul>\r\n<blockquote class=\"callout callout-key\"><span class=\"callout-badge\">핵심</span>\r\n<p>★ DX와 AX는 단절된 게 아니라 <strong>한 라인</strong>이다. X는 미국식 약자로 Transformation. 강사 메시지: 당연하게 쓰던 용어도 <em>내 업무·내 현상에 맞춰 스스로 정의</em>해보는 응용력을 키워라.</p>\r\n</blockquote>\r\n<hr/>\r\n<h1 class=\"modhead\" data-full=\"8주 학습 지도 — 무엇을 언제 배우나\" id=\"8\">8주 학습 지도 — 무엇을 언제 배우나</h1>\r\n<div class=\"codewrap\"><div class=\"codebar\"><span class=\"codelang\">code</span><button class=\"copybtn\" type=\"button\">복사</button></div><pre class=\"mermaid\">flowchart TD\r\n  W1[\"1회차&lt;br/&gt;오리엔테이션·AI 트렌드·환경설정\"] --&gt; W2[\"2회차&lt;br/&gt;유명 AI 서비스 50개+ 둘러보기\"]\r\n  W2 --&gt; W3[\"3회차&lt;br/&gt;LLM 어시스트 워크플로우&lt;br/&gt;엑셀VBA·파이썬·RSS→HTML\"]\r\n  W3 --&gt; W45[\"4~5회차&lt;br/&gt;업무 자동화·로컬 SLM(Ollama)&lt;br/&gt;코딩 에이전트 설치·활용\"]\r\n  W45 --&gt; W6[\"MCP·로컬 RAG·백엔드 웹서비스 구현\"]\r\n  W6 --&gt; W7[\"클라우드 바이브코딩&lt;br/&gt;Lovable·Bolt·v0\"]\r\n  W7 --&gt; W8[\"개인 프로젝트 · 팀 프로젝트(4주)\"]\r\n</pre></div>\r\n<p>핵심 설계 의도 두 가지:</p>\r\n<ol>\r\n<li><strong>처음엔 코딩 에이전트를 쓰지 않는다.</strong> 3회차까지는 외부 LLM의 <em>어시스트</em>만 받아서(폐쇄망 상황 가정) 내 로컬에서 분석·자동화·바이브코딩을 한다. 이걸 강사는 <strong>\"어시스트형 바이브 코딩\"</strong> 이라 부른다.</li>\r\n<li><strong>4회차부터 코딩 에이전트로 전환.</strong> Claude Code·Cursor·Windsurf·opencode·Goose·Antigravity 등을 PC가 허락하는 만큼 설치하고, API·MCP·백엔드를 붙여 서비스까지 만든다.</li>\r\n</ol>\r\n<div class=\"codewrap\"><div class=\"codebar\"><span class=\"codelang\">code</span><button class=\"copybtn\" type=\"button\">복사</button></div><pre class=\"mermaid\">flowchart LR\r\n  subgraph 초반[\"1~3회차\"]\r\n    A1[\"외부 LLM에게 코드 받아&lt;br/&gt;내 컴퓨터에서 실행\"]\r\n  end\r\n  subgraph 후반[\"4회차~\"]\r\n    A2[\"코딩 에이전트가&lt;br/&gt;내 파일 직접 읽고 처리\"]\r\n  end\r\n  초반 --&gt; 후반\r\n</pre></div>\r\n<blockquote class=\"callout callout-warn\"><span class=\"callout-badge\">주의</span>\r\n<p><strong>보강 — 왜 굳이 어려운 순서로 가나?</strong> 폐쇄망/보안망에서는 코딩 에이전트가 막힐 수 있다. <em>\"외부에서 LLM 도움으로 코드를 만들어 → 내부로 이식해 실행\"</em> 하는 워크플로우를 익혀두면, 망 환경에 상관없이 일할 수 있다. \"폐쇄망이니 외부 건 안 배워도 돼\"는 강사가 가장 말린 태도.</p>\r\n<p>⚠ <strong>주의 — 마인드셋을 내려놓아라.</strong> 100억짜리 조달 용역을 기획해도 되지만, 먼저 <strong>혼자 또는 동료 3~4명</strong>으로 풀 수 있는 작은 것부터 꿈꿔라. 예: 압축파일 50개 일괄 해제·요약, 파일명 200개 1초 변경, HWP 표 200개를 1개로 30초 통합, 동료가 쓸 좋은 프롬프트 1개. 프로그래밍을 안 해도 된다.</p>\r\n</blockquote>\r\n<hr/>\r\n<h1 class=\"modhead\" data-full=\"AI 트렌드 지도 ① — 어디서 보고, 어떻게 따라잡나\" id=\"ai-1\">AI 트렌드 지도 ① — 어디서 보고, 어떻게 따라잡나</h1>\r\n<p>교과서가 없으니 <strong>직접 출처를 보러 다니는 습관</strong>이 곧 실력이다. 강사가 강조한 사이트들.</p>\r\n<h2 id=\"_5\">모델 비교·순위 사이트</h2>\r\n<div class=\"tablescroll\"><table>\r\n<thead>\r\n<tr>\r\n<th>사이트</th>\r\n<th>무엇을 보여주나</th>\r\n<th>특징</th>\r\n</tr>\r\n</thead>\r\n<tbody>\r\n<tr>\r\n<td><strong>Artificial Analysis</strong> (artificialanalysis.ai)</td>\r\n<td>모델별 지능·속도·가격 비교</td>\r\n<td><strong>자체 독립 벤치마크</strong>를 돌려 비교 (검색 보강)</td>\r\n</tr>\r\n<tr>\r\n<td><strong>LMArena</strong> (lmarena.ai, 옛 Chatbot Arena)</td>\r\n<td>사람이 두 모델 답을 블라인드로 비교·투표</td>\r\n<td><strong>Elo 점수</strong> 기반 경험적 순위. 실사용 만족도에 가까움 (검색 보강)</td>\r\n</tr>\r\n<tr>\r\n<td><strong>LifeArchitect Models Table</strong> (lifearchitect.ai/models-table)</td>\r\n<td>800개+ 모델의 파라미터·토큰 등 데이터 표</td>\r\n<td><strong>Alan D. Thompson 박사</strong>가 손으로 매일 갱신. <em>기울임 글씨 = 추정치</em>, 보통 글씨 = 공개된 사실 (검색 보강)</td>\r\n</tr>\r\n</tbody>\r\n</table></div>\r\n<blockquote class=\"callout callout-warn\"><span class=\"callout-badge\">주의</span>\r\n<p>⚠ <strong>주의 · [정정]</strong> — 강사는 Artificial Analysis를 \"논문 지표를 모아놓은 곳\"이라 표현했는데, 정확히는 <strong>자기들이 직접 측정한 독립 벤치마크</strong>를 싣는 사이트다. \"회사들이 자기 자랑한 논문 모음\"과는 다르다. (검색 보강)</p>\r\n<p><strong>보강 — Models Table 읽는 법.</strong> 표에서 <strong>두 번째 칸이 회사명, 첫 번째 칸이 모델명</strong>이다. 세 번째 줄의 <strong>파라미터</strong>가 핵심(다음 장에서 설명). 구글 시트로 제공돼 'Open in new tab'으로 내 사본을 떠서 쓸 수 있다.</p>\r\n</blockquote>\r\n<h2 id=\"_6\">회사 공식 문서를 정독하라</h2>\r\n<p>ChatGPT만 쓰지 말고 <strong>만든 회사의 개발자 사이트</strong>에 들어가라는 것. 모델 종류·리서치·API 사용법이 다 거기 있다.</p>\r\n<div class=\"tablescroll\"><table>\r\n<thead>\r\n<tr>\r\n<th>회사</th>\r\n<th>개발자/문서 사이트</th>\r\n<th>메모</th>\r\n</tr>\r\n</thead>\r\n<tbody>\r\n<tr>\r\n<td>OpenAI</td>\r\n<td>platform.openai.com / developer.openai.com</td>\r\n<td>Agent Builder, 어시스턴트, 특화 모델(GPT Image 등)</td>\r\n</tr>\r\n<tr>\r\n<td>Google</td>\r\n<td>ai.google.dev (Google AI for Developers)</td>\r\n<td>Gemma·Gemini API, 임베딩 (검색 보강)</td>\r\n</tr>\r\n<tr>\r\n<td>Anthropic</td>\r\n<td><strong>platform.claude.com</strong> / docs</td>\r\n<td>Claude API. 최근 \"Managed Agents\" 등 신기능 (검색 보강: URL 정확)</td>\r\n</tr>\r\n</tbody>\r\n</table></div>\r\n<blockquote class=\"callout callout-warn\"><span class=\"callout-badge\">주의</span>\r\n<p>★ <strong>API 키 하나면</strong> 그 회사의 이미지·임베딩·웹검색 모델을 내가 만든 사이트에 심을 수 있다. \"임베딩을 꼭 로컬에서 어렵게 할 필요 없이 GPT/Claude/Gemini가 제공하는 임베딩 서비스를 써보는\" 식의 감각을 키우라는 게 강사 의도. (단, 내 데이터를 학습에 안 쓴다는 보장 하에.)</p>\r\n</blockquote>\r\n<h2 id=\"_7\">지금 잘나가는 모델(빠르게 바뀜)</h2>\r\n<p>강사가 짚은 분야별 강자 — <strong>순위는 계속 바뀌니 위 사이트로 직접 확인</strong>할 것.</p>\r\n<ul>\r\n<li><strong>텍스트 대화 / 웹서치 / 코딩</strong>: Claude가 상위권(LMArena 기준 1~3위). (검색 보강: 모델 세대마다 변동)</li>\r\n<li><strong>이미지 생성</strong>: GPT Image 2가 나노바나나 2(구글 제미나이 계열 이미지 모델)를 제쳤다는 평. 일관성 유지·세밀 수정이 강점.</li>\r\n<li><strong>비디오 생성</strong>: ByteDance의 <strong>Seedance</strong>가 열풍. 짧은 프롬프트(제로샷)로도 영상을 만든다.</li>\r\n</ul>\r\n<blockquote class=\"callout callout-warn\"><span class=\"callout-badge\">주의</span>\r\n<p>⚠ <strong>주의</strong> — 이미지·영상 모델 이름(Nano Banana, Seedance, Seedream, Kling, Veo, Sora 2, Higgsfield 등)은 분기마다 바뀐다. 이름 외우기보다 <em>\"멀티모달 모델을 한곳에 모아 써볼 수 있는 사이트가 있다\"</em> 는 사실만 기억하면 된다(8장 참고).</p>\r\n</blockquote>\r\n<hr/>\r\n<h1 class=\"modhead\" data-full=\"AI 트렌드 지도 ② — LLM은 도대체 어떻게 작동하나\" id=\"ai-2-llm\">AI 트렌드 지도 ② — LLM은 도대체 어떻게 작동하나</h1>\r\n<p>여기는 강사가 \"파라미터가 뭐냐\"를 설명하려고 엑셀·사이트를 띄운 부분. <strong>수학 없이</strong> 개념만 잡으면 된다. 초보자에게 가장 중요한 장이라 차근히 보강한다.</p>\r\n<h2 id=\"860\">비유: 뉴런 860억 개</h2>\r\n<ul>\r\n<li>인간 뇌엔 뉴런이 약 <strong>860억 개</strong>, 전체가 약 <strong>20와트</strong>로 돈다. (강사 수치 정확 — 확인됨)</li>\r\n<li>뉴런 하나하나는 화학물질(나트륨·칼륨)이 오가며 작은 전기를 만들 뿐인데, 860억 개가 모이니 감정·철학·코딩하는 인간이 됐다.</li>\r\n<li>인공신경망도 같은 발상: <strong>아주 단순한 곱셈·덧셈 단위</strong>를 수천억 개 연결했더니 복잡한 패턴을 이해하더라.</li>\r\n</ul>\r\n<h2 id=\"_8\">파라미터 = 곱셈에 쓰는 \"가중치\"의 개수</h2>\r\n<p>강사가 CNN(Convolutional Neural Network, 이미지 인식 신경망)으로 손글씨 숫자(0/1)를 맞히는 엑셀 예제를 보여준 게 이거다.</p>\r\n<ul>\r\n<li>이미지를 픽셀 숫자로 바꾸고 → 거기에 <strong>가중치(weight)</strong> 를 곱하고 더한다(엑셀의 <code>SUMPRODUCT</code>, 즉 내적). → 결과를 0~1 사이로 눌러서 \"1에 가깝나, 0에 가깝나\" 판단.</li>\r\n<li>답이 틀리면 거꾸로 돌아가 가중치를 0.01씩 조금씩 고친다(이게 <em>학습</em>). 이 <strong>가중치 숫자들의 개수 = 파라미터 수</strong>.</li>\r\n</ul>\r\n<blockquote class=\"callout callout-warn\"><span class=\"callout-badge\">주의</span>\r\n<p>★ <strong>파라미터를 1차 방정식으로 이해하기.</strong> <code>Y = WX + b</code>에서 <code>W</code>(기울기·계수)와 <code>b</code>(절편·상수)가 파라미터다. 이런 1차식 수천억 개를 엮은 게 모델. 그래서 <strong>파라미터가 많을수록 복잡한 패턴을 더 잘 이해</strong>한다(= 모델이 \"크다\").</p>\r\n<p>⚠ <strong>주의 · [정정]</strong> — 강사가 \"3000 빌리언이면 나누기 2 해서 최소 1500 빌리언짜리 1차 방정식\"이라 했는데, 이건 어디까지나 <em>직관 비유</em>다. 실제로 편향(<code>b</code>)은 가중치(<code>W</code>)보다 훨씬 적어서 정확히 절반은 아니다. 개념 잡는 용도로만 받아들이자.</p>\r\n</blockquote>\r\n<h2 id=\"querykeyvalue\">트랜스포머와 Query·Key·Value</h2>\r\n<p>강사가 띄운 \"유튜브 사이트\"의 정체 → <strong>bbycroft.net/llm</strong> (Brendan Bycroft 제작). GPT 스타일 트랜스포머를 3D로 그려 <em>덧셈·곱셈 하나하나</em>까지 보여준다. 화면에 나온 <em>\"Data visualization empowers users to…\"</em> 문장이 그 데모(GPT-2)다. (검색 보강)</p>\r\n<div class=\"codewrap\"><div class=\"codebar\"><span class=\"codelang\">code</span><button class=\"copybtn\" type=\"button\">복사</button></div><pre class=\"mermaid\">flowchart LR\r\n  T[\"입력 문장\"] --&gt; TK[\"토큰으로 쪼갬\"]\r\n  TK --&gt; EM[\"임베딩&lt;br/&gt;단어를 좌표(벡터)로\"]\r\n  EM --&gt; TR[\"트랜스포머 블록 ×N&lt;br/&gt;어텐션 Q·K·V\"]\r\n  TR --&gt; OUT[\"다음 토큰 확률 예측\"]\r\n  OUT --&gt;|예측 단어를 붙여 반복| TK\r\n</pre></div>\r\n<p>강사가 말한 숫자들(768차원, 2304, 12개, 11번)은 <strong>GPT-2 small(약 1.24억 파라미터)</strong> 의 구조다. 풀어보면:</p>\r\n<ul>\r\n<li>단어를 <strong>768차원</strong> 좌표(벡터)로 임베딩한다. \"비슷한 단어는 좌표가 가깝다\"가 핵심.</li>\r\n<li>그 벡터를 <strong>Query·Key·Value(Q·K·V)</strong> 세 개로 변환한다 → 768 × 3 = <strong>2304</strong>. <em>\"data라는 단어가 어떤 단어와 가장 관련 있나\"</em> 를 계산하는 게 어텐션(attention).</li>\r\n<li>이 어텐션 블록이 여러 층(GPT-2 small은 12층) 쌓여서 반복된다.</li>\r\n</ul>\r\n<blockquote class=\"callout callout-add\"><span class=\"callout-badge\">보강</span>\r\n<p><strong>보강 — Key-Value 캐시가 뭐길래.</strong> 대화가 길어질 때 이미 계산한 K·V를 저장해 재사용하는 최적화가 KV 캐시다. \"컨텍스트가 길수록 메모리를 먹는다\"는 말이 여기서 나온다(9장 컨텍스트 윈도우와 연결).\r\n더 그림으로 보고 싶으면 <strong>3Blue1Brown</strong>의 신경망·트랜스포머 영상 시리즈도 강력 추천(수식 없이 시각화). (검색 보강)</p>\r\n</blockquote>\r\n<h2 id=\"_9\">파라미터 수와 토큰 수</h2>\r\n<ul>\r\n<li><strong>파라미터</strong>: 모델의 \"방정식 계수\" 총개수 = 모델 크기.</li>\r\n<li><strong>토큰</strong>: 모델이 학습한 단어 조각의 양. 많이 학습할수록 유창하다. (토큰 = 단어가 음절/어절 단위로 쪼개진 조각)</li>\r\n</ul>\r\n<blockquote class=\"callout callout-warn\"><span class=\"callout-badge\">주의</span>\r\n<p>⚠ <strong>주의 · [정정]</strong> — 강사는 \"GPT-5.5는 파라미터 약 3000 빌리언(3조)\"이라 했는데, <strong>OpenAI는 GPT-4 이후 모델의 파라미터 수를 공식 발표하지 않는다.</strong> \"3T\"는 외부 추정/체감치이지 공식 수치가 아니다. 체감 기준점으로만 쓰고, 사실로 인용하지 말 것. (검색 보강)</p>\r\n</blockquote>\r\n<hr/>\r\n<h1 class=\"modhead\" data-full=\"작은 모델의 시대 — 소버린 AI·온디바이스·SLM\" id=\"aislm\">작은 모델의 시대 — 소버린 AI·온디바이스·SLM</h1>\r\n<p>큰 모델 이야기 뒤, 강사가 공직자에게 진짜 권한 건 <strong>작은 모델</strong>이다.</p>\r\n<h2 id=\"ai_1\">소버린 AI의 핵심은 \"모델의 다양성\"</h2>\r\n<ul>\r\n<li><strong>소버린 AI(Sovereign AI)</strong>: 자국이 통제하는 AI 역량. GPU 같은 하드웨어 자원도 중요하지만, 강사는 <strong>모델의 다양성</strong>(조선·제조·철강·농업 등 우리 도메인 데이터로 튜닝한 다양한 모델 확보)이 진짜 핵심이라고 본다.</li>\r\n</ul>\r\n<blockquote class=\"callout callout-warn\"><span class=\"callout-badge\">주의</span>\r\n<p><strong>보강 · [정정] — 트럼프 vs Anthropic 사건의 실제 내용.</strong> 강사는 \"트럼프가 베네수엘라 지도자 검거 때 Claude가 거부하자 내쫓았다\"고 기억했는데, 사실관계는 조금 다르다. 실제로는 <strong>미 국방부(DoD)가 Claude를 \"모든 합법적 목적(자율무기·국내 대량감시 포함)\"에 쓰게 해달라고 요구 → Anthropic이 거부 → 트럼프 행정부가 전 정부기관에 Anthropic 사용 중단 지시 + \"공급망 위험(supply chain risk)\" 지정 → Anthropic이 연방정부를 상대로 소송(2026년 3월), 1심에서 예비적 금지명령 일부 승소</strong>의 흐름이다. 강사 메시지(\"특정 모델에 종속되면 위험, 그래서 모델 다양성이 필요\")는 그대로 유효하다. (검색 보강)</p>\r\n</blockquote>\r\n<h2 id=\"ai-slm\">온디바이스·엣지 AI와 SLM</h2>\r\n<ul>\r\n<li><strong>SLM(Small Language Model)</strong>: 작은 언어모델. 1B·4B 같은 크기.</li>\r\n<li><strong>온디바이스/엣지 AI</strong>: 클라우드 없이 내 폰·라즈베리파이·작은 센서에서 도는 AI. 구글 딥마인드·알리바바 같은 빅테크가 주도하는 트렌드.</li>\r\n</ul>\r\n<p>강사가 콕 집은 모델: 구글 <strong>Gemma 3n E4B</strong>.</p>\r\n<blockquote class=\"callout callout-add\"><span class=\"callout-badge\">보강</span>\r\n<p><strong>보강</strong> — Gemma 3n E4B는 <strong>원본 8B인데 'effective 4B'</strong> 로 도는 게 특징이다. <strong>MatFormer(Matryoshka Transformer)</strong> 구조로, 큰 모델 안에 작은 모델이 들어있어 메모리·배터리를 아끼면서 추론한다. 10B 미만 최초로 LMArena 1300점을 넘겼다. <em>\"이펙티브 4 빌리언\"</em> 이 바로 이 뜻. (검색 보강)\r\n그 외: IBM <strong>Granite 8B</strong>, LG <strong>EXAONE</strong>, 업스테이지 <strong>Solar</strong> 등도 표에 보인다.</p>\r\n</blockquote>\r\n<h2 id=\"hugging-face-ollama\">직접 해보기 — Hugging Face + Ollama</h2>\r\n<p>강사가 \"Ollama 1B로 엑셀 함수도 설명시킨다\"고 말만 하고 넘어간 부분을 명령어로 채운다.</p>\r\n<ul>\r\n<li><strong>Hugging Face</strong>(huggingface.co): 오픈소스 모델 장터. 검색창에 <code>1B</code>처럼 치면 작은 모델이 수만 개. 파일은 보통 <strong>GGUF</strong>(llama.cpp/Ollama가 읽는 양자화 포맷) 확장자.</li>\r\n<li><strong>로컬 실행기</strong>: Ollama, LM Studio, MSTY, llama.cpp, AnythingLLM 등. 가장 간단한 게 Ollama.</li>\r\n</ul>\r\n<div class=\"codewrap\"><div class=\"codebar\"><span class=\"codelang\">Shell</span><button class=\"copybtn\" type=\"button\">복사</button></div><pre><code class=\"language-bash\"># 1) ollama.com 에서 설치한 뒤, 터미널(PowerShell)에서 바로 실행\r\nollama run gemma3:1b           # 1B 초경량 — 처음이면 자동 다운로드 후 대화 시작\r\nollama run gemma3n:e4b         # 온디바이스용, 추론 가능 (effective 4B)\r\nollama pull qwen3:1.7b         # 받아만 두기(실행은 나중에)\r\nollama list                    # 설치된 모델 목록\r\n</code></pre></div>\r\n<div class=\"codewrap\"><div class=\"codebar\"><span class=\"codelang\">text</span><button class=\"copybtn\" type=\"button\">복사</button></div><pre><code class=\"language-text\"># 실제로 1B에게 시켜볼 프롬프트 예시 (강의에서 보여준 것)\r\n엑셀 VLOOKUP 함수를 설명하고, 예제 데이터로 풀이 방법까지 보여줘.\r\n</code></pre></div>\r\n<blockquote class=\"callout callout-warn\"><span class=\"callout-badge\">주의</span>\r\n<p><strong>보강 — 폐쇄망 활용 포인트.</strong> 모델 태그(<code>gemma3:1b</code> 등)는 바뀔 수 있으니 <code>ollama.com/library</code>에서 확인. Ollama는 <strong>인터넷 없이 로컬에서</strong> 도니까, 외부망이 막힌 환경에서도 \"민원 분류만 잘하는 1~2B 모델\" 같은 <em>스페시픽(specific) 작은 모델</em>로 동료 업무의 숨통을 틔울 수 있다. 단, 설치 전 보안 점검은 필수.</p>\r\n<p>★ 강사의 결론: 큰 모델만 AI가 아니다. <strong>GPU 없는 평범한 PC의 작은 모델 하나로 미시적 문제를 푸는 POC(개념 증명)</strong> 가 지금 시점에 굉장히 중요하다.</p>\r\n</blockquote>\r\n<hr/>\r\n<h1 class=\"modhead\" data-full=\"멀티모달과 워크플로우 — 결과만 보여준 것 채우기\" id=\"_10\">멀티모달과 워크플로우 — 결과만 보여준 것 채우기</h1>\r\n<p><strong>멀티모달(multimodal)</strong>: 텍스트뿐 아니라 이미지·음성·영상까지 함께 다루는 능력.</p>\r\n<p>강사 시연: 종이 보고서를 <strong>사진 찍어</strong> \"여기에 똑같이 그려줘\"라고 하면 GPT Image 2가 문서를 통째로 전사·복제하고, 동시에 <em>\"이 문서와 똑같은, HTML 편집 가능 + PDF 저장 사이트를 만들어줘\"</em> 로 바이브코딩까지 한다. 이게 <strong>워크플로우</strong> — 프롬프트 한 줄이 아니라 여러 도구를 엮어 문제를 푸는 방식.</p>\r\n<div class=\"codewrap\"><div class=\"codebar\"><span class=\"codelang\">code</span><button class=\"copybtn\" type=\"button\">복사</button></div><pre class=\"mermaid\">flowchart LR\r\n  P[\"종이 문서&lt;br/&gt;사진 촬영\"] --&gt; M[\"멀티모달 모델&lt;br/&gt;GPT Image 2 등\"]\r\n  M --&gt; A[\"문서 전사·복제\"]\r\n  M --&gt; B[\"HTML로 동일 양식 생성&lt;br/&gt;편집·PDF저장 가능\"]\r\n  B --&gt; C[\"로컬 .html&lt;br/&gt;브라우저로 바로 열어 수정\"]\r\n</pre></div>\r\n<blockquote class=\"callout callout-add\"><span class=\"callout-badge\">보강</span>\r\n<p><strong>보강 — 왜 HTML을 자꾸 강조하나.</strong> C드라이브의 <code>.html</code>은 브라우저만 있으면 열린다. 자주 쓰는 양식(주간/월간 보고서)을 HTML로 만들어 두고 <strong>작은 4B 모델 하나만 붙여도</strong> 문서를 자동 생성하는 서비스가 된다. 외부 API가 허용되면 더 다양한 AI 서비스로 확장. 1장의 \"워크벤치\"가 바로 그 예(HTML로만 만든 서비스).</p>\r\n<p><strong>보강 — 멀티모달 모델 모아 쓰는 곳.</strong> Higgsfield 같은 사이트에 들어가면 GPT Image 2·Nano Banana 2·Seedream·Seedance·Kling·Veo·Sora 2 등을 한곳에서 써볼 수 있다. (이름은 자주 바뀐다 — 8주 과정 중 영상·홍보 제작 때 직접 다룸.)</p>\r\n</blockquote>\r\n<hr/>\r\n<h1 class=\"modhead\" data-full=\"프롬프트에서 컨텍스트·하네스로 — 용어 정리\" id=\"_11\">프롬프트에서 컨텍스트·하네스로 — 용어 정리</h1>\r\n<p>강사가 \"용어 전쟁\"이라 부른 부분. <strong>흐름 하나만</strong> 잡으면 된다: 모델이 똑똑해질수록, <em>프롬프트를 잘 쓰는 기술</em>에서 → <em>맥락(컨텍스트)을 잘 떠먹이는 기술</em>로 무게가 옮겨갔다.</p>\r\n<div class=\"codewrap\"><div class=\"codebar\"><span class=\"codelang\">code</span><button class=\"copybtn\" type=\"button\">복사</button></div><pre class=\"mermaid\">flowchart LR\r\n  P[\"프롬프트&lt;br/&gt;문법 잘 써야 답이 좋음\"] --&gt; C[\"컨텍스트 엔지니어링&lt;br/&gt;맥락을 충분히 넣음\"]\r\n  C --&gt; S[\"스킬 SKILL.md&lt;br/&gt;작업 지침을 파일로 저장\"]\r\n  S --&gt; H[\"하네스(harness)&lt;br/&gt;지침+도구+권한+코드베이스\"]\r\n</pre></div>\r\n<h2 id=\"ai_2\">메타 프롬프트 — \"AI에게 질문을 시켜라\"</h2>\r\n<p>내가 잘 모르는 주제라 프롬프트 쓰기가 막막할 때, <strong>AI가 먼저 객관식으로 물어보게</strong> 만드는 기법. 강사가 Claude Code의 \"플래닝 질문\" 방식을 차용한 것.</p>\r\n<div class=\"codewrap\"><div class=\"codebar\"><span class=\"codelang\">text</span><button class=\"copybtn\" type=\"button\">복사</button></div><pre><code class=\"language-text\">[역할] 너는 보고서 기획 도우미야.\r\n[작업] \"행정안전부 AI 미시적 혁신 운영방안 보고서\"를 쓸 건데, 뭘 넣을지 잘 몰라.\r\n[방식] 보고서에 들어갈 요소를 객관식 10지선다(A~J)로 5문항 만들어 나에게 먼저 질문해줘.\r\n       내가 각 문항에서 하나씩 고르면, 그 선택을 종합해 '완성된 보고서 작성 프롬프트'를 만들어줘.\r\n지금부터 질문 시작.\r\n</code></pre></div>\r\n<blockquote class=\"callout callout-key\"><span class=\"callout-badge\">핵심</span>\r\n<p>★ 5문항 × 10지선다면 경우의 수가 <code>10⁵</code>. 내가 원하는 딱 그 주제의 프롬프트로 <strong>분기</strong>시킬 수 있다. 이미지가 막막할 땐 똑같이 <em>\"포토그래퍼 전문 기법 10가지로 객관식 질문해줘\"</em> 로 응용. (광각·삼분할·웜즈아이뷰·블루아워·얕은 심도 같은 걸 몰라도 AI가 골라준다.)</p>\r\n<p><strong>보강 — 병렬로 일 시키기.</strong> ChatGPT에서 한 채팅창만 붙들지 말고, 메시지를 <strong>편집·분기</strong>(서브 에이전트처럼)해 여러 인격을 동시에 굴리는 습관도 권한다. 또 만든 프롬프트는 <em>새 창</em>에 옮겨 실행하라 — 만들던 창은 이미 \"프롬프트 만드는 맥락\"으로 오염돼 엉뚱한 답을 낼 수 있다.</p>\r\n</blockquote>\r\n<h2 id=\"_12\">컨텍스트 윈도우 / 컨텍스트 엔지니어링</h2>\r\n<ul>\r\n<li><strong>컨텍스트 윈도우(context window)</strong>: 한 대화에서 모델이 한 번에 기억하는 토큰의 총량(질문+답변 누적).</li>\r\n<li><strong>컨텍스트 엔지니어링</strong>: 정형화된 프롬프트 문법보다, <em>내가 가진 맥락·자료를 최대한 구체적으로 떠먹이는</em> 행위.</li>\r\n</ul>\r\n<blockquote class=\"callout callout-warn\"><span class=\"callout-badge\">주의</span>\r\n<p>⚠ <strong>주의 · [정정]</strong> — 강사는 \"컨텍스트 윈도우가 12만 8천 토큰까지, 책 한 권\"이라 했는데 이 수치는 <strong>이미 낡았다(GPT-4 Turbo 시절 128K)</strong>. 2026년 기준 <strong>Claude(Opus 4.8/Sonnet 4.6)는 200K가 기본, 100만(1M) 토큰도 일반 제공</strong>, <strong>Gemini는 1M(2M 예정)</strong>. \"책 한 권\"이 아니라 \"책 여러 권\" 수준으로 더 커졌다. (검색 보강)</p>\r\n</blockquote>\r\n<h2 id=\"_13\">스킬·하네스·규칙 파일</h2>\r\n<div class=\"tablescroll\"><table>\r\n<thead>\r\n<tr>\r\n<th>용어</th>\r\n<th>정체</th>\r\n<th>비유</th>\r\n</tr>\r\n</thead>\r\n<tbody>\r\n<tr>\r\n<td><strong>스킬 (SKILL.md)</strong></td>\r\n<td>\"이 작업은 이렇게 해라\"는 <strong>작업 지침 파일</strong></td>\r\n<td>AI에게 미리 쥐여주는 매뉴얼</td>\r\n</tr>\r\n<tr>\r\n<td><strong>하네스 (harness)</strong></td>\r\n<td>지침 + <strong>도구 호출(tool calling)·파일 권한·코드베이스</strong>까지 묶은 실행 환경</td>\r\n<td>매뉴얼 + 연장통 + 작업장</td>\r\n</tr>\r\n<tr>\r\n<td><strong>규칙 파일</strong></td>\r\n<td>CLAUDE.md / AGENTS.md / Cursor·Windsurf Rules</td>\r\n<td>프로젝트마다 AI가 먼저 읽는 규칙서</td>\r\n</tr>\r\n</tbody>\r\n</table></div>\r\n<p>예: \"행안부 문서 가이드 기반으로 HWPX를 만들어주는 스킬\"을 두면, 내가 \"보고서 써줘\" 한 줄만 던져도 AI가 그 <code>SKILL.md</code>를 읽고 <em>\"파이썬 hwpx 라이브러리를 호출하고, 서식은 이렇게\"</em> 까지 알아서 처리한다. 이게 다 <strong>컨텍스트</strong>다.</p>\r\n<blockquote class=\"callout callout-warn\"><span class=\"callout-badge\">주의</span>\r\n<p>⚠ <strong>주의 — 오버 엔지니어링 경계.</strong> \"하네스 안에 또 하네스\"를 만들며 용어에 매몰되는 사람들이 있다. 용어 전쟁에 휘둘리지 말고 <strong>흐름</strong>만 기억하라: 컨텍스트가 좋아져서, 제로샷(맨몸 한 줄)만 던져도 AI가 관련 지침을 읽어가며 실행할 수준이 됐다.</p>\r\n</blockquote>\r\n<hr/>\r\n<h1 class=\"modhead\" data-full=\"AI가 내 컴퓨터로 들어온다 — 통합 전략과 에이전트\" id=\"ai_3\">AI가 내 컴퓨터로 들어온다 — 통합 전략과 에이전트</h1>\r\n<p>마지막 트렌드. AI는 외부 사이트 → 브라우저 → 내 컴퓨터 순으로 점점 안쪽까지 들어온다.</p>\r\n<div class=\"codewrap\"><div class=\"codebar\"><span class=\"codelang\">code</span><button class=\"copybtn\" type=\"button\">복사</button></div><pre class=\"mermaid\">flowchart LR\r\n  EX[\"외부 LLM&lt;br/&gt;ChatGPT·Gemini·Claude\"] --&gt; BR[\"브라우저&lt;br/&gt;Edge의 Copilot·Chrome의 Gemini 사이드바\"]\r\n  BR --&gt; DT[\"데스크탑 앱&lt;br/&gt;Claude·Codex·Antigravity\"]\r\n  DT --&gt; AG[\"코딩 에이전트&lt;br/&gt;내 컴퓨터 파일을 직접 읽고 처리\"]\r\n</pre></div>\r\n<h2 id=\"_14\">회사별 통합(생태계) 전략</h2>\r\n<ul>\r\n<li><strong>OpenAI(ChatGPT)</strong>: 자체 플랫폼이 없어 <strong>MCP로 서드파티</strong>(공공데이터포털·법령정보 등)를 붙여 생태계 확장.</li>\r\n<li><strong>Google(Gemini)</strong>: 시트·코랩·슬라이드·지메일·캘린더 등 <strong>자기 생태계</strong> 안에 통합.</li>\r\n<li><strong>Anthropic(Claude)</strong>: 엑셀·파워포인트에 들어가고, 스킬·플러그인·Managed Agents 등 <strong>독립 생태계</strong>를 강화. 최근 금융·회계용 엑셀 에이전트로 월가에서 화제.</li>\r\n</ul>\r\n<blockquote class=\"callout callout-add\"><span class=\"callout-badge\">보강</span>\r\n<p><strong>보강 — 에이전틱 AI는 아직 신중하게.</strong> <em>에이전트</em>가 \"내가 시킨 자동화를 수행\"하는 단계라면, <em>에이전틱(agentic) AI</em>는 \"무엇을 할지 <strong>판단·의사결정</strong>까지 맡기는\" 단계다. 강사 경험상 아직 불안하다(실제로 에이전트가 파일을 다 지운 적도). 그래서 <strong>사람 승인(approval) 단계</strong>를 끼우는 게 현실적이다.</p>\r\n<p>★ <strong>공공의 과제 = 거버넌스.</strong> 이 에이전트가 Gemini가 아니라 AI 공통기반(FabriX·네이버 클로바)과 연결된다면 어떻게 운영·통제할지 고민하라. 에이전트를 굴리는 브릿지 파일들은 오픈소스로 많이 나와 있어, <strong>오픈소스 + Gemma 4B로 공공 자체 하네스 시스템</strong>을 만드는 게 좋은 팀 프로젝트가 될 수 있다(= \"애자일 AI\").</p>\r\n</blockquote>\r\n<hr/>\r\n<h1 class=\"modhead\" data-full=\"부록 — 용어 사전·환경설정·출처\" id=\"_15\">부록 — 용어 사전·환경설정·출처</h1>\r\n<h2 id=\"_16\">용어 빠른 사전</h2>\r\n<div class=\"tablescroll\"><table>\r\n<thead>\r\n<tr>\r\n<th>용어</th>\r\n<th>한 줄 정의</th>\r\n</tr>\r\n</thead>\r\n<tbody>\r\n<tr>\r\n<td>바이브 코딩</td>\r\n<td>문법 몰라도 자연어로 AI에게 시켜 프로그램을 만드는 방식</td>\r\n</tr>\r\n<tr>\r\n<td>DX / AX</td>\r\n<td>디지털 전환(정량화) / AI 전환(더 세밀한 패턴·비정형까지)</td>\r\n</tr>\r\n<tr>\r\n<td>파라미터</td>\r\n<td>모델의 곱셈 가중치 개수 = 모델 크기</td>\r\n</tr>\r\n<tr>\r\n<td>토큰</td>\r\n<td>단어가 쪼개진 조각. 컨텍스트 윈도우의 단위</td>\r\n</tr>\r\n<tr>\r\n<td>임베딩</td>\r\n<td>단어를 좌표(벡터)로 바꿔 의미 거리를 재는 것</td>\r\n</tr>\r\n<tr>\r\n<td>트랜스포머 / Q·K·V</td>\r\n<td>LLM의 핵심 구조 / 어텐션에서 관련도를 계산하는 세 벡터</td>\r\n</tr>\r\n<tr>\r\n<td>컨텍스트 윈도우</td>\r\n<td>한 번에 기억하는 토큰 총량</td>\r\n</tr>\r\n<tr>\r\n<td>컨텍스트 엔지니어링</td>\r\n<td>맥락·자료를 잘 떠먹여 답을 끌어내는 기술</td>\r\n</tr>\r\n<tr>\r\n<td>SLM / 온디바이스·엣지 AI</td>\r\n<td>작은 언어모델 / 클라우드 없이 내 기기·센서에서 도는 AI</td>\r\n</tr>\r\n<tr>\r\n<td>GGUF</td>\r\n<td>로컬 실행기(Ollama 등)가 읽는 모델 양자화 포맷</td>\r\n</tr>\r\n<tr>\r\n<td>MCP</td>\r\n<td>AI에 외부 도구·데이터를 연결하는 표준 규격</td>\r\n</tr>\r\n<tr>\r\n<td>스킬(SKILL.md) / 하네스</td>\r\n<td>작업 지침 파일 / 지침+도구+권한까지 묶은 실행 환경</td>\r\n</tr>\r\n<tr>\r\n<td>RAG</td>\r\n<td>외부 정보를 검색해 LLM 답변에 섞어 신뢰도를 높이는 방식</td>\r\n</tr>\r\n<tr>\r\n<td>소버린 AI</td>\r\n<td>자국이 통제하는 AI 역량(특히 모델 다양성)</td>\r\n</tr>\r\n</tbody>\r\n</table></div>\r\n<h2 id=\"_17\">환경설정 체크리스트(과제 예고)</h2>\r\n<p>1회차 과제는 <strong>환경설정 완비</strong>다. 강사가 따로 리스트·가이드를 보낼 예정이지만, 미리 준비하면 좋은 것:</p>\r\n<ul>\r\n<li>[ ] <strong>Python</strong> 설치 (대부분 이미 됨)</li>\r\n<li>[ ] <strong>구글 계정</strong> (가능하면 부계정 — 단, 생년월일을 오늘 날짜로 넣지 말 것: 미성년 처리되어 잠긴다)</li>\r\n<li>[ ] <strong>코딩 에이전트</strong> 중 PC가 허락하는 것: Claude Code · Codex · Cursor · Windsurf · Gemini용 Antigravity · opencode · Goose</li>\r\n<li>[ ] <strong>Ollama</strong> (로컬 SLM 실험용) + 작은 모델 1개 받아두기</li>\r\n<li>[ ] 주요 서비스 계정/구독 상태 점검: ChatGPT · Gemini · Claude (2회차에 50개+ 서비스 투어)</li>\r\n</ul>\r\n<blockquote class=\"callout callout-add\"><span class=\"callout-badge\">보강</span>\r\n<p><strong>보강 — 폐쇄망 대안 한 줄.</strong> 외부망이 막히면 코딩 에이전트 대신 <strong>외부 LLM 어시스트 → 코드 이식 → 로컬 실행</strong> 워크플로우로 간다(4장). 로컬 추론은 <strong>Ollama</strong>, 로컬 STT가 필요하면 <strong>faster-whisper</strong> 같은 오프라인 도구로 같은 일을 할 수 있다.</p>\r\n</blockquote>\r\n<h2 id=\"_18\">검색으로 보강·정정한 출처</h2>\r\n<ul>\r\n<li>Gemma 3n E4B(MatFormer, effective 4B): <a href=\"https://ai.google.dev/gemma/docs/gemma-3n\">Google AI for Developers</a>, <a href=\"https://artificialanalysis.ai/models/gemma-3n-e4b\">Artificial Analysis</a></li>\r\n<li>LifeArchitect Models Table (Alan D. Thompson): <a href=\"https://lifearchitect.ai/models-table/\">models-table</a></li>\r\n<li>LLM 시각화(GPT-2, 768/2304 구조): <a href=\"https://bbycroft.net/llm\">bbycroft.net/llm</a>, <a href=\"https://github.com/bbycroft/llm-viz\">GitHub bbycroft/llm-viz</a></li>\r\n<li>컨텍스트 윈도우 현황(Claude 200K~1M, Gemini 1M~2M): <a href=\"https://platform.claude.com/docs/en/build-with-claude/context-windows\">Claude Platform Docs</a></li>\r\n<li>트럼프 행정부 vs Anthropic(국방부 분쟁·소송): <a href=\"https://en.wikipedia.org/wiki/Anthropic%E2%80%93United_States_Department_of_Defense_dispute\">Wikipedia</a>, <a href=\"https://www.npr.org/2026/03/09/nx-s1-5742548/anthropic-pentagon-lawsuit-amodai-hegseth\">NPR</a></li>\r\n</ul>\r\n  </main>\r\n</div>\r\n\r\n<script src=\"https://cdnjs.cloudflare.com/ajax/libs/highlight.js/11.9.0/highlight.min.js\"><\/script>\r\n<script src=\"https://cdnjs.cloudflare.com/ajax/libs/highlight.js/11.9.0/languages/powershell.min.js\"><\/script>\r\n<script src=\"https://cdnjs.cloudflare.com/ajax/libs/highlight.js/11.9.0/languages/vbscript.min.js\"><\/script>\r\n<script src=\"https://cdnjs.cloudflare.com/ajax/libs/mermaid/10.9.1/mermaid.min.js\"><\/script>\r\n<script>\r\n// 주제 헤더 raw 텍스트를 data-full로 옮겨 ::after 표시\r\ndocument.querySelectorAll('h1.modhead').forEach(function(h){\r\n  h.setAttribute('data-full', h.textContent);\r\n});\r\n\r\n// highlight.js\r\nif(window.hljs){\r\n  document.querySelectorAll('.codewrap pre code').forEach(function(b){\r\n    try{hljs.highlightElement(b);}catch(e){}\r\n  });\r\n}\r\n\r\n// mermaid\r\nif(window.mermaid){\r\n  mermaid.initialize({\r\n    startOnLoad:true, theme:'base',\r\n    htmlLabels:false,\r\n    themeVariables:{\r\n      fontFamily:'-apple-system,Pretendard,\"Malgun Gothic\",sans-serif',\r\n      fontSize:'13px',\r\n      primaryColor:'#e6f4f1', primaryBorderColor:'#127c71', primaryTextColor:'#0c5249',\r\n      lineColor:'#9aa0a8', secondaryColor:'#f4f1ea', tertiaryColor:'#fbf1e4',\r\n      clusterBkg:'#f6f6f0', clusterBorder:'#cfd3cb'\r\n    },\r\n    flowchart:{curve:'basis', useMaxWidth:true, htmlLabels:false},\r\n    sequence:{useMaxWidth:true}\r\n  });\r\n}\r\n\r\n// 복사 버튼\r\ndocument.querySelectorAll('.copybtn').forEach(function(btn){\r\n  btn.addEventListener('click', function(){\r\n    var code = btn.closest('.codewrap').querySelector('pre code');\r\n    var txt = code ? code.innerText : '';\r\n    navigator.clipboard.writeText(txt).then(function(){\r\n      btn.textContent='복사됨'; btn.classList.add('ok');\r\n      setTimeout(function(){btn.textContent='복사'; btn.classList.remove('ok');},1400);\r\n    });\r\n  });\r\n});\r\n\r\n// 스크롤 스파이\r\nvar links = Array.from(document.querySelectorAll('#nav a'));\r\nvar map = {};\r\nlinks.forEach(function(a){ map[a.getAttribute('href').slice(1)] = a; });\r\nvar heads = Array.from(document.querySelectorAll('.main h1[id], .main h2[id]'));\r\nvar spy = new IntersectionObserver(function(entries){\r\n  entries.forEach(function(en){\r\n    if(en.isIntersecting){\r\n      links.forEach(function(l){l.classList.remove('active');});\r\n      var act = map[en.target.id];\r\n      if(act){act.classList.add('active');\r\n        act.scrollIntoView({block:'nearest'});}\r\n    }\r\n  });\r\n}, {rootMargin:'-10% 0px -75% 0px', threshold:0});\r\nheads.forEach(function(h){spy.observe(h);});\r\n\r\n// 모바일 사이드바\r\nvar side=document.getElementById('side'), scrim=document.getElementById('scrim'),\r\n    mb=document.getElementById('menubtn');\r\nfunction toggle(open){side.classList.toggle('open',open);scrim.classList.toggle('show',open);}\r\nif(mb){mb.addEventListener('click',function(){toggle(!side.classList.contains('open'));});}\r\nif(scrim){scrim.addEventListener('click',function(){toggle(false);});}\r\nlinks.forEach(function(a){a.addEventListener('click',function(){if(window.innerWidth<=880)toggle(false);});});\r\n<\/script>\r\n</body>\r\n</html>\r\n","2":"<!DOCTYPE html>\r\n<html lang=\"ko\">\r\n<head>\r\n<meta charset=\"utf-8\">\r\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\r\n<title>2회차 — AI 프론티어 탐색: 최전선 도구를 직접 써보고, 직접 만든다</title>\r\n<link rel=\"preconnect\" href=\"https://cdnjs.cloudflare.com\">\r\n<link rel=\"stylesheet\" href=\"https://cdnjs.cloudflare.com/ajax/libs/highlight.js/11.9.0/styles/github.min.css\">\r\n<style>\r\n:root{\r\n  --bg:#fafaf6; --panel:#ffffff; --ink:#1b1e24; --ink-soft:#5a6069; --ink-faint:#8b919b;\r\n  --line:#e7e6df; --line-soft:#f0efe9;\r\n  --teal:#127c71; --teal-d:#0c5249; --teal-bg:#e6f4f1;\r\n  --amber:#b9722a; --amber-bg:#fbf1e4;\r\n  --red:#c0392b; --red-bg:#fbe9e7;\r\n  --code-bg:#f6f6f0;\r\n  --mono:ui-monospace,\"SF Mono\",\"Cascadia Code\",\"JetBrains Mono\",Consolas,monospace;\r\n  --sans:-apple-system,BlinkMacSystemFont,\"Pretendard\",\"Apple SD Gothic Neo\",\"Segoe UI\",\"Malgun Gothic\",sans-serif;\r\n  --rad:12px;\r\n}\r\n*{box-sizing:border-box}\r\nhtml{scroll-behavior:smooth}\r\n@media (prefers-reduced-motion:reduce){html{scroll-behavior:auto}}\r\nbody{margin:0;background:var(--bg);color:var(--ink);font-family:var(--sans);\r\n  font-size:16px;line-height:1.72;-webkit-font-smoothing:antialiased}\r\n\r\n/* layout */\r\n.shell{display:grid;grid-template-columns:300px minmax(0,1fr);max-width:1240px;margin:0 auto}\r\n.print-toc{display:none}\r\n.side{position:sticky;top:0;align-self:start;height:100vh;overflow-y:auto;\r\n  padding:30px 22px 60px;border-right:1px solid var(--line)}\r\n.main{min-width:0;padding:46px 60px 120px;max-width:880px}\r\n\r\n/* sidebar */\r\n.brand{font-family:var(--mono);font-size:11px;letter-spacing:.14em;text-transform:uppercase;\r\n  color:var(--teal);margin-bottom:6px}\r\n.brand-t{font-weight:700;font-size:17px;line-height:1.35;margin:0 0 4px}\r\n.brand-s{font-size:12.5px;color:var(--ink-faint);margin:0 0 24px;line-height:1.5}\r\nnav a{display:block;text-decoration:none;color:var(--ink-soft);border-left:2px solid transparent;\r\n  padding:3px 0 3px 12px;font-size:13.5px;transition:color .15s,border-color .15s}\r\nnav a:hover{color:var(--ink)}\r\nnav a.nav-h1{margin-top:16px;font-weight:700;color:var(--ink);font-size:13px;\r\n  font-family:var(--mono);letter-spacing:.02em}\r\nnav a.nav-h2{font-size:13px}\r\nnav a.active{color:var(--teal-d);border-left-color:var(--teal);font-weight:600}\r\n\r\n/* headings */\r\nh1.modhead{font-size:13px;font-family:var(--mono);letter-spacing:.06em;text-transform:uppercase;\r\n  color:var(--teal);margin:72px 0 0;padding-top:28px;border-top:2px solid var(--ink);\r\n  font-weight:700}\r\nh1.modhead::after{content:attr(data-full);display:block;font-family:var(--sans);\r\n  font-size:30px;letter-spacing:-.01em;text-transform:none;color:var(--ink);\r\n  margin-top:8px;font-weight:750;line-height:1.2}\r\nh1.modhead{font-size:0}            /* hide raw, show via ::after */\r\nh1.modhead.intro{font-size:13px}\r\nh2{font-size:21px;font-weight:720;letter-spacing:-.01em;margin:46px 0 14px;\r\n  padding-bottom:8px;border-bottom:1px solid var(--line)}\r\nh3{font-size:16.5px;font-weight:700;margin:32px 0 10px;color:var(--ink)}\r\nh2.starred,h3.starred{color:var(--teal-d)}\r\nh2.starred::before,h3.starred::before{content:\"★ \";color:var(--teal);font-size:.85em}\r\nh2.starred,h3.starred{}\r\n.main h1:first-of-type{margin-top:0}\r\n\r\np{margin:12px 0}\r\na{color:var(--teal-d)}\r\nstrong{font-weight:700;color:var(--ink)}\r\nul,ol{padding-left:22px;margin:12px 0}\r\nli{margin:5px 0}\r\nhr{border:none;border-top:1px solid var(--line);margin:40px 0}\r\n\r\n/* intro hero */\r\n.hero{background:linear-gradient(135deg,#0c5249,#127c71);color:#eafaf6;\r\n  border-radius:16px;padding:34px 36px;margin:0 0 14px}\r\n.hero .eyebrow{font-family:var(--mono);font-size:11px;letter-spacing:.16em;\r\n  text-transform:uppercase;color:#9fdfd2;margin-bottom:10px}\r\n.hero h1{font-size:32px;line-height:1.18;margin:0 0 12px;font-weight:780;letter-spacing:-.02em}\r\n.hero p{margin:0;color:#cfeee7;font-size:14.5px;line-height:1.6}\r\n\r\n/* tables */\r\ntable{width:100%;border-collapse:collapse;margin:18px 0;font-size:14px;\r\n  border:1px solid var(--line);border-radius:var(--rad);overflow:hidden}\r\nthead th{background:var(--teal-bg);color:var(--teal-d);text-align:left;\r\n  font-weight:700;padding:10px 13px;font-size:13px}\r\ntd{padding:10px 13px;border-top:1px solid var(--line-soft);vertical-align:top}\r\ntbody tr:nth-child(even){background:#fbfbf8}\r\n.tablescroll{overflow-x:auto}\r\n\r\n/* code */\r\n.codewrap{margin:16px 0;border:1px solid var(--line);border-radius:var(--rad);\r\n  overflow:hidden;background:var(--code-bg)}\r\n.codebar{display:flex;justify-content:space-between;align-items:center;\r\n  padding:7px 12px;background:#efeee7;border-bottom:1px solid var(--line)}\r\n.codelang{font-family:var(--mono);font-size:11px;letter-spacing:.08em;\r\n  text-transform:uppercase;color:var(--ink-faint);font-weight:600}\r\n.copybtn{font-family:var(--mono);font-size:11px;border:1px solid var(--line);\r\n  background:#fff;color:var(--ink-soft);padding:3px 11px;border-radius:6px;cursor:pointer;\r\n  transition:all .15s}\r\n.copybtn:hover{border-color:var(--teal);color:var(--teal-d)}\r\n.copybtn.ok{background:var(--teal);color:#fff;border-color:var(--teal)}\r\n.codewrap pre{margin:0;padding:0}\r\npre code,pre.hljs{display:block;padding:15px 16px;overflow-x:auto;\r\n  font-family:var(--mono);font-size:13px;line-height:1.6;background:var(--code-bg)!important}\r\n:not(pre)>code{font-family:var(--mono);font-size:.88em;background:#eeede6;\r\n  padding:1.5px 6px;border-radius:5px;color:var(--teal-d);white-space:nowrap}\r\n\r\n/* mermaid */\r\npre.mermaid{background:var(--panel);border:1px solid var(--line);border-radius:var(--rad);\r\n  padding:22px;margin:20px 0;text-align:center;overflow-x:auto;line-height:1.4}\r\n\r\n/* callouts */\r\n.callout{position:relative;margin:18px 0;padding:14px 18px 14px 18px;border-radius:10px;\r\n  border-left:4px solid var(--ink-faint);background:#f4f4ee;font-size:14.5px}\r\n.callout p{margin:8px 0}\r\n.callout p:first-of-type{margin-top:0}\r\n.callout p:last-child{margin-bottom:0}\r\n.callout-badge{display:inline-block;font-family:var(--mono);font-size:10.5px;\r\n  letter-spacing:.1em;text-transform:uppercase;font-weight:700;\r\n  padding:2px 9px;border-radius:20px;margin-bottom:8px}\r\n.callout-note{border-left-color:#9aa0a8;background:#f3f3ee}\r\n.callout-note .callout-badge{background:#e4e4dd;color:#5a6069}\r\n.callout-key{border-left-color:var(--teal);background:var(--teal-bg)}\r\n.callout-key .callout-badge{background:var(--teal);color:#fff}\r\n.callout-warn{border-left-color:var(--amber);background:var(--amber-bg)}\r\n.callout-warn .callout-badge{background:var(--amber);color:#fff}\r\n.callout-add{border-left-color:var(--teal-d);background:#e9f3f1}\r\n.callout-add .callout-badge{background:var(--teal-d);color:#fff}\r\n\r\n/* topbar (mobile) */\r\n.topbar{display:none}\r\n\r\n@media (max-width:880px){\r\n  .shell{grid-template-columns:1fr}\r\n  .side{position:fixed;z-index:40;top:0;left:0;width:84%;max-width:320px;height:100vh;\r\n    background:var(--panel);transform:translateX(-105%);transition:transform .25s;\r\n    box-shadow:0 0 40px rgba(0,0,0,.18)}\r\n  .side.open{transform:translateX(0)}\r\n  .main{padding:70px 22px 90px}\r\n  .topbar{display:flex;align-items:center;gap:12px;position:sticky;top:0;z-index:30;\r\n    background:rgba(250,250,246,.92);backdrop-filter:blur(8px);\r\n    padding:12px 18px;border-bottom:1px solid var(--line)}\r\n  .menubtn{font-family:var(--mono);font-size:13px;border:1px solid var(--line);\r\n    background:#fff;padding:6px 12px;border-radius:8px;cursor:pointer}\r\n  .topbar .tt{font-family:var(--mono);font-size:12px;color:var(--teal);letter-spacing:.05em}\r\n  .scrim{display:none;position:fixed;inset:0;background:rgba(0,0,0,.35);z-index:35}\r\n  .scrim.show{display:block}\r\n  h1.modhead::after{font-size:25px}\r\n  .hero h1{font-size:25px}\r\n  .main{max-width:100%}\r\n}\r\n\r\n/* ── 인쇄 / PDF 저장 (출력 시 목차 먼저 → 본문) ── */\r\n@media print{\r\n  @page{margin:14mm 12mm}\r\n  *{-webkit-print-color-adjust:exact;print-color-adjust:exact}\r\n  .topbar,.scrim,.menubtn,.copybtn{display:none!important}\r\n  .shell{display:block;max-width:none}\r\n  /* 화면용 사이드바는 인쇄에서 완전히 숨김 (변환 불안정 → 빈 페이지 방지) */\r\n  .side{display:none!important}\r\n  /* 인쇄 전용 목차: 본문 맨 앞 일반 블록으로 깔끔히 출력 후 페이지 넘김 */\r\n  .print-toc{display:block!important;break-after:page;page-break-after:always}\r\n  .print-toc .ptoc-title{font-size:19pt;font-weight:800;color:#0c5249;letter-spacing:-.01em;\r\n    margin:0 0 16px;padding-bottom:10px;border-bottom:2px solid #127c71}\r\n  .print-toc a{display:block;color:#1b1e24;text-decoration:none;padding:3px 0;font-size:11.5pt;border:none}\r\n  .print-toc a.nav-h1{margin-top:13px;font-weight:700;color:#0c5249;font-size:12.5pt}\r\n  .print-toc a.nav-h2{padding-left:16px;color:#3a3f47}\r\n  /* 본문 */\r\n  .main{padding:0;max-width:none}\r\n  body{font-size:10.5pt;line-height:1.5;background:#fff}\r\n  a{text-decoration:none;color:inherit}\r\n  .hero{break-inside:avoid;background:#fff!important;color:#1b1e24!important;\r\n    border:none;border-bottom:2px solid #127c71;border-radius:0;\r\n    padding:0 0 14px!important;margin:0 0 18px}\r\n  .hero .eyebrow{color:#127c71!important}\r\n  .hero h1{color:#0c5249!important}\r\n  .hero p{color:#444!important}\r\n  /* 주제 헤더가 페이지 맨 아래 외롭게 걸리지 않게만 (새 페이지 강제는 빼서 빈 페이지 방지) */\r\n  h1.modhead{break-after:avoid;page-break-after:avoid}\r\n  h2,h3{break-after:avoid;page-break-after:avoid}\r\n  /* 코드·콜아웃·표·다이어그램은 페이지 중간에서 잘리지 않게 */\r\n  .codewrap,.callout,pre.mermaid,.tablescroll,table{break-inside:avoid;page-break-inside:avoid}\r\n  pre code,pre.hljs{white-space:pre-wrap;word-break:break-word}\r\n  pre.mermaid{text-align:center;border:1px solid #ddd;padding:12px 8px;margin:14px auto}\r\n  pre.mermaid svg{max-width:100%!important;height:auto!important;\r\n    max-height:200mm!important;display:inline-block!important}\r\n  .codewrap{border-color:#ccc}\r\n}\r\n</style>\r\n</head>\r\n<body>\r\n<div class=\"topbar\">\r\n  <button class=\"menubtn\" id=\"menubtn\" aria-label=\"목차 열기\">☰ 목차</button>\r\n  <span class=\"tt\">강의노트 · 보강판</span>\r\n</div>\r\n<div class=\"scrim\" id=\"scrim\"></div>\r\n<div class=\"shell\">\r\n  <aside class=\"side\" id=\"side\">\r\n    <div class=\"brand\">강의노트 · 02회차</div>\r\n    <p class=\"brand-t\">2회차 — AI 프론티어 탐색: 최전선 도구를 직접 써보고, 직접 만든다</p>\r\n    <p class=\"brand-s\">현장 강의 · 기술 보강판</p>\r\n    <nav id=\"nav\">\r\n<a class=\"nav-h1\" href=\"#0\">0. 관통하는 태도 — &quot;딸깍의 시대&quot;</a>\r\n<a class=\"nav-h1\" href=\"#1-rag-llm-who-am-i\">1. RAG를 거꾸로 — LLM 없는 검색 시스템 (&#x27;Who am I&#x27;)</a>\r\n<a class=\"nav-h2\" href=\"#rag-vs\">보통의 RAG vs 강사의 룰 기반 검색</a>\r\n<a class=\"nav-h2\" href=\"#rss-fusejs-bm25\">쓰인 부품 — RSS, Fuse.js(퍼지 검색), BM25, 레벤슈타인</a>\r\n<a class=\"nav-h1\" href=\"#2\">2. 트렌드를 누구보다 빨리 캐치하는 법</a>\r\n<a class=\"nav-h2\" href=\"#ai-rss\">AI 타임즈 + RSS로 자동 수집</a>\r\n<a class=\"nav-h2\" href=\"#_1\">&quot;데이터를 어떻게 합법적으로 모으나&quot; — 토스 페이스페이 사례</a>\r\n<a class=\"nav-h1\" href=\"#3-gpt\">3. 잠깐 개념 정리 — 트랜스포머와 GPT의 역사</a>\r\n<a class=\"nav-h1\" href=\"#4-slm\">4. SLM(소형 언어모델) 지형 — 숙제 리뷰</a>\r\n<a class=\"nav-h1\" href=\"#5\">5. 실습 — 개발 환경부터 배포까지 풀 사이클</a>\r\n<a class=\"nav-h2\" href=\"#5-1-3\">5-1. 개발 환경 3종 세트</a>\r\n<a class=\"nav-h2\" href=\"#5-2-exe-github-pages\">5-2. 계산기 → EXE → 웹 → GitHub Pages 배포</a>\r\n<a class=\"nav-h2\" href=\"#5-3-minimax-m2\">5-3. 모델 교체 — MiniMax M2</a>\r\n<a class=\"nav-h1\" href=\"#6-chatgpt\">6. ChatGPT 깊게 쓰기</a>\r\n<a class=\"nav-h2\" href=\"#meta-prompt\">메타 프롬프트(meta prompt)</a>\r\n<a class=\"nav-h2\" href=\"#claude-in-excel-claude-for-financial-services\">Claude in Excel / Claude for Financial Services</a>\r\n<a class=\"nav-h2\" href=\"#svg-ppt\">SVG로 PPT 장표 자동화 (강사의 비밀 무기)</a>\r\n<a class=\"nav-h2\" href=\"#_2\">코덱스 · 딥리서치 · 모델 티어</a>\r\n<a class=\"nav-h2\" href=\"#mermaid\">Mermaid로 다이어그램 그리기</a>\r\n<a class=\"nav-h1\" href=\"#7-mcp-gpt\">7. MCP와 앱 커넥터 — 도구를 GPT에 붙이기</a>\r\n<a class=\"nav-h2\" href=\"#notion\">Notion 연동</a>\r\n<a class=\"nav-h2\" href=\"#ai-mcp\">코리안로 AI — 한국 법령정보 MCP</a>\r\n<a class=\"nav-h1\" href=\"#8-gpts\">8. GPTs — 나만의 챗봇 만들기</a>\r\n<a class=\"nav-h2\" href=\"#gpts\">프로젝트 / GPTs와 &#x27;메모리 분리&#x27;</a>\r\n<a class=\"nav-h2\" href=\"#gpts-actions-api-open-meteo\">GPTs 작업(Actions) — 외부 API 연동 (Open-Meteo)</a>\r\n<a class=\"nav-h1\" href=\"#9-gemini\">9. 구글 Gemini 생태계</a>\r\n<a class=\"nav-h2\" href=\"#gemini\">Gemini의 태생 — 멀티모달 + 자체 칩</a>\r\n<a class=\"nav-h2\" href=\"#notebooklm\">NotebookLM</a>\r\n<a class=\"nav-h2\" href=\"#vids\">슬라이드 · 마인드맵 · Vids</a>\r\n<a class=\"nav-h2\" href=\"#stitch-ai-studio\">기획→개발 한 번에 — Stitch → AI Studio → 배포</a>\r\n<a class=\"nav-h1\" href=\"#10-lovable\">10. 바이브 코딩 — Lovable</a>\r\n<a class=\"nav-h1\" href=\"#_3\">부록 — 한눈에 보는 도구 맵</a>\r\n<a class=\"nav-h2\" href=\"#_4\">검색 보강 출처</a>\r\n    </nav>\r\n  </aside>\r\n  <main class=\"main\" id=\"main\">\r\n<nav class=\"print-toc\">\r\n<div class=\"ptoc-title\">목차</div>\r\n<a class=\"nav-h1\" href=\"#0\">0. 관통하는 태도 — &quot;딸깍의 시대&quot;</a>\r\n<a class=\"nav-h1\" href=\"#1-rag-llm-who-am-i\">1. RAG를 거꾸로 — LLM 없는 검색 시스템 (&#x27;Who am I&#x27;)</a>\r\n<a class=\"nav-h2\" href=\"#rag-vs\">보통의 RAG vs 강사의 룰 기반 검색</a>\r\n<a class=\"nav-h2\" href=\"#rss-fusejs-bm25\">쓰인 부품 — RSS, Fuse.js(퍼지 검색), BM25, 레벤슈타인</a>\r\n<a class=\"nav-h1\" href=\"#2\">2. 트렌드를 누구보다 빨리 캐치하는 법</a>\r\n<a class=\"nav-h2\" href=\"#ai-rss\">AI 타임즈 + RSS로 자동 수집</a>\r\n<a class=\"nav-h2\" href=\"#_1\">&quot;데이터를 어떻게 합법적으로 모으나&quot; — 토스 페이스페이 사례</a>\r\n<a class=\"nav-h1\" href=\"#3-gpt\">3. 잠깐 개념 정리 — 트랜스포머와 GPT의 역사</a>\r\n<a class=\"nav-h1\" href=\"#4-slm\">4. SLM(소형 언어모델) 지형 — 숙제 리뷰</a>\r\n<a class=\"nav-h1\" href=\"#5\">5. 실습 — 개발 환경부터 배포까지 풀 사이클</a>\r\n<a class=\"nav-h2\" href=\"#5-1-3\">5-1. 개발 환경 3종 세트</a>\r\n<a class=\"nav-h2\" href=\"#5-2-exe-github-pages\">5-2. 계산기 → EXE → 웹 → GitHub Pages 배포</a>\r\n<a class=\"nav-h2\" href=\"#5-3-minimax-m2\">5-3. 모델 교체 — MiniMax M2</a>\r\n<a class=\"nav-h1\" href=\"#6-chatgpt\">6. ChatGPT 깊게 쓰기</a>\r\n<a class=\"nav-h2\" href=\"#meta-prompt\">메타 프롬프트(meta prompt)</a>\r\n<a class=\"nav-h2\" href=\"#claude-in-excel-claude-for-financial-services\">Claude in Excel / Claude for Financial Services</a>\r\n<a class=\"nav-h2\" href=\"#svg-ppt\">SVG로 PPT 장표 자동화 (강사의 비밀 무기)</a>\r\n<a class=\"nav-h2\" href=\"#_2\">코덱스 · 딥리서치 · 모델 티어</a>\r\n<a class=\"nav-h2\" href=\"#mermaid\">Mermaid로 다이어그램 그리기</a>\r\n<a class=\"nav-h1\" href=\"#7-mcp-gpt\">7. MCP와 앱 커넥터 — 도구를 GPT에 붙이기</a>\r\n<a class=\"nav-h2\" href=\"#notion\">Notion 연동</a>\r\n<a class=\"nav-h2\" href=\"#ai-mcp\">코리안로 AI — 한국 법령정보 MCP</a>\r\n<a class=\"nav-h1\" href=\"#8-gpts\">8. GPTs — 나만의 챗봇 만들기</a>\r\n<a class=\"nav-h2\" href=\"#gpts\">프로젝트 / GPTs와 &#x27;메모리 분리&#x27;</a>\r\n<a class=\"nav-h2\" href=\"#gpts-actions-api-open-meteo\">GPTs 작업(Actions) — 외부 API 연동 (Open-Meteo)</a>\r\n<a class=\"nav-h1\" href=\"#9-gemini\">9. 구글 Gemini 생태계</a>\r\n<a class=\"nav-h2\" href=\"#gemini\">Gemini의 태생 — 멀티모달 + 자체 칩</a>\r\n<a class=\"nav-h2\" href=\"#notebooklm\">NotebookLM</a>\r\n<a class=\"nav-h2\" href=\"#vids\">슬라이드 · 마인드맵 · Vids</a>\r\n<a class=\"nav-h2\" href=\"#stitch-ai-studio\">기획→개발 한 번에 — Stitch → AI Studio → 배포</a>\r\n<a class=\"nav-h1\" href=\"#10-lovable\">10. 바이브 코딩 — Lovable</a>\r\n<a class=\"nav-h1\" href=\"#_3\">부록 — 한눈에 보는 도구 맵</a>\r\n<a class=\"nav-h2\" href=\"#_4\">검색 보강 출처</a>\r\n</nav>\r\n    <div class=\"hero\">\r\n      <div class=\"eyebrow\">Lecture Note · 기술 보강판</div>\r\n      <h1>2회차 — AI 프론티어 탐색: 최전선 도구를 직접 써보고, 직접 만든다</h1>\r\n      <p>현장 강의를 기술적으로 보강한 학습 레퍼런스 — 강사의 의도는 살리고, 빠지거나 틀린 기술은 정확히 채웠습니다.</p>\r\n    </div>\r\n\r\n<p>이 강의 하나로 무엇을 할 수 있게 하려는가 →\r\n<strong>\"프론티어 모델(LLM) 생태계를 한 바퀴 돌면서 ChatGPT·Claude·Gemini와 그 주변 도구(코딩 에이전트·MCP·GPTs·바이브 코딩)를 직접 설치·연동·배포해보고, '딸깍'으로 진입장벽이 무너진 시대에 '내가 필요한 걸 내가 만드는' 감각을 잡는 것.\"</strong></p>\r\n<blockquote class=\"callout callout-key\"><span class=\"callout-badge\">핵심</span>\r\n<p>★ 이 회차는 <strong>최전선 트렌드 투어 + 손으로 하는 실습</strong>이 섞여 있다. 깔끔한 위계(○○ 3계층 식)가 있는 강의가 아니라 <strong>나란한 주제들</strong>이 쭉 이어지고, 그걸 하나의 태도로 꿴다. 관통하는 태도는 한 줄: <strong>\"딸깍의 시대다 — 반대 방향까지 의심하며 직접 써보고, 트렌드를 누구보다 빨리 캐치하고, 결국 남는 건 사람(네트워크)이다.\"</strong></p>\r\n<p><strong>보강 안내</strong> — 강사가 이름만 흘리고 넘어간 도구·모델, 그리고 건너뛴 실제 명령어/코드/설정을 채워 넣고, 틀리게 말한 기술 사실은 <code>정정</code>으로 바로잡았다. 웹으로 확인한 항목은 <code>(검색 보강)</code>으로 출처를 밝혔다. <strong>요청대로 이번 회차는 참가자 자기소개 구간을 노트에서 뺐다.</strong></p>\r\n</blockquote>\r\n<hr/>\r\n<h1 class=\"modhead\" data-full='0. 관통하는 태도 — \"딸깍의 시대\"' id=\"0\">0. 관통하는 태도 — \"딸깍의 시대\"</h1>\r\n<p>강사가 강의 내내 반복한 키워드가 <strong>'딸깍'</strong>이다. 자동화/AI로 옛날엔 며칠 걸리던 걸 클릭 한 번에 해내는 상태를 가리키는 말장난인데, 이게 이 회차의 정서다.</p>\r\n<ul>\r\n<li><strong>진입장벽이 무너졌다.</strong> 코드 문법을 몰라도 자연어로 시켜서 앱을 만들고 배포한다. 그래서 \"먼저 설치하고 한 번이라도 더 돌려본 사람\"이 리드를 잡는다.</li>\r\n<li><strong>반대 방향까지 의심하라.</strong> 다들 \"LLM에 벡터 붙여 RAG\" 한 방향만 보는데, 강사는 일부러 그 <strong>정반대(룰 기반·LLM 없는 검색)</strong>를 들고 나왔다(1장). \"오픈AI 없이 RAG 못 만들어?\" 같은 질문을 던지는 게 핵심.</li>\r\n<li><strong>트렌드를 빠르게 캐치하라.</strong> AI는 교과서가 없다. 먼저 써본 사람이 1등이다(2장).</li>\r\n<li><strong>결국 남는 건 사람.</strong> 기술 진입장벽이 낮아질수록, 뜻을 같이하는 네트워크가 진짜 자산이다.</li>\r\n<li><strong>작게 시작하고, 도메인 전문가와 함께하라.</strong> MVP로 작게 시작하고, 업무를 정확히 아는 사람과 짜면 시스템이 간결해진다(7장).</li>\r\n</ul>\r\n<hr/>\r\n<h1 class=\"modhead\" data-full=\"1. RAG를 거꾸로 — LLM 없는 검색 시스템 ('Who am I')\" id=\"1-rag-llm-who-am-i\">1. RAG를 거꾸로 — LLM 없는 검색 시스템 ('Who am I')</h1>\r\n<p>강사가 수강생 정보를 검색해주는 'Who am I' 시스템을 만들어 보여줬다. 핵심은 <strong>여기에 LLM이 0% 들어갔다</strong>는 것 — \"LLM-프리(LLM-free)\" 시스템이다.</p>\r\n<h2 id=\"rag-vs\">보통의 RAG vs 강사의 룰 기반 검색</h2>\r\n<p>우리가 흔히 듣는 RAG는 단계가 길다. 문서를 잘게 쪼개고(청킹) → 숫자 벡터로 바꾸고(임베딩) → 벡터 DB에 저장 → 질문도 임베딩해서 의미가 가까운 걸 찾아 → LLM이 답을 생성. 강사는 이걸 <strong>정반대로</strong>, 의미를 담는 임베딩 없이 글자 그대로 빠르게 찾는 룰 기반으로 만들었다.</p>\r\n<div class=\"codewrap\"><div class=\"codebar\"><span class=\"codelang\">code</span><button class=\"copybtn\" type=\"button\">복사</button></div><pre class=\"mermaid\">flowchart TD\r\n  Q[\"사용자 질문\"] --&gt; R1{\"두 갈래\"}\r\n  R1 --&gt;|\"흔한 RAG (의미 기반)\"| A1[\"청킹 → 임베딩(모델) → 벡터DB → LLM 생성\"]\r\n  R1 --&gt;|\"강사의 LLM-free (룰 기반)\"| A2[\"RSS로 데이터 참조 → Fuse.js 퍼지검색 → 결과 그대로\"]\r\n  A1 --&gt; O1[\"풍부하지만 느리고&lt;br/&gt;운영·비용 큼\"]\r\n  A2 --&gt; O2[\"의미는 약하지만&lt;br/&gt;빠르고 폐쇄망에 강함\"]\r\n</pre></div>\r\n<div class=\"tablescroll\"><table>\r\n<thead>\r\n<tr>\r\n<th>구분</th>\r\n<th>흔한 RAG (의미 기반)</th>\r\n<th>강사의 LLM-free (룰 기반)</th>\r\n</tr>\r\n</thead>\r\n<tbody>\r\n<tr>\r\n<td>핵심 기술</td>\r\n<td>임베딩 + 벡터 DB + LLM</td>\r\n<td>RSS(XML) + 퍼지 검색(Fuse.js)</td>\r\n</tr>\r\n<tr>\r\n<td>검색 방식</td>\r\n<td>시맨틱 서치(의미가 가까운 것)</td>\r\n<td>글자/문자열 기반 매칭</td>\r\n</tr>\r\n<tr>\r\n<td>장점</td>\r\n<td>표현이 풍부, 맥락 이해</td>\r\n<td>빠르다, 명확하다, 폐쇄망에 쉽게 넣음</td>\r\n</tr>\r\n<tr>\r\n<td>단점</td>\r\n<td>느려질 수 있음, 임베딩 모델·벡터DB·LLM 운영비</td>\r\n<td>의미를 담지 못함(다국어·동의어 약함)</td>\r\n</tr>\r\n</tbody>\r\n</table></div>\r\n<blockquote class=\"callout callout-key\"><span class=\"callout-badge\">핵심</span>\r\n<p>★ <strong>공공·실무에선 \"명확한 게 중요\"할 때가 많다.</strong> 의미를 두루뭉술 담는 것보다, 한글 파일 안에 적힌 그대로(예: \"김태우\"라는 글자) 빠르고 정확히 뽑는 게 더 맞는 상황이 있다. 그래서 애매함(fuzzy)을 다루는 기술인데도 결과는 명확하게 떨어지는, 역설적인 조합이다.</p>\r\n</blockquote>\r\n<h2 id=\"rss-fusejs-bm25\">쓰인 부품 — RSS, Fuse.js(퍼지 검색), BM25, 레벤슈타인</h2>\r\n<ul>\r\n<li><strong>RSS</strong> — 블로그·뉴스 같은 데서 콘텐츠를 XML 형태로 받아오는 오래된 표준. 여기선 데이터 참조 통로로 썼다.</li>\r\n<li><strong>Fuse.js</strong> — \"Lightweight Fuzzy Search\", 자바스크립트 라이브러리. npm으로 설치한다. <strong>퍼지(fuzzy)</strong> = \"이것도 저것도 아닌\" 모호한 정도를 점수로 재는 기법이라, 오타나 부분 일치도 잡아준다.</li>\r\n<li><strong>레벤슈타인 거리(Levenshtein distance)</strong> — 문자열 두 개가 얼마나 다른지(몇 글자 바꿔야 같아지는지)를 재는 아주 고전적인 방식. 퍼지 검색의 바탕에 깔린다.</li>\r\n<li><strong>BM25</strong> — 검색 랭킹에서 유명한 룰 기반 알고리즘. 이것도 의미 모델 없이 동작.</li>\r\n</ul>\r\n<div class=\"codewrap\"><div class=\"codebar\"><span class=\"codelang\">Shell</span><button class=\"copybtn\" type=\"button\">복사</button></div><pre><code class=\"language-bash\">npm install fuse.js\r\n</code></pre></div>\r\n<div class=\"codewrap\"><div class=\"codebar\"><span class=\"codelang\">JavaScript</span><button class=\"copybtn\" type=\"button\">복사</button></div><pre><code class=\"language-js\">// 최소 예시 — 이름/경력 안에서 오타까지 감안해 검색\r\nimport Fuse from \"fuse.js\";\r\nconst people = [{ name: \"김태우\", career: \"AI 프랙티셔너\" }, /* ... */];\r\nconst fuse = new Fuse(people, { keys: [\"name\", \"career\"], threshold: 0.4 }); // threshold↑ = 더 느슨\r\nconst hits = fuse.search(\"김대우\"); // 오타여도 \"김태우\"가 잡힘 (fuzzy)\r\n</code></pre></div>\r\n<blockquote class=\"callout callout-add\"><span class=\"callout-badge\">보강</span>\r\n<p>보강 — <strong>이게 왜 폐쇄망에 강하냐.</strong> Fuse.js·BM25·레벤슈타인은 전부 룰 기반이라 외부 AI API가 필요 없다. 파이썬/JS 라이브러리 한두 개로 패키징해 인터넷 없는 사내망에 넣어도 그대로 돈다. 보안 심사를 통과하기도 쉽다. (의미 기반 RAG는 임베딩 모델·LLM 호출 때문에 통신이 필요해 이 점에서 불리하다.)</p>\r\n</blockquote>\r\n<hr/>\r\n<h1 class=\"modhead\" data-full=\"2. 트렌드를 누구보다 빨리 캐치하는 법\" id=\"2\">2. 트렌드를 누구보다 빨리 캐치하는 법</h1>\r\n<p>AI는 교과서가 없고 매일 쏟아진다. 강사가 쓰는 \"비밀 장소\"들을 공유했다.</p>\r\n<h2 id=\"ai-rss\">AI 타임즈 + RSS로 자동 수집</h2>\r\n<ul>\r\n<li><strong>AI 타임즈(AI Times)</strong> — 국내 기준 AI 소식이 가장 빠른 신문. 해외 모델 출시도 유튜브보다 먼저 뜬다. 브라우저 시작 페이지로 걸어두면 하루 한 번은 보게 된다는 게 팁.</li>\r\n<li><strong>RSS.app</strong> — 아무 사이트(심지어 스레드 같은 SNS)나 주소를 넣으면 RSS(XML) 피드로 <strong>래핑(wrapping)</strong>해주는 서비스. 이걸로 최신 글을 자동으로 땡겨와 나만의 채팅/이메일/슬랙으로 받아볼 수 있다.</li>\r\n<li><strong>Slack 자동 수집</strong> — 기업들은 유명 IT 기업 테크블로그들의 RSS를 한 채널에 몰아넣어 두고, 쉴 때 한 번씩 본다. \"자동화 + API 오케스트레이션\"만 잘해도 이런 트렌드 파이프라인이 만들어진다.</li>\r\n</ul>\r\n<blockquote class=\"callout callout-add\"><span class=\"callout-badge\">보강</span>\r\n<p>보강 — <strong>'오픈AI 초이'.</strong> 강사가 강력 추천한 스레드(Threads) 계정. 프로필이 강아지 사진인 익명 계정인데, 최신 AI 소식을 하루 5~10개씩 GIF까지 붙여 뿌린다. 스레드는 메타(인스타그램 회사)가 만든 글 중심 SNS(옛 트위터/X 대항마)이고, 국내에선 특이하게 반말 커뮤니티다. 이런 개인 계정이 공식 신문보다 빠를 때가 많다는 게 포인트.</p>\r\n</blockquote>\r\n<h2 id=\"_1\">\"데이터를 어떻게 합법적으로 모으나\" — 토스 페이스페이 사례</h2>\r\n<p>기술 자체보다 <strong>기획 한 번이 문제를 푼 사례</strong>로 소개됐다. 토스(Toss)가 <strong>페이스페이(face pay, 얼굴로 결제)</strong>를 밀면서 결제 단말기 시장을 노리는데, 여기 필요한 건 얼굴 인식(<strong>facial recognition</strong>) 모델. 문제는 \"수많은 사람 얼굴 데이터를 어떻게 합법적으로 구하나\"다.</p>\r\n<ul>\r\n<li>보통은 개인정보 동의 문제로 막힌다.</li>\r\n<li>토스(로 알려진 방식)는 <strong>대형 콘서트 입장 시 암표(부정 입장) 방지</strong>라는 목적을 걸고, 입장장에 얼굴 인식 카메라 + 카드 인증을 붙여 데이터를 합법적으로 모으고, 잘 마스킹해서 학습에 썼다는 식.</li>\r\n</ul>\r\n<blockquote class=\"callout callout-key\"><span class=\"callout-badge\">핵심</span>\r\n<p>★ 교훈: \"어떻게든 데이터를 구해서\"가 아니라, <strong>사람이 합법적으로 몰리는 상황을 사업으로 설계</strong>해 데이터 문제를 푼 것. 기술이 아니라 기획이 본질을 흔든 사례다.</p>\r\n</blockquote>\r\n<hr/>\r\n<h1 class=\"modhead\" data-full=\"3. 잠깐 개념 정리 — 트랜스포머와 GPT의 역사\" id=\"3-gpt\">3. 잠깐 개념 정리 — 트랜스포머와 GPT의 역사</h1>\r\n<p>\"거점 리더라면 GPT가 어디서 왔는지는 알고 가자\"며 강사가 짚은 부분. 초보자가 가장 헷갈리는 용어라 정리해둔다.</p>\r\n<div class=\"codewrap\"><div class=\"codebar\"><span class=\"codelang\">code</span><button class=\"copybtn\" type=\"button\">복사</button></div><pre class=\"mermaid\">flowchart TD\r\n  T[\"트랜스포머(Transformer)&lt;br/&gt;구글, 2017\"] --&gt; E[\"인코더(encoder)&lt;br/&gt;= 이해(NLU)\"]\r\n  T --&gt; D[\"디코더(decoder)&lt;br/&gt;= 생성(NLG)\"]\r\n  E --&gt; B[\"BERT 계열&lt;br/&gt;(이해 특화)\"]\r\n  D --&gt; G[\"GPT 계열&lt;br/&gt;(생성 특화) → ChatGPT\"]\r\n</pre></div>\r\n<blockquote class=\"callout callout-note\"><span class=\"callout-badge\">참고</span>\r\n<p>⚠ 정정 — <strong>NLP / NLU / NLG 정리.</strong> 강사가 디코더 영역을 한 번 \"NLP\"라고 불렀는데, 용어를 정확히 하면: <strong>NLP(자연어 처리)</strong>가 큰 우산이고, 그 아래 <strong>NLU(자연어 이해 — 입력을 해석)</strong>와 <strong>NLG(자연어 생성 — 출력을 만듦)</strong>가 있다. 트랜스포머의 인코더는 NLU 쪽, 디코더는 NLG 쪽에 대응한다고 보면 쉽다. ChatGPT는 디코더 계열(생성 특화).</p>\r\n<p>보강 — <strong>한 줄 히스토리.</strong> 트랜스포머 논문은 2017년 구글의 <em>\"Attention Is All You Need\"</em>. 정작 트랜스포머를 처음 만든 건 구글인데, 공개 정책 탓에 선점하지 못했고 오픈AI가 디코더 부분을 픽업해 키웠다. GPT-3까지는 주어진 지문 안에서만 잘 푸는 <strong>인컨텍스트 러닝(in-context learning)</strong> 수준이었는데, 여기에 <strong>RLHF(인간 피드백 기반 강화학습)</strong>를 얹은 GPT-3.5에서 체감 성능이 폭발했고, 그게 2022년 말 ChatGPT 공개로 이어졌다.</p>\r\n<p>⚠ 정정 — 강의 중 \"GPT 5.5 / 5.6\" 같은 버전 숫자가 나오는데, 이는 강사가 어림으로 던진 표기다. 모델 버전 숫자는 워낙 빨리·헷갈리게 바뀌니 정확한 제품명으로 외우기보다 <strong>\"최신 GPT-5 계열\"</strong> 정도로 기억해두는 게 안전하다.</p>\r\n</blockquote>\r\n<hr/>\r\n<h1 class=\"modhead\" data-full=\"4. SLM(소형 언어모델) 지형 — 숙제 리뷰\" id=\"4-slm\">4. SLM(소형 언어모델) 지형 — 숙제 리뷰</h1>\r\n<p>지난주 숙제가 \"SLM(Small Language Model, 소형 언어모델) 조사\"였다. 강사가 제출물을 모아 리뷰했다. 등장한 모델들:</p>\r\n<ul>\r\n<li><strong>Gemma 4</strong>(구글), <strong>Qwen3 / Qwen2.5</strong>(알리바바) — 최신·인기 라인</li>\r\n<li><strong>Mistral</strong>(프랑스), <strong>Granite</strong>(IBM), <strong>DeepSeek-OCR</strong>(중국)</li>\r\n<li>국산: <strong>EXAONE</strong>(LG), <strong>Kanana</strong>(카카오), <strong>42dot</strong>(현대차그룹 — 강사가 의외라고 평한 모델)</li>\r\n<li><strong>OpenAI Privacy Filter</strong> (← STT가 \"Owl/오프네일\"로 잘못 들은 그 모델)</li>\r\n</ul>\r\n<blockquote class=\"callout callout-warn\"><span class=\"callout-badge\">주의</span>\r\n<p>보강 — <strong>'Owl / 오프네일 프라이버시 필터'의 정체 = OpenAI Privacy Filter.</strong> STT가 \"OpenAI\"를 \"오프네일/Owl\"로 잘못 들은 것이고, 실제 모델명은 <strong>OpenAI Privacy Filter</strong>다(2026년 4월 공개, 오픈소스). <strong>1.5B 파라미터(활성 50M)의 양방향 토큰 분류(token classification) 모델</strong>로, 텍스트를 한 번에 훑어 이름·주소·이메일·전화·URL·날짜·계좌·비밀번호 8개 범주의 개인정보(PII)를 찾아 가린다. 강사의 질문(\"임베딩 직전이냐 후냐, 분류 모델이냐 회귀 모델이냐\")에 대한 답: <strong>사용자가 입력하자마자 도는 분류(classification) 모델</strong>이고, 클라우드 LLM에 보내기 <strong>전 단계</strong>에 두어 개인정보가 밖으로 나가기 전 로컬에서 먼저 마스킹한다. 그래서 <strong>온프레미스(내 노트북/사내 서버) 구동</strong>이 핵심 가치다. (검색 보강: openai.com/index/introducing-openai-privacy-filter, Hugging Face <code>openai/privacy-filter</code>)</p>\r\n<p>★ <strong>초보자 교훈 — AI의 환각(hallucination).</strong> 강사가 이 모델을 Claude에게 물었더니 \"그런 모델 없습니다\"라고 답했다고 한다. 하지만 실제로 존재한다. <strong>LLM은 자기 학습 시점 이후이거나 모르는 것을 종종 단정적으로 '없다'고 지어낸다(환각).</strong> \"AI가 아니라고 했으니 없는 거겠지\"라고 믿지 말고, 한 번 더 직접 확인하는 습관이 필요하다.</p>\r\n<p>보강 — <strong>이 작은 모델들이 왜 중요한가.</strong> Qwen2.5급 소형 모델은 GPU 없이 <strong>CPU(우리 PC)에서도 돌아간다.</strong> 오픈웨이트(open-weight)라 <strong>허깅페이스(Hugging Face)</strong>에서 누구나 받아 폐쇄망에 넣어 쓸 수 있다. 로컬 구동이 목적이면 <strong>올라마(Ollama)</strong> 같은 도구로 사내망에 올려 서빙하는 게 표준적인 출발점이다.</p>\r\n</blockquote>\r\n<hr/>\r\n<h1 class=\"modhead\" data-full=\"5. 실습 — 개발 환경부터 배포까지 풀 사이클\" id=\"5\">5. 실습 — 개발 환경부터 배포까지 풀 사이클</h1>\r\n<p>강의의 첫 손풀기 실습. <strong>VS Code + opencode + OpenRouter</strong>로 코딩 환경을 만들고 → 계산기를 만들어 → EXE/웹으로 배포하는 한 바퀴.</p>\r\n<h2 id=\"5-1-3\">5-1. 개발 환경 3종 세트</h2>\r\n<div class=\"codewrap\"><div class=\"codebar\"><span class=\"codelang\">code</span><button class=\"copybtn\" type=\"button\">복사</button></div><pre class=\"mermaid\">flowchart LR\r\n  V[\"VS Code&lt;br/&gt;(IDE)\"] --&gt; O[\"opencode&lt;br/&gt;(터미널 코딩 에이전트)\"]\r\n  O --&gt; R[\"OpenRouter&lt;br/&gt;(모델 공급자)\"]\r\n  R --&gt; M[\"여러 LLM을&lt;br/&gt;하나의 창구로 호출\"]\r\n</pre></div>\r\n<ul>\r\n<li><strong>VS Code</strong> — 코드 편집기(IDE). 커서(Cursor)의 근간이기도 하다. <a href=\"https://code.visualstudio.com\">code.visualstudio.com</a>에서 설치.</li>\r\n<li><strong>opencode</strong> — 터미널에서 도는 오픈소스 AI 코딩 에이전트. VS Code 안 터미널에 띄워 쓴다.</li>\r\n<li><strong>OpenRouter</strong> — 여러 AI 모델을 <strong>하나의 API 창구</strong>로 묶어주는 모델 공급자. 회사에 배치할 때도 모델 교체가 쉬워진다.</li>\r\n</ul>\r\n<p>실제 설치 순서(강사가 \"힌트는 Node.js\"라고만 하고 넘어간 부분을 채움):</p>\r\n<div class=\"codewrap\"><div class=\"codebar\"><span class=\"codelang\">Shell</span><button class=\"copybtn\" type=\"button\">복사</button></div><pre><code class=\"language-bash\"># 1) Node.js 18+ 설치 (https://nodejs.org) — opencode를 깔기 위한 런타임 + npm 제공\r\nnode -v                       # v18 이상인지 확인\r\n\r\n# 2) opencode 전역 설치  (npm 패키지명은 opencode가 아니라 opencode-ai!)\r\nnpm install -g opencode-ai\r\n\r\n# 3) 프로젝트 폴더에서 실행\r\nopencode\r\n\r\n# 4) OpenRouter 연결 — opencode 안에서\r\n/connect                      # 안내에 따라 OpenRouter API 키 붙여넣기\r\n#   또는 환경변수로 (Windows, 새 터미널부터 적용)\r\nsetx OPENROUTER_API_KEY \"sk-or-...\"\r\n\r\n# 5) 모델 바꾸기 — opencode 안에서\r\n/models                       # 목록에서 원하는 모델 선택\r\n</code></pre></div>\r\n<blockquote class=\"callout callout-note\"><span class=\"callout-badge\">참고</span>\r\n<p>⚠ 정정 — 강사는 <em>\"Node.js를 깔면 리눅스 환경이 같이 깔린다\"</em>고 했는데, 정확히는 아니다. <strong>Node.js는 opencode를 설치·구동하는 런타임(과 npm)을 줄 뿐, 리눅스를 설치해주지 않는다.</strong> opencode는 Windows의 PowerShell에서도 동작하지만, 공식 문서는 호환성 문제를 줄이려면 <strong>WSL(Windows Subsystem for Linux)</strong>에서 쓰길 권장한다. 강사가 느낀 \"리눅스 같다\"는 인상은 유닉스 셸/WSL 위에서 돌 때의 경험으로 보인다. (검색 보강: opencode.ai 공식 문서, OpenRouter의 opencode 연동 가이드)</p>\r\n<p>보강 — 코딩 에이전트엔 보통 <strong>Plan 모드(대화·계획)</strong>와 <strong>Build 모드(실제 코딩)</strong>가 있다. Plan에서 무엇을 할지 합의하고 Build로 넘기는 흐름은 거의 모든 코딩 에이전트(Claude Code, Codex 등)에 공통이다.</p>\r\n</blockquote>\r\n<h2 id=\"5-2-exe-github-pages\">5-2. 계산기 → EXE → 웹 → GitHub Pages 배포</h2>\r\n<p>무료 모델(느림)로 시작해도 되지만, 외부 패키지 없이 <strong>파이썬 내장 함수</strong>만으로 간단한 계산기/날짜계산기를 만들게 했다. 그다음 두 갈래로 배포.</p>\r\n<p><strong>(A) EXE로 묶기 — PyInstaller</strong></p>\r\n<div class=\"codewrap\"><div class=\"codebar\"><span class=\"codelang\">Shell</span><button class=\"copybtn\" type=\"button\">복사</button></div><pre><code class=\"language-bash\">pip install pyinstaller\r\npyinstaller --onefile --noconsole calculator.py   # 단일 .exe, --noconsole은 콘솔창 숨김(GUI용)\r\n# 결과물: dist/calculator.exe  → 탐색기에서 더블클릭 실행\r\n</code></pre></div>\r\n<p><strong>(B) 웹으로 띄우기 — Flask (127.0.0.1:5000)</strong></p>\r\n<p>강사 화면에 뜬 <code>127.0.0.1:5000</code>은 Flask 기본 포트다. 최소 예시:</p>\r\n<div class=\"codewrap\"><div class=\"codebar\"><span class=\"codelang\">python</span><button class=\"copybtn\" type=\"button\">복사</button></div><pre><code class=\"language-python\"># app.py\r\nfrom flask import Flask, request, render_template_string\r\napp = Flask(__name__)\r\nPAGE = \"\"\"\r\n&lt;form method=post&gt;&lt;input name=expr value=\"{{expr}}\"&gt;&lt;button&gt;=&lt;/button&gt;&lt;/form&gt;\r\n&lt;p&gt;결과: {{result}}&lt;/p&gt;\r\n\"\"\"\r\n@app.route(\"/\", methods=[\"GET\", \"POST\"])\r\ndef index():\r\n    expr, result = \"\", \"\"\r\n    if request.method == \"POST\":\r\n        expr = request.form[\"expr\"]\r\n        try:\r\n            result = eval(expr)           # ⚠ 데모용. 실제 서비스면 eval 금지(보안)!\r\n        except Exception as e:\r\n            result = f\"오류: {e}\"\r\n    return render_template_string(PAGE, expr=expr, result=result)\r\nif __name__ == \"__main__\":\r\n    app.run(host=\"127.0.0.1\", port=5000)  # http://127.0.0.1:5000\r\n</code></pre></div>\r\n<blockquote class=\"callout callout-warn\"><span class=\"callout-badge\">주의</span>\r\n<p>⚠ 주의 — 위 <code>eval()</code>은 데모를 짧게 보이려 쓴 것. 사용자 입력을 그대로 <code>eval</code> 하면 임의 코드가 실행될 수 있어 <strong>실제 서비스에선 절대 금지</strong>다. 안전한 수식 파서를 쓰거나 연산을 직접 구현해야 한다.</p>\r\n</blockquote>\r\n<p><strong>(C) GitHub Pages로 무료 공개</strong></p>\r\n<p>프론트(HTML/CSS/JS)로 만든 정적 페이지는 GitHub Pages로 공짜 호스팅된다. 주소는 <code>username.github.io</code> 형태.</p>\r\n<div class=\"codewrap\"><div class=\"codebar\"><span class=\"codelang\">Shell</span><button class=\"copybtn\" type=\"button\">복사</button></div><pre><code class=\"language-bash\">git init &amp;&amp; git add . &amp;&amp; git commit -m \"calculator\"\r\ngit branch -M main\r\ngit remote add origin https://github.com/&lt;username&gt;/&lt;repo&gt;.git\r\ngit push -u origin main\r\n# GitHub → 레포 → Settings → Pages → Branch: main / (root) → Save\r\n# 몇 분 뒤  https://&lt;username&gt;.github.io/&lt;repo&gt;/  로 공개\r\n</code></pre></div>\r\n<blockquote class=\"callout callout-key\"><span class=\"callout-badge\">핵심</span>\r\n<p>★ 강사 의도: 대단한 걸 만드는 게 아니라 <strong>기획 → 코딩 → 테스트 → 배포의 풀 사이클을 MVP로 한 번 겪어보는 것</strong>. 환경 설정이 사람마다 달라 까다로운데, 그 까다로움을 직접 통과해보는 게 이 실습의 진짜 목적이다.</p>\r\n</blockquote>\r\n<h2 id=\"5-3-minimax-m2\">5-3. 모델 교체 — MiniMax M2</h2>\r\n<p>무료 모델은 응답이 느리니, OpenRouter에서 <strong>MiniMax M2</strong>(유료)로 바꿔 속도를 확보하는 실습.</p>\r\n<blockquote class=\"callout callout-add\"><span class=\"callout-badge\">보강</span>\r\n<p>보강 — <strong>MiniMax M2.</strong> 중국 MiniMax가 내놓은 오픈웨이트 모델로 코딩·에이전트 작업에 강한 편이라 무료 모델 대신 권한 것. 강사가 말한 \"(M2.5)\"는 곁가지 표기로 보이고 핵심 모델명은 MiniMax M2. 모델 바꾸는 명령(<code>/models</code>)을 모르면 AI에게 \"opencode에서 모델 바꾸는 법\" 물어보면 바로 알려준다.</p>\r\n</blockquote>\r\n<hr/>\r\n<h1 class=\"modhead\" data-full=\"6. ChatGPT 깊게 쓰기\" id=\"6-chatgpt\">6. ChatGPT 깊게 쓰기</h1>\r\n<p>\"고급 과정이니 기본 프롬프트는 건너뛰고\" 한 단계 위 기능들로 갔다.</p>\r\n<h2 id=\"meta-prompt\">메타 프롬프트(meta prompt)</h2>\r\n<p><strong>프롬프트를 위한 프롬프트.</strong> 내가 좋은 프롬프트를 직접 짜기 어려우니, \"이런 워크플로우/봇을 만들려는데 거기 맞는 최적의 프롬프트(시스템 프롬프트)를 네가 짜라\"고 AI에게 시키는 기법.</p>\r\n<blockquote class=\"callout callout-key\"><span class=\"callout-badge\">핵심</span>\r\n<p>★ 프레임워크적 사고와 궁합이 좋다. 마케팅의 3C, 시장성/수익성/경쟁/실행난이도 같은 <strong>틀</strong>을 많이 알수록, 그 틀을 메타 프롬프트에 넣어 결과를 빠르게 뽑는다. 컨설팅이 하던 \"프레임으로 사고 → 장표화\"를 AI로 가속하는 셈.</p>\r\n</blockquote>\r\n<h2 id=\"claude-in-excel-claude-for-financial-services\">Claude in Excel / Claude for Financial Services</h2>\r\n<blockquote class=\"callout callout-add\"><span class=\"callout-badge\">보강</span>\r\n<p>보강 — 둘 다 Anthropic의 실제 제품. <strong>Claude in Excel</strong>은 엑셀 안에서 Claude가 셀을 잡아 분석·작성해준다(Claude 프로 계정 연동, 애드인 설치). <strong>Claude for Financial Services</strong>는 밸류에이션·리서치 같은 금융 업무용 B2B 서비스다. 한글도 잘 처리한다.</p>\r\n</blockquote>\r\n<h2 id=\"svg-ppt\">SVG로 PPT 장표 자동화 (강사의 비밀 무기)</h2>\r\n<p>PPT를 AI로 만들 때 이미지로 뽑으면 수정이 안 돼 곤란한데, 강사가 찾은 해법이 <strong>SVG(벡터)로 렌더링해 뽑기</strong>다.</p>\r\n<ul>\r\n<li>SVG로 받으면 PPT에 넣고 <strong>우클릭 → 그룹 해제</strong>로 개체별 편집이 된다(이미지와 달리).</li>\r\n<li>강사 체감상 <strong>Claude가 SVG를 가장 안 깨지게</strong> 만든다(Gemini 등은 다운로드 후 깨지는 경우가 있었다고).</li>\r\n<li>프롬프트에 컨설팅식 약속을 녹인다: <strong>원페이지 원메시지</strong>, 명확한 <strong>거버닝 센텐스(governing sentence, 그 장표의 한 줄 핵심)</strong>, <strong>As-Is / To-Be</strong>, A4 가로 고정, \"반드시 SVG로, PPT에 넣어도 안 깨지게, 3장만\".</li>\r\n<li>컬러는 말로 하기보다 <strong>HEX 색상 코드/브랜드 팔레트</strong>를 직접 주면 잘 따른다. \"맥킨지/BCG 스타일로\" 같은 지시도 먹힌다.</li>\r\n</ul>\r\n<blockquote class=\"callout callout-add\"><span class=\"callout-badge\">보강</span>\r\n<p>보강 — <strong>plan and execution.</strong> 강사가 언급한 \"플랜 앤 익스큐션\"은 에이전트가 <strong>계획을 먼저 세우고(plan) → 사용자 승인 후 실행(execution)</strong>하는 구조. 요즘 거의 모든 에이전트 플랫폼(Claude, Codex 등)의 기본 동작이다. Claude의 승인 모드로 직접 체험해볼 수 있다.</p>\r\n</blockquote>\r\n<h2 id=\"_2\">코덱스 · 딥리서치 · 모델 티어</h2>\r\n<ul>\r\n<li><strong>코덱스(Codex)</strong> — ChatGPT의 코딩 에이전트. 내 GitHub과 연동해야 제 화면이 뜨고, 연동하면 코덱스가 직접 코딩하며 GitHub에 푸시한다.</li>\r\n<li><strong>딥리서치(Deep Research)</strong> — 한 주제를 <strong>멀티스텝으로 깊게 파고들어</strong> 보고서로 만들어주는 기능. 거의 모든 AI 서비스에 들어와 있다. \"활용 방안 5개\" 같은 식으로 시킨다.</li>\r\n<li><strong>모델 티어</strong> — 어느 서비스든 보통 <strong>소형(빠름) / 표준 / 리즈닝(추론, 깊게 생각)</strong> 으로 나뉜다. 예: Gemini의 Flash(소형) / Pro(표준) / 추론 모드. 차이는 모델 크기·레이어·학습 방식.</li>\r\n</ul>\r\n<h2 id=\"mermaid\">Mermaid로 다이어그램 그리기</h2>\r\n<p>ChatGPT가 플로우차트를 그릴 때 따르는 특정 문법이 <strong>머메이드(Mermaid)</strong>다. \"머메이드 문법으로 ○○를 N단계 플로우차트로 그려줘\"라고 시키면 코드로 그려준다.</p>\r\n<div class=\"codewrap\"><div class=\"codebar\"><span class=\"codelang\">text</span><button class=\"copybtn\" type=\"button\">복사</button></div><pre><code class=\"language-text\">flowchart TD\r\n  A[원료] --&gt; B[설계]\r\n  B --&gt; C[제조]\r\n  C --&gt; D[패키징]\r\n  D --&gt; E[유통]\r\n</code></pre></div>\r\n<ul>\r\n<li><strong>Mermaid Live Editor</strong>(<a href=\"https://mermaid.live\">mermaid.live</a>) — 문법을 붙여넣으면 바로 그려지는 무료 에디터.</li>\r\n<li>활용 팁: 내 하루 업무를 줄글 일기로 쭉 적고 \"머메이드로 내 업무 루틴 정리해줘\" 하면 깔끔한 흐름도가 나온다.</li>\r\n</ul>\r\n<blockquote class=\"callout callout-add\"><span class=\"callout-badge\">보강</span>\r\n<p>보강 — <strong>폐쇄망용 오프라인 Mermaid 에디터.</strong> 강사는 <code>mermaid.min.js</code> + <code>index.html</code>만으로 <strong>인터넷 없이 도는 머메이드 에디터</strong>를 바이브 코딩으로 만들어 썼다. 프론트엔드 기술이 좋아져서, 이런 도구는 잘 패키징하면 통신 없이도 사내에서 돌릴 수 있다.</p>\r\n</blockquote>\r\n<hr/>\r\n<h1 class=\"modhead\" data-full=\"7. MCP와 앱 커넥터 — 도구를 GPT에 붙이기\" id=\"7-mcp-gpt\">7. MCP와 앱 커넥터 — 도구를 GPT에 붙이기</h1>\r\n<p>ChatGPT의 <strong>앱(앱 커넥터)</strong> 기능으로 외부 서비스를 붙여 쓴다. 그 바탕 규약이 <strong>MCP(Model Context Protocol)</strong>다.</p>\r\n<h2 id=\"notion\">Notion 연동</h2>\r\n<p>ChatGPT 설정에서 노션 앱을 연결하면, ChatGPT 화면에서 노션을 직접 컨트롤할 수 있다.</p>\r\n<ul>\r\n<li>연결 후 채팅에서 \"더 보기\"에 노션이 잡히고, 노션 모드로 전환된다.</li>\r\n<li>예시 지시: <strong>\"노션 데이터베이스로 만들어서 AI 트렌드 팔로우할 사이트 100개 정리해줘\"</strong> → 단순 링크 모음이 아니라 카테고리·추천도·난이도·\"왜 봐야 하는지\"까지 속성(property)으로 채워 정리한다.</li>\r\n<li>같은 방식으로 Gmail·구글 캘린더 등 여러 개를 동시에 붙일 수 있다(\"하나씩 붙이면 멀티가 된다\" = MCP의 특징).</li>\r\n</ul>\r\n<div class=\"codewrap\"><div class=\"codebar\"><span class=\"codelang\">code</span><button class=\"copybtn\" type=\"button\">복사</button></div><pre class=\"mermaid\">flowchart LR\r\n  U[\"사용자\"] --&gt; C[\"ChatGPT (호스트)\"]\r\n  C --&gt; M{\"MCP / 커넥터\"}\r\n  M --&gt; N[\"Notion\"]\r\n  M --&gt; G[\"Gmail / 캘린더\"]\r\n  M --&gt; K[\"코리안로 AI&lt;br/&gt;(법령 MCP)\"]\r\n</pre></div>\r\n<h2 id=\"ai-mcp\">코리안로 AI — 한국 법령정보 MCP</h2>\r\n<p>수강생 중 한 분이 만든 <strong>한국 법령정보 MCP</strong>를 강사가 직접 붙여봤다. 예: \"법인세법 52조 부당행위계산의 부인\" 조회가 잘 됐다. (인증키 없이도 동작.)</p>\r\n<p>ChatGPT에 커스텀 MCP 서버를 붙이는 경로(강사가 \"숨어 있다\"고 한 부분):</p>\r\n<div class=\"codewrap\"><div class=\"codebar\"><span class=\"codelang\">text</span><button class=\"copybtn\" type=\"button\">복사</button></div><pre><code class=\"language-text\">계정 설정 → 앱(커넥터) → 고급 설정 → 개발자 모드 ON\r\n→ \"앱 만들기\" → MCP 서버 URL 입력 → (인증 없음 가능) → 만들기\r\n→ 채팅창 + 버튼에서 'coriain law(코리안로)' 선택해 사용\r\n</code></pre></div>\r\n<blockquote class=\"callout callout-warn\"><span class=\"callout-badge\">주의</span>\r\n<p>★ <strong>진짜 MCP가 동작했는지 구분법.</strong> 응답 중 <strong>\"도구 요청 / 도구 호출(tool call)\"</strong> 형식이 떠야 MCP가 실제로 동작한 것. 그게 없이 그냥 웹서치 결과를 긁어오면 MCP가 아니라 웹 검색이다.</p>\r\n<p>⚠ 주의 — \"MCP 쓰면 다 된다\"는 너무 선언적이다. 실제론 ① 그 DB가 MCP를 붙일 수 있는지 ② 권한(role)으로 접근되는지 ③ 외부에서 호출 가능한지 ④ 스키마(schema)가 맞는지를 하나하나 따져야 한다. <strong>기술만으로 밀면 헤매고, 도메인 전문가와 함께 업무를 정확히 알면 구조가 간결해진다.</strong></p>\r\n</blockquote>\r\n<hr/>\r\n<h1 class=\"modhead\" data-full=\"8. GPTs — 나만의 챗봇 만들기\" id=\"8-gpts\">8. GPTs — 나만의 챗봇 만들기</h1>\r\n<h2 id=\"gpts\">프로젝트 / GPTs와 '메모리 분리'</h2>\r\n<p>GPT의 <strong>프로젝트</strong> 또는 <strong>My GPT(GPTs)</strong>로 나만의 파일·프롬프트를 고정한 전용 봇을 만든다.</p>\r\n<blockquote class=\"callout callout-key\"><span class=\"callout-badge\">핵심</span>\r\n<p>★ 강사가 찾아낸 숨은 설정 — 프로젝트의 <strong>'설정(Settings)' → 메모리(memory)</strong>. 기본값이면 다른 대화 맥락이 섞여 들어와 봇이 이상해질 수 있다. 메모리를 이 프로젝트 안에서만 독립적으로 작동하게 분리하면 깔끔해진다. (이 설정이 깊이 숨어 있어 모르고 지나치기 쉽다.)</p>\r\n</blockquote>\r\n<p>GPTs 만들기 흐름: <code>GPT 탐색 → GPT 만들기 → Configure(구성)</code>에서 이름·설명·아이콘·시작 버튼(starter)·권장 모델·웹서치/캔버스/이미지 사용 여부를 세팅하고, 시스템 프롬프트를 넣는다. 이 시스템 프롬프트도 <strong>메타 프롬프트로 뽑으면</strong> 빠르다.</p>\r\n<h2 id=\"gpts-actions-api-open-meteo\">GPTs 작업(Actions) — 외부 API 연동 (Open-Meteo)</h2>\r\n<p><strong>Actions</strong>는 외부 API를 GPTs에 붙이는 기능. <strong>OpenAPI 스키마(schema)</strong>를 넣으면 GPT가 그 API를 호출한다. 강사는 인증 없이 쓰는 <strong>Open-Meteo</strong>(무료 날씨 API)로 시연했다.</p>\r\n<div class=\"codewrap\"><div class=\"codebar\"><span class=\"codelang\">Shell</span><button class=\"copybtn\" type=\"button\">복사</button></div><pre><code class=\"language-bash\"># Open-Meteo는 인증키 없이 바로 호출되는 무료 날씨 API\r\ncurl \"https://api.open-meteo.com/v1/forecast?latitude=37.57&amp;longitude=126.98&amp;current=temperature_2m\"\r\n</code></pre></div>\r\n<p>연동 경로: <code>Configure → Actions → New Action</code>에 OpenAPI 스키마 붙여넣기 → <code>Authentication: None</code>. 스키마는 직접 짜기 어려우니 <strong>GPT에게 \"Open-Meteo를 GPTs Action에 추가하게 스키마랑 인스트럭션 다 짜줘\"</strong>라고 시키면 된다.</p>\r\n<blockquote class=\"callout callout-add\"><span class=\"callout-badge\">보강</span>\r\n<p>⚠ 정정/보강 — 강사 화면에 뜬 빨간 에러 <em>\"...has unrecognized method ... skipping\"</em>는 <strong>스키마 문법이 GPTs가 요구하는 OpenAPI 3.x 규격과 안 맞을 때</strong> 나는 메시지다. 에러 문구를 그대로 GPT에 던져 \"이 에러가 난다, 고쳐줘\" 하면 대개 잡힌다. 한글 지명이 안 먹으면 영문 지명을 쓰거나, <strong>Geocoding API로 \"Seoul\"→위경도 변환 후 forecast</strong> 두 단계로 붙이면 안정적이다.</p>\r\n<p>보강 — 같은 방식으로 <strong>data.go.kr(공공데이터포털)</strong> API를 붙이면 공공정보를 GPT 안에서 바로 다룰 수 있다. 또 GPTs/Actions에는 <strong>스케줄링</strong>도 걸 수 있어(\"매일 9시에 트렌드 찾아와\") 정기 작업으로 만들 수 있다.</p>\r\n</blockquote>\r\n<hr/>\r\n<h1 class=\"modhead\" data-full=\"9. 구글 Gemini 생태계\" id=\"9-gemini\">9. 구글 Gemini 생태계</h1>\r\n<p>강사가 개인적으로 제일 많이 쓴다는 구글 쪽. 한 바퀴 훑었다.</p>\r\n<h2 id=\"gemini\">Gemini의 태생 — 멀티모달 + 자체 칩</h2>\r\n<blockquote class=\"callout callout-add\"><span class=\"callout-badge\">보강</span>\r\n<p>보강 — ChatGPT는 초기에 <strong>코드·영어 위주로 학습</strong>해 한국어가 약했다(지금은 학습량이 늘어 문제없음). 반면 <strong>Gemini는 태생이 멀티모달</strong> — 이미지 등 다른 데이터와 언어를 동시에 학습한다. 구글은 <strong>TPU 등 칩(하드웨어)을 직접 설계</strong>해 자기 하드웨어에 최적화한다. 초기 이름은 <strong>바드(Bard)</strong>였고, 출시 직후엔 평이 안 좋다가 빠르게 안정됐다.</p>\r\n</blockquote>\r\n<ul>\r\n<li><strong>Gems</strong> — GPTs와 같은 개념의 \"나만의 Gemini 봇\". <code>새 Gem</code>에서 프롬프트 세팅.</li>\r\n<li><strong>사주 봇 '폴춘테카' 일화</strong> — 강사가 즉석에서 상수학·종교 등을 섞은 \"사주 봐주는 Gem\"을 만들고, \"이거 사업 되겠다 → 이름 지어줘\"로 <em>폴춘테카(Fortuneteca?)</em>라는 이름까지 뽑은 사례. <strong>결과는 매번 다른 확률 모델이라 '잘 맞는다/안 맞는다'가 갈리는 건 사실 랜덤</strong>이라는 점도 같이 짚었다. (서비스 아이디어로서 \"고민·운세\" 영역의 수요가 있다는 관찰.)</li>\r\n</ul>\r\n<h2 id=\"notebooklm\">NotebookLM</h2>\r\n<p>왼쪽에 자료를 넣으면 가운데에서 요약해주는 직관적 도구. 웹서치·딥리서치도 붙어 있고, <strong>오디오(팟캐스트) 자동 생성</strong>이 유명하다.</p>\r\n<blockquote class=\"callout callout-add\"><span class=\"callout-badge\">보강</span>\r\n<p>보강 — 강사 코멘트: 팟캐스트 시장은 서양(스포티파이 등)에선 크지만 국내선 아직 약하다. 구글 같은 글로벌 기획팀은 <strong>\"한국인만을 위한 게 아니라 전 세계 페르소나\"</strong>를 기본 전제로(제로 베이스) 기획한다는 점이 한국 기획과의 차이.</p>\r\n</blockquote>\r\n<h2 id=\"vids\">슬라이드 · 마인드맵 · Vids</h2>\r\n<ul>\r\n<li><strong>구글 Vids</strong> — AI 기반 영상 제작/편집 도구(워크스페이스). 영상을 슬라이드처럼 다룬다.</li>\r\n<li>Gemini에서 <strong>구글 슬라이드/마인드맵/플래시카드/인포그래픽/데이터표(구글 시트)</strong>로 바로 뽑을 수 있다. 마인드맵은 연산이 가벼워 거의 즉시 나온다.</li>\r\n</ul>\r\n<h2 id=\"stitch-ai-studio\">기획→개발 한 번에 — Stitch → AI Studio → 배포</h2>\r\n<div class=\"codewrap\"><div class=\"codebar\"><span class=\"codelang\">code</span><button class=\"copybtn\" type=\"button\">복사</button></div><pre class=\"mermaid\">flowchart LR\r\n  S[\"Stitch&lt;br/&gt;(AI UI 디자인)\"] --&gt;|\"핸드오프(handoff)\"| A[\"AI Studio&lt;br/&gt;(Build = 개발)\"]\r\n  A --&gt; P[\"배포: AI Studio Publish&lt;br/&gt;또는 Vercel v0\"]\r\n</pre></div>\r\n<blockquote class=\"callout callout-add\"><span class=\"callout-badge\">보강</span>\r\n<p>보강 — <strong>구글 Stitch → AI Studio.</strong> Stitch는 구글의 AI UI 디자인 도구(피그마 대항마)로, 프롬프트로 화면 시안을 만들고 <strong>HTML+Tailwind CSS 코드</strong>로 내보내거나 Figma로 붙여넣을 수 있다. 거기서 'AI Studio로 내보내기'를 하면 구글 <strong>AI Studio의 Build</strong>가 그 시안을 받아 백엔드·API까지 붙여 동작 앱으로 만든다. 기획(Stitch)→개발(AI Studio)으로 바통을 넘기는 이 이음매가 <strong>핸드오프(handoff)</strong>. 마지막엔 AI Studio에서 URL 공개하거나 <strong>Vercel v0</strong>로 빼서 배포한다. (검색 보강: developers.googleblog.com Stitch 소개 / Stitch↔AI Studio 워크플로우)</p>\r\n<p>★ <strong>실전 팁 — AI Studio 무료 배포.</strong> 배포할 때 'Billing / Setup Billing'(결제 설정)으로 가면 안 된다. <strong>'Share'에서 비공개(reject) 버튼을 풀면 그냥 퍼블릭으로 공개</strong>된다(카드 등록 불필요). 설정이 숨어 있을 뿐이다.</p>\r\n</blockquote>\r\n<ul>\r\n<li><strong>구글 Flow</strong> — 구글 랩스의 동영상/이미지 생성 도구. 강사 활용 팁: <strong>PPT 커버 페이지에 짧은 동영상</strong>을 넣으면(\"계속 재생\" 체크) 주목도가 올라가 강의평이 좋아진다.</li>\r\n</ul>\r\n<hr/>\r\n<h1 class=\"modhead\" data-full=\"10. 바이브 코딩 — Lovable\" id=\"10-lovable\">10. 바이브 코딩 — Lovable</h1>\r\n<p>강사가 제일 많이 쓰는 바이브 코딩 플랫폼.</p>\r\n<blockquote class=\"callout callout-add\"><span class=\"callout-badge\">보강</span>\r\n<p>보강 — <strong>Lovable(러버블).</strong> 스웨덴 회사의 바이브 코딩 플랫폼. 프롬프트만으로 <strong>프론트 + 백엔드(기본 백엔드는 Supabase 연동)</strong>까지 붙은 웹앱을 만들어 실제 배포까지 한다. 무료는 하루 약 5프롬프트, 유료는 약 월 20달러.</p>\r\n</blockquote>\r\n<p>강사가 Lovable로 직접 만들어 쓰는 것들:\r\n- <strong>실시간 강의 인터랙션 보드</strong> — 로그인 없이 링크로 접속, 공지 띄우기, <strong>무기명(익명) 채팅</strong>, <strong>실시간 투표(\"이해하셨나요?\")</strong>, 동시 200명까지 테스트. (조용한 정서의 청중과 강사 사이 \"중간 지대\"를 만든 도구.)\r\n- <strong>데이터 배포 플랫폼</strong> — 수강생에게 API 키를 발급해 중앙에서 데이터를 받아가게.\r\n- <strong>주식 백테스팅</strong> — <strong>yfinance</strong> 연동으로 롱숏 트레이딩 백테스트.</p>\r\n<blockquote class=\"callout callout-warn\"><span class=\"callout-badge\">주의</span>\r\n<p>⚠ 주의 — <strong>데이터 주권.</strong> 수강생 질문대로 Lovable+Supabase는 <strong>데이터가 외부(클라우드)에 저장</strong>된다. 데이터 주권·보안이 중요한 공공/민감 업무라면 어디에 데이터가 쌓이는지 반드시 확인하고 써야 한다.</p>\r\n<p>보강 — <strong>증권 자동매매 API.</strong> 한국투자증권·하나투자증권은 오픈 API가 잘 돼 있어, <strong>API 키만 발급받으면(이 발급 과정이 제일 번거롭다) 조회는 물론 매수·매도까지 코드로 가능</strong>. 강사는 100만 원 넣고 자동매매를 돌려 약 3만 원 수익을 봤다는 일화. 취미·학습용으로 권함.</p>\r\n<p>★ 강사의 마무리 한 줄: <strong>\"요즘은 내가 필요한 걸 내가 만들어 쓰는 게 최고다.\"</strong> 일상/업무에서 겪는 작은 문제를 직접 짜서 풀어보는 것 — 그게 이 회차 전체의 결론이다.</p>\r\n</blockquote>\r\n<hr/>\r\n<h1 class=\"modhead\" data-full=\"부록 — 한눈에 보는 도구 맵\" id=\"_3\">부록 — 한눈에 보는 도구 맵</h1>\r\n<div class=\"tablescroll\"><table>\r\n<thead>\r\n<tr>\r\n<th>분류</th>\r\n<th>도구</th>\r\n<th>한 줄</th>\r\n</tr>\r\n</thead>\r\n<tbody>\r\n<tr>\r\n<td>코딩 환경</td>\r\n<td>VS Code, opencode, OpenRouter</td>\r\n<td>IDE + 터미널 에이전트 + 모델 창구</td>\r\n</tr>\r\n<tr>\r\n<td>배포</td>\r\n<td>PyInstaller, Flask, GitHub Pages</td>\r\n<td>EXE 묶기 / 로컬 웹 / 무료 정적 호스팅</td>\r\n</tr>\r\n<tr>\r\n<td>트렌드</td>\r\n<td>AI 타임즈, RSS.app, 스레드(오픈AI 초이), Slack</td>\r\n<td>최신 소식 자동 수집 파이프라인</td>\r\n</tr>\r\n<tr>\r\n<td>검색</td>\r\n<td>Fuse.js, BM25, 레벤슈타인</td>\r\n<td>LLM 없는 룰 기반 퍼지 검색</td>\r\n</tr>\r\n<tr>\r\n<td>문서</td>\r\n<td>Claude in Excel, SVG 장표, Mermaid</td>\r\n<td>분석·PPT·다이어그램 자동화</td>\r\n</tr>\r\n<tr>\r\n<td>연동</td>\r\n<td>MCP / 커넥터, GPTs Actions, Open-Meteo, data.go.kr</td>\r\n<td>외부 도구·API를 챗봇에 붙이기</td>\r\n</tr>\r\n<tr>\r\n<td>구글</td>\r\n<td>Gemini, Gems, NotebookLM, Vids, Stitch→AI Studio, Flow, v0</td>\r\n<td>기획→개발→배포 생태계</td>\r\n</tr>\r\n<tr>\r\n<td>바이브 코딩</td>\r\n<td>Lovable(+Supabase), yfinance, 증권 API</td>\r\n<td>프롬프트로 실제 서비스 만들기</td>\r\n</tr>\r\n<tr>\r\n<td>SLM/보안</td>\r\n<td>Qwen·Gemma·EXAONE·Kanana·42dot, OpenAI Privacy Filter, Ollama</td>\r\n<td>로컬·폐쇄망 구동, 개인정보 마스킹</td>\r\n</tr>\r\n</tbody>\r\n</table></div>\r\n<h2 id=\"_4\">검색 보강 출처</h2>\r\n<ul>\r\n<li>opencode 설치·OpenRouter 연동: opencode.ai 공식 문서, OpenRouter \"opencode integration\" 가이드</li>\r\n<li>OpenAI Privacy Filter(='Owl/오프네일'): openai.com/index/introducing-openai-privacy-filter, Hugging Face <code>openai/privacy-filter</code></li>\r\n<li>구글 Stitch → AI Studio 워크플로우: developers.googleblog.com \"Introducing Stitch\", Stitch↔AI Studio 디자인-투-코드 가이드</li>\r\n</ul>\r\n  </main>\r\n</div>\r\n\r\n<script src=\"https://cdnjs.cloudflare.com/ajax/libs/highlight.js/11.9.0/highlight.min.js\"><\/script>\r\n<script src=\"https://cdnjs.cloudflare.com/ajax/libs/highlight.js/11.9.0/languages/powershell.min.js\"><\/script>\r\n<script src=\"https://cdnjs.cloudflare.com/ajax/libs/highlight.js/11.9.0/languages/vbscript.min.js\"><\/script>\r\n<script src=\"https://cdnjs.cloudflare.com/ajax/libs/mermaid/10.9.1/mermaid.min.js\"><\/script>\r\n<script>\r\n// 주제 헤더 raw 텍스트를 data-full로 옮겨 ::after 표시\r\ndocument.querySelectorAll('h1.modhead').forEach(function(h){\r\n  h.setAttribute('data-full', h.textContent);\r\n});\r\n\r\n// highlight.js\r\nif(window.hljs){\r\n  document.querySelectorAll('.codewrap pre code').forEach(function(b){\r\n    try{hljs.highlightElement(b);}catch(e){}\r\n  });\r\n}\r\n\r\n// mermaid\r\nif(window.mermaid){\r\n  mermaid.initialize({\r\n    startOnLoad:true, theme:'base',\r\n    htmlLabels:false,\r\n    themeVariables:{\r\n      fontFamily:'-apple-system,Pretendard,\"Malgun Gothic\",sans-serif',\r\n      fontSize:'13px',\r\n      primaryColor:'#e6f4f1', primaryBorderColor:'#127c71', primaryTextColor:'#0c5249',\r\n      lineColor:'#9aa0a8', secondaryColor:'#f4f1ea', tertiaryColor:'#fbf1e4',\r\n      clusterBkg:'#f6f6f0', clusterBorder:'#cfd3cb'\r\n    },\r\n    flowchart:{curve:'basis', useMaxWidth:true, htmlLabels:false},\r\n    sequence:{useMaxWidth:true}\r\n  });\r\n}\r\n\r\n// 복사 버튼\r\ndocument.querySelectorAll('.copybtn').forEach(function(btn){\r\n  btn.addEventListener('click', function(){\r\n    var code = btn.closest('.codewrap').querySelector('pre code');\r\n    var txt = code ? code.innerText : '';\r\n    navigator.clipboard.writeText(txt).then(function(){\r\n      btn.textContent='복사됨'; btn.classList.add('ok');\r\n      setTimeout(function(){btn.textContent='복사'; btn.classList.remove('ok');},1400);\r\n    });\r\n  });\r\n});\r\n\r\n// 스크롤 스파이\r\nvar links = Array.from(document.querySelectorAll('#nav a'));\r\nvar map = {};\r\nlinks.forEach(function(a){ map[a.getAttribute('href').slice(1)] = a; });\r\nvar heads = Array.from(document.querySelectorAll('.main h1[id], .main h2[id]'));\r\nvar spy = new IntersectionObserver(function(entries){\r\n  entries.forEach(function(en){\r\n    if(en.isIntersecting){\r\n      links.forEach(function(l){l.classList.remove('active');});\r\n      var act = map[en.target.id];\r\n      if(act){act.classList.add('active');\r\n        act.scrollIntoView({block:'nearest'});}\r\n    }\r\n  });\r\n}, {rootMargin:'-10% 0px -75% 0px', threshold:0});\r\nheads.forEach(function(h){spy.observe(h);});\r\n\r\n// 모바일 사이드바\r\nvar side=document.getElementById('side'), scrim=document.getElementById('scrim'),\r\n    mb=document.getElementById('menubtn');\r\nfunction toggle(open){side.classList.toggle('open',open);scrim.classList.toggle('show',open);}\r\nif(mb){mb.addEventListener('click',function(){toggle(!side.classList.contains('open'));});}\r\nif(scrim){scrim.addEventListener('click',function(){toggle(false);});}\r\nlinks.forEach(function(a){a.addEventListener('click',function(){if(window.innerWidth<=880)toggle(false);});});\r\n<\/script>\r\n</body>\r\n</html>\r\n","3":"<!DOCTYPE html>\r\n<html lang=\"ko\">\r\n<head>\r\n<meta charset=\"utf-8\">\r\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\r\n<title>3회차 — AI 서비스 워크플로우: 도구를 레고처럼 조합하기</title>\r\n<link rel=\"preconnect\" href=\"https://cdnjs.cloudflare.com\">\r\n<link rel=\"stylesheet\" href=\"https://cdnjs.cloudflare.com/ajax/libs/highlight.js/11.9.0/styles/github.min.css\">\r\n<style>\r\n:root{\r\n  --bg:#fafaf6; --panel:#ffffff; --ink:#1b1e24; --ink-soft:#5a6069; --ink-faint:#8b919b;\r\n  --line:#e7e6df; --line-soft:#f0efe9;\r\n  --teal:#127c71; --teal-d:#0c5249; --teal-bg:#e6f4f1;\r\n  --amber:#b9722a; --amber-bg:#fbf1e4;\r\n  --red:#c0392b; --red-bg:#fbe9e7;\r\n  --code-bg:#f6f6f0;\r\n  --mono:ui-monospace,\"SF Mono\",\"Cascadia Code\",\"JetBrains Mono\",Consolas,monospace;\r\n  --sans:-apple-system,BlinkMacSystemFont,\"Pretendard\",\"Apple SD Gothic Neo\",\"Segoe UI\",\"Malgun Gothic\",sans-serif;\r\n  --rad:12px;\r\n}\r\n*{box-sizing:border-box}\r\nhtml{scroll-behavior:smooth}\r\n@media (prefers-reduced-motion:reduce){html{scroll-behavior:auto}}\r\nbody{margin:0;background:var(--bg);color:var(--ink);font-family:var(--sans);\r\n  font-size:16px;line-height:1.72;-webkit-font-smoothing:antialiased}\r\n\r\n/* layout */\r\n.shell{display:grid;grid-template-columns:300px minmax(0,1fr);max-width:1240px;margin:0 auto}\r\n.print-toc{display:none}\r\n.side{position:sticky;top:0;align-self:start;height:100vh;overflow-y:auto;\r\n  padding:30px 22px 60px;border-right:1px solid var(--line)}\r\n.main{min-width:0;padding:46px 60px 120px;max-width:880px}\r\n\r\n/* sidebar */\r\n.brand{font-family:var(--mono);font-size:11px;letter-spacing:.14em;text-transform:uppercase;\r\n  color:var(--teal);margin-bottom:6px}\r\n.brand-t{font-weight:700;font-size:17px;line-height:1.35;margin:0 0 4px}\r\n.brand-s{font-size:12.5px;color:var(--ink-faint);margin:0 0 24px;line-height:1.5}\r\nnav a{display:block;text-decoration:none;color:var(--ink-soft);border-left:2px solid transparent;\r\n  padding:3px 0 3px 12px;font-size:13.5px;transition:color .15s,border-color .15s}\r\nnav a:hover{color:var(--ink)}\r\nnav a.nav-h1{margin-top:16px;font-weight:700;color:var(--ink);font-size:13px;\r\n  font-family:var(--mono);letter-spacing:.02em}\r\nnav a.nav-h2{font-size:13px}\r\nnav a.active{color:var(--teal-d);border-left-color:var(--teal);font-weight:600}\r\n\r\n/* headings */\r\nh1.modhead{font-size:13px;font-family:var(--mono);letter-spacing:.06em;text-transform:uppercase;\r\n  color:var(--teal);margin:72px 0 0;padding-top:28px;border-top:2px solid var(--ink);\r\n  font-weight:700}\r\nh1.modhead::after{content:attr(data-full);display:block;font-family:var(--sans);\r\n  font-size:30px;letter-spacing:-.01em;text-transform:none;color:var(--ink);\r\n  margin-top:8px;font-weight:750;line-height:1.2}\r\nh1.modhead{font-size:0}            /* hide raw, show via ::after */\r\nh1.modhead.intro{font-size:13px}\r\nh2{font-size:21px;font-weight:720;letter-spacing:-.01em;margin:46px 0 14px;\r\n  padding-bottom:8px;border-bottom:1px solid var(--line)}\r\nh3{font-size:16.5px;font-weight:700;margin:32px 0 10px;color:var(--ink)}\r\nh2.starred,h3.starred{color:var(--teal-d)}\r\nh2.starred::before,h3.starred::before{content:\"★ \";color:var(--teal);font-size:.85em}\r\nh2.starred,h3.starred{}\r\n.main h1:first-of-type{margin-top:0}\r\n\r\np{margin:12px 0}\r\na{color:var(--teal-d)}\r\nstrong{font-weight:700;color:var(--ink)}\r\nul,ol{padding-left:22px;margin:12px 0}\r\nli{margin:5px 0}\r\nhr{border:none;border-top:1px solid var(--line);margin:40px 0}\r\n\r\n/* intro hero */\r\n.hero{background:linear-gradient(135deg,#0c5249,#127c71);color:#eafaf6;\r\n  border-radius:16px;padding:34px 36px;margin:0 0 14px}\r\n.hero .eyebrow{font-family:var(--mono);font-size:11px;letter-spacing:.16em;\r\n  text-transform:uppercase;color:#9fdfd2;margin-bottom:10px}\r\n.hero h1{font-size:32px;line-height:1.18;margin:0 0 12px;font-weight:780;letter-spacing:-.02em}\r\n.hero p{margin:0;color:#cfeee7;font-size:14.5px;line-height:1.6}\r\n\r\n/* tables */\r\ntable{width:100%;border-collapse:collapse;margin:18px 0;font-size:14px;\r\n  border:1px solid var(--line);border-radius:var(--rad);overflow:hidden}\r\nthead th{background:var(--teal-bg);color:var(--teal-d);text-align:left;\r\n  font-weight:700;padding:10px 13px;font-size:13px}\r\ntd{padding:10px 13px;border-top:1px solid var(--line-soft);vertical-align:top}\r\ntbody tr:nth-child(even){background:#fbfbf8}\r\n.tablescroll{overflow-x:auto}\r\n\r\n/* code */\r\n.codewrap{margin:16px 0;border:1px solid var(--line);border-radius:var(--rad);\r\n  overflow:hidden;background:var(--code-bg)}\r\n.codebar{display:flex;justify-content:space-between;align-items:center;\r\n  padding:7px 12px;background:#efeee7;border-bottom:1px solid var(--line)}\r\n.codelang{font-family:var(--mono);font-size:11px;letter-spacing:.08em;\r\n  text-transform:uppercase;color:var(--ink-faint);font-weight:600}\r\n.copybtn{font-family:var(--mono);font-size:11px;border:1px solid var(--line);\r\n  background:#fff;color:var(--ink-soft);padding:3px 11px;border-radius:6px;cursor:pointer;\r\n  transition:all .15s}\r\n.copybtn:hover{border-color:var(--teal);color:var(--teal-d)}\r\n.copybtn.ok{background:var(--teal);color:#fff;border-color:var(--teal)}\r\n.codewrap pre{margin:0;padding:0}\r\npre code,pre.hljs{display:block;padding:15px 16px;overflow-x:auto;\r\n  font-family:var(--mono);font-size:13px;line-height:1.6;background:var(--code-bg)!important}\r\n:not(pre)>code{font-family:var(--mono);font-size:.88em;background:#eeede6;\r\n  padding:1.5px 6px;border-radius:5px;color:var(--teal-d);white-space:nowrap}\r\n\r\n/* mermaid */\r\npre.mermaid{background:var(--panel);border:1px solid var(--line);border-radius:var(--rad);\r\n  padding:22px;margin:20px 0;text-align:center;overflow-x:auto;line-height:1.4}\r\n\r\n/* callouts */\r\n.callout{position:relative;margin:18px 0;padding:14px 18px 14px 18px;border-radius:10px;\r\n  border-left:4px solid var(--ink-faint);background:#f4f4ee;font-size:14.5px}\r\n.callout p{margin:8px 0}\r\n.callout p:first-of-type{margin-top:0}\r\n.callout p:last-child{margin-bottom:0}\r\n.callout-badge{display:inline-block;font-family:var(--mono);font-size:10.5px;\r\n  letter-spacing:.1em;text-transform:uppercase;font-weight:700;\r\n  padding:2px 9px;border-radius:20px;margin-bottom:8px}\r\n.callout-note{border-left-color:#9aa0a8;background:#f3f3ee}\r\n.callout-note .callout-badge{background:#e4e4dd;color:#5a6069}\r\n.callout-key{border-left-color:var(--teal);background:var(--teal-bg)}\r\n.callout-key .callout-badge{background:var(--teal);color:#fff}\r\n.callout-warn{border-left-color:var(--amber);background:var(--amber-bg)}\r\n.callout-warn .callout-badge{background:var(--amber);color:#fff}\r\n.callout-add{border-left-color:var(--teal-d);background:#e9f3f1}\r\n.callout-add .callout-badge{background:var(--teal-d);color:#fff}\r\n\r\n/* topbar (mobile) */\r\n.topbar{display:none}\r\n\r\n@media (max-width:880px){\r\n  .shell{grid-template-columns:1fr}\r\n  .side{position:fixed;z-index:40;top:0;left:0;width:84%;max-width:320px;height:100vh;\r\n    background:var(--panel);transform:translateX(-105%);transition:transform .25s;\r\n    box-shadow:0 0 40px rgba(0,0,0,.18)}\r\n  .side.open{transform:translateX(0)}\r\n  .main{padding:70px 22px 90px}\r\n  .topbar{display:flex;align-items:center;gap:12px;position:sticky;top:0;z-index:30;\r\n    background:rgba(250,250,246,.92);backdrop-filter:blur(8px);\r\n    padding:12px 18px;border-bottom:1px solid var(--line)}\r\n  .menubtn{font-family:var(--mono);font-size:13px;border:1px solid var(--line);\r\n    background:#fff;padding:6px 12px;border-radius:8px;cursor:pointer}\r\n  .topbar .tt{font-family:var(--mono);font-size:12px;color:var(--teal);letter-spacing:.05em}\r\n  .scrim{display:none;position:fixed;inset:0;background:rgba(0,0,0,.35);z-index:35}\r\n  .scrim.show{display:block}\r\n  h1.modhead::after{font-size:25px}\r\n  .hero h1{font-size:25px}\r\n  .main{max-width:100%}\r\n}\r\n\r\n/* ── 인쇄 / PDF 저장 (출력 시 목차 먼저 → 본문) ── */\r\n@media print{\r\n  @page{margin:14mm 12mm}\r\n  *{-webkit-print-color-adjust:exact;print-color-adjust:exact}\r\n  .topbar,.scrim,.menubtn,.copybtn{display:none!important}\r\n  .shell{display:block;max-width:none}\r\n  /* 화면용 사이드바는 인쇄에서 완전히 숨김 (변환 불안정 → 빈 페이지 방지) */\r\n  .side{display:none!important}\r\n  /* 인쇄 전용 목차: 본문 맨 앞 일반 블록으로 깔끔히 출력 후 페이지 넘김 */\r\n  .print-toc{display:block!important;break-after:page;page-break-after:always}\r\n  .print-toc .ptoc-title{font-size:19pt;font-weight:800;color:#0c5249;letter-spacing:-.01em;\r\n    margin:0 0 16px;padding-bottom:10px;border-bottom:2px solid #127c71}\r\n  .print-toc a{display:block;color:#1b1e24;text-decoration:none;padding:3px 0;font-size:11.5pt;border:none}\r\n  .print-toc a.nav-h1{margin-top:13px;font-weight:700;color:#0c5249;font-size:12.5pt}\r\n  .print-toc a.nav-h2{padding-left:16px;color:#3a3f47}\r\n  /* 본문 */\r\n  .main{padding:0;max-width:none}\r\n  body{font-size:10.5pt;line-height:1.5;background:#fff}\r\n  a{text-decoration:none;color:inherit}\r\n  .hero{break-inside:avoid;background:#fff!important;color:#1b1e24!important;\r\n    border:none;border-bottom:2px solid #127c71;border-radius:0;\r\n    padding:0 0 14px!important;margin:0 0 18px}\r\n  .hero .eyebrow{color:#127c71!important}\r\n  .hero h1{color:#0c5249!important}\r\n  .hero p{color:#444!important}\r\n  /* 주제 헤더가 페이지 맨 아래 외롭게 걸리지 않게만 (새 페이지 강제는 빼서 빈 페이지 방지) */\r\n  h1.modhead{break-after:avoid;page-break-after:avoid}\r\n  h2,h3{break-after:avoid;page-break-after:avoid}\r\n  /* 코드·콜아웃·표·다이어그램은 페이지 중간에서 잘리지 않게 */\r\n  .codewrap,.callout,pre.mermaid,.tablescroll,table{break-inside:avoid;page-break-inside:avoid}\r\n  pre code,pre.hljs{white-space:pre-wrap;word-break:break-word}\r\n  pre.mermaid{text-align:center;border:1px solid #ddd;padding:12px 8px;margin:14px auto}\r\n  pre.mermaid svg{max-width:100%!important;height:auto!important;\r\n    max-height:200mm!important;display:inline-block!important}\r\n  .codewrap{border-color:#ccc}\r\n}\r\n</style>\r\n</head>\r\n<body>\r\n<div class=\"topbar\">\r\n  <button class=\"menubtn\" id=\"menubtn\" aria-label=\"목차 열기\">☰ 목차</button>\r\n  <span class=\"tt\">강의노트 · 보강판</span>\r\n</div>\r\n<div class=\"scrim\" id=\"scrim\"></div>\r\n<div class=\"shell\">\r\n  <aside class=\"side\" id=\"side\">\r\n    <div class=\"brand\">강의노트 · 03회차</div>\r\n    <p class=\"brand-t\">3회차 — AI 서비스 워크플로우: 도구를 레고처럼 조합하기</p>\r\n    <p class=\"brand-s\">현장 강의 · 기술 보강판</p>\r\n    <nav id=\"nav\">\r\n<a class=\"nav-h1\" href=\"#_1\">들어가며 — 레고 블록 오케스트레이션</a>\r\n<a class=\"nav-h1\" href=\"#1\">1부 · 메타 프롬프트 — 프롬프트를 만드는 프롬프트</a>\r\n<a class=\"nav-h2\" href=\"#_2\">메타 프롬프트의 구조: 상황(업무·제약·목표)</a>\r\n<a class=\"nav-h2\" href=\"#pre-mortem-ai\">프리모텀(Pre-mortem) — AI의 &#x27;아첨&#x27;을 깨는 질문법</a>\r\n<a class=\"nav-h2\" href=\"#ai\">스텝 바이 스텝 — AI에 끌려가지 말고 리드하기</a>\r\n<a class=\"nav-h2\" href=\"#qa-ai\">Q&amp;amp;A 프롬프트 — AI가 먼저 객관식으로 물어보게</a>\r\n<a class=\"nav-h1\" href=\"#2-text-to-sql\">2부 · 데이터베이스와 Text-to-SQL (핵심 실습)</a>\r\n<a class=\"nav-h2\" href=\"#_3\">왜 데이터베이스인가 — 파이썬만으로 안 되는 이유</a>\r\n<a class=\"nav-h2\" href=\"#_4\">전체 워크플로우 한눈에</a>\r\n<a class=\"nav-h2\" href=\"#1-vba-csv\">1단계 · VBA로 CSV 메타데이터 모으기</a>\r\n<a class=\"nav-h2\" href=\"#2\">2단계 · 데이터 전처리 — 데이터가 거짓말할 때</a>\r\n<a class=\"nav-h2\" href=\"#3-sqlite-db-browser\">3단계 · SQLite + DB Browser 설치</a>\r\n<a class=\"nav-h2\" href=\"#4-db-csv\">4단계 · DB 만들고 CSV 임포트</a>\r\n<a class=\"nav-h2\" href=\"#5-ddl-text-to-sql\">5단계 · 테이블 정의서(DDL) → Text-to-SQL</a>\r\n<a class=\"nav-h2\" href=\"#6-sql\">6단계 · 윈도우 함수 — SQL 분석의 진짜 무기</a>\r\n<a class=\"nav-h2\" href=\"#7-sqlite\">7단계 · 주피터 노트북에서 SQLite 연결</a>\r\n<a class=\"nav-h2\" href=\"#_5\">보강 · 데이터베이스가 빠른 이유 — 메모리 계층과 캐싱</a>\r\n<a class=\"nav-h1\" href=\"#3-notebooklm\">3부 · 콘텐츠 제작 워크플로우 — NotebookLM 레고</a>\r\n<a class=\"nav-h2\" href=\"#notebooklm\">NotebookLM으로 카드뉴스·영상 기획</a>\r\n<a class=\"nav-h2\" href=\"#codia-ai-notebooklm-ppt\">Codia AI — NotebookLM 슬라이드를 &#x27;편집 가능한 PPT&#x27;로</a>\r\n<a class=\"nav-h1\" href=\"#4-geoseo-ai\">4부 · GEO/SEO — AI 시대의 검색 최적화</a>\r\n<a class=\"nav-h2\" href=\"#geo\">GEO란 — 검색 패러다임의 전환</a>\r\n<a class=\"nav-h2\" href=\"#lovable\">실습 · 기관 사이트 진단 → Lovable로 개선</a>\r\n<a class=\"nav-h1\" href=\"#5\">5부 · 콜센터 녹취 분석 — 음성 워크플로우</a>\r\n<a class=\"nav-h2\" href=\"#_6\">워크플로우 설계 (레고 블록)</a>\r\n<a class=\"nav-h2\" href=\"#_7\">실제 코드 골격</a>\r\n<a class=\"nav-h1\" href=\"#_8\">마무리 &amp;amp; 과제</a>\r\n<a class=\"nav-h1\" href=\"#_9\">부록 — 용어 사전 · 출처</a>\r\n<a class=\"nav-h2\" href=\"#_10\">용어 빠른 사전</a>\r\n<a class=\"nav-h2\" href=\"#_11\">검색으로 확인·보강한 출처</a>\r\n    </nav>\r\n  </aside>\r\n  <main class=\"main\" id=\"main\">\r\n<nav class=\"print-toc\">\r\n<div class=\"ptoc-title\">목차</div>\r\n<a class=\"nav-h1\" href=\"#_1\">들어가며 — 레고 블록 오케스트레이션</a>\r\n<a class=\"nav-h1\" href=\"#1\">1부 · 메타 프롬프트 — 프롬프트를 만드는 프롬프트</a>\r\n<a class=\"nav-h2\" href=\"#_2\">메타 프롬프트의 구조: 상황(업무·제약·목표)</a>\r\n<a class=\"nav-h2\" href=\"#pre-mortem-ai\">프리모텀(Pre-mortem) — AI의 &#x27;아첨&#x27;을 깨는 질문법</a>\r\n<a class=\"nav-h2\" href=\"#ai\">스텝 바이 스텝 — AI에 끌려가지 말고 리드하기</a>\r\n<a class=\"nav-h2\" href=\"#qa-ai\">Q&amp;amp;A 프롬프트 — AI가 먼저 객관식으로 물어보게</a>\r\n<a class=\"nav-h1\" href=\"#2-text-to-sql\">2부 · 데이터베이스와 Text-to-SQL (핵심 실습)</a>\r\n<a class=\"nav-h2\" href=\"#_3\">왜 데이터베이스인가 — 파이썬만으로 안 되는 이유</a>\r\n<a class=\"nav-h2\" href=\"#_4\">전체 워크플로우 한눈에</a>\r\n<a class=\"nav-h2\" href=\"#1-vba-csv\">1단계 · VBA로 CSV 메타데이터 모으기</a>\r\n<a class=\"nav-h2\" href=\"#2\">2단계 · 데이터 전처리 — 데이터가 거짓말할 때</a>\r\n<a class=\"nav-h2\" href=\"#3-sqlite-db-browser\">3단계 · SQLite + DB Browser 설치</a>\r\n<a class=\"nav-h2\" href=\"#4-db-csv\">4단계 · DB 만들고 CSV 임포트</a>\r\n<a class=\"nav-h2\" href=\"#5-ddl-text-to-sql\">5단계 · 테이블 정의서(DDL) → Text-to-SQL</a>\r\n<a class=\"nav-h2\" href=\"#6-sql\">6단계 · 윈도우 함수 — SQL 분석의 진짜 무기</a>\r\n<a class=\"nav-h2\" href=\"#7-sqlite\">7단계 · 주피터 노트북에서 SQLite 연결</a>\r\n<a class=\"nav-h2\" href=\"#_5\">보강 · 데이터베이스가 빠른 이유 — 메모리 계층과 캐싱</a>\r\n<a class=\"nav-h1\" href=\"#3-notebooklm\">3부 · 콘텐츠 제작 워크플로우 — NotebookLM 레고</a>\r\n<a class=\"nav-h2\" href=\"#notebooklm\">NotebookLM으로 카드뉴스·영상 기획</a>\r\n<a class=\"nav-h2\" href=\"#codia-ai-notebooklm-ppt\">Codia AI — NotebookLM 슬라이드를 &#x27;편집 가능한 PPT&#x27;로</a>\r\n<a class=\"nav-h1\" href=\"#4-geoseo-ai\">4부 · GEO/SEO — AI 시대의 검색 최적화</a>\r\n<a class=\"nav-h2\" href=\"#geo\">GEO란 — 검색 패러다임의 전환</a>\r\n<a class=\"nav-h2\" href=\"#lovable\">실습 · 기관 사이트 진단 → Lovable로 개선</a>\r\n<a class=\"nav-h1\" href=\"#5\">5부 · 콜센터 녹취 분석 — 음성 워크플로우</a>\r\n<a class=\"nav-h2\" href=\"#_6\">워크플로우 설계 (레고 블록)</a>\r\n<a class=\"nav-h2\" href=\"#_7\">실제 코드 골격</a>\r\n<a class=\"nav-h1\" href=\"#_8\">마무리 &amp;amp; 과제</a>\r\n<a class=\"nav-h1\" href=\"#_9\">부록 — 용어 사전 · 출처</a>\r\n<a class=\"nav-h2\" href=\"#_10\">용어 빠른 사전</a>\r\n<a class=\"nav-h2\" href=\"#_11\">검색으로 확인·보강한 출처</a>\r\n</nav>\r\n    <div class=\"hero\">\r\n      <div class=\"eyebrow\">Lecture Note · 기술 보강판</div>\r\n      <h1>3회차 — AI 서비스 워크플로우: 도구를 레고처럼 조합하기</h1>\r\n      <p>현장 강의를 기술적으로 보강한 학습 레퍼런스 — 강사의 의도는 살리고, 빠지거나 틀린 기술은 정확히 채웠습니다.</p>\r\n    </div>\r\n\r\n<p>이 강의 하나로 무엇을 할 수 있게 하려는가 →\r\n<strong>\"메타 프롬프트부터 데이터베이스·콘텐츠·검색·음성까지, 흩어진 AI 도구들을 '레고 블록'처럼 조합(오케스트레이션)해 실제 업무 워크플로우를 직접 짜는 것. 문법(how)은 AI가 해주니, 나는 '무엇을 왜(why·what)' 풀지에 집중한다.\"</strong></p>\r\n<blockquote class=\"callout callout-key\"><span class=\"callout-badge\">핵심</span>\r\n<p>★ 이번 회차는 신성진 강사의 7시간 실습 집약 세션이다(원래 제목 \"메타 프롬프트 설계와 AI 서비스 워크플로우, 오케스트레이션\"). 다섯 덩어리 — ① 메타 프롬프트 ② 데이터베이스·Text-to-SQL(가장 큰 실습) ③ NotebookLM 콘텐츠 제작 ④ GEO/SEO 진단 ⑤ 콜센터 녹취 분석 — 가 \"레고 블록 조합\"이라는 한 줄 태도로 꿰인다.</p>\r\n<p><strong>보강 안내</strong> — 강사가 화면으로 빠르게 지나간 설치·코드·SQL을 초보자가 따라 할 수 있게 <strong>실제 동작하는 명령어/코드로 채웠다.</strong> 불확실한 사실(프리모텀 근거·LLM 에스컬레이션 연구·GEO·아나콘다 라이선스)은 검색으로 확인해 <code>(검색 보강)</code>으로 표시하고 출처는 부록에. 운영성 멘트(점심·식당·버스·숙박·기차표·을지훈련 일정 등)는 노트에서 뺐고, 학습에 도움 되는 비유·일화·청중 질문은 살렸다.</p>\r\n</blockquote>\r\n<hr/>\r\n<h1 class=\"modhead\" data-full=\"들어가며 — 레고 블록 오케스트레이션\" id=\"_1\">들어가며 — 레고 블록 오케스트레이션</h1>\r\n<p>강의 전체를 관통하는 한 가지 그림. 세상에 AI 도구가 2만 8천 개가 넘는데, 이걸 <strong>난이도순으로 하나씩 정복</strong>하려 들지 말고 <strong>조합 가능한 부품</strong>으로 모으라는 것.</p>\r\n<div class=\"codewrap\"><div class=\"codebar\"><span class=\"codelang\">code</span><button class=\"copybtn\" type=\"button\">복사</button></div><pre class=\"mermaid\">flowchart LR\r\n  W[\"내가 풀 문제&lt;br/&gt;(why·what)\"] --&gt; O[\"도구 조합 설계&lt;br/&gt;(오케스트레이션)\"]\r\n  O --&gt; A[\"메타 프롬프트\"]\r\n  O --&gt; B[\"DB · SQL\"]\r\n  O --&gt; C[\"NotebookLM · Codia\"]\r\n  O --&gt; D[\"GEO/SEO · Lovable\"]\r\n  O --&gt; E[\"Whisper · Ollama\"]\r\n</pre></div>\r\n<blockquote class=\"callout callout-key\"><span class=\"callout-badge\">핵심</span>\r\n<p>★ 강사가 반복한 핵심: <strong>how(SQL 문법, 파이썬 코드)는 이제 AI가 다 해준다.</strong> 우리에게 남는 건 \"무엇을, 왜 분석·해결할 것인가\"라는 판단과, 도구를 엮어 워크플로우를 만드는 감각이다. 1회차의 <em>\"지식보다 태도\"</em>, <em>\"레고 블록\"</em> 메시지를 실습으로 옮긴 회차다.</p>\r\n</blockquote>\r\n<hr/>\r\n<h1 class=\"modhead\" data-full=\"1부 · 메타 프롬프트 — 프롬프트를 만드는 프롬프트\" id=\"1\">1부 · 메타 프롬프트 — 프롬프트를 만드는 프롬프트</h1>\r\n<p><strong>메타 프롬프트(meta prompt)</strong> = 프롬프트를 위한 프롬프트. 내가 직접 좋은 프롬프트를 쓰는 게 아니라, <em>\"내 업무는 이렇고 목표·제약은 이러니, 이걸 잘 처리하는 프롬프트를 만들어줘\"</em> 라고 시켜서 <strong>프롬프트 자체를 산출물로 받는</strong> 기법.</p>\r\n<h2 id=\"_2\">메타 프롬프트의 구조: 상황(업무·제약·목표)</h2>\r\n<div class=\"codewrap\"><div class=\"codebar\"><span class=\"codelang\">code</span><button class=\"copybtn\" type=\"button\">복사</button></div><pre class=\"mermaid\">flowchart LR\r\n  S[\"상황 기술&lt;br/&gt;업무 · 목표 · 제약\"] --&gt; R[\"'이걸 처리하는&lt;br/&gt;프롬프트를 만들어줘'\"]\r\n  R --&gt; P[\"완성된 프롬프트&lt;br/&gt;(few-shot·CoT 형태)\"]\r\n  P --&gt; T[\"튜닝 후 공유 뱅크&lt;br/&gt;(MD 파일 업로드)\"]\r\n</pre></div>\r\n<p>실습(워밍업)은 이랬다 — 내 업무로 메타 프롬프트를 만들고, <strong>모델 두 개(예: ChatGPT ↔ Claude/Gemini/Copilot)에 같은 요청을 넣어 교차 비교</strong>한 뒤, 더 나은 쪽을 골라 공유 폴더에 올려 <em>프롬프트 뱅크</em>를 쌓는 것.</p>\r\n<p>강사 예시:</p>\r\n<div class=\"codewrap\"><div class=\"codebar\"><span class=\"codelang\">text</span><button class=\"copybtn\" type=\"button\">복사</button></div><pre><code class=\"language-text\">나는 ○○구 교통정책과 주무관이고, 버스 노선 민원에 답변한다.\r\n[목표] 공문 형식의 민원 답변 1건\r\n[제약] 법령을 반드시 인용 / 추측·가정 금지 / 500자 이내\r\n이 업무를 처리하는 '시스템 프롬프트'를 만들어줘. (민원 내용을 넣으면 답변이 나오도록)\r\n</code></pre></div>\r\n<blockquote class=\"callout callout-add\"><span class=\"callout-badge\">보강</span>\r\n<p><strong>보강 — 같이 나온 용어 한 줄씩.</strong> <em>퓨샷(few-shot)</em> = 예시 몇 개를 같이 줘서 형식을 따라 하게 하는 것. <em>체인 오브 소트(Chain of Thought, CoT)</em> = \"단계적으로 생각해줘\"처럼 추론 과정을 펼치게 하는 것. 메타 프롬프트가 만들어주는 결과가 보통 이 형태로 나온다.</p>\r\n</blockquote>\r\n<h2 id=\"pre-mortem-ai\">프리모텀(Pre-mortem) — AI의 '아첨'을 깨는 질문법</h2>\r\n<p>강사가 가장 공들여 소개한 기법. ChatGPT·Gemini 같은 모델은 <strong>아첨(sycophancy)</strong> 경향이 있어 미래 계획을 물으면 장밋빛 답만 준다. 사람 뇌도 계획할 땐 전두엽이 희망 위주로 돌아 나쁜 시나리오를 잘 안 떠올린다.</p>\r\n<blockquote class=\"callout callout-warn\"><span class=\"callout-badge\">주의</span>\r\n<p>★ <strong>핵심 — 실패를 '이미 일어난 일'로 가정하라.</strong> \"이 축제 6개월 뒤 어떻게 될까?\"(미래형) 대신 <strong>\"이 축제를 열었는데 6개월 뒤 아무도 안 왔어. 그 이유는?\"</strong>(과거형)으로 물으면, AI가 약점(홍보 차별화 실패, 클라우드 비용 과다, 로그인 이탈 등)을 날카롭게 짚어낸다.</p>\r\n<p><strong>보강 (검색 보강) — 근거가 있는 기법이다.</strong> 프리모텀은 게리 클라인(Gary Klein)이 <em>Harvard Business Review</em> 2007년 9월호 \"Performing a Project Premortem\"에서 제시했다. 바탕 원리는 <strong>사전 부검적 통찰(prospective hindsight)</strong> — Mitchell·Russo·Pennington의 1989년 연구에서 \"이미 일어났다\"고 가정하면 원인을 정확히 짚는 능력이 <strong>약 30% 향상</strong>된다고 나왔다. 과신·집단사고를 깨는 효과도 있다.</p>\r\n<p>⚠ <strong>주의 — LLM의 호전성·아첨은 실제 위험이다.</strong> 강사가 든 \"10개 모델 중 9개가 '핵 버튼 눌러라'고 답했다\"는 일화는 과장이 아니다. 2024년 코넬 등 연구 <em>\"Escalation Risks from Language Models…\"</em> 에서 5개 LLM이 모의 워게임에서 갈등을 키웠고 GPT-4-Base는 평균 <strong>33%</strong> 확률로 핵공격을 실행했다(검색 보강). AI의 답을 그대로 믿지 말고 프리모텀처럼 <strong>반대로 캐묻는</strong> 습관이 필요하다.</p>\r\n</blockquote>\r\n<h2 id=\"ai\">스텝 바이 스텝 — AI에 끌려가지 말고 리드하기</h2>\r\n<p>모델을 고급(띵킹) 모드로 올리면 한 번에 봇물 터지듯 쏟아내서 리뷰를 못 하게 된다. 그래서 프롬프트에 <em>\"한 번에 다 쏟지 말고 단계별로 작성하고, 내가 OK 하면 다음으로\"</em> 를 넣는다.</p>\r\n<blockquote class=\"callout callout-add\"><span class=\"callout-badge\">보강</span>\r\n<p><strong>보강 — 주피터 노트북에서 특히 유용.</strong> 셀 단위로 코드를 받아 한 셀 실행 → 확인 → 다음 셀. 뒤(2부)에서 SQLite 연결 코드를 이렇게 셀 단위로 받는다. \"GPT한테 끌려가지 말고 내가 리드한다\"가 이 회차의 작업 습관.</p>\r\n</blockquote>\r\n<h2 id=\"qa-ai\">Q&amp;A 프롬프트 — AI가 먼저 객관식으로 물어보게</h2>\r\n<p>이미지 생성처럼 <em>무엇을 넣어야 잘 나오는지 내가 모를 때</em> 쓰는 기법. \"원샷\"으로 던지지 말고 AI와 주고받는다.</p>\r\n<div class=\"codewrap\"><div class=\"codebar\"><span class=\"codelang\">text</span><button class=\"copybtn\" type=\"button\">복사</button></div><pre><code class=\"language-text\">강의용 커버 이미지를 만들 건데 어떤 요소가 필요한지 잘 몰라.\r\n이미지를 잘 만드는 데 필요한 핵심 요소 5개를 '객관식'으로 나에게 하나씩 물어봐.\r\n내가 고르면 그 선택을 종합해 '이미지 생성 프롬프트'를 만들어줘.\r\n</code></pre></div>\r\n<blockquote class=\"callout callout-add\"><span class=\"callout-badge\">보강</span>\r\n<p><strong>보강 — 1회차 '메타 프롬프트'와 같은 뿌리.</strong> 1회차에서 본 \"AI가 객관식으로 먼저 질문하게 하기\"의 실전 버전이다. 이미지/영상 프롬프트는 모델이 영어로 뱉는 경우가 많은데(이미지 모델이 영어로 더 학습됨), 그대로 쓰면 더 잘 나온다.</p>\r\n</blockquote>\r\n<hr/>\r\n<h1 class=\"modhead\" data-full=\"2부 · 데이터베이스와 Text-to-SQL (핵심 실습)\" id=\"2-text-to-sql\">2부 · 데이터베이스와 Text-to-SQL (핵심 실습)</h1>\r\n<p>이번 회차의 절반. \"AI 시대에 DB가 왜 필요해?\"에서 출발해, <strong>CSV → 정제 → SQLite → AI로 SQL 생성 → 파이썬 분석</strong>까지 한 줄로 꿴다.</p>\r\n<h2 id=\"_3\">왜 데이터베이스인가 — 파이썬만으로 안 되는 이유</h2>\r\n<p>신입들이 자주 묻는다. \"그냥 파이썬으로 다 불러오면 되지 왜 DB를 써요?\" 강사의 답:</p>\r\n<div class=\"tablescroll\"><table>\r\n<thead>\r\n<tr>\r\n<th>관점</th>\r\n<th>파이썬(판다스)만</th>\r\n<th>데이터베이스(SQLite 등)</th>\r\n</tr>\r\n</thead>\r\n<tbody>\r\n<tr>\r\n<td>메모리</td>\r\n<td><code>read_csv</code>로 전부 메모리에 적재 → 큰 데이터면 <strong>Out of Memory</strong></td>\r\n<td>엔진이 메모리를 제어, 디스크로 스왑해서라도 결과를 냄</td>\r\n</tr>\r\n<tr>\r\n<td>신뢰성</td>\r\n<td>휘발성(메모리 기반)</td>\r\n<td>트랜잭션·무결성 보장 (은행 잔고가 OOM나면 안 되니까)</td>\r\n</tr>\r\n<tr>\r\n<td>용량</td>\r\n<td>PC 성능에 종속</td>\r\n<td>디스크 크기만큼, 사실상 무제한</td>\r\n</tr>\r\n<tr>\r\n<td>전처리</td>\r\n<td>레코드 커지면 느려짐</td>\r\n<td>옵티마이저로 필터·조인을 최적화</td>\r\n</tr>\r\n<tr>\r\n<td>재현성</td>\r\n<td>코드/환경 따라 달라질 수 있음</td>\r\n<td>같은 SQL → 같은 결과</td>\r\n</tr>\r\n</tbody>\r\n</table></div>\r\n<blockquote class=\"callout callout-key\"><span class=\"callout-badge\">핵심</span>\r\n<p>★ <strong>핵심 기준 — 107만 행.</strong> 엑셀이 보여줄 수 있는 최대 행은 1,048,576행(약 107만). 그 이상을 다룰 거라면 <strong>무조건 DB에 넣으라</strong>는 게 강사의 단언. 100만 건을 일일이 눈으로 볼 일은 없고, 결국 <em>필터링·통계·집계</em>만 쓰는데 그건 DB가 압도적으로 빠르고 가볍다.</p>\r\n<p><strong>보강 — DB 기술은 결국 두 가지: 잘 저장 + 잘 조회.</strong>\r\n- <em>옷장 비유</em>: 옷은 잘 넣었는데(저장) \"어느 서랍에 뒀더라\"가 안 떠오르면(조회 실패) 소용없다. 인감도장을 \"잘 뒀는데 어디 뒀지…\" 하며 한참 찾는 게 딱 그 경우.\r\n- <em>도서관 비유</em>: 제목을 알면 가나다순(=인덱스)으로 금방 찾지만, 제목을 모르면 처음부터 끝까지 다 봐야 한다(=풀 스캔). <strong>인덱스(Index)</strong> 는 원하는 값을 빨리 찾기 위한 저장 기술이다.</p>\r\n</blockquote>\r\n<h2 id=\"_4\">전체 워크플로우 한눈에</h2>\r\n<div class=\"codewrap\"><div class=\"codebar\"><span class=\"codelang\">code</span><button class=\"copybtn\" type=\"button\">복사</button></div><pre class=\"mermaid\">flowchart LR\r\n  CSV[\"공공 CSV 여러 개\"] --&gt; VBA[\"① VBA로&lt;br/&gt;메타데이터 점검\"]\r\n  VBA --&gt; FIX[\"② 전처리&lt;br/&gt;(단위·컬럼명 통일)\"]\r\n  FIX --&gt; IMP[\"③ SQLite 임포트\"]\r\n  IMP --&gt; DDL[\"④ 테이블 정의서(DDL)\"]\r\n  DDL --&gt; T2S[\"⑤ GPT Text-to-SQL\"]\r\n  T2S --&gt; RUN[\"⑥ DB Browser 실행\"]\r\n  RUN --&gt; PY[\"⑦ 주피터 read_sql → df\"]\r\n</pre></div>\r\n<h2 id=\"1-vba-csv\">1단계 · VBA로 CSV 메타데이터 모으기</h2>\r\n<p>연도별로 쪼개진 CSV가 6개(혹은 300개)일 때, <strong>각 파일의 헤더 + 데이터 5행만 모아 한 엑셀로</strong> 만들어 한눈에 비교한다(= 분석 전 \"내 데이터가 어떻게 생겼나\"를 아는 메타인지).</p>\r\n<p>강사가 GPT에 넣은 프롬프트:</p>\r\n<div class=\"codewrap\"><div class=\"codebar\"><span class=\"codelang\">text</span><button class=\"copybtn\" type=\"button\">복사</button></div><pre><code class=\"language-text\">특정 폴더의 모든 CSV를 읽어서, 첫 행은 컬럼 이름으로 하고,\r\n각 CSV의 1~6행 데이터를 새 metadata.xlsx 파일의 '파일별 시트'로 저장하는 VBA를 작성해줘.\r\n</code></pre></div>\r\n<p>실행 방법(엑셀): <strong>Alt+F11</strong>(VBA 편집기) → 왼쪽에서 마우스 오른쪽 → <strong>삽입 → 모듈</strong> → 코드 붙여넣기 → <strong>F5(실행)</strong>.\r\n- 맥: <strong>Fn + Option + F11</strong>, 또는 메뉴 <em>도구 → 매크로 → Visual Basic Editor</em>.</p>\r\n<p>GPT가 만들어 줄 VBA는 대략 이런 모양이다(동작 확인용, 단순 CSV 기준):</p>\r\n<div class=\"codewrap\"><div class=\"codebar\"><span class=\"codelang\">VBA</span><button class=\"copybtn\" type=\"button\">복사</button></div><pre><code class=\"language-vbscript\">Sub CSV메타데이터_모으기()\r\n    Dim folder As String, f As String\r\n    Dim wbOut As Workbook, ws As Worksheet\r\n    Dim fso As Object, ts As Object\r\n    Dim i As Long, j As Long, cols() As String\r\n\r\n    With Application.FileDialog(msoFileDialogFolderPicker)\r\n        If .Show &lt;&gt; -1 Then Exit Sub\r\n        folder = .SelectedItems(1)\r\n    End With\r\n\r\n    Set wbOut = Workbooks.Add\r\n    Set fso = CreateObject(\"Scripting.FileSystemObject\")\r\n\r\n    f = Dir(folder &amp; \"\\*.csv\")\r\n    Do While f &lt;&gt; \"\"\r\n        Set ws = wbOut.Sheets.Add\r\n        ws.Name = Left(fso.GetBaseName(f), 31)          ' 시트명 31자 제한\r\n        Set ts = fso.OpenTextFile(folder &amp; \"\\\" &amp; f, 1, False, -2)  ' -2: 시스템 기본 인코딩\r\n        i = 1\r\n        Do While Not ts.AtEndOfStream And i &lt;= 6        ' 헤더 + 5행\r\n            cols = Split(ts.ReadLine, \",\")\r\n            For j = 0 To UBound(cols)\r\n                ws.Cells(i, j + 1).Value = cols(j)\r\n            Next j\r\n            i = i + 1\r\n        Loop\r\n        ts.Close\r\n        f = Dir\r\n    Loop\r\n    MsgBox \"완료: \" &amp; (wbOut.Sheets.Count - 1) &amp; \"개 CSV 처리\"\r\nEnd Sub\r\n</code></pre></div>\r\n<blockquote class=\"callout callout-warn\"><span class=\"callout-badge\">주의</span>\r\n<p>⚠ <strong>주의 · 함정 세 가지.</strong> ① 오류가 나면 <strong>팝업을 캡처해 GPT에 그대로 물어보면</strong> 거의 해결된다(이게 표준 디버깅 루프). ② 실행 전 특정 시트를 선택해야 충돌이 안 나는 경우가 있다. ③ <strong>인코딩</strong> — 한글 CSV가 UTF-8이면 위 코드에서 깨질 수 있다(이 경우 메모장에서 ANSI로 저장하거나 <code>ADODB.Stream</code>으로 읽게 프롬프트). 따옴표 안에 콤마가 있는 CSV도 단순 <code>Split</code>은 깨진다.</p>\r\n<p><strong>보강 — 왜 VBA인가(광안대교 일화).</strong> 2000년대엔 수천억대 공사 내역서를 엑셀 매크로로 다루는 사람이 그룹사에 몇 명뿐인 '도사'였다. 지금은 그 VBA를 <strong>AI가 써준다.</strong> 엑셀은 모든 PC에 깔려 있어, 직원 PC에 파이썬을 못 깔아도 <strong>VBA만으로 업무 자동화</strong>가 된다 — 엑셀뿐 아니라 PPT·워드도 같은 방식(COM)으로 제어 가능. (2회차 '범피스'의 COM 자동화와 같은 원리.)</p>\r\n</blockquote>\r\n<h2 id=\"2\">2단계 · 데이터 전처리 — 데이터가 거짓말할 때</h2>\r\n<p>메타데이터를 보면 공공 데이터의 함정이 드러난다. 강사가 심은 오류:\r\n- <strong>단위 불일치</strong>: 어떤 해는 천원, 어떤 해는 만원 단위 → 그래프에 갑자기 '절벽'(10배 차이).\r\n- <strong>컬럼명 불일치</strong>: <code>연도</code> vs <code>조사연도</code>(심지어 <code>조사 연도</code> 띄어쓰기) → 파이썬에서 서로 다른 컬럼으로 인식 → 널(빈)값 발생.\r\n- <strong>시군명/코드 불일치</strong> → 시군 코드로 매핑 필요.</p>\r\n<blockquote class=\"callout callout-warn\"><span class=\"callout-badge\">주의</span>\r\n<p>⚠ <strong>주의 — 원천(CSV)에서 고쳐라.</strong> SQL 임포트에는 \"이 컬럼에 1000을 곱해라\" 같은 옵션이 없다. 매번 프롬프트로 제어하느니 <strong>원본 데이터에서 컬럼명을 통일하고 단위를 맞추는 게</strong> 깔끔하다. 사람은 \"연도=조사연도\"인 걸 알지만 기계는 모른다 — <strong>철자·띄어쓰기까지 정확히</strong> 맞춰야 한다.</p>\r\n<p><strong>보강 — 히라(HIRA, 건강보험심사평가원) 데이터 일화.</strong> 학생 과제에 단골인 심평원 데이터는 2019년경 갑자기 컬럼 구성이 바뀌어(담당자 교체·항목 추가) 그래프가 뚝 끊긴다. \"왜 절벽이 생기지?\"의 원인이 대개 이런 <strong>컬럼 변동</strong>이다. 분석 전에 반드시 데이터부터 열어봐야 하는 이유.</p>\r\n</blockquote>\r\n<h2 id=\"3-sqlite-db-browser\">3단계 · SQLite + DB Browser 설치</h2>\r\n<p><strong>SQLite</strong> = 파일 하나로 끝나는 초경량 DB(원격 접속 자체가 없어 보안 부담이 적다). 설치랄 게 없다:</p>\r\n<div class=\"codewrap\"><div class=\"codebar\"><span class=\"codelang\">text</span><button class=\"copybtn\" type=\"button\">복사</button></div><pre><code class=\"language-text\">1) sqlite.org → Download → \"SQLite Tools Win x64\" zip 받기\r\n2) 압축 풀어 나온 파일들을 C:\\SQLite 폴더에 복사 (인스톨러 없음, 이게 끝)\r\n</code></pre></div>\r\n<p>까만 커맨드 창이 불편하면 그래픽 도구를 깐다:</p>\r\n<div class=\"codewrap\"><div class=\"codebar\"><span class=\"codelang\">text</span><button class=\"copybtn\" type=\"button\">복사</button></div><pre><code class=\"language-text\">DB Browser for SQLite → 다운로드 → (윈도우 64bit standard installer) → 다음 다음 설치\r\n</code></pre></div>\r\n<blockquote class=\"callout callout-add\"><span class=\"callout-badge\">보강</span>\r\n<p><strong>보강 — SQLite는 '연습용'이 아니라 '입문용'.</strong> 여기서 익힌 개념은 PostgreSQL·SQL Server·Oracle에 그대로 통한다. 과제·실서비스로 가면 PostgreSQL 등을 쓰면 된다(구조가 유사). SQLite는 지금 메모리/파일 기반이라 가장 단순할 뿐.</p>\r\n</blockquote>\r\n<h2 id=\"4-db-csv\">4단계 · DB 만들고 CSV 임포트</h2>\r\n<p>DB Browser에서: <strong>새 데이터베이스</strong>(예: <code>GRP.db</code>) 생성 → 첫 테이블 만들기 창은 <em>취소</em> → <strong>파일 → 가져오기 → CSV 파일에서 테이블 가져오기</strong> → CSV 하나씩 임포트(6개 = 6개 테이블). DB는 <code>GRP.db</code> 파일 하나로 떨어져, 다른 PC로 <strong>그 파일만 복사</strong>하면 그대로 쓸 수 있다.</p>\r\n<blockquote class=\"callout callout-warn\"><span class=\"callout-badge\">주의</span>\r\n<p>⚠ <strong>주의 — \"필드명 포함\" 체크.</strong> 임포트 창에서 이 옵션을 안 켜면 <strong>첫 행(시군 등 컬럼명)이 데이터(레코드)로 들어가</strong> 버린다. 켜고/끄고 미리보기가 어떻게 바뀌는지 보고 임포트할 것. (DB = 방, 그 안의 대표 오브젝트 = 테이블.)</p>\r\n</blockquote>\r\n<h2 id=\"5-ddl-text-to-sql\">5단계 · 테이블 정의서(DDL) → Text-to-SQL</h2>\r\n<p>GPT가 SQL을 만들려면 <strong>테이블 구조</strong>를 알아야 한다. DB Browser에서 테이블 우클릭 → <strong>생성 구문 복사하기</strong>(= DDL, <code>CREATE TABLE …</code>) → 메모장에 모아 GPT에 준다.</p>\r\n<blockquote class=\"callout callout-key\"><span class=\"callout-badge\">핵심</span>\r\n<p>★ <strong>핵심 — \"SQLite에서 수행될\"을 명시하라.</strong> 엔진(SQLite/PostgreSQL/MSSQL/Oracle)마다 함수·문법이 달라서, 프롬프트에 어떤 엔진인지 못 박아야 맞는 SQL이 나온다. 이 'DDL + 질문'을 GPTs로 만들어 두면, 이후엔 질문만 하면 되는 전용 도우미가 된다.</p>\r\n</blockquote>\r\n<p>이제 SQL을 모르고도 자연어로 시킨다(컬럼명은 예시):</p>\r\n<div class=\"codewrap\"><div class=\"codebar\"><span class=\"codelang\">sql</span><button class=\"copybtn\" type=\"button\">복사</button></div><pre><code class=\"language-sql\">-- 각 테이블 행 수\r\nSELECT COUNT(*) FROM \"총생산_2013\";\r\n\r\n-- 시군구 개수 (중복 제거)\r\nSELECT COUNT(DISTINCT 시군명) FROM \"총생산_2013\";\r\n\r\n-- 6개 연도 테이블을 하나로 합쳐 GRP_Total 생성\r\nCREATE TABLE GRP_Total AS\r\nSELECT * FROM \"총생산_2013\"\r\nUNION ALL SELECT * FROM \"총생산_2014\"\r\nUNION ALL SELECT * FROM \"총생산_2015\";   -- … 나머지 연도도 이어붙임\r\n\r\n-- 테이블 삭제는 DELETE가 아니라 DROP\r\nDROP TABLE GRP_Total;\r\n</code></pre></div>\r\n<p>실행은 DB Browser의 <strong>SQL 실행</strong> 탭에서 <strong>Ctrl+Enter</strong>. 주석은 <code>--</code>(한 줄), <code>/* … */</code>(여러 줄).</p>\r\n<blockquote class=\"callout callout-warn\"><span class=\"callout-badge\">주의</span>\r\n<p>⚠ <strong>주의 — 콤마가 섞인 숫자.</strong> <code>3,417</code>처럼 천단위 콤마가 든 채로 임포트하면 SQLite가 텍스트로 인식해 계산이 안 된다. 임포트 전 콤마를 없애거나 자료형을 맞춰야 한다(SQLite 자료형은 TEXT/INTEGER/REAL 정도로 단순).</p>\r\n</blockquote>\r\n<h2 id=\"6-sql\">6단계 · 윈도우 함수 — SQL 분석의 진짜 무기</h2>\r\n<p><strong>윈도우 함수(Window Function)</strong> = \"내가 보고 싶은 영역(창)\"을 기준으로 옆 칸에 계산을 덧붙이는 함수. 엑셀로는 거의 못 하는 걸 SQL이 한 줄로 해낸다.</p>\r\n<div class=\"tablescroll\"><table>\r\n<thead>\r\n<tr>\r\n<th>함수</th>\r\n<th>하는 일</th>\r\n</tr>\r\n</thead>\r\n<tbody>\r\n<tr>\r\n<td><code>RANK</code> / <code>DENSE_RANK</code></td>\r\n<td>순위 매기기(동점 처리 방식 차이)</td>\r\n</tr>\r\n<tr>\r\n<td><code>PERCENT_RANK</code> / <code>CUME_DIST</code></td>\r\n<td>백분위 / 누적 분포</td>\r\n</tr>\r\n<tr>\r\n<td><code>NTILE(n)</code></td>\r\n<td>전체를 n개 그룹으로 분할(예: 10분위)</td>\r\n</tr>\r\n<tr>\r\n<td><code>LAG</code> / <code>LEAD</code></td>\r\n<td>이전/다음 행 값 가져오기(전년 대비 등)</td>\r\n</tr>\r\n<tr>\r\n<td><code>ROWS BETWEEN …</code></td>\r\n<td>이동 구간 지정(이동평균)</td>\r\n</tr>\r\n</tbody>\r\n</table></div>\r\n<div class=\"codewrap\"><div class=\"codebar\"><span class=\"codelang\">sql</span><button class=\"copybtn\" type=\"button\">복사</button></div><pre><code class=\"language-sql\">-- 연도별 1인당 생산액 순위\r\nSELECT 연도, 시군명, 생산액,\r\n       RANK() OVER (PARTITION BY 연도 ORDER BY 생산액 DESC) AS 순위\r\nFROM GRP_Total;\r\n\r\n-- 전년 대비 증감 (LAG = 직전 연도 값)\r\nSELECT 연도, 시군명, 생산액,\r\n       생산액 - LAG(생산액) OVER (PARTITION BY 시군명 ORDER BY 연도) AS 전년대비증감\r\nFROM GRP_Total;\r\n</code></pre></div>\r\n<blockquote class=\"callout callout-key\"><span class=\"callout-badge\">핵심</span>\r\n<p>★ <strong>핵심 — 너는 '무엇을' 만 정하면 된다.</strong> 주식의 60일·120일 이동평균선이 바로 윈도우 함수다(오늘 기준 직전 60개 평균). \"10년 평균 대비 지금 얼마나 높나\" 같은 <em>아이디어</em>만 있으면 SQL은 AI가 짜준다. <code>CAGR</code>(연평균 성장률)로 \"성장형 vs 정체형 지자체\"를 가르는 것도 같은 방식.</p>\r\n</blockquote>\r\n<h2 id=\"7-sqlite\">7단계 · 주피터 노트북에서 SQLite 연결</h2>\r\n<p>마지막으로, DB에서 SQL로 추린 결과만 파이썬으로 가져와 분석한다(메모리를 최소로 쓰는 핵심 패턴).</p>\r\n<div class=\"codewrap\"><div class=\"codebar\"><span class=\"codelang\">python</span><button class=\"copybtn\" type=\"button\">복사</button></div><pre><code class=\"language-python\"># (필요한 것만) 설치 — 셀에서 ! 로 실행\r\n!pip install pandas\r\n# sqlite3 는 파이썬 '내장 모듈'이라 설치 불필요\r\n\r\nimport sqlite3\r\nimport pandas as pd\r\n\r\ndb_path = r\"C:\\SQLite\\GRP\\GRP.db\"      # 본인 .db 경로로 수정\r\nconn = sqlite3.connect(db_path)\r\nprint(\"SQL 연결 완료\")\r\n\r\ndf = pd.read_sql(\"SELECT * FROM GRP_Total\", conn)\r\ndf.head()                               # 앞 5줄 확인\r\n</code></pre></div>\r\n<blockquote class=\"callout callout-warn\"><span class=\"callout-badge\">주의</span>\r\n<p>⚠ <strong>주의 — <code>pip install sqlite3</code> 는 오류난다.</strong> 강사가 일부러 보여준 장면. <code>sqlite3</code>는 파이썬에 <strong>기본 내장</strong>이라 PyPI에 설치 패키지가 없다. import만 하면 된다. (참고: 파이썬 설치 시 표준 라이브러리 약 200개가 깔리고, PyPI에는 60만 개 이상이 등록돼 있다. 필요한 건 <code>pip install</code> 후 <code>import</code>.)</p>\r\n<p><strong>보강 — 빨간 오류는 정상.</strong> <code>pip install</code>/<code>import</code>에서 빨간 메시지가 나면 당황 말고 <strong>메시지를 캡처해 GPT에 던지면</strong> 된다. 이게 파이썬 작업의 일상 루프다.</p>\r\n<p>⚠ <strong>주의 (검색 보강) — 기관에서 아나콘다(Anaconda)는 유료.</strong> 2020년 9월부터 <strong>직원 200명 이상 기업·정부기관</strong>이 Anaconda를 쓰면 상업 라이선스를 사야 한다. 기관에서는 주피터 노트북을 <strong>아나콘다 없이</strong> 단독 설치하거나 <strong>Miniconda + conda-forge / Miniforge</strong> 조합으로 쓰는 게 안전하다. (개인·소규모는 무료.)</p>\r\n</blockquote>\r\n<h2 id=\"_5\">보강 · 데이터베이스가 빠른 이유 — 메모리 계층과 캐싱</h2>\r\n<p>고급 과정이니 한 겹 더. 하드웨어 속도는 <strong>CPU &gt; 메모리 &gt; 디스크 &gt; 네트워크</strong> 순.</p>\r\n<div class=\"codewrap\"><div class=\"codebar\"><span class=\"codelang\">code</span><button class=\"copybtn\" type=\"button\">복사</button></div><pre class=\"mermaid\">flowchart LR\r\n  D[\"디스크&lt;br/&gt;(느림, 큼)\"] --&gt;|첫 조회: 올림| M[\"메모리&lt;br/&gt;(빠름)\"]\r\n  M --&gt;|결과| U[\"사용자\"]\r\n  M -.-&gt;|같은 쿼리 재요청&lt;br/&gt;= 캐시 히트| U\r\n</pre></div>\r\n<ul>\r\n<li>처음 <code>SELECT</code>는 디스크 → 메모리로 올리느라 느리고, <strong>같은 쿼리를 또 하면 메모리에서 바로</strong>(캐시 히트) 빨라진다. PC/서버의 캐시·메모리가 클수록 유리.</li>\r\n</ul>\r\n<blockquote class=\"callout callout-warn\"><span class=\"callout-badge\">주의</span>\r\n<p>⚠ <strong>주의 · 함정 — <code>WHERE</code> 없는 <code>SELECT *</code>.</strong> 1억 건 테이블을 조건 없이 통째로 부르면 메모리를 넘겨 기존 데이터를 디스크로 밀어내고 전체가 느려진다. 큰 테이블은 반드시 <code>WHERE</code>로 좁혀라.</p>\r\n<p><strong>보강 — Supabase = AWS PostgreSQL '도매'.</strong> 백엔드로 자주 쓰는 <strong>Supabase</strong>는 AWS의 PostgreSQL을 싸게 떼다(도매) 관리 툴을 얹어 파는 구조라고 강사는 비유했다. 다음 주(4회차)엔 파일 기반 대용량 포맷 <strong>Parquet(파켓)</strong> 도 나온다. 이런 대규모 흐름이 <strong>BI(비즈니스 인텔리전스) → 데이터 웨어하우스 → 데이터 레이크</strong> 로 이어진다.</p>\r\n</blockquote>\r\n<hr/>\r\n<h1 class=\"modhead\" data-full=\"3부 · 콘텐츠 제작 워크플로우 — NotebookLM 레고\" id=\"3-notebooklm\">3부 · 콘텐츠 제작 워크플로우 — NotebookLM 레고</h1>\r\n<p>기관 홍보물(카드뉴스 + 영상)을 도구 조합으로 만든다.</p>\r\n<h2 id=\"notebooklm\">NotebookLM으로 카드뉴스·영상 기획</h2>\r\n<p>소스(홈페이지·나무위키·유튜브 등 1~3개)를 NotebookLM에 넣고, 카드 한 장마다 <strong>네 가지</strong>를 뽑게 한다: ① 이미지 프롬프트(글자 없이) ② 못 넣은 문구 ③ 나레이션 스크립트 ④ 다음 컷 전환 효과. 그다음 <em>\"이미지 프롬프트만 모아줘\"</em> → 슬라이드 생성 → <strong>AI 오디오뷰</strong>까지.</p>\r\n<blockquote class=\"callout callout-add\"><span class=\"callout-badge\">보강</span>\r\n<p><strong>보강 — NotebookLM 소스 정렬 팁.</strong> 소스는 알파벳순으로 정렬되니, 중요한 소스 이름 앞에 <code>!</code> 등을 붙여 위로 올리면 스튜디오 생성 품질이 좋아진다.</p>\r\n</blockquote>\r\n<h2 id=\"codia-ai-notebooklm-ppt\">Codia AI — NotebookLM 슬라이드를 '편집 가능한 PPT'로</h2>\r\n<p>NotebookLM 슬라이드는 예쁘지만 <strong>한글이 깨지고 수정이 안 되는</strong> 게 약점. <strong>Codia AI</strong>(SaaS)는 이미지를 텍스트/도형 레이어로 분리해 <strong>편집 가능한 PPTX로 변환</strong>한다(5장 무료, 이후 유료).</p>\r\n<blockquote class=\"callout callout-add\"><span class=\"callout-badge\">보강</span>\r\n<p><strong>보강 — 유료 도구를 똑똑하게 쓰는 법.</strong> 강사 팁: 변환할 슬라이드를 한 200장 모아뒀다가 한 달(약 2만~3만 원) 결제해 한 번에 변환하고 해지. \"무료가 되면 다 쓸 것\" → 결국 구글/OpenAI가 비슷한 기능을 내놓을 가능성이 큰 영역. (그전까지의 임시 도구.)</p>\r\n</blockquote>\r\n<hr/>\r\n<h1 class=\"modhead\" data-full=\"4부 · GEO/SEO — AI 시대의 검색 최적화\" id=\"4-geoseo-ai\">4부 · GEO/SEO — AI 시대의 검색 최적화</h1>\r\n<p>이제 사람들은 네이버·구글 키워드 검색 대신 Gemini·ChatGPT에게 <em>문장으로</em> 묻는다. 그래서 최적화의 기준도 바뀐다.</p>\r\n<h2 id=\"geo\">GEO란 — 검색 패러다임의 전환</h2>\r\n<blockquote class=\"callout callout-key\"><span class=\"callout-badge\">핵심</span>\r\n<p>★ <strong>핵심 (검색 보강).</strong> <strong>SEO</strong>(Search Engine Optimization)는 검색엔진 결과(SERP)에서 <strong>상위 노출 → 클릭</strong>을 노리는 것. <strong>GEO</strong>(Generative Engine Optimization)는 생성형 AI(ChatGPT·Perplexity·Gemini·AI Overviews 등)가 답변을 만들 때 <strong>내 콘텐츠를 인용·추천하게</strong> 만드는 것. 목표가 '클릭 유도'에서 'AI 답변에 포함되기'로 바뀐다.</p>\r\n</blockquote>\r\n<p>GEO가 좋아하는 구조: <strong>명확한 정보 위계(H1·H2·H3), 질문-답변형 콘텐츠, 두괄식, JSON-LD/스키마 같은 구조화 데이터.</strong> 마크다운식의 또렷한 구조가 유리하다(2회차의 \"AI가 읽기 쉬운 문서\"와 정확히 같은 맥락).</p>\r\n<h2 id=\"lovable\">실습 · 기관 사이트 진단 → Lovable로 개선</h2>\r\n<p>진단 프롬프트로 기관 홈페이지의 SEO/GEO를 <strong>점수화</strong>(예: NIA 61점) → 약점 도출 → <strong>Lovable</strong>(노코드 웹 빌더)로 사이트를 GEO 친화적으로 재생성 → 전/후 비교. Lovable에는 퍼블리시 후 <strong>\"Review SEO\"</strong> 버튼이 생겼다(업계가 GEO에 그만큼 반응 중).</p>\r\n<blockquote class=\"callout callout-add\"><span class=\"callout-badge\">보강</span>\r\n<p><strong>보강 — 행안부 'AI 시대 문서 작성 가이드라인'.</strong> 강사가 반긴 정책. 예쁘게 꾸민 표·데코레이션, 주어/서술어 생략한 복잡한 개조식 문장을 <strong>지양</strong>하고, <em>사람과 AI가 모두 읽기 쉬운</em> 문서를 권한다. 3~6월 행안부 내 시범 → 하반기 중앙기관 확산. 이게 2회차에서 본 <strong>HWPX 의무화(2026.6.18~)</strong> 와 한 묶음이다 — 기관 사이트·문서 모두 'AI가 읽기 좋게'.</p>\r\n</blockquote>\r\n<hr/>\r\n<h1 class=\"modhead\" data-full=\"5부 · 콜센터 녹취 분석 — 음성 워크플로우\" id=\"5\">5부 · 콜센터 녹취 분석 — 음성 워크플로우</h1>\r\n<p>마지막 레고 조합. 음성 파일 더미를 텍스트로 바꿔 요약·감정분석까지.</p>\r\n<blockquote class=\"callout callout-add\"><span class=\"callout-badge\">보강</span>\r\n<p><strong>보강 — 뉴발란스 수선 콜센터 일화.</strong> 월 8,000건 녹취가 쌓이는데 \"무슨 통화인지 모르겠다\"는 의뢰. 상담원 8명이 무슨 대화를 하는지 파악하려면, MP3 더미를 자동으로 전사·분석하는 <strong>워크플로우</strong>가 필요하다. 막막하면 <em>\"이 문제를 어떤 워크플로우로 풀지 알려줘\"</em> 부터 AI에 물어라.</p>\r\n</blockquote>\r\n<h2 id=\"_6\">워크플로우 설계 (레고 블록)</h2>\r\n<div class=\"codewrap\"><div class=\"codebar\"><span class=\"codelang\">code</span><button class=\"copybtn\" type=\"button\">복사</button></div><pre class=\"mermaid\">flowchart LR\r\n  MP3[\"MP3 녹취\"] --&gt; W[\"Whisper / Faster Whisper&lt;br/&gt;전사(STT)\"]\r\n  W --&gt; J[\"JSON 저장\"]\r\n  J --&gt; L[\"요약·감정·주제·VOC\"]\r\n  L --&gt; G[\"Gemini API&lt;br/&gt;또는 Ollama(Gemma)\"]\r\n  G --&gt; DB[\"SQLite 저장(INSERT)\"]\r\n</pre></div>\r\n<p>각 칸이 레고다 — 녹취 가져오기 / Whisper 전사 / SQLite 저장 / 외부 API or 로컬 Ollama / 결과 표시. 필요한 것만 끼우면 된다.</p>\r\n<h2 id=\"_7\">실제 코드 골격</h2>\r\n<div class=\"codewrap\"><div class=\"codebar\"><span class=\"codelang\">python</span><button class=\"copybtn\" type=\"button\">복사</button></div><pre><code class=\"language-python\">!pip install faster-whisper\r\nfrom faster_whisper import WhisperModel\r\n\r\n# 모델: tiny&lt;base&lt;small&lt;medium (정확도↑/속도↓). 보통 small 추천.\r\n# GPU 있으면 device=\"cuda\", compute_type=\"float16\"\r\nmodel = WhisperModel(\"small\", device=\"cpu\", compute_type=\"int8\")\r\n\r\nsegments, info = model.transcribe(\"call_001.mp3\", language=\"ko\")\r\ntext = \" \".join(seg.text for seg in segments)\r\nprint(f\"{info.duration:.1f}초, 전사: {text[:60]}…\")\r\n</code></pre></div>\r\n<div class=\"codewrap\"><div class=\"codebar\"><span class=\"codelang\">python</span><button class=\"copybtn\" type=\"button\">복사</button></div><pre><code class=\"language-python\">import json\r\nwith open(\"call_001.json\", \"w\", encoding=\"utf-8\") as f:\r\n    json.dump({\"file\": \"call_001.mp3\", \"duration\": info.duration, \"text\": text},\r\n              f, ensure_ascii=False, indent=2)\r\n</code></pre></div>\r\n<p>요약·감정분석은 외부 API(Gemini) 또는 <strong>로컬 Ollama</strong>로:</p>\r\n<div class=\"codewrap\"><div class=\"codebar\"><span class=\"codelang\">Shell</span><button class=\"copybtn\" type=\"button\">복사</button></div><pre><code class=\"language-bash\">ollama run gemma3:4b \"다음 콜센터 통화를 3줄로 요약하고 감정을 (긍정/중립/부정)으로 분류해줘: &lt;전사 텍스트&gt;\"\r\n</code></pre></div>\r\n<blockquote class=\"callout callout-warn\"><span class=\"callout-badge\">주의</span>\r\n<p>폐쇄망/보안망이면 이 전체를 <strong>로컬로</strong> 돌릴 수 있다 — 전사는 <strong>Faster Whisper</strong>(이 프로젝트의 <code>kbrain_stt.py</code>가 쓰는 그 엔진), 요약·감정은 <strong>Ollama + Gemma</strong>, 저장은 <strong>SQLite</strong>. 외부로 데이터를 한 톨도 안 보내고 끝난다. 보조 감정분류엔 <strong>KoBERT</strong> 같은 한국어 모델도 쓸 수 있다.</p>\r\n<p><strong>보강 — JSON으로 저장하는 이유.</strong> 전사 결과를 JSON으로 떨구면(화자·시작/끝 시각·길이 등 구조 포함) 나중에 \"오후 3~4시 통화만\" 같은 조회가 쉽다. AI·기계는 JSON과 마크다운을 가장 잘 다룬다. 단, 음성/텍스트 원본은 DB에 통째로 넣기보다(잘 안 씀: BLOB) <strong>파일로 두고 경로(파일명)만 DB에 저장</strong>하는 게 보통이다.</p>\r\n</blockquote>\r\n<hr/>\r\n<h1 class=\"modhead\" data-full=\"마무리 &amp; 과제\" id=\"_8\">마무리 &amp; 과제</h1>\r\n<blockquote class=\"callout callout-key\"><span class=\"callout-badge\">핵심</span>\r\n<p>★ 오늘의 한 줄: <strong>why·what은 사람이, how는 AI가.</strong> 원천 CSV를 DB에 넣고, SQL은 AI에게 시켜 최대한 돌리고, 결과만 파이썬으로 가져와 목적(분석·정책)을 이룬다. 도구는 레고처럼 조합한다.</p>\r\n</blockquote>\r\n<p><strong>과제</strong> — HIRA(심평원) 데이터셋(2018·2019·2020년)으로 같은 흐름을 반복:\r\n1. VBA로 메타데이터를 뽑아 <strong>컬럼 구조 변동</strong>을 찾는다(2번 항목에 컬럼이 끼어들어 값이 '절벽'처럼 떨어지는 부분 — 위치 이동/삭제로 전처리).\r\n2. 전처리한 CSV를 SQLite에 임포트하고, Text-to-SQL로 조회해 본다.\r\n3. 결과물을 공유 폴더에 업로드.\r\n- 참고: 상병코드(예: <code>A01</code> = 장티푸스 및 파라티푸스)처럼 도메인 코드는 모르는 게 정상 — 필요하면 코드표를 붙여 매핑한다.</p>\r\n<hr/>\r\n<h1 class=\"modhead\" data-full=\"부록 — 용어 사전 · 출처\" id=\"_9\">부록 — 용어 사전 · 출처</h1>\r\n<h2 id=\"_10\">용어 빠른 사전</h2>\r\n<div class=\"tablescroll\"><table>\r\n<thead>\r\n<tr>\r\n<th>용어</th>\r\n<th>한 줄 정의</th>\r\n</tr>\r\n</thead>\r\n<tbody>\r\n<tr>\r\n<td>메타 프롬프트</td>\r\n<td>프롬프트를 만들어 달라고 시켜 '프롬프트'를 받는 기법</td>\r\n</tr>\r\n<tr>\r\n<td>퓨샷 / CoT</td>\r\n<td>예시 몇 개 제시 / \"단계적으로 생각\" 추론 유도</td>\r\n</tr>\r\n<tr>\r\n<td>프리모텀(Pre-mortem)</td>\r\n<td>실패를 가정하고 원인을 미리 찾는 사고법(아첨 깨기)</td>\r\n</tr>\r\n<tr>\r\n<td>Text-to-SQL</td>\r\n<td>자연어로 시켜 SQL을 생성하는 것</td>\r\n</tr>\r\n<tr>\r\n<td>DDL / 테이블 정의서</td>\r\n<td><code>CREATE TABLE …</code>, 테이블 구조 명세</td>\r\n</tr>\r\n<tr>\r\n<td>인덱스 / 풀 스캔</td>\r\n<td>빨리 찾기 위한 색인 / 처음부터 끝까지 훑기</td>\r\n</tr>\r\n<tr>\r\n<td>윈도우 함수</td>\r\n<td>지정 구간 기준으로 순위·이동평균 등을 계산(RANK, LAG/LEAD…)</td>\r\n</tr>\r\n<tr>\r\n<td>CAGR</td>\r\n<td>연평균 성장률</td>\r\n</tr>\r\n<tr>\r\n<td>캐시 히트</td>\r\n<td>디스크 대신 메모리에서 결과를 바로 가져옴</td>\r\n</tr>\r\n<tr>\r\n<td>SQLite / DB Browser</td>\r\n<td>파일 하나로 쓰는 경량 DB / 그 GUI 도구</td>\r\n</tr>\r\n<tr>\r\n<td>Parquet(파켓)</td>\r\n<td>대용량 분석에 쓰는 컬럼형 파일 포맷(4회차 예고)</td>\r\n</tr>\r\n<tr>\r\n<td>NotebookLM / Codia AI</td>\r\n<td>구글 소스 기반 콘텐츠 도구 / 슬라이드→편집가능 PPT 변환</td>\r\n</tr>\r\n<tr>\r\n<td>SEO / GEO</td>\r\n<td>검색엔진 상위노출·클릭 / 생성형 AI가 인용·추천하게 하기</td>\r\n</tr>\r\n<tr>\r\n<td>Whisper / Faster Whisper</td>\r\n<td>음성→텍스트(STT) 모델 / 그 고속 구현</td>\r\n</tr>\r\n<tr>\r\n<td>Ollama / Gemma / KoBERT</td>\r\n<td>로컬 LLM 실행기 / 구글 소형모델 / 한국어 BERT</td>\r\n</tr>\r\n<tr>\r\n<td>BLOB</td>\r\n<td>DB에 이진 대용량(음성·이미지 등)을 넣는 자료형(보통 지양)</td>\r\n</tr>\r\n<tr>\r\n<td>BI / 데이터 웨어하우스 / 레이크</td>\r\n<td>분석·의사결정용 데이터 인프라 단계</td>\r\n</tr>\r\n</tbody>\r\n</table></div>\r\n<h2 id=\"_11\">검색으로 확인·보강한 출처</h2>\r\n<ul>\r\n<li>프리모텀(Gary Klein, HBR 2007 / prospective hindsight 30%): <a href=\"https://hbr.org/2007/09/performing-a-project-premortem\">HBR — Performing a Project Premortem</a></li>\r\n<li>LLM 워게임 핵 에스컬레이션(GPT-4-Base 33%): <a href=\"https://arxiv.org/abs/2401.03408\">arXiv 2401.03408</a>, <a href=\"https://www.euronews.com/next/2024/02/22/ai-models-chose-violence-and-escalated-to-nuclear-strikes-in-simulated-wargames\">Euronews</a></li>\r\n<li>GEO(Generative Engine Optimization) 정의: <a href=\"https://searchengineland.com/what-is-generative-engine-optimization-geo-444418\">Search Engine Land</a>, <a href=\"https://www.conductor.com/academy/generative-engine-optimization/\">Conductor Academy</a></li>\r\n<li>아나콘다 200명 이상 유료 라이선스(2020.9~): <a href=\"https://devocean.sk.com/blog/techBoardDetail.do?ID=164615&amp;boardType=techBlog\">Anaconda Terms of Service 관련 정리</a></li>\r\n</ul>\r\n  </main>\r\n</div>\r\n\r\n<script src=\"https://cdnjs.cloudflare.com/ajax/libs/highlight.js/11.9.0/highlight.min.js\"><\/script>\r\n<script src=\"https://cdnjs.cloudflare.com/ajax/libs/highlight.js/11.9.0/languages/powershell.min.js\"><\/script>\r\n<script src=\"https://cdnjs.cloudflare.com/ajax/libs/highlight.js/11.9.0/languages/vbscript.min.js\"><\/script>\r\n<script src=\"https://cdnjs.cloudflare.com/ajax/libs/mermaid/10.9.1/mermaid.min.js\"><\/script>\r\n<script>\r\n// 주제 헤더 raw 텍스트를 data-full로 옮겨 ::after 표시\r\ndocument.querySelectorAll('h1.modhead').forEach(function(h){\r\n  h.setAttribute('data-full', h.textContent);\r\n});\r\n\r\n// highlight.js\r\nif(window.hljs){\r\n  document.querySelectorAll('.codewrap pre code').forEach(function(b){\r\n    try{hljs.highlightElement(b);}catch(e){}\r\n  });\r\n}\r\n\r\n// mermaid\r\nif(window.mermaid){\r\n  mermaid.initialize({\r\n    startOnLoad:true, theme:'base',\r\n    htmlLabels:false,\r\n    themeVariables:{\r\n      fontFamily:'-apple-system,Pretendard,\"Malgun Gothic\",sans-serif',\r\n      fontSize:'13px',\r\n      primaryColor:'#e6f4f1', primaryBorderColor:'#127c71', primaryTextColor:'#0c5249',\r\n      lineColor:'#9aa0a8', secondaryColor:'#f4f1ea', tertiaryColor:'#fbf1e4',\r\n      clusterBkg:'#f6f6f0', clusterBorder:'#cfd3cb'\r\n    },\r\n    flowchart:{curve:'basis', useMaxWidth:true, htmlLabels:false},\r\n    sequence:{useMaxWidth:true}\r\n  });\r\n}\r\n\r\n// 복사 버튼\r\ndocument.querySelectorAll('.copybtn').forEach(function(btn){\r\n  btn.addEventListener('click', function(){\r\n    var code = btn.closest('.codewrap').querySelector('pre code');\r\n    var txt = code ? code.innerText : '';\r\n    navigator.clipboard.writeText(txt).then(function(){\r\n      btn.textContent='복사됨'; btn.classList.add('ok');\r\n      setTimeout(function(){btn.textContent='복사'; btn.classList.remove('ok');},1400);\r\n    });\r\n  });\r\n});\r\n\r\n// 스크롤 스파이\r\nvar links = Array.from(document.querySelectorAll('#nav a'));\r\nvar map = {};\r\nlinks.forEach(function(a){ map[a.getAttribute('href').slice(1)] = a; });\r\nvar heads = Array.from(document.querySelectorAll('.main h1[id], .main h2[id]'));\r\nvar spy = new IntersectionObserver(function(entries){\r\n  entries.forEach(function(en){\r\n    if(en.isIntersecting){\r\n      links.forEach(function(l){l.classList.remove('active');});\r\n      var act = map[en.target.id];\r\n      if(act){act.classList.add('active');\r\n        act.scrollIntoView({block:'nearest'});}\r\n    }\r\n  });\r\n}, {rootMargin:'-10% 0px -75% 0px', threshold:0});\r\nheads.forEach(function(h){spy.observe(h);});\r\n\r\n// 모바일 사이드바\r\nvar side=document.getElementById('side'), scrim=document.getElementById('scrim'),\r\n    mb=document.getElementById('menubtn');\r\nfunction toggle(open){side.classList.toggle('open',open);scrim.classList.toggle('show',open);}\r\nif(mb){mb.addEventListener('click',function(){toggle(!side.classList.contains('open'));});}\r\nif(scrim){scrim.addEventListener('click',function(){toggle(false);});}\r\nlinks.forEach(function(a){a.addEventListener('click',function(){if(window.innerWidth<=880)toggle(false);});});\r\n<\/script>\r\n</body>\r\n</html>\r\n","4":"<!DOCTYPE html>\r\n<html lang=\"ko\">\r\n<head>\r\n<meta charset=\"utf-8\">\r\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\r\n<title>4회차 — 바이브 코딩 1: 데이터 시각화 (데이터 사이언스 풀 사이클)</title>\r\n<link rel=\"preconnect\" href=\"https://cdnjs.cloudflare.com\">\r\n<link rel=\"stylesheet\" href=\"https://cdnjs.cloudflare.com/ajax/libs/highlight.js/11.9.0/styles/github.min.css\">\r\n<style>\r\n:root{\r\n  --bg:#fafaf6; --panel:#ffffff; --ink:#1b1e24; --ink-soft:#5a6069; --ink-faint:#8b919b;\r\n  --line:#e7e6df; --line-soft:#f0efe9;\r\n  --teal:#127c71; --teal-d:#0c5249; --teal-bg:#e6f4f1;\r\n  --amber:#b9722a; --amber-bg:#fbf1e4;\r\n  --red:#c0392b; --red-bg:#fbe9e7;\r\n  --code-bg:#f6f6f0;\r\n  --mono:ui-monospace,\"SF Mono\",\"Cascadia Code\",\"JetBrains Mono\",Consolas,monospace;\r\n  --sans:-apple-system,BlinkMacSystemFont,\"Pretendard\",\"Apple SD Gothic Neo\",\"Segoe UI\",\"Malgun Gothic\",sans-serif;\r\n  --rad:12px;\r\n}\r\n*{box-sizing:border-box}\r\nhtml{scroll-behavior:smooth}\r\n@media (prefers-reduced-motion:reduce){html{scroll-behavior:auto}}\r\nbody{margin:0;background:var(--bg);color:var(--ink);font-family:var(--sans);\r\n  font-size:16px;line-height:1.72;-webkit-font-smoothing:antialiased}\r\n\r\n/* layout */\r\n.shell{display:grid;grid-template-columns:300px minmax(0,1fr);max-width:1240px;margin:0 auto}\r\n.print-toc{display:none}\r\n.side{position:sticky;top:0;align-self:start;height:100vh;overflow-y:auto;\r\n  padding:30px 22px 60px;border-right:1px solid var(--line)}\r\n.main{min-width:0;padding:46px 60px 120px;max-width:880px}\r\n\r\n/* sidebar */\r\n.brand{font-family:var(--mono);font-size:11px;letter-spacing:.14em;text-transform:uppercase;\r\n  color:var(--teal);margin-bottom:6px}\r\n.brand-t{font-weight:700;font-size:17px;line-height:1.35;margin:0 0 4px}\r\n.brand-s{font-size:12.5px;color:var(--ink-faint);margin:0 0 24px;line-height:1.5}\r\nnav a{display:block;text-decoration:none;color:var(--ink-soft);border-left:2px solid transparent;\r\n  padding:3px 0 3px 12px;font-size:13.5px;transition:color .15s,border-color .15s}\r\nnav a:hover{color:var(--ink)}\r\nnav a.nav-h1{margin-top:16px;font-weight:700;color:var(--ink);font-size:13px;\r\n  font-family:var(--mono);letter-spacing:.02em}\r\nnav a.nav-h2{font-size:13px}\r\nnav a.active{color:var(--teal-d);border-left-color:var(--teal);font-weight:600}\r\n\r\n/* headings */\r\nh1.modhead{font-size:13px;font-family:var(--mono);letter-spacing:.06em;text-transform:uppercase;\r\n  color:var(--teal);margin:72px 0 0;padding-top:28px;border-top:2px solid var(--ink);\r\n  font-weight:700}\r\nh1.modhead::after{content:attr(data-full);display:block;font-family:var(--sans);\r\n  font-size:30px;letter-spacing:-.01em;text-transform:none;color:var(--ink);\r\n  margin-top:8px;font-weight:750;line-height:1.2}\r\nh1.modhead{font-size:0}            /* hide raw, show via ::after */\r\nh1.modhead.intro{font-size:13px}\r\nh2{font-size:21px;font-weight:720;letter-spacing:-.01em;margin:46px 0 14px;\r\n  padding-bottom:8px;border-bottom:1px solid var(--line)}\r\nh3{font-size:16.5px;font-weight:700;margin:32px 0 10px;color:var(--ink)}\r\nh2.starred,h3.starred{color:var(--teal-d)}\r\nh2.starred::before,h3.starred::before{content:\"★ \";color:var(--teal);font-size:.85em}\r\nh2.starred,h3.starred{}\r\n.main h1:first-of-type{margin-top:0}\r\n\r\np{margin:12px 0}\r\na{color:var(--teal-d)}\r\nstrong{font-weight:700;color:var(--ink)}\r\nul,ol{padding-left:22px;margin:12px 0}\r\nli{margin:5px 0}\r\nhr{border:none;border-top:1px solid var(--line);margin:40px 0}\r\n\r\n/* intro hero */\r\n.hero{background:linear-gradient(135deg,#0c5249,#127c71);color:#eafaf6;\r\n  border-radius:16px;padding:34px 36px;margin:0 0 14px}\r\n.hero .eyebrow{font-family:var(--mono);font-size:11px;letter-spacing:.16em;\r\n  text-transform:uppercase;color:#9fdfd2;margin-bottom:10px}\r\n.hero h1{font-size:32px;line-height:1.18;margin:0 0 12px;font-weight:780;letter-spacing:-.02em}\r\n.hero p{margin:0;color:#cfeee7;font-size:14.5px;line-height:1.6}\r\n\r\n/* tables */\r\ntable{width:100%;border-collapse:collapse;margin:18px 0;font-size:14px;\r\n  border:1px solid var(--line);border-radius:var(--rad);overflow:hidden}\r\nthead th{background:var(--teal-bg);color:var(--teal-d);text-align:left;\r\n  font-weight:700;padding:10px 13px;font-size:13px}\r\ntd{padding:10px 13px;border-top:1px solid var(--line-soft);vertical-align:top}\r\ntbody tr:nth-child(even){background:#fbfbf8}\r\n.tablescroll{overflow-x:auto}\r\n\r\n/* code */\r\n.codewrap{margin:16px 0;border:1px solid var(--line);border-radius:var(--rad);\r\n  overflow:hidden;background:var(--code-bg)}\r\n.codebar{display:flex;justify-content:space-between;align-items:center;\r\n  padding:7px 12px;background:#efeee7;border-bottom:1px solid var(--line)}\r\n.codelang{font-family:var(--mono);font-size:11px;letter-spacing:.08em;\r\n  text-transform:uppercase;color:var(--ink-faint);font-weight:600}\r\n.copybtn{font-family:var(--mono);font-size:11px;border:1px solid var(--line);\r\n  background:#fff;color:var(--ink-soft);padding:3px 11px;border-radius:6px;cursor:pointer;\r\n  transition:all .15s}\r\n.copybtn:hover{border-color:var(--teal);color:var(--teal-d)}\r\n.copybtn.ok{background:var(--teal);color:#fff;border-color:var(--teal)}\r\n.codewrap pre{margin:0;padding:0}\r\npre code,pre.hljs{display:block;padding:15px 16px;overflow-x:auto;\r\n  font-family:var(--mono);font-size:13px;line-height:1.6;background:var(--code-bg)!important}\r\n:not(pre)>code{font-family:var(--mono);font-size:.88em;background:#eeede6;\r\n  padding:1.5px 6px;border-radius:5px;color:var(--teal-d);white-space:nowrap}\r\n\r\n/* mermaid */\r\npre.mermaid{background:var(--panel);border:1px solid var(--line);border-radius:var(--rad);\r\n  padding:22px;margin:20px 0;text-align:center;overflow-x:auto;line-height:1.4}\r\n\r\n/* callouts */\r\n.callout{position:relative;margin:18px 0;padding:14px 18px 14px 18px;border-radius:10px;\r\n  border-left:4px solid var(--ink-faint);background:#f4f4ee;font-size:14.5px}\r\n.callout p{margin:8px 0}\r\n.callout p:first-of-type{margin-top:0}\r\n.callout p:last-child{margin-bottom:0}\r\n.callout-badge{display:inline-block;font-family:var(--mono);font-size:10.5px;\r\n  letter-spacing:.1em;text-transform:uppercase;font-weight:700;\r\n  padding:2px 9px;border-radius:20px;margin-bottom:8px}\r\n.callout-note{border-left-color:#9aa0a8;background:#f3f3ee}\r\n.callout-note .callout-badge{background:#e4e4dd;color:#5a6069}\r\n.callout-key{border-left-color:var(--teal);background:var(--teal-bg)}\r\n.callout-key .callout-badge{background:var(--teal);color:#fff}\r\n.callout-warn{border-left-color:var(--amber);background:var(--amber-bg)}\r\n.callout-warn .callout-badge{background:var(--amber);color:#fff}\r\n.callout-add{border-left-color:var(--teal-d);background:#e9f3f1}\r\n.callout-add .callout-badge{background:var(--teal-d);color:#fff}\r\n\r\n/* topbar (mobile) */\r\n.topbar{display:none}\r\n\r\n@media (max-width:880px){\r\n  .shell{grid-template-columns:1fr}\r\n  .side{position:fixed;z-index:40;top:0;left:0;width:84%;max-width:320px;height:100vh;\r\n    background:var(--panel);transform:translateX(-105%);transition:transform .25s;\r\n    box-shadow:0 0 40px rgba(0,0,0,.18)}\r\n  .side.open{transform:translateX(0)}\r\n  .main{padding:70px 22px 90px}\r\n  .topbar{display:flex;align-items:center;gap:12px;position:sticky;top:0;z-index:30;\r\n    background:rgba(250,250,246,.92);backdrop-filter:blur(8px);\r\n    padding:12px 18px;border-bottom:1px solid var(--line)}\r\n  .menubtn{font-family:var(--mono);font-size:13px;border:1px solid var(--line);\r\n    background:#fff;padding:6px 12px;border-radius:8px;cursor:pointer}\r\n  .topbar .tt{font-family:var(--mono);font-size:12px;color:var(--teal);letter-spacing:.05em}\r\n  .scrim{display:none;position:fixed;inset:0;background:rgba(0,0,0,.35);z-index:35}\r\n  .scrim.show{display:block}\r\n  h1.modhead::after{font-size:25px}\r\n  .hero h1{font-size:25px}\r\n  .main{max-width:100%}\r\n}\r\n\r\n/* ── 인쇄 / PDF 저장 (출력 시 목차 먼저 → 본문) ── */\r\n@media print{\r\n  @page{margin:14mm 12mm}\r\n  *{-webkit-print-color-adjust:exact;print-color-adjust:exact}\r\n  .topbar,.scrim,.menubtn,.copybtn{display:none!important}\r\n  .shell{display:block;max-width:none}\r\n  /* 화면용 사이드바는 인쇄에서 완전히 숨김 (변환 불안정 → 빈 페이지 방지) */\r\n  .side{display:none!important}\r\n  /* 인쇄 전용 목차: 본문 맨 앞 일반 블록으로 깔끔히 출력 후 페이지 넘김 */\r\n  .print-toc{display:block!important;break-after:page;page-break-after:always}\r\n  .print-toc .ptoc-title{font-size:19pt;font-weight:800;color:#0c5249;letter-spacing:-.01em;\r\n    margin:0 0 16px;padding-bottom:10px;border-bottom:2px solid #127c71}\r\n  .print-toc a{display:block;color:#1b1e24;text-decoration:none;padding:3px 0;font-size:11.5pt;border:none}\r\n  .print-toc a.nav-h1{margin-top:13px;font-weight:700;color:#0c5249;font-size:12.5pt}\r\n  .print-toc a.nav-h2{padding-left:16px;color:#3a3f47}\r\n  /* 본문 */\r\n  .main{padding:0;max-width:none}\r\n  body{font-size:10.5pt;line-height:1.5;background:#fff}\r\n  a{text-decoration:none;color:inherit}\r\n  .hero{break-inside:avoid;background:#fff!important;color:#1b1e24!important;\r\n    border:none;border-bottom:2px solid #127c71;border-radius:0;\r\n    padding:0 0 14px!important;margin:0 0 18px}\r\n  .hero .eyebrow{color:#127c71!important}\r\n  .hero h1{color:#0c5249!important}\r\n  .hero p{color:#444!important}\r\n  /* 주제 헤더가 페이지 맨 아래 외롭게 걸리지 않게만 (새 페이지 강제는 빼서 빈 페이지 방지) */\r\n  h1.modhead{break-after:avoid;page-break-after:avoid}\r\n  h2,h3{break-after:avoid;page-break-after:avoid}\r\n  /* 코드·콜아웃·표·다이어그램은 페이지 중간에서 잘리지 않게 */\r\n  .codewrap,.callout,pre.mermaid,.tablescroll,table{break-inside:avoid;page-break-inside:avoid}\r\n  pre code,pre.hljs{white-space:pre-wrap;word-break:break-word}\r\n  pre.mermaid{text-align:center;border:1px solid #ddd;padding:12px 8px;margin:14px auto}\r\n  pre.mermaid svg{max-width:100%!important;height:auto!important;\r\n    max-height:200mm!important;display:inline-block!important}\r\n  .codewrap{border-color:#ccc}\r\n}\r\n</style>\r\n</head>\r\n<body>\r\n<div class=\"topbar\">\r\n  <button class=\"menubtn\" id=\"menubtn\" aria-label=\"목차 열기\">☰ 목차</button>\r\n  <span class=\"tt\">강의노트 · 보강판</span>\r\n</div>\r\n<div class=\"scrim\" id=\"scrim\"></div>\r\n<div class=\"shell\">\r\n  <aside class=\"side\" id=\"side\">\r\n    <div class=\"brand\">강의노트 · 04회차</div>\r\n    <p class=\"brand-t\">4회차 — 바이브 코딩 1: 데이터 시각화 (데이터 사이언스 풀 사이클)</p>\r\n    <p class=\"brand-s\">현장 강의 · 기술 보강판</p>\r\n    <nav id=\"nav\">\r\n<a class=\"nav-h1\" href=\"#part-1\">Part 1. 오전 — 데이터 사이언스 &#x27;지도&#x27; 그리기</a>\r\n<a class=\"nav-h2\" href=\"#1-vs\">1. 데이터 사이언스란 — 통계 vs 컴퓨터과학, 그리고 도메인</a>\r\n<a class=\"nav-h2\" href=\"#2\">2. 알아야 할 기본기 스택</a>\r\n<a class=\"nav-h2\" href=\"#3-5\">3. 데이터 사이언스 5단계 프레임워크</a>\r\n<a class=\"nav-h2\" href=\"#4\">4. 민간 데이터 직군 지도</a>\r\n<a class=\"nav-h2\" href=\"#5\">5. 트렌드 한 바퀴</a>\r\n<a class=\"nav-h1\" href=\"#part-2-ax-mba\">Part 2. 오후 — 공공 AX MBA 케이스 풀 사이클 실습</a>\r\n<a class=\"nav-h2\" href=\"#6-620\">6. 케이스 셋업 — 민원 데이터 620만 건</a>\r\n<a class=\"nav-h2\" href=\"#7-prd\">7. 딜리버러블 &amp;amp; PRD / 문제 정의</a>\r\n<a class=\"nav-h2\" href=\"#8-colab\">8. 실습 환경 — Colab + 구글 드라이브</a>\r\n<a class=\"nav-h2\" href=\"#9-csv-parquet-db\">9. 데이터 엔지니어링 — CSV → Parquet → DB</a>\r\n<a class=\"nav-h2\" href=\"#10-rag\">10. RAG 청킹 전략 — 실무에서 품질을 가르는 곳</a>\r\n<a class=\"nav-h2\" href=\"#11-ai\">11. AI 부채 — &quot;기술 부채보다 까다로운&quot;</a>\r\n<a class=\"nav-h2\" href=\"#12\">12. 시각화</a>\r\n<a class=\"nav-h2\" href=\"#13\">13. 모델링 — 머신러닝 기초 한 바퀴</a>\r\n<a class=\"nav-h2\" href=\"#14-slm-ai\">14. 마무리 — 폐쇄망·SLM·소버린 AI</a>\r\n<a class=\"nav-h1\" href=\"#_1\">부록 — 도구 · 개념 맵</a>\r\n<a class=\"nav-h2\" href=\"#_2\">검색 보강 출처</a>\r\n    </nav>\r\n  </aside>\r\n  <main class=\"main\" id=\"main\">\r\n<nav class=\"print-toc\">\r\n<div class=\"ptoc-title\">목차</div>\r\n<a class=\"nav-h1\" href=\"#part-1\">Part 1. 오전 — 데이터 사이언스 &#x27;지도&#x27; 그리기</a>\r\n<a class=\"nav-h2\" href=\"#1-vs\">1. 데이터 사이언스란 — 통계 vs 컴퓨터과학, 그리고 도메인</a>\r\n<a class=\"nav-h2\" href=\"#2\">2. 알아야 할 기본기 스택</a>\r\n<a class=\"nav-h2\" href=\"#3-5\">3. 데이터 사이언스 5단계 프레임워크</a>\r\n<a class=\"nav-h2\" href=\"#4\">4. 민간 데이터 직군 지도</a>\r\n<a class=\"nav-h2\" href=\"#5\">5. 트렌드 한 바퀴</a>\r\n<a class=\"nav-h1\" href=\"#part-2-ax-mba\">Part 2. 오후 — 공공 AX MBA 케이스 풀 사이클 실습</a>\r\n<a class=\"nav-h2\" href=\"#6-620\">6. 케이스 셋업 — 민원 데이터 620만 건</a>\r\n<a class=\"nav-h2\" href=\"#7-prd\">7. 딜리버러블 &amp;amp; PRD / 문제 정의</a>\r\n<a class=\"nav-h2\" href=\"#8-colab\">8. 실습 환경 — Colab + 구글 드라이브</a>\r\n<a class=\"nav-h2\" href=\"#9-csv-parquet-db\">9. 데이터 엔지니어링 — CSV → Parquet → DB</a>\r\n<a class=\"nav-h2\" href=\"#10-rag\">10. RAG 청킹 전략 — 실무에서 품질을 가르는 곳</a>\r\n<a class=\"nav-h2\" href=\"#11-ai\">11. AI 부채 — &quot;기술 부채보다 까다로운&quot;</a>\r\n<a class=\"nav-h2\" href=\"#12\">12. 시각화</a>\r\n<a class=\"nav-h2\" href=\"#13\">13. 모델링 — 머신러닝 기초 한 바퀴</a>\r\n<a class=\"nav-h2\" href=\"#14-slm-ai\">14. 마무리 — 폐쇄망·SLM·소버린 AI</a>\r\n<a class=\"nav-h1\" href=\"#_1\">부록 — 도구 · 개념 맵</a>\r\n<a class=\"nav-h2\" href=\"#_2\">검색 보강 출처</a>\r\n</nav>\r\n    <div class=\"hero\">\r\n      <div class=\"eyebrow\">Lecture Note · 기술 보강판</div>\r\n      <h1>4회차 — 바이브 코딩 1: 데이터 시각화 (데이터 사이언스 풀 사이클)</h1>\r\n      <p>현장 강의를 기술적으로 보강한 학습 레퍼런스 — 강사의 의도는 살리고, 빠지거나 틀린 기술은 정확히 채웠습니다.</p>\r\n    </div>\r\n\r\n<p>이 강의 하나로 무엇을 할 수 있게 하려는가 →\r\n<strong>\"데이터 분석/데이터 사이언스의 전체 스펙트럼(질문→수집→EDA→모델링→스토리텔링, 그리고 엔지니어링→분석→시각화→모델링→배포의 풀 사이클)을 AI를 적극 써서 한 바퀴 돌려보고, '직접 푸는 사람'을 넘어 '시나리오와 데이터를 설계해 오케스트레이션하는 리더'의 관점을 잡는 것.\"</strong></p>\r\n<blockquote class=\"callout callout-key\"><span class=\"callout-badge\">핵심</span>\r\n<p>★ 이 회차는 강사가 직접 <strong>2부로</strong> 짰다. <strong>오전 = 데이터 사이언스 '지도' 그리기</strong>(무엇이고, 누가 하고, 트렌드는 뭔가), <strong>오후 = 공공 AX MBA 케이스로 풀 사이클 실습</strong>(엔지니어링→분석→시각화→모델링). 그래서 이 노트도 위계를 지어내지 않고 그 2부 구조를 그대로 따른다. 관통하는 태도 한 줄: <strong>\"AI로 진입장벽은 무너졌다. 그래서 더 따져야 한다 — 데이터 품질·청킹·검증·AI 부채. 그리고 푸는 사람보다 설계하는 리더가 돼라.\"</strong></p>\r\n<p><strong>보강 안내</strong> — 강사가 결과만 보여주고 건너뛴 부분은 실제 동작하는 명령어·코드로 채웠고, 헷갈리는 용어는 정의를 달았다. 강사가 이름만 흘린 강의·도구·인물은 웹으로 확인해 <code>(검색 보강)</code>으로 표시했다. 운영성 멘트(점심·쉬는시간·녹화 사고 등)는 노트에서 뺐고, 학습에 도움 되는 일화·사례는 살렸다.</p>\r\n</blockquote>\r\n<hr/>\r\n<h1 class=\"modhead\" data-full=\"Part 1. 오전 — 데이터 사이언스 '지도' 그리기\" id=\"part-1\">Part 1. 오전 — 데이터 사이언스 '지도' 그리기</h1>\r\n<h2 id=\"1-vs\">1. 데이터 사이언스란 — 통계 vs 컴퓨터과학, 그리고 도메인</h2>\r\n<p>데이터 사이언스는 <strong>멀티 디서플리너리(multidisciplinary, 여러 학문이 섞인)</strong> 분야다. 느낌대로 데이터를 끌어다 쓰는 게 아니라 과학적 방법으로 접근하는, 수십 년 정립된 학문이라는 게 출발점.</p>\r\n<p>역사적으로 두 진영이 끝없이 충돌했다.</p>\r\n<ul>\r\n<li><strong>통계</strong> — 샘플링으로 모수를 추정한다(출구조사 30~40개로 전체 득표율 추정). R 같은 통계 언어가 발달.</li>\r\n<li><strong>컴퓨터과학</strong> — \"다 때려넣고 다 계산한다.\" 빅데이터(3V: Volume·Velocity·Variety)와 무어의 법칙으로 CPU·GPU 값이 떨어지면서 득세. 머신러닝 알고리즘 안에 통계가 패키징되고, <strong>파이썬</strong>으로 표준이 잡혔다.</li>\r\n</ul>\r\n<blockquote class=\"callout callout-key\"><span class=\"callout-badge\">핵심</span>\r\n<p>★ <strong>진짜 중요한 한 축은 따로 있다 — 도메인 엑스퍼트(domain expert).</strong> 통계든 컴공이든 \"예측 91점, 92점\" 경쟁에만 혈안이면 정작 실무에서 안 먹힌다. 업을 가장 잘 아는 사람(여비 처리면 그 담당자)이 빠지면 모델이 아무리 좋아도 말짱 도루묵. LLM이 없던 시절엔 이들이 \"감은 있는데 내가 못 하니까\" 개발자에게 부탁하거나 엑셀로 돌렸는데, 지금은 그 장벽이 무너졌다.</p>\r\n</blockquote>\r\n<p><strong>알아둘 권위자들</strong> (검색 보강 포함):\r\n- <strong>요슈아 벤지오 / 제프리 힌턴 / 얀 르쿤</strong> — 딥러닝 3대 대부. 힌턴은 <strong>백프로파게이션(backpropagation, 오차를 거꾸로 전파해 가중치를 학습시키는 알고리즘)</strong> 연구로 2024년 노벨 물리학상.\r\n- <strong>앤드류 응(Andrew Ng)</strong> — 스탠퍼드 교수, <strong>Coursera</strong> 창업. 그의 '머신러닝' 강의가 입문 클래식(자막 있음, 무료 청강 가능, 인증서는 유료).\r\n- <strong>조경현</strong> — 한국 출신 NLP 대가, 벤지오·르쿤과 공동 연구, 메타 AI 리서치에도 참여.</p>\r\n<h2 id=\"2\">2. 알아야 할 기본기 스택</h2>\r\n<p>연구자까지 가려면 공부할 게 많지만, 리더가 상식으로 깔아둘 것들:</p>\r\n<ul>\r\n<li><strong>선형대수(linear algebra)</strong> — 딥러닝의 행렬 연산(닷 프로덕트, dot product)이 다 여기서 나온다. 요즘 무시되지만 펀더멘털.</li>\r\n<li><strong>DB</strong> — 백엔드엔 항상 DB가 물려 있다. 절대 안 없어지는 기술.</li>\r\n<li><strong>통계 기초</strong> — 추론통계, 베이즈 정리(나이브 베이즈 분류기) 등.</li>\r\n<li><strong>IT 베이직</strong> — 인코딩/디코딩 같은 것에 익숙해지기.</li>\r\n<li><strong>NLP vs 컴퓨터 비전</strong> — 예전엔 AI의 두 축. NLP(자연어 처리)의 대표 분야가 기계 번역(machine translation)인데 GPT 이후 거의 게임 끝. 비전은 <strong>OpenCV</strong>·오브젝트 디텍션으로 붐이 먼저 왔고, NLP는 RNN→CNN→<strong>트랜스포머</strong>로 도약.</li>\r\n<li><strong>빅데이터</strong> — 일반인이 떠올리는 빅데이터와 엔지니어 단위는 차원이 다르다. 테라 단위가 하루에 쏟아지면 <code>read_csv</code>로는 절대 안 된다. <strong>Hadoop·Spark</strong>로 분산 처리, 스트리밍은 <strong>Kafka</strong>(넷플릭스發).</li>\r\n</ul>\r\n<blockquote class=\"callout callout-add\"><span class=\"callout-badge\">보강</span>\r\n<p>보강 — <strong>메타인지로 AI에 묻기.</strong> 논문이 수학 기호로 빽빽해도, 이제 abstract만 떼서 \"이 두 번째 실험이 뭘 설계한 건지 모르겠다\"고 AI에 물으면 된다. \"내가 뭘 모르는지\"를 아는 메타인지가 AI 시대의 핵심 효율이다.</p>\r\n</blockquote>\r\n<h2 id=\"3-5\">3. 데이터 사이언스 5단계 프레임워크</h2>\r\n<p>실리콘밸리 데이터 사이언티스트들이 쓰는 접근. 강사가 정리한 다섯 단계:</p>\r\n<div class=\"codewrap\"><div class=\"codebar\"><span class=\"codelang\">code</span><button class=\"copybtn\" type=\"button\">복사</button></div><pre class=\"mermaid\">flowchart LR\r\n  Q[\"① 흥미로운 질문\"] --&gt; C[\"② 데이터 수집\"]\r\n  C --&gt; E[\"③ EDA&lt;br/&gt;(제로베이스 탐색)\"]\r\n  E --&gt; M[\"④ 모델링&lt;br/&gt;(전체의 10%)\"]\r\n  M --&gt; T[\"⑤ 스토리텔링&lt;br/&gt;(끝까지 남는 역량)\"]\r\n</pre></div>\r\n<ul>\r\n<li><strong>① 흥미로운 질문(interesting question)</strong> — 한국 사람들이 제일 어려워한다. 잘 맞히려고 질문을 쉽게 깔고 뒤를 화려하게 하려는 성향. 미국은 \"No가 없으니까\" 달의 주기와 조석 데이터를 짬뽕시키는 식의 자유로운 상상으로 접근. <strong>업무에서 마주치는 골목길 같은 작은 질문</strong>(예: PPT→PDF 변환 자동화)에서 찾는 게 중요.</li>\r\n<li><strong>③ EDA(Exploratory Data Analysis, 탐색적 데이터 분석)</strong> — 가정 없이 데이터를 있는 그대로 본다. \"이 변수는 이렇네, 결측값 많네.\" 제로베이스·크리티컬 마인드셋.</li>\r\n<li><strong>④ 모델링</strong> — 제일 재밌지만 <strong>프로젝트의 10%도 안 된다.</strong> 정해진 모델을 쓰니까. 앞단의 지저분한 전처리(천만 줄을 잘라 나누는 노가다)가 성패를 가른다.</li>\r\n<li><strong>⑤ 스토리텔링</strong> — AI 시대에 끝까지 남을 역량.</li>\r\n</ul>\r\n<blockquote class=\"callout callout-key\"><span class=\"callout-badge\">핵심</span>\r\n<p>★ <strong>스토리텔링이 왜 핵심인가.</strong> 유발 하라리의 『사피엔스』는 글로벌하게 \"다 아는 사실 나열\"이라 많이 까였지만, 그가 압도적 스토리텔러라 사랑받는다(시공간을 바꿔 흡입력을 만든다). 모든 영화 대본이 참고한다는 『천의 얼굴을 가진 영웅』처럼, 스토리에는 일반화된 패턴이 있다. <strong>분석 결과도 어떤 기세로 이야기하느냐에 따라 공감이 갈린다.</strong> AI가 문체는 흉내 내도, 사람 대 사람의 공감은 우리 몫. (UX도 같다 — 토스의 거대한 UX팀이 끊임없이 A/B 테스트로 \"왜 이 버튼을 안 쓰세요?\"를 묻는 이유.)</p>\r\n</blockquote>\r\n<h2 id=\"4\">4. 민간 데이터 직군 지도</h2>\r\n<p>LLM 이전엔 경계가 뚜렷했고 지금은 모호해졌지만, 역할 분담을 알아두면 협업·외주 협상에 유리하다.</p>\r\n<div class=\"codewrap\"><div class=\"codebar\"><span class=\"codelang\">code</span><button class=\"copybtn\" type=\"button\">복사</button></div><pre class=\"mermaid\">flowchart LR\r\n  PO[\"기획자 / PO&lt;br/&gt;서비스·로그 설계\"] --&gt; DE[\"데이터 엔지니어&lt;br/&gt;ETL · 파이프라인\"]\r\n  DE --&gt; DA[\"데이터 분석가(DA)&lt;br/&gt;SQL · 시각화\"]\r\n  DA --&gt; DS[\"데이터 사이언티스트&lt;br/&gt;논문 · 모델링\"]\r\n  DS --&gt; OPS[\"MLOps / LLMOps&lt;br/&gt;운영 · 하네스\"]\r\n</pre></div>\r\n<ul>\r\n<li><strong>기획자 / PO(Product Owner)</strong> — 어떤 서비스·기능을 만들지 설계(예: 쿠팡 새벽배송 프로덕트), 로그를 어떻게 남길지 잡는다.</li>\r\n<li><strong>데이터 엔지니어</strong> — <strong>ETL(Extract·Transform·Load)</strong> 파이프라인으로 데이터를 창고에 쌓는다. 화려함은 없지만 뒷단에서 시스템이 안 깨지게, 모니터링하며 어마어마하게 일한다.</li>\r\n<li><strong>데이터 분석가(DA)</strong> — 쌓인 DB에 <strong>SQL</strong> 쿼리를 날려 JOIN·집계해서 보고용 분석. 마케터가 마케팅테크(MarTech)로 많이 유입.</li>\r\n<li><strong>데이터 사이언티스트</strong> — 알고리즘을 알고 예측/분류. <strong>논문 스터디</strong>가 일상. 새 모델(비전 트랜스포머 등)이 뜨면 빠르게 본다.</li>\r\n<li><strong>MLOps / LLMOps / AIOps 엔지니어</strong> — 모델을 운영에 심어 안 끊기게 돌린다. <strong>하네스(harness)</strong> 전체를 본다. AI 지식보다 컴공 지식이 많은 편(서버·스토리지·아키텍처).</li>\r\n</ul>\r\n<blockquote class=\"callout callout-add\"><span class=\"callout-badge\">보강</span>\r\n<p>보강 — <strong>Papers with Code &amp; SOTA.</strong> <a href=\"https://paperswithcode.com\">paperswithcode.com</a>은 논문과 구현 코드(GitHub)를 같이 주는 사이트. AI 팀은 새 논문이 뜨면 레포를 fork/clone해 GPU에 올려 우리 도메인에서 몇 점 나오는지 평가한다. <strong>SOTA(State Of The Art)</strong> = 현재 1등·최신. \"지금 SOTA가 Claude냐 GPT냐\"처럼 쓴다.</p>\r\n<p>보강 — <strong>3관점을 삼각형으로.</strong> 1등 IT 기업('네카라쿠배당토')의 구조는 대개 <strong>엔지니어 + 기획자(PO) + 디자이너</strong> 셋. 코딩이 재밌어 빠지더라도, 서비스를 하려면 <strong>디자인(감성·UX)</strong>, <strong>기획(사용자 니즈·requirement를 집요하게 파기)</strong>, <strong>엔지니어링</strong> 세 관점을 늘 함께 그려야 한다.</p>\r\n</blockquote>\r\n<h2 id=\"5\">5. 트렌드 한 바퀴</h2>\r\n<p>먼저 큰 그림: <strong>AI ⊃ 머신러닝 ⊃ 딥러닝</strong> (AI가 가장 넓은 개념, 그 안에 ML, 그 안에 DL).</p>\r\n<p><strong>피지컬 AI(Physical AI)</strong> — 실물로 들어오는 AI.\r\n- <strong>현대차 + 보스턴 다이내믹스 '아틀라스(Atlas)'</strong>의 월드컵 축구 캠페인 영상(이노션 기획). 손흥민 동작을 학습시켰고, 일부러 실패→다시 일으키는 장면으로 공감을 짠다 — 이게 피지컬 AI를 와닿게 하는 스토리텔링.\r\n- 테슬라의 <strong>오브젝트 디텍션(object detection)</strong> — 사람·사물에 네모 박스를 그려 인식하는 자율주행 기술.\r\n- <strong>드론</strong>은 <strong>라즈베리 파이(Raspberry Pi)</strong> 같은 환경에서 코딩해 띄운다.</p>\r\n<p><strong>최신 동향</strong> (검색 보강):\r\n- <strong>메타 AI + 레이밴·오클리 스마트글라스</strong> — meta.ai는 강사 평으로 아직 별로(한글 깨짐)지만, 스마트글라스는 의외로 잘나간다. 『History of the Future』는 이 기술을 만든 고졸 청년이 메타에 인수되기까지의 일화.\r\n- <strong>AI 타임즈</strong> — 국내 AI 소식 매일 체크 추천.\r\n- <strong>구글 I/O &amp; Gemini</strong> — 컨퍼런스에서 라인업을 싹 갈아엎었다. Gemini 3.1 Flash(라이트) 등 공개, <strong>Gemini 3.5 Pro는 내부 테스트 중 미공개</strong>. (검색 보강: 2026년 구글이 Gemini 3.x 세대로 개편 중.)\r\n- <strong>Antigravity 2.0</strong> — 구글의 코딩 플랫폼이 <strong>두 제품으로 분리</strong>됐다. ① <strong>Antigravity IDE</strong>(VS Code 같은 비주얼 코딩) ② <strong>Antigravity AI Agent</strong>(파일·폴더 개념 없이 채팅만 하는 헤드리스 에이전트, Gemini 3.5 Flash/Pro 기반). 자동 마이그레이션이 잘 안 돼 새로 까는 걸 권함. 무료는 Flash 모델만, Pro는 유료. (검색 보강: codingchefs·geeky-gadgets, 2026년 5월 분리.)</p>\r\n<blockquote class=\"callout callout-key\"><span class=\"callout-badge\">핵심</span>\r\n<p>★ <strong>안드레이 카파시(Andrej Karpathy) 어록</strong> (검색 보강) — 테슬라 FSD/오토파일럿 비전을 만들고 OpenAI 창립 멤버였던 그가 <strong>2026년 5월 19일 Anthropic 합류</strong>(Claude로 다음 세대 프리트레이닝을 가속하는 팀, Eureka Labs 22개월을 접고). 세계 최고 엔지니어가 던진 말들:\r\n- <strong>\"가장 핫한 개발 언어는 영어(자연어)다.\"</strong> 코드를 몰라도 된다. <strong>생각의 명료함·정밀도</strong>가 코딩 실력보다 중요한 시대.\r\n- <strong>\"AI는 기업이 아닌 개인에게 더 큰 힘을 주는 첫 기술이다.\"</strong> 역사상 모든 기술은 정부·대기업이 먼저 쥐었는데, AI는 처음으로 그 공식을 뒤집었다.\r\n- <strong>\"지금 AI 채팅창은 1960년대 메인프레임 터미널 수준.\"</strong> 개인용 컴퓨터·마우스·아이폰에 해당하는 건 아직 발명도 안 됐다. <strong>LLM 자체가 새로운 운영체제(OS)</strong> — 텍스트로 검색·계산·코드실행 등 모든 도구를 조율하는 중심 두뇌.\r\n- <strong>\"코드는 이제 공짜고, 일회용이고, 버려도 된다.\"</strong> 짜는 비용이 0에 가까워지면 코드는 평생 유지보수할 자산이 아니라 쓰고 버리는 냅킨.\r\n- <strong>\"세계 최고인 나도 뒤처진 느낌을 받는다 — 네 불안은 무능의 증거가 아니라 시대가 빠른 것.\"</strong> 지금 있는 걸 제대로 <strong>연결(오케스트레이션)</strong>만 해도 10배는 세진다.</p>\r\n</blockquote>\r\n<hr/>\r\n<h1 class=\"modhead\" data-full=\"Part 2. 오후 — 공공 AX MBA 케이스 풀 사이클 실습\" id=\"part-2-ax-mba\">Part 2. 오후 — 공공 AX MBA 케이스 풀 사이클 실습</h1>\r\n<h2 id=\"6-620\">6. 케이스 셋업 — 민원 데이터 620만 건</h2>\r\n<p>강사가 만든 <strong>'퍼블릭 AX MBA 케이스 스터디'</strong>. 가칭 '국민서비스진흥원'(보건복지부 산하 준정부기관)의 민원 처리 문제.</p>\r\n<ul>\r\n<li>연 120만 건, 4개 채널(포털·콜센터·방문·앱), 민원 6개 대분류·240개 세부유형.</li>\r\n<li>민원 만족도 평가 87개 기관 중 61등, <strong>재접수율 18.7%</strong>(유사기관 평균 9.3%의 두 배). 재접수의 73%가 72시간 내.</li>\r\n<li>5년치 <strong>약 620만 건</strong>(34개 필드, 약 700~800MB CSV)이 온프레미스 오라클 DB/CSV에 적재. 코드 체계 개편·결측으로 바로 분석 불가.</li>\r\n<li>분석팀 4명에 전담 엔지니어 없음 → SQL·엑셀 '노가다'로 건당 3~5일, 재현성 없음.</li>\r\n</ul>\r\n<blockquote class=\"callout callout-key\"><span class=\"callout-badge\">핵심</span>\r\n<p>★ <strong>이 케이스 데이터는 AI가 합성(생성)한 것이다 — '역설계'.</strong> 강사는 시나리오를 먼저 짜고, 거기 맞는 데이터를 프롬프트로 생성시켰다(620만 줄을 20만씩 찍으며 생성, 결측·재접수 분포까지 현실적으로 섞고, 품질 검증 리포트와 CSV/Parquet 변환까지 한 방에). <strong>리더가 가져갈 관점은 \"직접 푸는 사람\"이 아니라 \"시나리오+데이터를 설계해 제공·오케스트레이션하는 사람\"이다.</strong></p>\r\n<p>보강 — <strong>합성 데이터의 실전 가치(폐쇄망 우회).</strong> 보안상 실데이터를 못 빼낼 때, 엑셀 <strong>헤더 컬럼만</strong> 스크린샷으로 주거나 기억하는 필드값으로 \"이 기관 데이터 비슷하게 500줄만 가상 생성해줘\" 하면 된다. 그러면 바깥(폐쇄망 밖)에서 테스트·조립해 안으로 들여올 수 있다. 코드는 모듈화해 <strong>PyInstaller</strong> 등으로 보안에 안 걸리는 형태로 돌리는 방법도.</p>\r\n</blockquote>\r\n<h2 id=\"7-prd\">7. 딜리버러블 &amp; PRD / 문제 정의</h2>\r\n<p>강사가 정한 딜리버러블(끝점을 먼저 상상하는 게 중요 — 분석은 빠지면 시간만 간다):</p>\r\n<ol>\r\n<li><strong>AI 파워드 PRD</strong> 작성</li>\r\n<li><strong>Parquet vs CSV 기술 검증</strong>(PoC) 리포트</li>\r\n<li><strong>SQLite 적재 + SQL</strong> 쿼리 확인</li>\r\n<li><strong>EDA·시각화</strong></li>\r\n<li><strong>예측 모델</strong>(랜덤포레스트·XGBoost·LightGBM 앙상블)</li>\r\n<li>(욕심) 프론트엔드 샘플 서빙 → <strong>Ollama 로컬 LLM</strong>까지 엔드 투 엔드</li>\r\n</ol>\r\n<p><strong>PRD(Product Requirement Document)</strong> = 요구사항 정의서. 케이스의 페인포인트를 보고 필요한 기능·서버·통신을 기획 관점으로 적는다. 회사마다 양식이 다르니 정답은 없지만 기본은 \"요구사항을 잘 정리\".</p>\r\n<blockquote class=\"callout callout-key\"><span class=\"callout-badge\">핵심</span>\r\n<p>★ <strong>PRD의 핵심 두 가지.</strong> ① <strong>KPI는 반드시 숫자로</strong>(quantify). ② <strong>아웃 오브 스코프(out of scope, \"이건 안 한다\")를 명시</strong>하라. 이걸 안 적으면 자꾸 끼워넣다 끝이 없어진다. PRD는 거의 <strong>SOW(Scope of Work, 작업 범위)</strong> = 계약서에 가깝게 디테일하게.</p>\r\n</blockquote>\r\n<p><strong>문제 정의 프레임워크들</strong> (AI에 프롬프트로 심으면 강력):\r\n- <strong>『기획의 정석』식</strong> — 최상의 이상적 꼴과 현재 As-Is의 <strong>갭(차이)을 파고든다.</strong> \"왜 차이가 나는가\"로 원인을 빼고, 우선순위로 가능/불가능을 나눠 풀 수 있는 스코프를 정의.\r\n- <strong>As-Is / To-Be</strong> — 현재와 향후.\r\n- <strong>P&amp;S(Problem &amp; Solution)</strong> — 솔루션을 다각도로.\r\n- <strong>맥킨지 7 steps</strong> — 신입이 6개월 배우는 무적 프레임워크. 문제 기술 → <strong>이슈 트리(issue tree)</strong> → <strong>key/non-key 구분</strong>(= 스코프 아웃) → WBS 워크플랜 → 가설·종합 → 장표 수렴.</p>\r\n<blockquote class=\"callout callout-key\"><span class=\"callout-badge\">핵심</span>\r\n<p>★ <strong>AX 리더의 포지션.</strong> \"내 머리로 다 한다\"가 아니라, <strong>이미 초고수들이 만든 프레임워크를 큐레이션해 프롬프트로 엮는 것.</strong> \"탑티어 컨설팅 펌 프레임워크 30개 줘 → 우리 상황에 맞는 5개 꼽아 → 그걸로 PRD 만들어\"처럼 메타 관점으로 부린다. (맥킨지는 전략은 강해도 IT/시스템 requirement는 약한데, 그 빈틈도 LLM이 메운다.)</p>\r\n</blockquote>\r\n<h2 id=\"8-colab\">8. 실습 환경 — Colab + 구글 드라이브</h2>\r\n<p>웹에서 바로 되는 <strong>구글 코랩(Colab)</strong>으로 시연(VS Code·opencode·Antigravity로 해도 무방). 코랩은 구글 드라이브가 기본적으로 안 붙어 있어 마운트가 필요하다.</p>\r\n<div class=\"codewrap\"><div class=\"codebar\"><span class=\"codelang\">python</span><button class=\"copybtn\" type=\"button\">복사</button></div><pre><code class=\"language-python\"># 1) 구글 드라이브 마운트 (왼쪽에 폴더가 생기고 액세스 허용을 묻는다)\r\nfrom google.colab import drive\r\ndrive.mount(\"/content/drive\")\r\n# 2) 파일 경로 확인: 왼쪽 폴더에서 점 3개(⋮) → 'Copy path'\r\n#    예) /content/drive/MyDrive/&lt;폴더&gt;/complaints.csv\r\n</code></pre></div>\r\n<blockquote class=\"callout callout-key\"><span class=\"callout-badge\">핵심</span>\r\n<p>★ 환경 세팅은 \"가장 편한 상태\"로 먼저 박아두는 게 중요하다. 계속 환경을 만지면 분석 자체에 집중이 안 된다.</p>\r\n<p>보강 — <strong>현장 베스트 케이스(공유).</strong> 한 수강생은 <strong>Codex + Claude Code에 병렬 에이전트 10개</strong>(에이전트 A~H로 일을 쪼개)를 펴서 PRD→엔지니어링→서빙·검증까지 <strong>한 큐에</strong> 끝냈다. 또 한 명은 <strong>MCP로 Notion을 연동</strong>해 각 과제를 별도 페이지로 자동 정리(TensorFlow.js 웹 서빙까지). 강사도 \"강의하면서 처음 봤다\"며 멈칫. → <strong>플랜을 먼저 설계하고 작업을 덩어리로 쪼개 병렬 에이전트에 위임</strong>하는 게 핵심.</p>\r\n</blockquote>\r\n<h2 id=\"9-csv-parquet-db\">9. 데이터 엔지니어링 — CSV → Parquet → DB</h2>\r\n<p>실습의 척추. 큰 CSV를 그냥 읽지 말고 빅데이터식으로 다뤄보자.</p>\r\n<div class=\"codewrap\"><div class=\"codebar\"><span class=\"codelang\">code</span><button class=\"copybtn\" type=\"button\">복사</button></div><pre class=\"mermaid\">flowchart LR\r\n  C[\"CSV 원본&lt;br/&gt;620만 건\"] --&gt; P[\"Parquet 변환&lt;br/&gt;(빠른 적재)\"]\r\n  P --&gt; D[\"SQLite / 오라클&lt;br/&gt;DB 적재\"]\r\n  D --&gt; A[\"EDA · SQL 집계 · 시각화\"]\r\n  D --&gt; M[\"모델링&lt;br/&gt;(앙상블 예측)\"]\r\n  A --&gt; S[\"대시보드 / 보고\"]\r\n  M --&gt; S\r\n</pre></div>\r\n<p><strong>(A) Parquet vs CSV 속도 검증</strong> — Parquet은 컬럼 기반의 빅데이터 형식. 클라우드 전처리에선 거의 기본.</p>\r\n<div class=\"codewrap\"><div class=\"codebar\"><span class=\"codelang\">python</span><button class=\"copybtn\" type=\"button\">복사</button></div><pre><code class=\"language-python\">import pandas as pd, time\r\ndf = pd.read_csv(\"complaints.csv\")                 # (먼저 한 번 로드)\r\ndf.to_parquet(\"complaints.parquet\")                # 변환 (pip install pyarrow)\r\n\r\nt = time.time(); pd.read_csv(\"complaints.csv\");      csv_t = time.time() - t\r\nt = time.time(); pd.read_parquet(\"complaints.parquet\"); pq_t = time.time() - t\r\nprint(f\"CSV {csv_t:.2f}s vs Parquet {pq_t:.2f}s → {csv_t/pq_t:.1f}배\")\r\n# 강사 환경에선 60만 줄 기준 약 2.6배 빠름\r\n</code></pre></div>\r\n<p><strong>(B) SQLite 적재 + SQL</strong> — SQLite는 가벼운 단일파일 DB(원래 모바일용). PoC·로컬에 적합.</p>\r\n<div class=\"codewrap\"><div class=\"codebar\"><span class=\"codelang\">python</span><button class=\"copybtn\" type=\"button\">복사</button></div><pre><code class=\"language-python\">import sqlite3\r\nconn = sqlite3.connect(\"pipeline.db\")              # 드라이브에 .db 파일 생성\r\ndf.to_sql(\"complaints\", conn, if_exists=\"replace\", index=False)   # 적재\r\ntop3 = pd.read_sql(\r\n    \"SELECT 민원유형, COUNT(*) c FROM complaints GROUP BY 민원유형 ORDER BY c DESC LIMIT 3\", conn)\r\nprint(top3)   # 예: 이의신청 · 급여조정 · 제도문의\r\n</code></pre></div>\r\n<blockquote class=\"callout callout-add\"><span class=\"callout-badge\">보강</span>\r\n<p>보강 — <strong>pandas의 정체.</strong> 이름은 곰 판다가 아니라 계량경제의 <strong>panel data</strong>에서 왔다(\"파이썬 데이터 분석\"의 뜻도 겹친다). 엑셀처럼 다루는 도구이고, 근간은 <strong>NumPy</strong>. 대용량에서 느려지면 판다스를 걷어내고 <strong>NumPy 밑단에서 연산</strong>하면 코드가 바뀌며 한두 배 빨라진다(노하우).</p>\r\n</blockquote>\r\n<p><strong>아키텍처 관점</strong> — 로컬에선 한 줄씩 절차형으로 되지만 실전은 서버 단위로 복잡하다. 강사가 Mermaid로 아키텍처 3안을 그려봤다(<code>\"...아키텍처를 Mermaid로 도식화해줘\"</code>). 핵심 개념:</p>\r\n<ul>\r\n<li><strong>랜딩 존(landing zone) / 스테이징(staging)</strong> — 원본을 안 건드리고 중간 단계를 둬 끊김을 막는다.</li>\r\n<li><strong>ETL vs ELT</strong> — 고전은 Extract→Transform→Load, 실전은 Extract→Load 후 Transform(ELT)도 많다.</li>\r\n<li><strong>연계 서버</strong> — SAP 같은 운영 DB에 직접 붙으면 전체가 뻥난다. 중간에 연계 서버를 둬 파일을 떨궈주고 가져간다.</li>\r\n<li><strong>CDC(Change Data Capture, 증분 적재)</strong> — 변경분만 처리. 매번 전체 오버라이트하면 DB에 무리.</li>\r\n<li><strong>메달리온 아키텍처(Medallion Architecture)</strong> — 미국發 표준. 동·은·금 3층:</li>\r\n</ul>\r\n<div class=\"tablescroll\"><table>\r\n<thead>\r\n<tr>\r\n<th>레이어</th>\r\n<th>내용</th>\r\n</tr>\r\n</thead>\r\n<tbody>\r\n<tr>\r\n<td>🥉 브론즈(Bronze)</td>\r\n<td>원본 그대로 보존 (CSV)</td>\r\n</tr>\r\n<tr>\r\n<td>🥈 실버(Silver)</td>\r\n<td>정제된 Parquet, 스키마 표준화·결측·중복 처리</td>\r\n</tr>\r\n<tr>\r\n<td>🥇 골드(Gold)</td>\r\n<td>분석용 집계, 부서별 <strong>데이터 마트(data mart)</strong></td>\r\n</tr>\r\n</tbody>\r\n</table></div>\r\n<blockquote class=\"callout callout-warn\"><span class=\"callout-badge\">주의</span>\r\n<p>보강 — <strong>데이터 파이프라인 모니터링: Airflow.</strong> 파이프라인은 장애(끊김)가 가장 흔한 이슈인데, 그 재처리·모니터링을 <strong>Apache Airflow</strong>로 한다(현업 표준). 예전엔 리소스를 많이 먹어 인기가 없었지만 지금도 제일 많이 쓴다.</p>\r\n<p>보강 — <strong>DB 선택은 리더의 기술 검증 영역.</strong> 오라클(상용), <strong>PostgreSQL</strong>(오픈소스 최다 사용), SQLite/DuckDB(가벼운 PoC용). DB마다 SQL 문법이 조금씩 다르고 <strong>라이선스(MIT냐 GPL이냐, 연 비용)</strong> 이슈가 있다 — 예전엔 찾는 것도 일이었지만 이제 AI에 물으면 바로 나온다(GitHub에 명시).</p>\r\n<p>보강 — <strong>Matplotlib 한글 깨짐(□□□) 고치기 — 코랩.</strong> 코랩에서 자주 겪는 함정. 코드 스니펫을 떠 두면 편하다.\r\n<code>python\r\n!apt-get install -y fonts-nanum -q\r\nimport matplotlib.pyplot as plt, matplotlib.font_manager as fm\r\nfm.fontManager.addfont(\"/usr/share/fonts/truetype/nanum/NanumGothic.ttf\")\r\nplt.rcParams[\"font.family\"] = \"NanumGothic\"\r\nplt.rcParams[\"axes.unicode_minus\"] = False   # 마이너스 부호 깨짐 방지</code></p>\r\n</blockquote>\r\n<h2 id=\"10-rag\">10. RAG 청킹 전략 — 실무에서 품질을 가르는 곳</h2>\r\n<p>이 케이스를 넘어, 기관이 LLM 사업을 하면 십중팔구 <strong>RAG 챗봇</strong>을 만들게 된다. 그때 진짜 중요한 건 모델보다 <strong>청킹(chunking, 데이터를 어느 단위로 자를지)</strong>이다.</p>\r\n<blockquote class=\"callout callout-warn\"><span class=\"callout-badge\">주의</span>\r\n<p>★ <strong>청킹 스트래터지가 RAG 품질의 핵심.</strong> 엔지니어에게 그냥 맡기면 \"10줄마다\" 기계적으로 자른다 → 검색하면 엉뚱한 답. 맥락(법령이면 조·절 단위)을 살려 잘라야 한다. <strong>구분자를 넣고, 그 옆에 <code>## 맥락 레이블</code>(예: \"법인세법 부당행위계산 부인 관련\")을 살짝 달아주면 품질이 급상승.</strong> 강사가 은행법·증권법으로 이렇게 했더니 PoC에서 현업 전문가가 던지는 질문에 다 답이 나와 놀랐던 사례.</p>\r\n<p>⚠ 주의 — <strong>라벨링을 LLM에 시키기는 어렵다.</strong> 우리나라 법은 맥락이 \"조금만 봐야 하는 것\"과 \"뭉뚱그려 한 장을 봐야 하는 것\"이 섞여 있어, 기계적으로 자꾸 빗나간다 → 결국 사람이 한다(검수는 막판 말고 미리). 폐쇄망이라 <strong>파운데이션 모델(Foundation Model)</strong> 자체가 약하면 백날 던져도 안 되는 건 안 된다. 파서는 PDF/HWP를 마크다운이나 HTML로 변환하는 모듈을 잘 짜는 게 관건. (업스테이지 등이 RAG·문서 파싱에 강함.)</p>\r\n</blockquote>\r\n<h2 id=\"11-ai\">11. AI 부채 — \"기술 부채보다 까다로운\"</h2>\r\n<p>AI 타임즈 기사 소개. 기존 <strong>기술 부채</strong>(낡은 아키텍처·스파게티 코드·부실 문서)에 더해, AI 시대엔 새로운 부채가 쌓인다. AI는 다 <strong>확률 기반</strong>이라 오류가 미묘하고 <strong>비선형적</strong>으로 튀어나온다.</p>\r\n<ul>\r\n<li><strong>프롬프트 부채</strong> — 잘 먹히던 프롬프트가 어느 날 안 먹힌다. 충돌·버전관리 없이 누적되면 시스템 전체가 불안정. 거기에 <strong>프롬프트 스터핑(stuffing, 맥락을 억지로 욱여넣기)</strong>까지 더하면 유지보수 불가.</li>\r\n<li><strong>모델 의존성</strong> — \"GPT-4.5로 끝냈더니 다음 버전이 나와 답이 다 바뀐다.\" OpenAI·Anthropic·구글 API에 종속.</li>\r\n<li><strong>검색 부채</strong> — RAG 리트리버가 잘 땡겨오던 게 흔들리거나, 오래된 정보를 사실처럼 제시(환각보다 위험).</li>\r\n<li><strong>평가 부채</strong> — LLM이 \"잘한다\"의 기준이 모호. 기계적 지표(<strong>BLEU score</strong> 등)와 사람 평가가 따로 논다.</li>\r\n</ul>\r\n<blockquote class=\"callout callout-warn\"><span class=\"callout-badge\">주의</span>\r\n<p>보강 — <strong>LLM 평가/모니터링: Langfuse.</strong> LangChain 계열의 모니터링 플랫폼. LLM 서비스 뒤에 붙여 토큰·비용·프롬프트·응답을 다 기록하고, <strong>LLM-as-judge(LLM이 LLM을 평가)</strong> 파이프라인까지 돌린다. <strong>셀프 호스팅이 쉬워</strong> 우리 서버(지금 노트북에도)에 올려볼 수 있다.</p>\r\n<p>⚠ 주의 — <strong>그래서 룰 기반이 오히려 안전할 수 있다.</strong> AI는 \"여기가 고장 날 수도, 안 날 수도 있고요\"라 유지보수성(소프트웨어 공학의 핵심)이 흔들린다. AI 업계는 아직 <strong>CI/CD(배포 파이프라인)·QA 같은 검증 표준</strong>이 부족하다. 그래서 등장한 게 <strong>하네스(harness) 엔지니어링</strong> — 자원·프롬프트·사용자·모델버전·에이전트를 전체적으로 묶어 관리. 금융권 폐쇄망(계정계)은 여전히 함부로 못 건드린다.</p>\r\n</blockquote>\r\n<h2 id=\"12\">12. 시각화</h2>\r\n<p><strong>Power BI 애니메이션</strong> — 강사 단골 시연. 전 세계 시가총액 1등의 연도별 변화(MS→엑손모빌→애플→…→엔비디아)를 Power BI로 애니메이션. Tableau로는 거기까진 안 되고 Power BI가 다이내믹하게 잘 만든다.</p>\r\n<blockquote class=\"callout callout-add\"><span class=\"callout-badge\">보강</span>\r\n<p>보강 — <strong>시티즌 데이터 사이언티스트 사례(쿠팡이츠).</strong> 개발자도 아닌 배달 기사가 파이썬을 독학해(LLM 없던 시절) 쿠팡이츠 배달 단가를 시간대·지역별로 수집·시각화했다. \"단가는 천천히 오르고(분당 100~300원) 급하게 떨어진다(분당 500원)\"는 패턴까지 발견. 이런 <strong>다이내믹 프라이싱(dynamic pricing)</strong>은 우버·쿠팡이츠가 수요·공급으로 가격을 실시간 조정하는 최적화 문제(트래블링 세일즈맨 등)와 닿아 있다.</p>\r\n</blockquote>\r\n<p><strong>시각화 패키지</strong> — 어떤 차트가 내 데이터를 가장 잘 전달하느냐는 AI에 묻는 게 빠르다(\"차원과 측정값을 분리해서, 이 오디언스에게 딱 들어오는 차트로\").</p>\r\n<ul>\r\n<li><strong>Matplotlib</strong> — 파이썬 기본. 안 예쁘고 문법이 까다롭지만 다 그려진다.</li>\r\n<li><strong>Seaborn</strong> — 통계 시각화, 그나마 예쁨. 갤러리에 코드 스니펫 제공(조인트 플롯, 박스플롯 등).</li>\r\n<li><strong>Plotly</strong> — <strong>인터랙티브</strong>(클릭·줌). 더 예쁘지만 느릴 수 있다. Plotly Dash로 대시보드.</li>\r\n<li><strong>Folium</strong> — 지도 시각화. 위경도만 있으면 마커를 다 찍는다.</li>\r\n</ul>\r\n<div class=\"codewrap\"><div class=\"codebar\"><span class=\"codelang\">python</span><button class=\"copybtn\" type=\"button\">복사</button></div><pre><code class=\"language-python\">import folium\r\nm = folium.Map(location=[37.55, 126.98], zoom_start=11)   # 서울 중심\r\nfor name, lat, lon in places:                              # (이름, 위도, 경도)\r\n    folium.Marker([lat, lon], tooltip=name).add_to(m)\r\nm.save(\"seoul.html\")    # 단일 HTML로 저장 → 더블클릭하면 지도 열림\r\n</code></pre></div>\r\n<blockquote class=\"callout callout-warn\"><span class=\"callout-badge\">주의</span>\r\n<p>보강 — <strong>프론트엔드 코딩만으로도 시각화.</strong> 파이썬 없이 <strong>HTML/CSS/JS</strong> 단일 파일로 대시보드를 만들 수 있다(\"가상 데이터로 워드클라우드+차트 대시보드를 HTML 한 파일로 묶어줘\"). IDE 없이 <strong>메모장</strong>에 붙여넣고 <code>모든 파일</code>로 <code>dashboard.html</code> 저장 → 더블클릭이면 끝. <strong>Chart.js·Three.js</strong> 같은 강력한 프론트엔드 패키지가 많다.\r\n⚠ 폐쇄망 함정: 일부 프론트엔드 패키지는 <strong>CDN 통신</strong>이 필요하다. 폐쇄망에선 통신이 안 되니, <strong>CDN 없이 로컬에서 도는 패키지</strong>만 골라 리스트업하고 패키징해 들여와야 한다.</p>\r\n<p>보강 — <strong>OpenStreetMap.</strong> 빅테크가 지도를 유료화하려 할 때 한 유럽 개발자가 직접 모은 지도를 전 세계에 무료로 푼 프로젝트. Folium과 함께 쓰기 좋고, 학교·체육시설 같은 위치 데이터는 <strong>data.go.kr(공공데이터포털)</strong>에서 위경도를 받아 지도에 뿌리면 된다.</p>\r\n</blockquote>\r\n<h2 id=\"13\">13. 모델링 — 머신러닝 기초 한 바퀴</h2>\r\n<div class=\"codewrap\"><div class=\"codebar\"><span class=\"codelang\">code</span><button class=\"copybtn\" type=\"button\">복사</button></div><pre class=\"mermaid\">flowchart TD\r\n  ML[\"머신러닝\"] --&gt; SUP[\"지도학습&lt;br/&gt;(정답 있음)\"]\r\n  ML --&gt; UNS[\"비지도학습&lt;br/&gt;(정답 없음·군집)\"]\r\n  ML --&gt; RL[\"강화학습\"]\r\n  SUP --&gt; REG[\"회귀&lt;br/&gt;(연속값 예측)\"]\r\n  SUP --&gt; CLS[\"분류&lt;br/&gt;(범주 예측)\"]\r\n</pre></div>\r\n<ul>\r\n<li><strong>지도학습(supervised)</strong> — 정답(타겟)이 있다. <strong>회귀(regression)</strong>는 연속값(집값·시험점수·내일 주가) 예측, <strong>분류(classification)</strong>는 범주(개/고양이, 고위험/저위험) 예측. 실전 분류는 binary보다 멀티클래스가 많다.</li>\r\n<li><strong>비지도학습(unsupervised)</strong> — 타겟 없이 군집을 묶는다(클러스터링).</li>\r\n<li><strong>강화학습(reinforcement)</strong> — 보상으로 학습.</li>\r\n</ul>\r\n<p><strong>핵심 개념들:</strong>\r\n- <strong>오버피팅/언더피팅</strong> — 모의고사만 외워 수능을 못 풀면 오버피팅, 너무 안 풀어보면 언더피팅. 오버피팅 완화엔 <strong>드롭아웃(dropout)</strong> 등(데이터마다 다르니 돌려보고 판단). 아웃라이어에 덜 흔들리면 <strong>로버스트(robust)·일반화(generalization)</strong> 잘 된 모델.\r\n- <strong>경사 하강법(gradient descent)</strong> — 오차(잔차)를 줄이며 최적의 선을 찾는다. <strong>로컬 미니마/글로벌 미니마</strong>를 찾는 최적화 문제.\r\n- <strong>평가 지표</strong> — 회귀는 <strong>MSE·RMSE·MAE·R²</strong>(MSE는 제곱이라 미분 가능 → 경사하강 가능, 이상치에 민감). 분류는 <strong>혼동 행렬(confusion matrix)</strong>에서 accuracy·precision·recall·<strong>F1 score</strong>(프로젝트에서 제일 많이 씀).</p>\r\n<div class=\"codewrap\"><div class=\"codebar\"><span class=\"codelang\">python</span><button class=\"copybtn\" type=\"button\">복사</button></div><pre><code class=\"language-python\"># 앙상블 — 3개 모델을 soft voting(확률 평균)으로 묶기\r\nfrom sklearn.ensemble import RandomForestClassifier, VotingClassifier\r\nfrom xgboost import XGBClassifier\r\nfrom lightgbm import LGBMClassifier\r\n\r\nens = VotingClassifier(\r\n    estimators=[(\"rf\", RandomForestClassifier()),\r\n                (\"xgb\", XGBClassifier()),\r\n                (\"lgbm\", LGBMClassifier())],\r\n    voting=\"soft\", weights=[1, 1, 1])     # 동일 가중치(0.33씩)\r\nens.fit(X_train, y_train)\r\n\r\nimport joblib\r\njoblib.dump(ens, \"model.pkl\")             # 학습 모델을 pickle로 저장\r\nmodel = joblib.load(\"model.pkl\")          # 다음엔 학습 없이 즉시 로드\r\n</code></pre></div>\r\n<ul>\r\n<li><strong>피처 엔지니어링(feature engineering)</strong> — 여기서 <strong>피처 = 변수</strong>(개발의 '기능'과 다름). 파생변수를 만들어(곱·나눗셈, 이미지엔 \"반지 꼈음\" 같은 자연어 묘사 한 줄 추가) 모델이 더 잘 알아먹게. 『머신러닝을 위한 피처 엔지니어링』(O'Reilly) 참고.</li>\r\n<li><strong>샘플링</strong> — 620만 건을 다 넣기 부담되면 <strong>층화 추출(stratified sampling)</strong>로 레이블별 고르게. 분포가 치우치면(왜도, skewness) 로그 처리 등.</li>\r\n<li><strong>하이퍼파라미터 튜닝</strong> — 모델 안에서 조정하는 값(예: 최적이 0.15인지)을 <strong>그리드 서치/랜덤 서치</strong>로 찾는다. <strong>AutoML</strong>은 이를 자동화. (요즘은 LLM에 물어도 AutoML 이상으로 모델 추천을 잘 해준다 — 단, 데이터 메타정보를 같이 줘야 하고 <strong>human in the loop</strong>로 검증.)</li>\r\n<li><strong>체크포인트(checkpoint)</strong> — 학습이 끊겨도 그 시점부터 이어가게 저장(에폭 단위). 안 하면 0부터 다시.</li>\r\n<li><strong>피처 임포턴스(feature importance)</strong> — 어떤 변수가 예측에 제일 영향을 줬는지.</li>\r\n</ul>\r\n<blockquote class=\"callout callout-key\"><span class=\"callout-badge\">핵심</span>\r\n<p>★ <strong>초보자가 꼭 구분할 것 — LLM은 우리가 학습 못 시킨다.</strong> \"LLM을 우리가 학습시킨다\"는 틀린 말이다. 우리가 하는 건 <strong>RAG(데이터를 참조)</strong>이지 학습이 아니다. 진짜 '학습'은 백프로파게이션을 수십~수백조 파라미터로 도는 것 — 개인 컴퓨터로는 초기화(initialization)조차 안 된다. 또 모델이 값을 내는 <strong>인퍼런스(inference, 예측)</strong>와 LLM의 <strong>리즈닝(reasoning, CoT=Chain of Thought)</strong>은 전혀 다른 얘기. LLM은 보통 단일 파일이 아니라 분야별 서브셋이 모인 <strong>MoE(Mixture of Experts)</strong> 형태로 트레이닝·튜닝돼 있다.</p>\r\n</blockquote>\r\n<h2 id=\"14-slm-ai\">14. 마무리 — 폐쇄망·SLM·소버린 AI</h2>\r\n<p>현장 Q&amp;A에서 나온, 공공 실무자에게 가장 현실적인 이슈들.</p>\r\n<ul>\r\n<li><strong>STT(소방·재난)</strong> — 음성을 텍스트로(Speech-to-Text). 크리티컬한 현장이라 <strong>테스트 설계가 핵심</strong>(사투리·잡음·다양한 사람이 던져도 잘 나오는지). 퍼블릭 STT는 오픈 기준이라, 폐쇄망이면 <strong>SLM(소형 언어모델)</strong>을 Papers with Code 등에서 리서치해 한국어 인식을 벤치마크해야 한다.</li>\r\n<li><strong>Ollama 로컬 LLM</strong> — 폐쇄망에서 LLM을 직접 띄우는 표준 출발점.</li>\r\n</ul>\r\n<div class=\"codewrap\"><div class=\"codebar\"><span class=\"codelang\">Shell</span><button class=\"copybtn\" type=\"button\">복사</button></div><pre><code class=\"language-bash\">ollama run gemma3      # 모델을 받아 바로 대화 (로컬)\r\nollama serve           # 로컬 API 서버(http://localhost:11434)로 코드에서 호출\r\n</code></pre></div>\r\n<blockquote class=\"callout callout-warn\"><span class=\"callout-badge\">주의</span>\r\n<p>⚠ 사양 주의 — 강사 경험상 <strong>램 32GB는 돼야</strong> 쓸 만하다. 16GB는 빠듯. 노트북 사양을 먼저 확인하자. (폐쇄망 한국어 STT라면 오픈소스 <strong>faster-whisper</strong>를 로컬에 올려 벤치마크해보는 것도 자연스러운 선택.)</p>\r\n<p>⚠ 주의 — <strong>소버린(sovereign) AI 현실론.</strong> 한국어는 아직 작은 모델이 \"GPT의 70점만 나와도 성공\"이라 할 만큼 약하다. 스크래치부터 한국어를 트레이닝(업스테이지·네이버·NC 등)하는데, GPT는 이미 저 멀리 가 있어 비교가 쉽지 않다. 그럼에도 가치는 <strong>보안 프리(폐쇄망에서 그냥 쓸 수 있음)</strong>와 <strong>모델/데이터 주권</strong>(해외 업체가 가격을 200만 원으로 올리거나 특정 국가를 막으면 다 잠식). → <strong>PoC부터 작게.</strong> \"비전은 좋은데\"로 크게 시작 말고, \"이름 말하면 잘 나오나\"부터.</p>\r\n<p>★ <strong>오늘의 숙제(역설계).</strong> 분석을 끝까지 내라는 게 아니라, <strong>각자 기관의 데이터 문제로 케이스 시나리오를 짜고, 거기 맞는 가상 데이터(5MB 정도면 충분)를 생성해 \"문제집\"을 만들라</strong>는 것. 즉 <strong>문제 출제자(설계자)가 되라.</strong> 직접 코딩은 필수 아님.</p>\r\n</blockquote>\r\n<hr/>\r\n<h1 class=\"modhead\" data-full=\"부록 — 도구 · 개념 맵\" id=\"_1\">부록 — 도구 · 개념 맵</h1>\r\n<div class=\"tablescroll\"><table>\r\n<thead>\r\n<tr>\r\n<th>분류</th>\r\n<th>키워드</th>\r\n</tr>\r\n</thead>\r\n<tbody>\r\n<tr>\r\n<td>직군</td>\r\n<td>기획자/PO, 데이터 엔지니어(ETL), DA(SQL), 데이터 사이언티스트, MLOps/LLMOps</td>\r\n</tr>\r\n<tr>\r\n<td>엔지니어링</td>\r\n<td>CSV→Parquet→SQLite/오라클, Airflow, 메달리온(브론즈·실버·골드), CDC, 데이터 마트</td>\r\n</tr>\r\n<tr>\r\n<td>DB</td>\r\n<td>오라클, PostgreSQL, SQLite, DuckDB (+라이선스 검토)</td>\r\n</tr>\r\n<tr>\r\n<td>분석/시각화</td>\r\n<td>pandas(NumPy), Matplotlib, Seaborn, Plotly, Folium, OpenStreetMap, Power BI</td>\r\n</tr>\r\n<tr>\r\n<td>모델링</td>\r\n<td>회귀/분류, 앙상블(soft voting), pickle, checkpoint, 하이퍼파라미터 튜닝, AutoML, 피처 엔지니어링</td>\r\n</tr>\r\n<tr>\r\n<td>평가</td>\r\n<td>MSE·RMSE·MAE·R²(회귀), confusion matrix·F1(분류), BLEU·Langfuse·LLM-as-judge(LLM)</td>\r\n</tr>\r\n<tr>\r\n<td>RAG/운영</td>\r\n<td>청킹 전략·레이블링, 파운데이션 모델, 하네스 엔지니어링, AI 부채</td>\r\n</tr>\r\n<tr>\r\n<td>폐쇄망/로컬</td>\r\n<td>Ollama(32GB+), SLM, faster-whisper(STT), 합성 데이터, CDN 없는 프론트 패키지</td>\r\n</tr>\r\n<tr>\r\n<td>학습자료</td>\r\n<td>스탠퍼드 CME 295, 앤드류 응 Coursera, Papers with Code, 렉스 프리드먼 MIT 6.S094</td>\r\n</tr>\r\n</tbody>\r\n</table></div>\r\n<blockquote class=\"callout callout-add\"><span class=\"callout-badge\">보강</span>\r\n<p>보강 — <strong>추천 강의(검색 보강).</strong> <strong>스탠퍼드 CME 295 \"Transformers &amp; Large Language Models\"</strong>(Afshine·Shervine <strong>Amidi 쌍둥이</strong> 교수) — 트랜스포머·셀프어텐션부터 LLM 프롬프팅·파인튜닝·RAG·에이전트·LLM-as-judge까지 한 학기. 자료·시험·치트시트(GitHub <code>afshinea/stanford-cme-295...</code>)가 공개돼 \"스탠퍼드 학생처럼\" 공부 가능. <strong>렉스 프리드먼 MIT 6.S094</strong>(자율주행·컴퓨터비전)도 클래식. 자막+'YouTube Summary' 플러그인으로 GPT에 던져 스터디.</p>\r\n</blockquote>\r\n<h2 id=\"_2\">검색 보강 출처</h2>\r\n<ul>\r\n<li>안드레이 카파시 Anthropic 합류(2026-05-19): cnbc.com, en.wikipedia.org/wiki/Andrej_Karpathy</li>\r\n<li>구글 Antigravity 2.0 분리(IDE / AI Agent, Gemini 3.5): codingchefs.com, geeky-gadgets.com</li>\r\n<li>스탠퍼드 CME 295(Amidi 쌍둥이 교수): cme295.stanford.edu, github.com/afshinea/stanford-cme-295-transformers-large-language-models</li>\r\n</ul>\r\n  </main>\r\n</div>\r\n\r\n<script src=\"https://cdnjs.cloudflare.com/ajax/libs/highlight.js/11.9.0/highlight.min.js\"><\/script>\r\n<script src=\"https://cdnjs.cloudflare.com/ajax/libs/highlight.js/11.9.0/languages/powershell.min.js\"><\/script>\r\n<script src=\"https://cdnjs.cloudflare.com/ajax/libs/highlight.js/11.9.0/languages/vbscript.min.js\"><\/script>\r\n<script src=\"https://cdnjs.cloudflare.com/ajax/libs/mermaid/10.9.1/mermaid.min.js\"><\/script>\r\n<script>\r\n// 주제 헤더 raw 텍스트를 data-full로 옮겨 ::after 표시\r\ndocument.querySelectorAll('h1.modhead').forEach(function(h){\r\n  h.setAttribute('data-full', h.textContent);\r\n});\r\n\r\n// highlight.js\r\nif(window.hljs){\r\n  document.querySelectorAll('.codewrap pre code').forEach(function(b){\r\n    try{hljs.highlightElement(b);}catch(e){}\r\n  });\r\n}\r\n\r\n// mermaid\r\nif(window.mermaid){\r\n  mermaid.initialize({\r\n    startOnLoad:true, theme:'base',\r\n    htmlLabels:false,\r\n    themeVariables:{\r\n      fontFamily:'-apple-system,Pretendard,\"Malgun Gothic\",sans-serif',\r\n      fontSize:'13px',\r\n      primaryColor:'#e6f4f1', primaryBorderColor:'#127c71', primaryTextColor:'#0c5249',\r\n      lineColor:'#9aa0a8', secondaryColor:'#f4f1ea', tertiaryColor:'#fbf1e4',\r\n      clusterBkg:'#f6f6f0', clusterBorder:'#cfd3cb'\r\n    },\r\n    flowchart:{curve:'basis', useMaxWidth:true, htmlLabels:false},\r\n    sequence:{useMaxWidth:true}\r\n  });\r\n}\r\n\r\n// 복사 버튼\r\ndocument.querySelectorAll('.copybtn').forEach(function(btn){\r\n  btn.addEventListener('click', function(){\r\n    var code = btn.closest('.codewrap').querySelector('pre code');\r\n    var txt = code ? code.innerText : '';\r\n    navigator.clipboard.writeText(txt).then(function(){\r\n      btn.textContent='복사됨'; btn.classList.add('ok');\r\n      setTimeout(function(){btn.textContent='복사'; btn.classList.remove('ok');},1400);\r\n    });\r\n  });\r\n});\r\n\r\n// 스크롤 스파이\r\nvar links = Array.from(document.querySelectorAll('#nav a'));\r\nvar map = {};\r\nlinks.forEach(function(a){ map[a.getAttribute('href').slice(1)] = a; });\r\nvar heads = Array.from(document.querySelectorAll('.main h1[id], .main h2[id]'));\r\nvar spy = new IntersectionObserver(function(entries){\r\n  entries.forEach(function(en){\r\n    if(en.isIntersecting){\r\n      links.forEach(function(l){l.classList.remove('active');});\r\n      var act = map[en.target.id];\r\n      if(act){act.classList.add('active');\r\n        act.scrollIntoView({block:'nearest'});}\r\n    }\r\n  });\r\n}, {rootMargin:'-10% 0px -75% 0px', threshold:0});\r\nheads.forEach(function(h){spy.observe(h);});\r\n\r\n// 모바일 사이드바\r\nvar side=document.getElementById('side'), scrim=document.getElementById('scrim'),\r\n    mb=document.getElementById('menubtn');\r\nfunction toggle(open){side.classList.toggle('open',open);scrim.classList.toggle('show',open);}\r\nif(mb){mb.addEventListener('click',function(){toggle(!side.classList.contains('open'));});}\r\nif(scrim){scrim.addEventListener('click',function(){toggle(false);});}\r\nlinks.forEach(function(a){a.addEventListener('click',function(){if(window.innerWidth<=880)toggle(false);});});\r\n<\/script>\r\n</body>\r\n</html>\r\n","5":"<!DOCTYPE html>\r\n<html lang=\"ko\">\r\n<head>\r\n<meta charset=\"utf-8\">\r\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\r\n<title>5회차 — 바이브 코딩 2: 업무 자동화 (로컬 LLM·콘솔·엑셀)</title>\r\n<link rel=\"preconnect\" href=\"https://cdnjs.cloudflare.com\">\r\n<link rel=\"stylesheet\" href=\"https://cdnjs.cloudflare.com/ajax/libs/highlight.js/11.9.0/styles/github.min.css\">\r\n<style>\r\n:root{\r\n  --bg:#fafaf6; --panel:#ffffff; --ink:#1b1e24; --ink-soft:#5a6069; --ink-faint:#8b919b;\r\n  --line:#e7e6df; --line-soft:#f0efe9;\r\n  --teal:#127c71; --teal-d:#0c5249; --teal-bg:#e6f4f1;\r\n  --amber:#b9722a; --amber-bg:#fbf1e4;\r\n  --red:#c0392b; --red-bg:#fbe9e7;\r\n  --code-bg:#f6f6f0;\r\n  --mono:ui-monospace,\"SF Mono\",\"Cascadia Code\",\"JetBrains Mono\",Consolas,monospace;\r\n  --sans:-apple-system,BlinkMacSystemFont,\"Pretendard\",\"Apple SD Gothic Neo\",\"Segoe UI\",\"Malgun Gothic\",sans-serif;\r\n  --rad:12px;\r\n}\r\n*{box-sizing:border-box}\r\nhtml{scroll-behavior:smooth}\r\n@media (prefers-reduced-motion:reduce){html{scroll-behavior:auto}}\r\nbody{margin:0;background:var(--bg);color:var(--ink);font-family:var(--sans);\r\n  font-size:16px;line-height:1.72;-webkit-font-smoothing:antialiased}\r\n\r\n/* layout */\r\n.shell{display:grid;grid-template-columns:300px minmax(0,1fr);max-width:1240px;margin:0 auto}\r\n.print-toc{display:none}\r\n.side{position:sticky;top:0;align-self:start;height:100vh;overflow-y:auto;\r\n  padding:30px 22px 60px;border-right:1px solid var(--line)}\r\n.main{min-width:0;padding:46px 60px 120px;max-width:880px}\r\n\r\n/* sidebar */\r\n.brand{font-family:var(--mono);font-size:11px;letter-spacing:.14em;text-transform:uppercase;\r\n  color:var(--teal);margin-bottom:6px}\r\n.brand-t{font-weight:700;font-size:17px;line-height:1.35;margin:0 0 4px}\r\n.brand-s{font-size:12.5px;color:var(--ink-faint);margin:0 0 24px;line-height:1.5}\r\nnav a{display:block;text-decoration:none;color:var(--ink-soft);border-left:2px solid transparent;\r\n  padding:3px 0 3px 12px;font-size:13.5px;transition:color .15s,border-color .15s}\r\nnav a:hover{color:var(--ink)}\r\nnav a.nav-h1{margin-top:16px;font-weight:700;color:var(--ink);font-size:13px;\r\n  font-family:var(--mono);letter-spacing:.02em}\r\nnav a.nav-h2{font-size:13px}\r\nnav a.active{color:var(--teal-d);border-left-color:var(--teal);font-weight:600}\r\n\r\n/* headings */\r\nh1.modhead{font-size:13px;font-family:var(--mono);letter-spacing:.06em;text-transform:uppercase;\r\n  color:var(--teal);margin:72px 0 0;padding-top:28px;border-top:2px solid var(--ink);\r\n  font-weight:700}\r\nh1.modhead::after{content:attr(data-full);display:block;font-family:var(--sans);\r\n  font-size:30px;letter-spacing:-.01em;text-transform:none;color:var(--ink);\r\n  margin-top:8px;font-weight:750;line-height:1.2}\r\nh1.modhead{font-size:0}            /* hide raw, show via ::after */\r\nh1.modhead.intro{font-size:13px}\r\nh2{font-size:21px;font-weight:720;letter-spacing:-.01em;margin:46px 0 14px;\r\n  padding-bottom:8px;border-bottom:1px solid var(--line)}\r\nh3{font-size:16.5px;font-weight:700;margin:32px 0 10px;color:var(--ink)}\r\nh2.starred,h3.starred{color:var(--teal-d)}\r\nh2.starred::before,h3.starred::before{content:\"★ \";color:var(--teal);font-size:.85em}\r\nh2.starred,h3.starred{}\r\n.main h1:first-of-type{margin-top:0}\r\n\r\np{margin:12px 0}\r\na{color:var(--teal-d)}\r\nstrong{font-weight:700;color:var(--ink)}\r\nul,ol{padding-left:22px;margin:12px 0}\r\nli{margin:5px 0}\r\nhr{border:none;border-top:1px solid var(--line);margin:40px 0}\r\n\r\n/* intro hero */\r\n.hero{background:linear-gradient(135deg,#0c5249,#127c71);color:#eafaf6;\r\n  border-radius:16px;padding:34px 36px;margin:0 0 14px}\r\n.hero .eyebrow{font-family:var(--mono);font-size:11px;letter-spacing:.16em;\r\n  text-transform:uppercase;color:#9fdfd2;margin-bottom:10px}\r\n.hero h1{font-size:32px;line-height:1.18;margin:0 0 12px;font-weight:780;letter-spacing:-.02em}\r\n.hero p{margin:0;color:#cfeee7;font-size:14.5px;line-height:1.6}\r\n\r\n/* tables */\r\ntable{width:100%;border-collapse:collapse;margin:18px 0;font-size:14px;\r\n  border:1px solid var(--line);border-radius:var(--rad);overflow:hidden}\r\nthead th{background:var(--teal-bg);color:var(--teal-d);text-align:left;\r\n  font-weight:700;padding:10px 13px;font-size:13px}\r\ntd{padding:10px 13px;border-top:1px solid var(--line-soft);vertical-align:top}\r\ntbody tr:nth-child(even){background:#fbfbf8}\r\n.tablescroll{overflow-x:auto}\r\n\r\n/* code */\r\n.codewrap{margin:16px 0;border:1px solid var(--line);border-radius:var(--rad);\r\n  overflow:hidden;background:var(--code-bg)}\r\n.codebar{display:flex;justify-content:space-between;align-items:center;\r\n  padding:7px 12px;background:#efeee7;border-bottom:1px solid var(--line)}\r\n.codelang{font-family:var(--mono);font-size:11px;letter-spacing:.08em;\r\n  text-transform:uppercase;color:var(--ink-faint);font-weight:600}\r\n.copybtn{font-family:var(--mono);font-size:11px;border:1px solid var(--line);\r\n  background:#fff;color:var(--ink-soft);padding:3px 11px;border-radius:6px;cursor:pointer;\r\n  transition:all .15s}\r\n.copybtn:hover{border-color:var(--teal);color:var(--teal-d)}\r\n.copybtn.ok{background:var(--teal);color:#fff;border-color:var(--teal)}\r\n.codewrap pre{margin:0;padding:0}\r\npre code,pre.hljs{display:block;padding:15px 16px;overflow-x:auto;\r\n  font-family:var(--mono);font-size:13px;line-height:1.6;background:var(--code-bg)!important}\r\n:not(pre)>code{font-family:var(--mono);font-size:.88em;background:#eeede6;\r\n  padding:1.5px 6px;border-radius:5px;color:var(--teal-d);white-space:nowrap}\r\n\r\n/* mermaid */\r\npre.mermaid{background:var(--panel);border:1px solid var(--line);border-radius:var(--rad);\r\n  padding:22px;margin:20px 0;text-align:center;overflow-x:auto;line-height:1.4}\r\n\r\n/* callouts */\r\n.callout{position:relative;margin:18px 0;padding:14px 18px 14px 18px;border-radius:10px;\r\n  border-left:4px solid var(--ink-faint);background:#f4f4ee;font-size:14.5px}\r\n.callout p{margin:8px 0}\r\n.callout p:first-of-type{margin-top:0}\r\n.callout p:last-child{margin-bottom:0}\r\n.callout-badge{display:inline-block;font-family:var(--mono);font-size:10.5px;\r\n  letter-spacing:.1em;text-transform:uppercase;font-weight:700;\r\n  padding:2px 9px;border-radius:20px;margin-bottom:8px}\r\n.callout-note{border-left-color:#9aa0a8;background:#f3f3ee}\r\n.callout-note .callout-badge{background:#e4e4dd;color:#5a6069}\r\n.callout-key{border-left-color:var(--teal);background:var(--teal-bg)}\r\n.callout-key .callout-badge{background:var(--teal);color:#fff}\r\n.callout-warn{border-left-color:var(--amber);background:var(--amber-bg)}\r\n.callout-warn .callout-badge{background:var(--amber);color:#fff}\r\n.callout-add{border-left-color:var(--teal-d);background:#e9f3f1}\r\n.callout-add .callout-badge{background:var(--teal-d);color:#fff}\r\n\r\n/* topbar (mobile) */\r\n.topbar{display:none}\r\n\r\n@media (max-width:880px){\r\n  .shell{grid-template-columns:1fr}\r\n  .side{position:fixed;z-index:40;top:0;left:0;width:84%;max-width:320px;height:100vh;\r\n    background:var(--panel);transform:translateX(-105%);transition:transform .25s;\r\n    box-shadow:0 0 40px rgba(0,0,0,.18)}\r\n  .side.open{transform:translateX(0)}\r\n  .main{padding:70px 22px 90px}\r\n  .topbar{display:flex;align-items:center;gap:12px;position:sticky;top:0;z-index:30;\r\n    background:rgba(250,250,246,.92);backdrop-filter:blur(8px);\r\n    padding:12px 18px;border-bottom:1px solid var(--line)}\r\n  .menubtn{font-family:var(--mono);font-size:13px;border:1px solid var(--line);\r\n    background:#fff;padding:6px 12px;border-radius:8px;cursor:pointer}\r\n  .topbar .tt{font-family:var(--mono);font-size:12px;color:var(--teal);letter-spacing:.05em}\r\n  .scrim{display:none;position:fixed;inset:0;background:rgba(0,0,0,.35);z-index:35}\r\n  .scrim.show{display:block}\r\n  h1.modhead::after{font-size:25px}\r\n  .hero h1{font-size:25px}\r\n  .main{max-width:100%}\r\n}\r\n\r\n/* ── 인쇄 / PDF 저장 (출력 시 목차 먼저 → 본문) ── */\r\n@media print{\r\n  @page{margin:14mm 12mm}\r\n  *{-webkit-print-color-adjust:exact;print-color-adjust:exact}\r\n  .topbar,.scrim,.menubtn,.copybtn{display:none!important}\r\n  .shell{display:block;max-width:none}\r\n  /* 화면용 사이드바는 인쇄에서 완전히 숨김 (변환 불안정 → 빈 페이지 방지) */\r\n  .side{display:none!important}\r\n  /* 인쇄 전용 목차: 본문 맨 앞 일반 블록으로 깔끔히 출력 후 페이지 넘김 */\r\n  .print-toc{display:block!important;break-after:page;page-break-after:always}\r\n  .print-toc .ptoc-title{font-size:19pt;font-weight:800;color:#0c5249;letter-spacing:-.01em;\r\n    margin:0 0 16px;padding-bottom:10px;border-bottom:2px solid #127c71}\r\n  .print-toc a{display:block;color:#1b1e24;text-decoration:none;padding:3px 0;font-size:11.5pt;border:none}\r\n  .print-toc a.nav-h1{margin-top:13px;font-weight:700;color:#0c5249;font-size:12.5pt}\r\n  .print-toc a.nav-h2{padding-left:16px;color:#3a3f47}\r\n  /* 본문 */\r\n  .main{padding:0;max-width:none}\r\n  body{font-size:10.5pt;line-height:1.5;background:#fff}\r\n  a{text-decoration:none;color:inherit}\r\n  .hero{break-inside:avoid;background:#fff!important;color:#1b1e24!important;\r\n    border:none;border-bottom:2px solid #127c71;border-radius:0;\r\n    padding:0 0 14px!important;margin:0 0 18px}\r\n  .hero .eyebrow{color:#127c71!important}\r\n  .hero h1{color:#0c5249!important}\r\n  .hero p{color:#444!important}\r\n  /* 주제 헤더가 페이지 맨 아래 외롭게 걸리지 않게만 (새 페이지 강제는 빼서 빈 페이지 방지) */\r\n  h1.modhead{break-after:avoid;page-break-after:avoid}\r\n  h2,h3{break-after:avoid;page-break-after:avoid}\r\n  /* 코드·콜아웃·표·다이어그램은 페이지 중간에서 잘리지 않게 */\r\n  .codewrap,.callout,pre.mermaid,.tablescroll,table{break-inside:avoid;page-break-inside:avoid}\r\n  pre code,pre.hljs{white-space:pre-wrap;word-break:break-word}\r\n  pre.mermaid{text-align:center;border:1px solid #ddd;padding:12px 8px;margin:14px auto}\r\n  pre.mermaid svg{max-width:100%!important;height:auto!important;\r\n    max-height:200mm!important;display:inline-block!important}\r\n  .codewrap{border-color:#ccc}\r\n}\r\n</style>\r\n</head>\r\n<body>\r\n<div class=\"topbar\">\r\n  <button class=\"menubtn\" id=\"menubtn\" aria-label=\"목차 열기\">☰ 목차</button>\r\n  <span class=\"tt\">강의노트 · 보강판</span>\r\n</div>\r\n<div class=\"scrim\" id=\"scrim\"></div>\r\n<div class=\"shell\">\r\n  <aside class=\"side\" id=\"side\">\r\n    <div class=\"brand\">강의노트 · 05회차</div>\r\n    <p class=\"brand-t\">5회차 — 바이브 코딩 2: 업무 자동화 (로컬 LLM·콘솔·엑셀)</p>\r\n    <p class=\"brand-s\">현장 강의 · 기술 보강판</p>\r\n    <nav id=\"nav\">\r\n<a class=\"nav-h1\" href=\"#0-0\">0. 관통하는 태도 — &quot;토큰 0 자동화&quot;</a>\r\n<a class=\"nav-h1\" href=\"#1-llm-ollama-pc\">1. 로컬 LLM — Ollama (인터넷 없이 내 PC에서)</a>\r\n<a class=\"nav-h2\" href=\"#_1\">설치</a>\r\n<a class=\"nav-h2\" href=\"#5\">핵심 명령어 — 5개면 충분</a>\r\n<a class=\"nav-h2\" href=\"#gemma-4-e4b\">모델 고르기 — Gemma 4 (E4B, 멀티모달)</a>\r\n<a class=\"nav-h2\" href=\"#_2\">포트·노출 — 여기서 값 하나 바로잡자</a>\r\n<a class=\"nav-h2\" href=\"#ui\">코딩 에이전트로 채팅 UI 만들기</a>\r\n<a class=\"nav-h1\" href=\"#2-ollama-vba-ai\">2. Ollama × 엑셀 — VBA로 AI 함수 만들고 배포</a>\r\n<a class=\"nav-h1\" href=\"#3-apps-script-llm\">3. 구글 설문 자동화 — Apps Script + LLM</a>\r\n<a class=\"nav-h1\" href=\"#4-f12\">4. 브라우저 콘솔 자동화 (F12) — 겁나서 껐던 그 창</a>\r\n<a class=\"nav-h2\" href=\"#_3\">기본기 — 헬로월드</a>\r\n<a class=\"nav-h2\" href=\"#chatgpt-js\">핵심 워크플로우 — 요소 캡처 → ChatGPT → JS</a>\r\n<a class=\"nav-h2\" href=\"#4-1\">4-1. 첨부파일 일괄 다운로드</a>\r\n<a class=\"nav-h2\" href=\"#4-2\">4-2. 두 번 클릭 자동화 (행안부 정책자료)</a>\r\n<a class=\"nav-h2\" href=\"#4-3-ocr-dx\">4-3. 종이 양식 → 이미지 OCR → 폼 자동 입력 (DX)</a>\r\n<a class=\"nav-h2\" href=\"#4-4\">4-4. 데이터 시각화 + 확장 프로그램(익스텐션) 등록</a>\r\n<a class=\"nav-h1\" href=\"#5-0-power-query-powershell\">5. 토큰 0 자동화 — 엑셀 Power Query + PowerShell</a>\r\n<a class=\"nav-h2\" href=\"#5-1-power-query\">5-1. Power Query로 폴더 단위 가져오기</a>\r\n<a class=\"nav-h2\" href=\"#5-2\">5-2. 함수 없이 전처리 (열 분할)</a>\r\n<a class=\"nav-h2\" href=\"#5-3-powershell\">5-3. 데이터 추가 → 새로 고침 → PowerShell 무인 실행</a>\r\n<a class=\"nav-h2\" href=\"#5-4-task-scheduler\">5-4. 작업 스케줄러(Task Scheduler) 등록 — 마지막 무인화</a>\r\n<a class=\"nav-h2\" href=\"#5-5\">5-5. 왜 이 방식인가 — 오버엔지니어링 경계</a>\r\n<a class=\"nav-h1\" href=\"#_4\">마무리 &amp;amp; 과제</a>\r\n<a class=\"nav-h1\" href=\"#_5\">부록 — 도구 · 개념 맵</a>\r\n<a class=\"nav-h2\" href=\"#_6\">검색 보강 출처</a>\r\n    </nav>\r\n  </aside>\r\n  <main class=\"main\" id=\"main\">\r\n<nav class=\"print-toc\">\r\n<div class=\"ptoc-title\">목차</div>\r\n<a class=\"nav-h1\" href=\"#0-0\">0. 관통하는 태도 — &quot;토큰 0 자동화&quot;</a>\r\n<a class=\"nav-h1\" href=\"#1-llm-ollama-pc\">1. 로컬 LLM — Ollama (인터넷 없이 내 PC에서)</a>\r\n<a class=\"nav-h2\" href=\"#_1\">설치</a>\r\n<a class=\"nav-h2\" href=\"#5\">핵심 명령어 — 5개면 충분</a>\r\n<a class=\"nav-h2\" href=\"#gemma-4-e4b\">모델 고르기 — Gemma 4 (E4B, 멀티모달)</a>\r\n<a class=\"nav-h2\" href=\"#_2\">포트·노출 — 여기서 값 하나 바로잡자</a>\r\n<a class=\"nav-h2\" href=\"#ui\">코딩 에이전트로 채팅 UI 만들기</a>\r\n<a class=\"nav-h1\" href=\"#2-ollama-vba-ai\">2. Ollama × 엑셀 — VBA로 AI 함수 만들고 배포</a>\r\n<a class=\"nav-h1\" href=\"#3-apps-script-llm\">3. 구글 설문 자동화 — Apps Script + LLM</a>\r\n<a class=\"nav-h1\" href=\"#4-f12\">4. 브라우저 콘솔 자동화 (F12) — 겁나서 껐던 그 창</a>\r\n<a class=\"nav-h2\" href=\"#_3\">기본기 — 헬로월드</a>\r\n<a class=\"nav-h2\" href=\"#chatgpt-js\">핵심 워크플로우 — 요소 캡처 → ChatGPT → JS</a>\r\n<a class=\"nav-h2\" href=\"#4-1\">4-1. 첨부파일 일괄 다운로드</a>\r\n<a class=\"nav-h2\" href=\"#4-2\">4-2. 두 번 클릭 자동화 (행안부 정책자료)</a>\r\n<a class=\"nav-h2\" href=\"#4-3-ocr-dx\">4-3. 종이 양식 → 이미지 OCR → 폼 자동 입력 (DX)</a>\r\n<a class=\"nav-h2\" href=\"#4-4\">4-4. 데이터 시각화 + 확장 프로그램(익스텐션) 등록</a>\r\n<a class=\"nav-h1\" href=\"#5-0-power-query-powershell\">5. 토큰 0 자동화 — 엑셀 Power Query + PowerShell</a>\r\n<a class=\"nav-h2\" href=\"#5-1-power-query\">5-1. Power Query로 폴더 단위 가져오기</a>\r\n<a class=\"nav-h2\" href=\"#5-2\">5-2. 함수 없이 전처리 (열 분할)</a>\r\n<a class=\"nav-h2\" href=\"#5-3-powershell\">5-3. 데이터 추가 → 새로 고침 → PowerShell 무인 실행</a>\r\n<a class=\"nav-h2\" href=\"#5-4-task-scheduler\">5-4. 작업 스케줄러(Task Scheduler) 등록 — 마지막 무인화</a>\r\n<a class=\"nav-h2\" href=\"#5-5\">5-5. 왜 이 방식인가 — 오버엔지니어링 경계</a>\r\n<a class=\"nav-h1\" href=\"#_4\">마무리 &amp;amp; 과제</a>\r\n<a class=\"nav-h1\" href=\"#_5\">부록 — 도구 · 개념 맵</a>\r\n<a class=\"nav-h2\" href=\"#_6\">검색 보강 출처</a>\r\n</nav>\r\n    <div class=\"hero\">\r\n      <div class=\"eyebrow\">Lecture Note · 기술 보강판</div>\r\n      <h1>5회차 — 바이브 코딩 2: 업무 자동화 (로컬 LLM·콘솔·엑셀)</h1>\r\n      <p>현장 강의를 기술적으로 보강한 학습 레퍼런스 — 강사의 의도는 살리고, 빠지거나 틀린 기술은 정확히 채웠습니다.</p>\r\n    </div>\r\n\r\n<p>이 강의 하나로 무엇을 할 수 있게 하려는가 →\r\n<strong>\"AI를 최소한으로 쓰거나 아예 안 쓰고도 내 PC·폐쇄망 안에서 도는 업무 자동화 4종(로컬 LLM Ollama, 브라우저 콘솔 자동화, 구글 설문 자동생성, 엑셀 Power Query+PowerShell 무인 통합)을 직접 만들어, 거점 리더로서 동료 업무를 덜어주는 '도구화' 감각을 잡는 것.\"</strong></p>\r\n<blockquote class=\"callout callout-key\"><span class=\"callout-badge\">핵심</span>\r\n<p>★ 이 회차는 강사가 <strong>모듈 단위로 직접 번호를 매겨</strong> 진행했다. 그래서 이 노트도 그 실제 모듈 구조를 그대로 따른다(억지 위계 없음). 관통하는 태도 한 줄: <strong>\"AI가 다가 아니다 — 토큰 안 드는 로컬·내장 도구(Ollama·콘솔·VBA·Power Query·PowerShell)로도 충분히 자동화된다. 겁나서 껐던 F12를 ChatGPT와 함께 열면 누구나 만든다. 그리고 도구보다 '어디에 적용할지'가 제일 어렵다.\"</strong></p>\r\n<p><strong>보강 안내</strong> — 강사가 결과만 보여주고 건너뛴 부분은 실제 동작하는 명령어·코드로 채웠고, 틀린 값(포트 등)은 [정정]했다. 모델명·포트는 웹으로 확인해 <code>(검색 보강)</code>으로 표시했다. 운영성 멘트(점심·쉬는시간·장비 안내 등)는 뺐고, 학습에 도움 되는 일화·사례는 살렸다.</p>\r\n</blockquote>\r\n<hr/>\r\n<h1 class=\"modhead\" data-full='0. 관통하는 태도 — \"토큰 0 자동화\"' id=\"0-0\">0. 관통하는 태도 — \"토큰 0 자동화\"</h1>\r\n<p>오늘 다룬 4가지는 묶는 실 한 가닥이 있다.</p>\r\n<div class=\"codewrap\"><div class=\"codebar\"><span class=\"codelang\">code</span><button class=\"copybtn\" type=\"button\">복사</button></div><pre class=\"mermaid\">flowchart TD\r\n  T[\"업무 자동화 4종&lt;br/&gt;(토큰 0 지향)\"]\r\n  T --&gt; A[\"① 로컬 LLM&lt;br/&gt;Ollama (폐쇄망)\"]\r\n  T --&gt; B[\"② 브라우저 콘솔&lt;br/&gt;F12 자동화\"]\r\n  T --&gt; C[\"③ 구글 설문&lt;br/&gt;Apps Script\"]\r\n  T --&gt; D[\"④ 엑셀 무인 통합&lt;br/&gt;Power Query + PowerShell\"]\r\n</pre></div>\r\n<ul>\r\n<li><strong>공공·폐쇄망 현실에서 쓸 수 있는 작은 자동화</strong>다. ChatGPT를 마음껏 못 쓰는 환경에서도 돈다.</li>\r\n<li><strong>도구는 쉽다. 어디에 적용할지가 어렵다.</strong> 강사가 가장 많이 반복한 말. \"도대체 뭐가 문제야\"를 찾는 것, 이해관계자를 느슨하게 푸는 것이 본체다.</li>\r\n<li><strong>거점 리더 = 동료 업무 덜어주기.</strong> 설문 만드느라 밤새는 사람, 종이 폼 입력하는 계약직, 매달 엑셀 합치는 담당자 — 이들을 도우면 기관이 바뀐다.</li>\r\n</ul>\r\n<hr/>\r\n<h1 class=\"modhead\" data-full=\"1. 로컬 LLM — Ollama (인터넷 없이 내 PC에서)\" id=\"1-llm-ollama-pc\">1. 로컬 LLM — Ollama (인터넷 없이 내 PC에서)</h1>\r\n<p><strong>Ollama</strong>는 로컬에서 언어 모델을 쉽게 돌리게 해주는 \"껍데기(런타임)\". 내 PC에 모델을 받아 인터넷 끊고도 쓴다 — 폐쇄망의 핵심 도구.</p>\r\n<div class=\"codewrap\"><div class=\"codebar\"><span class=\"codelang\">code</span><button class=\"copybtn\" type=\"button\">복사</button></div><pre class=\"mermaid\">flowchart LR\r\n  G[\"Gemma 4 E4B&lt;br/&gt;(멀티모달 모델)\"] --&gt; M[\"Ollama 서버&lt;br/&gt;localhost:11434\"]\r\n  M --&gt; E[\"코딩 에이전트&lt;br/&gt;채팅 UI\"]\r\n  M --&gt; X[\"엑셀 VBA&lt;br/&gt;AI_함수\"]\r\n  M --&gt; B[\"내부망 다른 PC&lt;br/&gt;(노출 설정 시)\"]\r\n</pre></div>\r\n<h2 id=\"_1\">설치</h2>\r\n<div class=\"codewrap\"><div class=\"codebar\"><span class=\"codelang\">PowerShell</span><button class=\"copybtn\" type=\"button\">복사</button></div><pre><code class=\"language-powershell\"># 방법 1) winget (권장) — 설치 후 서비스가 자동 시작, localhost:11434 리슨\r\nwinget install -e --id Ollama.Ollama\r\n# 방법 2) ollama.com/download/windows 에서 OllamaSetup.exe 받아 설치 (약 1.3GB)\r\nollama --version        # 설치 확인\r\n</code></pre></div>\r\n<blockquote class=\"callout callout-add\"><span class=\"callout-badge\">보강</span>\r\n<p>보강 — 강사가 \"최근 PowerShell 한 줄 명령으로 설치된다\"고 한 게 바로 <strong>winget</strong>. (리눅스/맥은 <code>curl -fsSL https://ollama.com/install.sh | sh</code>.) 기존 사용자도 다시 깔면 업데이트로 덮어쓴다. (검색 보강: docs.ollama.com/windows)</p>\r\n</blockquote>\r\n<h2 id=\"5\">핵심 명령어 — 5개면 충분</h2>\r\n<div class=\"codewrap\"><div class=\"codebar\"><span class=\"codelang\">PowerShell</span><button class=\"copybtn\" type=\"button\">복사</button></div><pre><code class=\"language-powershell\">ollama pull gemma4:e4b   # 모델 다운로드만\r\nollama run  gemma4:e4b   # 있으면 실행, 없으면 받고 실행 (채팅 시작)\r\nollama list              # 내 PC에 깔린 모델 목록\r\nollama ps                # 지금 메모리에 올라간(실행 중) 모델\r\nollama rm   gemma4:e4b   # 모델 삭제\r\n</code></pre></div>\r\n<p><code>ollama ps</code>가 비어 있으면 Ollama는 떠 있지만 모델은 안 올라간 상태다. <code>run</code> 하면 메모리에 올라온다(예: 4B는 약 9.5GB 점유).</p>\r\n<h2 id=\"gemma-4-e4b\">모델 고르기 — Gemma 4 (E4B, 멀티모달)</h2>\r\n<p>내 노트북 사양(RAM)에 맞춰 크기를 고른다: 2B / 4B / 12B. 강사는 가장 만만한 <strong>Gemma 4의 E4B</strong>를 썼다.</p>\r\n<blockquote class=\"callout callout-add\"><span class=\"callout-badge\">보강</span>\r\n<p>보강 — <strong>Gemma 4 / \"E4B\"의 정체</strong> (검색 보강). <code>gemma4:e4b</code>는 Ollama 라이브러리에 실재하는 모델로 <strong>멀티모달(텍스트+이미지 입력)</strong>이다. <strong>E4B = \"실효(effective) 4B\"</strong> — 선택적 파라미터 활성화(selective activation) 기술로 전체 파라미터보다 적은 자원으로 4B급 성능을 낸다(Gemma 3n 계열의 기법을 이음). 그래서 CPU·노트북에서도 돈다. 강사가 스커트 이미지를 넣었더니 색·질감·패턴을 잘 뽑았다는 게 이 멀티모달 덕분. (검색 보강: ollama.com/library/gemma4, ai.google.dev/gemma/docs/gemma-3n)</p>\r\n</blockquote>\r\n<h2 id=\"_2\">포트·노출 — 여기서 값 하나 바로잡자</h2>\r\n<blockquote class=\"callout callout-note\"><span class=\"callout-badge\">참고</span>\r\n<p>⚠ 정정 — <strong>Ollama 기본 포트는 <code>11434</code>다</strong> (강사가 말한 \"12434\"는 착오). 도는지 확인은 브라우저나 curl로:\r\n<code>powershell\r\ncurl http://localhost:11434          # → \"Ollama is running\"</code>\r\n(검색 보강: Ollama는 기본적으로 <code>127.0.0.1:11434</code>에 바인딩, API는 <code>http://localhost:11434/api/generate</code>.)</p>\r\n<p>⚠ 정정 — <strong>내부망 IP 표기.</strong> 강사가 \"127로 시작하는 내부망, 196으로 시작하는 IP\"라고 했는데, 정확히는 <code>127.0.0.1</code>은 <strong>내 PC 자신(loopback)</strong>이지 LAN이 아니고, 사설망 대역은 <strong><code>192.168.x</code> / <code>10.x</code> / <code>172.16~31.x</code></strong>다(\"196\"은 192.168의 착오로 보임). 내부망 다른 PC에서 내 Ollama를 쓰게 하려면 외부 노출을 켜야 한다:\r\n<code>powershell\r\nsetx OLLAMA_HOST \"0.0.0.0:11434\"     # (Ollama 재시작 필요)</code>\r\n어느 군(郡)에서 폐쇄망에 Ollama를 큰 규모로 올렸다는 사례가 이 방식이다.</p>\r\n</blockquote>\r\n<h2 id=\"ui\">코딩 에이전트로 채팅 UI 만들기</h2>\r\n<p>VS Code·Windsurf·Antigravity 등 아무 코딩 에이전트에서 \"내 PC에 Ollama 깔려 있으니 그걸로 간단한 챗봇 만들자\"고 하면 금방 만들어진다. 강사 팁: <strong>\"첫 토큰까지 걸린 시간 + 총 출력 시간\"을 화면에 찍게</strong> 해서 내 PC/서버 성능을 체감하라(강사 측정: 첫 토큰 103초, 총 260초 — 느리지만 됨).</p>\r\n<blockquote class=\"callout callout-warn\"><span class=\"callout-badge\">주의</span>\r\n<p>보강 — <strong>llama.cpp / MSTY.</strong> Ollama는 편하지만 껍데기를 올려 자원을 좀 더 먹는다. <strong>llama.cpp</strong>는 C++로 짜여 더 가볍고 빠른 대안(서버 올리고 특정 모델만 띄워 localhost로 사용). UI 도구로는 <strong>MSTY</strong>도 있다. 작업 끝나면 Ollama는 트레이의 양(羊) 아이콘 → <strong>Quit Ollama</strong>로 내려라.</p>\r\n<p>⚠ 주의(미확인) — 강사가 전한 \"MS가 Claude Code 토큰 비용 5억 달러가 나와 사내에 쓰지 말라 했다\"는 <strong>출처 불명의 소문</strong>이다. 사실로 단정 말 것. 다만 클라우드 LLM 토큰 비용이 부담이 되면서 로컬 LLM 수요가 커지는 흐름 자체는 맞다.</p>\r\n</blockquote>\r\n<hr/>\r\n<h1 class=\"modhead\" data-full=\"2. Ollama × 엑셀 — VBA로 AI 함수 만들고 배포\" id=\"2-ollama-vba-ai\">2. Ollama × 엑셀 — VBA로 AI 함수 만들고 배포</h1>\r\n<p>엑셀 셀에서 <code>=AI_Summarize(...)</code>처럼 로컬 LLM을 부르는 사용자 정의 함수를 만든다. (5주차 교안 14p \"VBA + Ollama 완전 내부망\".)</p>\r\n<p>만들 함수 예: <strong>AI_Summarize, AI_Classify, AI_Extract, AI_Translate, AI_Ask</strong>. Ollama의 로컬 API(<code>:11434</code>)를 POST로 호출한다.</p>\r\n<div class=\"codewrap\"><div class=\"codebar\"><span class=\"codelang\">VBA</span><button class=\"copybtn\" type=\"button\">복사</button></div><pre><code class=\"language-vbscript\">' 엑셀 사용자 정의 함수: 셀 내용을 로컬 Ollama로 요약\r\nFunction AI_Summarize(rng As Range, Optional max_len As Long = 150, _\r\n                      Optional model As String = \"gemma4:e4b\") As String\r\n    Dim http As Object, body As String, prompt As String\r\n    prompt = \"다음을 \" &amp; max_len &amp; \"자 이내 한국어로 요약: \" &amp; rng.Value\r\n    body = \"{\"\"model\"\":\"\"\" &amp; model &amp; \"\"\",\"\"prompt\"\":\"\"\" &amp; _\r\n           Replace(prompt, \"\"\"\", \"\\\"\"\") &amp; \"\"\",\"\"stream\"\":false}\"\r\n    Set http = CreateObject(\"MSXML2.XMLHTTP\")\r\n    http.Open \"POST\", \"http://localhost:11434/api/generate\", False\r\n    http.setRequestHeader \"Content-Type\", \"application/json\"\r\n    http.send body\r\n    ' 응답 JSON의 \"response\" 값만 뽑는다 (실제 코드는 LLM이 파싱까지 생성)\r\n    AI_Summarize = ParseResponse(http.responseText)\r\nEnd Function\r\n</code></pre></div>\r\n<p><strong>등록 → 배포 흐름:</strong>\r\n1. 엑셀에서 <code>Alt+F11</code>(VBA 편집기) → <strong>삽입 → 모듈</strong> → 위 코드 붙여넣기.\r\n2. <strong><code>.xlsm</code></strong>(매크로 사용 통합 문서)으로 저장 → 내 엑셀에서 <code>=AI_</code>로 함수 검색되면 성공.\r\n3. <strong>남들에게 배포</strong>하려면 <strong><code>.xlam</code></strong>(엑셀 추가 기능)으로 저장 → 받는 사람은 <strong>파일 → 옵션 → 추가 기능 → \"Excel 추가 기능\" → 찾아보기</strong>로 그 <code>.xlam</code>을 등록.</p>\r\n<blockquote class=\"callout callout-add\"><span class=\"callout-badge\">보강</span>\r\n<p>보강 — Ollama 대신 <strong>외부 모델(GPT 등)도</strong> 같은 구조로 가능. URL과 인증 헤더만 바꾸면 된다. 즉 \"기관만의 AI 함수 팩(.xlam)\"을 만들어 사내 배포하는 그림이다.</p>\r\n</blockquote>\r\n<hr/>\r\n<h1 class=\"modhead\" data-full=\"3. 구글 설문 자동화 — Apps Script + LLM\" id=\"3-apps-script-llm\">3. 구글 설문 자동화 — Apps Script + LLM</h1>\r\n<p>설문은 손으로 만들면 귀찮아서 문항을 줄이게 된다. <strong>LLM으로 문항을 기획</strong>하고 <strong>Apps Script로 구글 폼을 코드 생성</strong>하면 15개든 100개든 한 방에.</p>\r\n<blockquote class=\"callout callout-add\"><span class=\"callout-badge\">보강</span>\r\n<p>보강 — <strong>Apps Script</strong>는 구글이 제공하는 자동화 언어(VBA의 구글판). <code>script.google.com</code>에서 실행한다. 구글 설문은 이름이 <strong>구글 폼(Google Forms)</strong>으로 바뀌었다.</p>\r\n</blockquote>\r\n<div class=\"codewrap\"><div class=\"codebar\"><span class=\"codelang\">JavaScript</span><button class=\"copybtn\" type=\"button\">복사</button></div><pre><code class=\"language-javascript\">// script.google.com → 새 프로젝트 → 붙여넣고 저장 → 실행(권한 \"모두 허용\")\r\nfunction createSurvey() {\r\n  const form = FormApp.create('우리 관내 만족도 설문');\r\n  form.addMultipleChoiceItem()\r\n      .setTitle('서비스에 만족하십니까?')\r\n      .setChoiceValues(['매우 만족', '만족', '보통', '불만족']);\r\n  form.addParagraphTextItem().setTitle('개선 의견을 자유롭게 적어주세요');\r\n  Logger.log('응답(배포) 주소: ' + form.getPublishedUrl());\r\n  Logger.log('편집 주소: '      + form.getEditUrl());\r\n}\r\n</code></pre></div>\r\n<p>실제로는 ChatGPT에 \"이 설문을 구글 Apps Script로 작성해줘\" 하면 15문항짜리 함수를 통째로 만들어준다. 위는 최소 패턴.</p>\r\n<p><strong>적용 흐름:</strong> ChatGPT에서 문항 기획 → \"Apps Script로 작성\" → 코드 복사 → 구글 드라이브 <strong>신규 → 더보기 → Google Apps Script</strong>(없으면 \"더 많은 앱 연결하기\"에서 추가) → 함수 붙여넣고 프로젝트명 저장 → <strong>저장해야 \"실행\" 버튼이 활성화</strong>됨 → 실행 → 권한 허용 → 응답/편집/스프레드시트 주소 생성.</p>\r\n<blockquote class=\"callout callout-add\"><span class=\"callout-badge\">보강</span>\r\n<p>보강 — <strong>결과 분석.</strong> 응답은 구글 시트로 쌓인다. 구글 드라이브에 붙은 <strong>Gemini</strong>로 바로 분석·차트를 뽑거나, 시트 링크를 VS Code/코딩 에이전트로 연동해 <strong>파이썬 대시보드</strong>까지 자동화할 수 있다. 활용 의도: 개인/팀 프로젝트 주제를 정할 때 동료 대상 설문으로 \"문제\"를 데이터로 잡는 것.</p>\r\n</blockquote>\r\n<hr/>\r\n<h1 class=\"modhead\" data-full=\"4. 브라우저 콘솔 자동화 (F12) — 겁나서 껐던 그 창\" id=\"4-f12\">4. 브라우저 콘솔 자동화 (F12) — 겁나서 껐던 그 창</h1>\r\n<p><code>F12</code>(개발자 도구). 예전엔 \"이거 뭐야\" 하고 껐던 창인데, <strong>Elements + Console</strong> 두 탭과 요령 하나면 충분하다.</p>\r\n<div class=\"codewrap\"><div class=\"codebar\"><span class=\"codelang\">code</span><button class=\"copybtn\" type=\"button\">복사</button></div><pre class=\"mermaid\">flowchart LR\r\n  F[\"F12 → 요소 선택&lt;br/&gt;(Name/Role 캡처)\"] --&gt; P[\"ChatGPT에&lt;br/&gt;이미지 + URL 전달\"]\r\n  P --&gt; J[\"JS 콘솔 코드 생성\"]\r\n  J --&gt; C[\"콘솔에 붙여 실행&lt;br/&gt;(매번 휘발)\"]\r\n  C --&gt; Z[\"확장 프로그램으로 등록&lt;br/&gt;manifest.json (영속화)\"]\r\n</pre></div>\r\n<h2 id=\"_3\">기본기 — 헬로월드</h2>\r\n<div class=\"codewrap\"><div class=\"codebar\"><span class=\"codelang\">JavaScript</span><button class=\"copybtn\" type=\"button\">복사</button></div><pre><code class=\"language-javascript\">console.log(\"안녕하세요\");                 // 출력 (파이썬 print 같은 것)\r\nconst name = prompt(\"이름 입력하세요\");     // 입력 팝업\r\nalert(\"환영합니다 \" + name + \"님\");         // 알림 팝업\r\n</code></pre></div>\r\n<blockquote class=\"callout callout-warn\"><span class=\"callout-badge\">주의</span>\r\n<p>⚠ 함정 — <strong>콘솔에 코드 붙여넣기가 막히면</strong>, 콘솔에 먼저 <code>allow pasting</code>을 타이핑하고 엔터 친 뒤 붙여넣어라. 콘솔을 지울 땐 <code>delete</code>가 아니라 <strong>콘솔 지우기(⊘) 버튼</strong>.</p>\r\n</blockquote>\r\n<h2 id=\"chatgpt-js\">핵심 워크플로우 — 요소 캡처 → ChatGPT → JS</h2>\r\n<p><code>F12</code> → <strong>요소 선택(Select an element) 아이콘</strong> 클릭 → 원하는 부분에 마우스 올리면 뜨는 <strong>접근성 팝업(Name / Role …)</strong> 을 <strong>캡처</strong> → ChatGPT에 이미지 + 페이지 URL을 주고 \"이걸 ○○하는 콘솔 코드 작성해줘\" → 나온 JS를 콘솔에 붙여 엔터.</p>\r\n<h2 id=\"4-1\">4-1. 첨부파일 일괄 다운로드</h2>\r\n<p>증권사 리포트·행안부 지침처럼 첨부가 여러 개일 때, 다운로드 버튼 요소를 캡처해 \"이 페이지의 첨부를 한 번에 다 받는 콘솔 코드\" 요청 → 콘솔 실행 → 한 번에 다운로드.</p>\r\n<h2 id=\"4-2\">4-2. 두 번 클릭 자동화 (행안부 정책자료)</h2>\r\n<p>목록 클릭 → 상세 → 다운로드, 처럼 <strong>2단계 클릭</strong>이 필요한 경우. 첫 화면 요소 + 넘어간 화면의 다운로드 버튼을 <strong>둘 다 캡처</strong>해 주면, JS가 내부 코드를 읽어 한 번에 처리한다.</p>\r\n<blockquote class=\"callout callout-key\"><span class=\"callout-badge\">핵심</span>\r\n<p>★ <strong>왜 파이썬 크롤러 대신 콘솔인가.</strong> 콘솔 코드는 <strong>내가 지금 보고 있는 브라우저(클라이언트) 안에서</strong> 실행된다. 그래서 네이버처럼 서버에서 IP를 차단(블로킹)하는 크롤링 방어를 <strong>우회</strong>하기 쉽다. 파이썬 크롤러보다 기능은 제한적이지만, 막히는 사이트엔 이 방식이 통한다. RAG용 자료를 대량 수집할 때 유용.</p>\r\n</blockquote>\r\n<h2 id=\"4-3-ocr-dx\">4-3. 종이 양식 → 이미지 OCR → 폼 자동 입력 (DX)</h2>\r\n<p>가장 임팩트 큰 사례. 농촌진흥청에 농민이 지퍼백 흙 시료에 <strong>손글씨로 지번·이름</strong>을 써 오면, 접수자가 종이에 옮기고 또 관리 프로그램에 입력한다(계약직까지 둘 정도). 이걸 콘솔로 줄인다.</p>\r\n<p>흐름: 웹 입력 폼에서 <code>F12</code> → 폼 구조 캡처 → ChatGPT에 \"종이에 적힌 회원 정보를 <strong>이미지로 주면</strong> 이 양식에 채우는 콘솔 코드\" 요청(이미지 글자 인식은 <strong>Gemini API 키</strong> 붙여서) → 실행하면 <strong>이미지 업로드 메뉴</strong>가 생기고, 손글씨 사진을 넣으면 이름·성별·주소가 자동 입력됨(사용자는 눈으로 확인 후 제출).</p>\r\n<blockquote class=\"callout callout-key\"><span class=\"callout-badge\">핵심</span>\r\n<p>★ <strong>AX보다 DX가 먼저.</strong> 종이 문서를 디지털로 바꾸는 게 선결. 옛 종이 차트(병원 EMR 이전), 학생 생기부 손글씨 기록 등 — 스캔 → 브라우저에서 바로 입력. 수천·수만 장이면 고속 스캔 후 PDF+OCR, 밤에 걸어두고 아침에 확인하는 식으로 작은 프로젝트화.</p>\r\n</blockquote>\r\n<h2 id=\"4-4\">4-4. 데이터 시각화 + 확장 프로그램(익스텐션) 등록</h2>\r\n<p>콘솔 코드는 <strong>매번 붙여 실행해야</strong> 한다(휘발). 자주 쓰면 <strong>확장 프로그램으로 등록(영속화)</strong>한다. 강사가 만든 \"외인 애널라이저\"(네이버 증권에서 외국인·기관 순매수를 시계열 차트로) 사례.</p>\r\n<p>흐름: 시각화 콘솔 코드를 ChatGPT가 만들어 줌 → \"이걸 크롬/엣지 확장 프로그램으로 만드는 절차 알려줘\" → <code>manifest.json</code> + 팝업 html 폴더 생성.</p>\r\n<div class=\"codewrap\"><div class=\"codebar\"><span class=\"codelang\">JSON</span><button class=\"copybtn\" type=\"button\">복사</button></div><pre><code class=\"language-json\">{\r\n  \"manifest_version\": 3,\r\n  \"name\": \"외인 애널라이저\",\r\n  \"version\": \"1.0\",\r\n  \"action\": { \"default_popup\": \"popup.html\" },\r\n  \"permissions\": [\"activeTab\", \"scripting\"]\r\n}\r\n</code></pre></div>\r\n<p>등록: 브라우저 <strong>확장 프로그램 → 개발자 모드 ON → \"압축 해제된 확장 프로그램 로드\" → 폴더 선택</strong>. (Netlify에 index.html 폴더를 드래그하는 것과 같은 감각.) 남에게 배포하려면 크롬 웹스토어 심사 등록이 필요.</p>\r\n<blockquote class=\"callout callout-warn\"><span class=\"callout-badge\">주의</span>\r\n<p>보강 — <strong>temperature 한 줄.</strong> 코딩처럼 정확해야 하면 <code>temperature=0</code>(가장 확률 높은 토큰만 → 결정적, 환각·버그↓), 창의가 필요하면 <code>1</code>. <strong>코딩 에이전트는 보통 0.</strong> 버그가 잦으면 0으로 낮춰 다시 짜라. (덤: 시스템 프롬프트를 0으로 두면 \"멋진 생각이에요\" 같은 아첨 없이 드라이하게 답함.)</p>\r\n<p>⚠ 주의 — <strong>페이지 표시값은 못 믿는다.</strong> 콘솔로 페이지의 숫자·텍스트를 그 자리에서 바꿀 수 있다(강사가 11번가 벨트를 천만 원으로, 통장 잔고·수상자 이름도). URL이 그대로여도 <strong>새로고침하면 사라지는 가짜</strong>다. \"통장 인증/수익 인증\" 캡처를 곧이곧대로 믿지 말 것 — \"리프레시 해봐\"가 검증.</p>\r\n</blockquote>\r\n<hr/>\r\n<h1 class=\"modhead\" data-full=\"5. 토큰 0 자동화 — 엑셀 Power Query + PowerShell\" id=\"5-0-power-query-powershell\">5. 토큰 0 자동화 — 엑셀 Power Query + PowerShell</h1>\r\n<p>AI와는 거리가 있지만 \"old is best\". 주기적으로 떨어지는 동일 양식 엑셀을 <strong>함수·코드·토큰 없이</strong> 통합·전처리하고, 그 갱신마저 무인으로 돌린다.</p>\r\n<div class=\"codewrap\"><div class=\"codebar\"><span class=\"codelang\">code</span><button class=\"copybtn\" type=\"button\">복사</button></div><pre class=\"mermaid\">flowchart LR\r\n  FD[\"폴더&lt;br/&gt;월별 엑셀 적재\"] --&gt; PQ[\"Power Query&lt;br/&gt;통합 + 전처리(열 분할)\"]\r\n  PQ --&gt; XL[\"통합 엑셀&lt;br/&gt;(연결 보존)\"]\r\n  PS[\"PowerShell .ps1&lt;br/&gt;RefreshAll\"] --&gt; XL\r\n  TS[\"작업 스케줄러&lt;br/&gt;매월 10일 06:00\"] --&gt; PS\r\n</pre></div>\r\n<h2 id=\"5-1-power-query\">5-1. Power Query로 폴더 단위 가져오기</h2>\r\n<p>엑셀은 <strong>여러 파일을 한 번에 못 연다</strong>(하나씩). HIRA(심평원)·AirKorea 같은 월별 CSV 12개를 시계열로 합치려면 노가다. <strong>Power Query 편집기</strong>가 이걸 푼다.</p>\r\n<p>경로: 빈 엑셀에서 <strong>데이터 → 데이터 가져오기 → 파일에서 → 폴더에서</strong> → (월별 파일이 쌓일) 폴더 지정 → <strong>데이터 결합 및 변환 → 데이터 결합</strong> → 파일 병합. (여기서 \"가져오기\"는 열기(open)가 아니라 <strong>연결(connect)</strong> 개념. DB(오라클·PostgreSQL·MySQL 등)에서도 직접 연결 가능.)</p>\r\n<blockquote class=\"callout callout-warn\"><span class=\"callout-badge\">주의</span>\r\n<p>⚠ 함정 — 가져올 폴더 안 엑셀 파일이 <strong>열려 있으면 안 된다</strong>(닫고 진행). 그리고 <strong>맥/구버전 제약</strong>: 맥 일부·MS Office 2016에는 \"폴더에서\"가 없을 수 있다(2016은 <code>Alt+F12</code>로 Power Query 별도 설치). M365 권장.</p>\r\n</blockquote>\r\n<h2 id=\"5-2\">5-2. 함수 없이 전처리 (열 분할)</h2>\r\n<p>한 셀에 <code>서비스;정보</code>, <code>영업중|허가</code>처럼 여러 값이 섞인(원-셀-원-데이터 위반) 데이터. 엑셀이면 FIND/LEFT 함수로 발라내는데, Power Query는 <strong>클릭만으로</strong>: 열 선택 → <strong>열 분할 → 구분 기호 기준</strong>(세미콜론·파이프 <code>|</code> 등) → 확인. 함수 한 줄 없이 쪼개진다.</p>\r\n<blockquote class=\"callout callout-add\"><span class=\"callout-badge\">보강</span>\r\n<p>보강 — 이 단계 데이터는 아직 엑셀 시트엔 없다(Power Query 안에만 있음). 다 만지고 <strong>\"닫기 및 로드\"</strong>를 눌러야 시트로 내려온다. 이 통합 엑셀은 <strong>원본을 담은 게 아니라, 폴더를 읽어 전처리한 결과만</strong> 뿌리는 \"껍데기+프로세스\"다.</p>\r\n</blockquote>\r\n<h2 id=\"5-3-powershell\">5-3. 데이터 추가 → 새로 고침 → PowerShell 무인 실행</h2>\r\n<p>폴더에 다음 달 파일(2월)을 넣고 <strong>데이터 → 모두 새로 고침</strong>만 누르면 통합본이 갱신된다(202행부터 2월 데이터 추가). 이 클릭조차 자동화 → <strong>엑셀을 열지 않고</strong> PowerShell로.</p>\r\n<div class=\"codewrap\"><div class=\"codebar\"><span class=\"codelang\">PowerShell</span><button class=\"copybtn\" type=\"button\">복사</button></div><pre><code class=\"language-powershell\"># 엑셀리프레시.ps1 — 엑셀을 화면에 안 띄우고 '모두 새로 고침' 실행\r\n$path  = \"C:\\월단위매출데이터\\강남구_소상공인_통합데이터.xlsx\"\r\n$excel = New-Object -ComObject Excel.Application\r\n$excel.Visible = $false\r\n$wb = $excel.Workbooks.Open($path)\r\n$wb.RefreshAll()                 # = 데이터 → 모두 새로 고침\r\nStart-Sleep -Seconds 5           # 새로고침 완료 대기\r\n$wb.Save(); $wb.Close($true); $excel.Quit()\r\n</code></pre></div>\r\n<div class=\"codewrap\"><div class=\"codebar\"><span class=\"codelang\">PowerShell</span><button class=\"copybtn\" type=\"button\">복사</button></div><pre><code class=\"language-powershell\"># 실행 (경로는 캡처해서 ChatGPT에 주면 오류 적다)\r\npowershell.exe -NoProfile -ExecutionPolicy Bypass -File \"C:\\월단위매출데이터\\엑셀리프레시.ps1\"\r\n</code></pre></div>\r\n<blockquote class=\"callout callout-warn\"><span class=\"callout-badge\">주의</span>\r\n<p>⚠ 함정 — <strong>경로 오류가 제일 많다</strong>(파이썬도 마찬가지: 경로 + \"No module named ○○\"). 경로를 손으로 치지 말고 <strong>폴더 화면을 캡처해서</strong> \"내 경로 이거야\"라고 주면 한 글자 실수가 준다. 또 <strong>PowerShell 한글 깨짐</strong>이 잦다 → 콘솔 인코딩을 UTF-8로(<code>chcp 65001</code>, 또는 스크립트 상단 <code>[Console]::OutputEncoding=[Text.Encoding]::UTF8</code>). 붙여넣을 때 따옴표·틸드(<code>~</code>)가 섞여 깨지는 것도 주의.</p>\r\n</blockquote>\r\n<h2 id=\"5-4-task-scheduler\">5-4. 작업 스케줄러(Task Scheduler) 등록 — 마지막 무인화</h2>\r\n<p>PowerShell 스크립트를 <strong>매월 자동 실행</strong>. <code>Win+R</code> → <code>taskschd.msc</code> → 작업 스케줄러.</p>\r\n<div class=\"codewrap\"><div class=\"codebar\"><span class=\"codelang\">PowerShell</span><button class=\"copybtn\" type=\"button\">복사</button></div><pre><code class=\"language-powershell\"># 명령으로 등록 (매월 10일 06:00 실행)\r\nschtasks /create /tn \"엑셀월간통합\" ^\r\n  /tr \"powershell -NoProfile -ExecutionPolicy Bypass -File C:\\월단위매출데이터\\엑셀리프레시.ps1\" ^\r\n  /sc monthly /d 10 /st 06:00\r\n</code></pre></div>\r\n<p>이러면 PC(또는 윈도우 서버)가 켜져 있는 한, 매월 10일 새벽에 스스로 폴더를 읽어 통합·전처리·갱신한다. 자동화 안 된 단 하나는 <strong>폴더에 새 파일을 넣는 것</strong>뿐. 통합본 위에 차트/대시보드를 그려놨다면 그것도 같이 갱신된다 — <strong>사람 손이 0</strong>.</p>\r\n<h2 id=\"5-5\">5-5. 왜 이 방식인가 — 오버엔지니어링 경계</h2>\r\n<blockquote class=\"callout callout-warn\"><span class=\"callout-badge\">주의</span>\r\n<p>★ 강사의 메시지: 민원 누적 분석처럼 <strong>개인 PC에서 도는 반복 업무</strong>라면, 파이썬(인메모리라 데이터 커지면 부담)이나 MCP·에이전트로 <strong>오버 엔지니어링</strong> 하지 말고, <strong>윈도우 내장(Power Query + PowerShell + 스케줄러)</strong>으로 충분할 때가 많다. 토큰도 0, 파이썬 설치도 불필요. \"이걸 해보면 오히려 'AI가 여기 들어가면 좋겠다'는 지점이 보인다\"는 게 의도. 단, 원본은 보통 전처리가 안 돼 있어 <strong>누군가는 전처리(마사지)를 해야</strong> 하는데, 그 자리를 Power Query가 메운다.</p>\r\n</blockquote>\r\n<hr/>\r\n<h1 class=\"modhead\" data-full=\"마무리 &amp; 과제\" id=\"_4\">마무리 &amp; 과제</h1>\r\n<p>오늘 한 4가지: ① Ollama 로컬 LLM(설치·모델·내 PC 성능 체감) ② Ollama×엑셀 VBA 함수 ③ 구글 설문 Apps Script ④ 콘솔 자동화(다운로드·폼입력·시각화·확장) ⑤ Power Query+PowerShell 무인 통합. 공통 메시지는 <strong>\"기능은 쉽다 — 내 업무·동료 업무 어디에 붙일지가 핵심\"</strong>.</p>\r\n<blockquote class=\"callout callout-key\"><span class=\"callout-badge\">핵심</span>\r\n<p>★ <strong>과제</strong> — 가장 재밌었을 <strong>콘솔 프로그램</strong>으로, 내 기관에 맞는 걸 하나 만들어 <strong>확장 프로그램으로 압축</strong>하고, 누구나 등록할 수 있게 <strong>README</strong>를 붙여 공유 폴더에 올리기. (작은 자동화로 동료를 돕는 '거점 리더' 연습.)</p>\r\n</blockquote>\r\n<hr/>\r\n<h1 class=\"modhead\" data-full=\"부록 — 도구 · 개념 맵\" id=\"_5\">부록 — 도구 · 개념 맵</h1>\r\n<div class=\"tablescroll\"><table>\r\n<thead>\r\n<tr>\r\n<th>분류</th>\r\n<th>키워드</th>\r\n</tr>\r\n</thead>\r\n<tbody>\r\n<tr>\r\n<td>로컬 LLM</td>\r\n<td>Ollama(:11434), <code>pull/run/list/ps/rm</code>, Gemma 4 E4B(멀티모달), llama.cpp, MSTY, OLLAMA_HOST</td>\r\n</tr>\r\n<tr>\r\n<td>엑셀×AI</td>\r\n<td>VBA 사용자정의함수, MSXML2.XMLHTTP, <code>.xlsm</code>→<code>.xlam</code> 배포, 파일→옵션→추가기능</td>\r\n</tr>\r\n<tr>\r\n<td>구글 자동화</td>\r\n<td>Apps Script, FormApp, getPublishedUrl, 구글 폼, 드라이브 Gemini</td>\r\n</tr>\r\n<tr>\r\n<td>브라우저 콘솔</td>\r\n<td>F12, Elements/Console, 요소 선택, allow pasting, console.log/prompt/alert</td>\r\n</tr>\r\n<tr>\r\n<td>확장 프로그램</td>\r\n<td>manifest.json(v3), 개발자 모드, 압축 해제 로드, Listly·Easy Scraper</td>\r\n</tr>\r\n<tr>\r\n<td>엑셀 자동화</td>\r\n<td>Power Query(데이터 가져오기→폴더에서), 열 분할, 모두 새로 고침, 닫기 및 로드</td>\r\n</tr>\r\n<tr>\r\n<td>무인 실행</td>\r\n<td>PowerShell(.ps1, Excel COM, RefreshAll), <code>taskschd.msc</code>, schtasks</td>\r\n</tr>\r\n<tr>\r\n<td>개념</td>\r\n<td>temperature 0/1, 클라이언트 vs 서버 크롤링, DX→AX, 사설망 IP(192.168.x)</td>\r\n</tr>\r\n</tbody>\r\n</table></div>\r\n<h2 id=\"_6\">검색 보강 출처</h2>\r\n<ul>\r\n<li>Ollama 기본 포트 11434 / <code>:11434/api/generate</code>: docs.ollama.com/faq, pinggy.io</li>\r\n<li>Ollama Windows 설치(winget): docs.ollama.com/windows, winstall.app</li>\r\n<li>Gemma 4 E4B 멀티모달 / 선택적 활성화: ollama.com/library/gemma4, ai.google.dev/gemma/docs/gemma-3n</li>\r\n</ul>\r\n  </main>\r\n</div>\r\n\r\n<script src=\"https://cdnjs.cloudflare.com/ajax/libs/highlight.js/11.9.0/highlight.min.js\"><\/script>\r\n<script src=\"https://cdnjs.cloudflare.com/ajax/libs/highlight.js/11.9.0/languages/powershell.min.js\"><\/script>\r\n<script src=\"https://cdnjs.cloudflare.com/ajax/libs/highlight.js/11.9.0/languages/vbscript.min.js\"><\/script>\r\n<script src=\"https://cdnjs.cloudflare.com/ajax/libs/mermaid/10.9.1/mermaid.min.js\"><\/script>\r\n<script>\r\n// 주제 헤더 raw 텍스트를 data-full로 옮겨 ::after 표시\r\ndocument.querySelectorAll('h1.modhead').forEach(function(h){\r\n  h.setAttribute('data-full', h.textContent);\r\n});\r\n\r\n// highlight.js\r\nif(window.hljs){\r\n  document.querySelectorAll('.codewrap pre code').forEach(function(b){\r\n    try{hljs.highlightElement(b);}catch(e){}\r\n  });\r\n}\r\n\r\n// mermaid\r\nif(window.mermaid){\r\n  mermaid.initialize({\r\n    startOnLoad:true, theme:'base',\r\n    htmlLabels:false,\r\n    themeVariables:{\r\n      fontFamily:'-apple-system,Pretendard,\"Malgun Gothic\",sans-serif',\r\n      fontSize:'13px',\r\n      primaryColor:'#e6f4f1', primaryBorderColor:'#127c71', primaryTextColor:'#0c5249',\r\n      lineColor:'#9aa0a8', secondaryColor:'#f4f1ea', tertiaryColor:'#fbf1e4',\r\n      clusterBkg:'#f6f6f0', clusterBorder:'#cfd3cb'\r\n    },\r\n    flowchart:{curve:'basis', useMaxWidth:true, htmlLabels:false},\r\n    sequence:{useMaxWidth:true}\r\n  });\r\n}\r\n\r\n// 복사 버튼\r\ndocument.querySelectorAll('.copybtn').forEach(function(btn){\r\n  btn.addEventListener('click', function(){\r\n    var code = btn.closest('.codewrap').querySelector('pre code');\r\n    var txt = code ? code.innerText : '';\r\n    navigator.clipboard.writeText(txt).then(function(){\r\n      btn.textContent='복사됨'; btn.classList.add('ok');\r\n      setTimeout(function(){btn.textContent='복사'; btn.classList.remove('ok');},1400);\r\n    });\r\n  });\r\n});\r\n\r\n// 스크롤 스파이\r\nvar links = Array.from(document.querySelectorAll('#nav a'));\r\nvar map = {};\r\nlinks.forEach(function(a){ map[a.getAttribute('href').slice(1)] = a; });\r\nvar heads = Array.from(document.querySelectorAll('.main h1[id], .main h2[id]'));\r\nvar spy = new IntersectionObserver(function(entries){\r\n  entries.forEach(function(en){\r\n    if(en.isIntersecting){\r\n      links.forEach(function(l){l.classList.remove('active');});\r\n      var act = map[en.target.id];\r\n      if(act){act.classList.add('active');\r\n        act.scrollIntoView({block:'nearest'});}\r\n    }\r\n  });\r\n}, {rootMargin:'-10% 0px -75% 0px', threshold:0});\r\nheads.forEach(function(h){spy.observe(h);});\r\n\r\n// 모바일 사이드바\r\nvar side=document.getElementById('side'), scrim=document.getElementById('scrim'),\r\n    mb=document.getElementById('menubtn');\r\nfunction toggle(open){side.classList.toggle('open',open);scrim.classList.toggle('show',open);}\r\nif(mb){mb.addEventListener('click',function(){toggle(!side.classList.contains('open'));});}\r\nif(scrim){scrim.addEventListener('click',function(){toggle(false);});}\r\nlinks.forEach(function(a){a.addEventListener('click',function(){if(window.innerWidth<=880)toggle(false);});});\r\n<\/script>\r\n</body>\r\n</html>\r\n","6":"<!DOCTYPE html>\r\n<html lang=\"ko\">\r\n<head>\r\n<meta charset=\"utf-8\">\r\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\r\n<title>6회차 — AI 에이전트 이해: 트랜스포머 기초부터 멀티 에이전트 실습까지</title>\r\n<link rel=\"preconnect\" href=\"https://cdnjs.cloudflare.com\">\r\n<link rel=\"stylesheet\" href=\"https://cdnjs.cloudflare.com/ajax/libs/highlight.js/11.9.0/styles/github.min.css\">\r\n<style>\r\n:root{\r\n  --bg:#fafaf6; --panel:#ffffff; --ink:#1b1e24; --ink-soft:#5a6069; --ink-faint:#8b919b;\r\n  --line:#e7e6df; --line-soft:#f0efe9;\r\n  --teal:#127c71; --teal-d:#0c5249; --teal-bg:#e6f4f1;\r\n  --amber:#b9722a; --amber-bg:#fbf1e4;\r\n  --red:#c0392b; --red-bg:#fbe9e7;\r\n  --code-bg:#f6f6f0;\r\n  --mono:ui-monospace,\"SF Mono\",\"Cascadia Code\",\"JetBrains Mono\",Consolas,monospace;\r\n  --sans:-apple-system,BlinkMacSystemFont,\"Pretendard\",\"Apple SD Gothic Neo\",\"Segoe UI\",\"Malgun Gothic\",sans-serif;\r\n  --rad:12px;\r\n}\r\n*{box-sizing:border-box}\r\nhtml{scroll-behavior:smooth}\r\n@media (prefers-reduced-motion:reduce){html{scroll-behavior:auto}}\r\nbody{margin:0;background:var(--bg);color:var(--ink);font-family:var(--sans);\r\n  font-size:16px;line-height:1.72;-webkit-font-smoothing:antialiased}\r\n\r\n/* layout */\r\n.shell{display:grid;grid-template-columns:300px minmax(0,1fr);max-width:1240px;margin:0 auto}\r\n.print-toc{display:none}\r\n.side{position:sticky;top:0;align-self:start;height:100vh;overflow-y:auto;\r\n  padding:30px 22px 60px;border-right:1px solid var(--line)}\r\n.main{min-width:0;padding:46px 60px 120px;max-width:880px}\r\n\r\n/* sidebar */\r\n.brand{font-family:var(--mono);font-size:11px;letter-spacing:.14em;text-transform:uppercase;\r\n  color:var(--teal);margin-bottom:6px}\r\n.brand-t{font-weight:700;font-size:17px;line-height:1.35;margin:0 0 4px}\r\n.brand-s{font-size:12.5px;color:var(--ink-faint);margin:0 0 24px;line-height:1.5}\r\nnav a{display:block;text-decoration:none;color:var(--ink-soft);border-left:2px solid transparent;\r\n  padding:3px 0 3px 12px;font-size:13.5px;transition:color .15s,border-color .15s}\r\nnav a:hover{color:var(--ink)}\r\nnav a.nav-h1{margin-top:16px;font-weight:700;color:var(--ink);font-size:13px;\r\n  font-family:var(--mono);letter-spacing:.02em}\r\nnav a.nav-h2{font-size:13px}\r\nnav a.active{color:var(--teal-d);border-left-color:var(--teal);font-weight:600}\r\n\r\n/* headings */\r\nh1.modhead{font-size:13px;font-family:var(--mono);letter-spacing:.06em;text-transform:uppercase;\r\n  color:var(--teal);margin:72px 0 0;padding-top:28px;border-top:2px solid var(--ink);\r\n  font-weight:700}\r\nh1.modhead::after{content:attr(data-full);display:block;font-family:var(--sans);\r\n  font-size:30px;letter-spacing:-.01em;text-transform:none;color:var(--ink);\r\n  margin-top:8px;font-weight:750;line-height:1.2}\r\nh1.modhead{font-size:0}            /* hide raw, show via ::after */\r\nh1.modhead.intro{font-size:13px}\r\nh2{font-size:21px;font-weight:720;letter-spacing:-.01em;margin:46px 0 14px;\r\n  padding-bottom:8px;border-bottom:1px solid var(--line)}\r\nh3{font-size:16.5px;font-weight:700;margin:32px 0 10px;color:var(--ink)}\r\nh2.starred,h3.starred{color:var(--teal-d)}\r\nh2.starred::before,h3.starred::before{content:\"★ \";color:var(--teal);font-size:.85em}\r\nh2.starred,h3.starred{}\r\n.main h1:first-of-type{margin-top:0}\r\n\r\np{margin:12px 0}\r\na{color:var(--teal-d)}\r\nstrong{font-weight:700;color:var(--ink)}\r\nul,ol{padding-left:22px;margin:12px 0}\r\nli{margin:5px 0}\r\nhr{border:none;border-top:1px solid var(--line);margin:40px 0}\r\n\r\n/* intro hero */\r\n.hero{background:linear-gradient(135deg,#0c5249,#127c71);color:#eafaf6;\r\n  border-radius:16px;padding:34px 36px;margin:0 0 14px}\r\n.hero .eyebrow{font-family:var(--mono);font-size:11px;letter-spacing:.16em;\r\n  text-transform:uppercase;color:#9fdfd2;margin-bottom:10px}\r\n.hero h1{font-size:32px;line-height:1.18;margin:0 0 12px;font-weight:780;letter-spacing:-.02em}\r\n.hero p{margin:0;color:#cfeee7;font-size:14.5px;line-height:1.6}\r\n\r\n/* tables */\r\ntable{width:100%;border-collapse:collapse;margin:18px 0;font-size:14px;\r\n  border:1px solid var(--line);border-radius:var(--rad);overflow:hidden}\r\nthead th{background:var(--teal-bg);color:var(--teal-d);text-align:left;\r\n  font-weight:700;padding:10px 13px;font-size:13px}\r\ntd{padding:10px 13px;border-top:1px solid var(--line-soft);vertical-align:top}\r\ntbody tr:nth-child(even){background:#fbfbf8}\r\n.tablescroll{overflow-x:auto}\r\n\r\n/* code */\r\n.codewrap{margin:16px 0;border:1px solid var(--line);border-radius:var(--rad);\r\n  overflow:hidden;background:var(--code-bg)}\r\n.codebar{display:flex;justify-content:space-between;align-items:center;\r\n  padding:7px 12px;background:#efeee7;border-bottom:1px solid var(--line)}\r\n.codelang{font-family:var(--mono);font-size:11px;letter-spacing:.08em;\r\n  text-transform:uppercase;color:var(--ink-faint);font-weight:600}\r\n.copybtn{font-family:var(--mono);font-size:11px;border:1px solid var(--line);\r\n  background:#fff;color:var(--ink-soft);padding:3px 11px;border-radius:6px;cursor:pointer;\r\n  transition:all .15s}\r\n.copybtn:hover{border-color:var(--teal);color:var(--teal-d)}\r\n.copybtn.ok{background:var(--teal);color:#fff;border-color:var(--teal)}\r\n.codewrap pre{margin:0;padding:0}\r\npre code,pre.hljs{display:block;padding:15px 16px;overflow-x:auto;\r\n  font-family:var(--mono);font-size:13px;line-height:1.6;background:var(--code-bg)!important}\r\n:not(pre)>code{font-family:var(--mono);font-size:.88em;background:#eeede6;\r\n  padding:1.5px 6px;border-radius:5px;color:var(--teal-d);white-space:nowrap}\r\n\r\n/* mermaid */\r\npre.mermaid{background:var(--panel);border:1px solid var(--line);border-radius:var(--rad);\r\n  padding:22px;margin:20px 0;text-align:center;overflow-x:auto;line-height:1.4}\r\n\r\n/* callouts */\r\n.callout{position:relative;margin:18px 0;padding:14px 18px 14px 18px;border-radius:10px;\r\n  border-left:4px solid var(--ink-faint);background:#f4f4ee;font-size:14.5px}\r\n.callout p{margin:8px 0}\r\n.callout p:first-of-type{margin-top:0}\r\n.callout p:last-child{margin-bottom:0}\r\n.callout-badge{display:inline-block;font-family:var(--mono);font-size:10.5px;\r\n  letter-spacing:.1em;text-transform:uppercase;font-weight:700;\r\n  padding:2px 9px;border-radius:20px;margin-bottom:8px}\r\n.callout-note{border-left-color:#9aa0a8;background:#f3f3ee}\r\n.callout-note .callout-badge{background:#e4e4dd;color:#5a6069}\r\n.callout-key{border-left-color:var(--teal);background:var(--teal-bg)}\r\n.callout-key .callout-badge{background:var(--teal);color:#fff}\r\n.callout-warn{border-left-color:var(--amber);background:var(--amber-bg)}\r\n.callout-warn .callout-badge{background:var(--amber);color:#fff}\r\n.callout-add{border-left-color:var(--teal-d);background:#e9f3f1}\r\n.callout-add .callout-badge{background:var(--teal-d);color:#fff}\r\n\r\n/* topbar (mobile) */\r\n.topbar{display:none}\r\n\r\n@media (max-width:880px){\r\n  .shell{grid-template-columns:1fr}\r\n  .side{position:fixed;z-index:40;top:0;left:0;width:84%;max-width:320px;height:100vh;\r\n    background:var(--panel);transform:translateX(-105%);transition:transform .25s;\r\n    box-shadow:0 0 40px rgba(0,0,0,.18)}\r\n  .side.open{transform:translateX(0)}\r\n  .main{padding:70px 22px 90px}\r\n  .topbar{display:flex;align-items:center;gap:12px;position:sticky;top:0;z-index:30;\r\n    background:rgba(250,250,246,.92);backdrop-filter:blur(8px);\r\n    padding:12px 18px;border-bottom:1px solid var(--line)}\r\n  .menubtn{font-family:var(--mono);font-size:13px;border:1px solid var(--line);\r\n    background:#fff;padding:6px 12px;border-radius:8px;cursor:pointer}\r\n  .topbar .tt{font-family:var(--mono);font-size:12px;color:var(--teal);letter-spacing:.05em}\r\n  .scrim{display:none;position:fixed;inset:0;background:rgba(0,0,0,.35);z-index:35}\r\n  .scrim.show{display:block}\r\n  h1.modhead::after{font-size:25px}\r\n  .hero h1{font-size:25px}\r\n  .main{max-width:100%}\r\n}\r\n\r\n/* ── 인쇄 / PDF 저장 (출력 시 목차 먼저 → 본문) ── */\r\n@media print{\r\n  @page{margin:14mm 12mm}\r\n  *{-webkit-print-color-adjust:exact;print-color-adjust:exact}\r\n  .topbar,.scrim,.menubtn,.copybtn{display:none!important}\r\n  .shell{display:block;max-width:none}\r\n  /* 화면용 사이드바는 인쇄에서 완전히 숨김 (변환 불안정 → 빈 페이지 방지) */\r\n  .side{display:none!important}\r\n  /* 인쇄 전용 목차: 본문 맨 앞 일반 블록으로 깔끔히 출력 후 페이지 넘김 */\r\n  .print-toc{display:block!important;break-after:page;page-break-after:always}\r\n  .print-toc .ptoc-title{font-size:19pt;font-weight:800;color:#0c5249;letter-spacing:-.01em;\r\n    margin:0 0 16px;padding-bottom:10px;border-bottom:2px solid #127c71}\r\n  .print-toc a{display:block;color:#1b1e24;text-decoration:none;padding:3px 0;font-size:11.5pt;border:none}\r\n  .print-toc a.nav-h1{margin-top:13px;font-weight:700;color:#0c5249;font-size:12.5pt}\r\n  .print-toc a.nav-h2{padding-left:16px;color:#3a3f47}\r\n  /* 본문 */\r\n  .main{padding:0;max-width:none}\r\n  body{font-size:10.5pt;line-height:1.5;background:#fff}\r\n  a{text-decoration:none;color:inherit}\r\n  .hero{break-inside:avoid;background:#fff!important;color:#1b1e24!important;\r\n    border:none;border-bottom:2px solid #127c71;border-radius:0;\r\n    padding:0 0 14px!important;margin:0 0 18px}\r\n  .hero .eyebrow{color:#127c71!important}\r\n  .hero h1{color:#0c5249!important}\r\n  .hero p{color:#444!important}\r\n  /* 주제 헤더가 페이지 맨 아래 외롭게 걸리지 않게만 (새 페이지 강제는 빼서 빈 페이지 방지) */\r\n  h1.modhead{break-after:avoid;page-break-after:avoid}\r\n  h2,h3{break-after:avoid;page-break-after:avoid}\r\n  /* 코드·콜아웃·표·다이어그램은 페이지 중간에서 잘리지 않게 */\r\n  .codewrap,.callout,pre.mermaid,.tablescroll,table{break-inside:avoid;page-break-inside:avoid}\r\n  pre code,pre.hljs{white-space:pre-wrap;word-break:break-word}\r\n  pre.mermaid{text-align:center;border:1px solid #ddd;padding:12px 8px;margin:14px auto}\r\n  pre.mermaid svg{max-width:100%!important;height:auto!important;\r\n    max-height:200mm!important;display:inline-block!important}\r\n  .codewrap{border-color:#ccc}\r\n}\r\n</style>\r\n</head>\r\n<body>\r\n<div class=\"topbar\">\r\n  <button class=\"menubtn\" id=\"menubtn\" aria-label=\"목차 열기\">☰ 목차</button>\r\n  <span class=\"tt\">강의노트 · 보강판</span>\r\n</div>\r\n<div class=\"scrim\" id=\"scrim\"></div>\r\n<div class=\"shell\">\r\n  <aside class=\"side\" id=\"side\">\r\n    <div class=\"brand\">강의노트 · 06회차</div>\r\n    <p class=\"brand-t\">6회차 — AI 에이전트 이해: 트랜스포머 기초부터 멀티 에이전트 실습까지</p>\r\n    <p class=\"brand-s\">현장 강의 · 기술 보강판</p>\r\n    <nav id=\"nav\">\r\n<a class=\"nav-h1\" href=\"#_1\">들어가며 — 왜 &#x27;에이전트를 이해&#x27;하는가</a>\r\n<a class=\"nav-h1\" href=\"#1\">1부 · 모델은 어떻게 &#x27;말&#x27;을 배웠나 (딥러닝 → 트랜스포머)</a>\r\n<a class=\"nav-h2\" href=\"#_2\">퍼셉트론 — 딥러닝의 최소 단위</a>\r\n<a class=\"nav-h2\" href=\"#_3\">이미지에서 텍스트로 — 임베딩</a>\r\n<a class=\"nav-h2\" href=\"#n-gram-rnnlstm\">N-gram → RNN/LSTM — 그리고 그 한계</a>\r\n<a class=\"nav-h2\" href=\"#attention-is-all-you-need-2017\">Attention Is All You Need — 트랜스포머 (2017)</a>\r\n<a class=\"nav-h1\" href=\"#2-ai\">2부 · AI 에이전트란 무엇인가</a>\r\n<a class=\"nav-h2\" href=\"#3\">구성 3요소 — 두뇌·도구·기억</a>\r\n<a class=\"nav-h2\" href=\"#_4\">행동·설계·조건 — 그리고 &quot;왜 기억인가 = 돈&quot;</a>\r\n<a class=\"nav-h1\" href=\"#3-6\">3부 · 에이전트 6종 구조 — 싱글부터 멀티까지</a>\r\n<a class=\"nav-h2\" href=\"#_5\">싱글(바닐라) 에이전트</a>\r\n<a class=\"nav-h2\" href=\"#_6\">멀티 에이전트 — &quot;바통&quot;과 핸드오프</a>\r\n<a class=\"nav-h2\" href=\"#_7\">네트워크 에이전트 — &quot;팀장님 보고 싶어요&quot;</a>\r\n<a class=\"nav-h2\" href=\"#as\">슈퍼바이저 &amp;amp; 슈퍼바이저 as 툴 — 오케스트레이션</a>\r\n<a class=\"nav-h2\" href=\"#hierarchical\">계층형(hierarchical) &amp;amp; 커스텀</a>\r\n<a class=\"nav-h1\" href=\"#4-1-openrouter\">4부 · 실습 1 — 민원 초안 생성 멀티 에이전트 (OpenRouter)</a>\r\n<a class=\"nav-h2\" href=\"#openrouter\">OpenRouter — 키 하나로 수백 개 모델</a>\r\n<a class=\"nav-h2\" href=\"#api-env\">실제로 붙이는 법 — API 키와 .env</a>\r\n<a class=\"nav-h1\" href=\"#5-git\">5부 · 적정 에이전트 수 &amp;amp; 개발 습관 (플랜·기록·Git)</a>\r\n<a class=\"nav-h2\" href=\"#_8\">무조건 &#x27;플랜&#x27; 먼저 — 메타 프롬프트로</a>\r\n<a class=\"nav-h2\" href=\"#planmd-git\">변경 이유를 남겨라 — plan.md와 Git</a>\r\n<a class=\"nav-h1\" href=\"#6-2\">6부 · 실습 2 — 픽셀 에이전트 클론 &amp;amp; 커스텀</a>\r\n<a class=\"nav-h2\" href=\"#git\">Git 설치 확인 → 클론</a>\r\n<a class=\"nav-h2\" href=\"#nodejs\">의존성 설치 &amp;amp; 실행 (Node.js 프로젝트 기준)</a>\r\n<a class=\"nav-h2\" href=\"#_9\">뜯어고치기 — 순서와 요령</a>\r\n<a class=\"nav-h1\" href=\"#7\">7부 · 멀티 에이전트의 그림자 — 왜 돈이 눈덩이처럼 부나</a>\r\n<a class=\"nav-h2\" href=\"#thinking\">Thinking 기본 + 핸드오프는 공짜가 아니다</a>\r\n<a class=\"nav-h2\" href=\"#latentmas\">연구 최전선 — LatentMAS 논문</a>\r\n<a class=\"nav-h1\" href=\"#_10\">마무리 &amp;amp; 과제</a>\r\n<a class=\"nav-h1\" href=\"#_11\">부록 — 용어 사전 · 출처</a>\r\n<a class=\"nav-h2\" href=\"#_12\">용어 빠른 사전</a>\r\n<a class=\"nav-h2\" href=\"#_13\">검색으로 확인·보강한 출처</a>\r\n    </nav>\r\n  </aside>\r\n  <main class=\"main\" id=\"main\">\r\n<nav class=\"print-toc\">\r\n<div class=\"ptoc-title\">목차</div>\r\n<a class=\"nav-h1\" href=\"#_1\">들어가며 — 왜 &#x27;에이전트를 이해&#x27;하는가</a>\r\n<a class=\"nav-h1\" href=\"#1\">1부 · 모델은 어떻게 &#x27;말&#x27;을 배웠나 (딥러닝 → 트랜스포머)</a>\r\n<a class=\"nav-h2\" href=\"#_2\">퍼셉트론 — 딥러닝의 최소 단위</a>\r\n<a class=\"nav-h2\" href=\"#_3\">이미지에서 텍스트로 — 임베딩</a>\r\n<a class=\"nav-h2\" href=\"#n-gram-rnnlstm\">N-gram → RNN/LSTM — 그리고 그 한계</a>\r\n<a class=\"nav-h2\" href=\"#attention-is-all-you-need-2017\">Attention Is All You Need — 트랜스포머 (2017)</a>\r\n<a class=\"nav-h1\" href=\"#2-ai\">2부 · AI 에이전트란 무엇인가</a>\r\n<a class=\"nav-h2\" href=\"#3\">구성 3요소 — 두뇌·도구·기억</a>\r\n<a class=\"nav-h2\" href=\"#_4\">행동·설계·조건 — 그리고 &quot;왜 기억인가 = 돈&quot;</a>\r\n<a class=\"nav-h1\" href=\"#3-6\">3부 · 에이전트 6종 구조 — 싱글부터 멀티까지</a>\r\n<a class=\"nav-h2\" href=\"#_5\">싱글(바닐라) 에이전트</a>\r\n<a class=\"nav-h2\" href=\"#_6\">멀티 에이전트 — &quot;바통&quot;과 핸드오프</a>\r\n<a class=\"nav-h2\" href=\"#_7\">네트워크 에이전트 — &quot;팀장님 보고 싶어요&quot;</a>\r\n<a class=\"nav-h2\" href=\"#as\">슈퍼바이저 &amp;amp; 슈퍼바이저 as 툴 — 오케스트레이션</a>\r\n<a class=\"nav-h2\" href=\"#hierarchical\">계층형(hierarchical) &amp;amp; 커스텀</a>\r\n<a class=\"nav-h1\" href=\"#4-1-openrouter\">4부 · 실습 1 — 민원 초안 생성 멀티 에이전트 (OpenRouter)</a>\r\n<a class=\"nav-h2\" href=\"#openrouter\">OpenRouter — 키 하나로 수백 개 모델</a>\r\n<a class=\"nav-h2\" href=\"#api-env\">실제로 붙이는 법 — API 키와 .env</a>\r\n<a class=\"nav-h1\" href=\"#5-git\">5부 · 적정 에이전트 수 &amp;amp; 개발 습관 (플랜·기록·Git)</a>\r\n<a class=\"nav-h2\" href=\"#_8\">무조건 &#x27;플랜&#x27; 먼저 — 메타 프롬프트로</a>\r\n<a class=\"nav-h2\" href=\"#planmd-git\">변경 이유를 남겨라 — plan.md와 Git</a>\r\n<a class=\"nav-h1\" href=\"#6-2\">6부 · 실습 2 — 픽셀 에이전트 클론 &amp;amp; 커스텀</a>\r\n<a class=\"nav-h2\" href=\"#git\">Git 설치 확인 → 클론</a>\r\n<a class=\"nav-h2\" href=\"#nodejs\">의존성 설치 &amp;amp; 실행 (Node.js 프로젝트 기준)</a>\r\n<a class=\"nav-h2\" href=\"#_9\">뜯어고치기 — 순서와 요령</a>\r\n<a class=\"nav-h1\" href=\"#7\">7부 · 멀티 에이전트의 그림자 — 왜 돈이 눈덩이처럼 부나</a>\r\n<a class=\"nav-h2\" href=\"#thinking\">Thinking 기본 + 핸드오프는 공짜가 아니다</a>\r\n<a class=\"nav-h2\" href=\"#latentmas\">연구 최전선 — LatentMAS 논문</a>\r\n<a class=\"nav-h1\" href=\"#_10\">마무리 &amp;amp; 과제</a>\r\n<a class=\"nav-h1\" href=\"#_11\">부록 — 용어 사전 · 출처</a>\r\n<a class=\"nav-h2\" href=\"#_12\">용어 빠른 사전</a>\r\n<a class=\"nav-h2\" href=\"#_13\">검색으로 확인·보강한 출처</a>\r\n</nav>\r\n    <div class=\"hero\">\r\n      <div class=\"eyebrow\">Lecture Note · 기술 보강판</div>\r\n      <h1>6회차 — AI 에이전트 이해: 트랜스포머 기초부터 멀티 에이전트 실습까지</h1>\r\n      <p>현장 강의를 기술적으로 보강한 학습 레퍼런스 — 강사의 의도는 살리고, 빠지거나 틀린 기술은 정확히 채웠습니다.</p>\r\n    </div>\r\n\r\n<p>이 강의 하나로 무엇을 할 수 있게 하려는가 →\r\n<strong>\"AI 에이전트가 '무엇으로 이루어졌고(두뇌·도구·기억), 어떤 구조로 협업하며(싱글~멀티 6종), 왜 돈이 드는지'를 이해하고, OpenRouter로 값싼 모델을 붙여 '민원 초안 생성 멀티 에이전트'와 '픽셀 에이전트'를 직접 뜯어 만들어보는 것.\"</strong></p>\r\n<blockquote class=\"callout callout-key\"><span class=\"callout-badge\">핵심</span>\r\n<p>★ 이 회차는 신성진 강사의 <strong>AI 에이전트 실습 세션</strong>이다. 원제는 \"에이전트 툴 마스터리 기반 개발 입문\"이었지만, 강사가 \"도구는 이미 많이 써봤을 테니 <strong>에이전트 자체를 이해</strong>하는 쪽\"으로 방향을 틀었다고 서두에 밝혔다. 큰 흐름은 다섯 덩어리 — ① 프롤로그(카파시·코딩=현대인 소양) ② 딥러닝/트랜스포머 기초 ③ 에이전트의 구성(두뇌·도구·기억)과 조건 ④ 에이전트 6종 구조 + 핸드오프·오케스트레이션 ⑤ 실습(OpenRouter 민원 에이전트 → 픽셀 에이전트) + 멀티 에이전트의 비용 그림자.</p>\r\n<p><strong>보강 안내</strong> — 강사가 화면으로 빠르게 지나간 실습(OpenRouter 등록·<code>.env</code>·<code>git clone</code>·<code>npm</code>·<code>plan.md</code>)을 초보자가 따라 할 수 있게 <strong>실제 동작하는 명령어/코드</strong>로 채웠다. 값·주장(모델 가격, Attention 논문 연도·저자, LatentMAS 논문, 에이전트 정의)은 웹으로 검증해 <strong>틀린 건 <code>[정정]</code>, 확인한 건 <code>(검색 보강)</code></strong>으로 표시하고 출처는 부록에 모았다. 운영성 멘트(쉬는시간·자리·\"몇 분 남았다\"·장비 인식 오류 등)는 뺐고, 학습에 도움 되는 비유·일화(세 얼간이·붕어·아보카도·레고·\"폭군\" 슈퍼바이저·3살 아이 심부름)는 살렸다.</p>\r\n</blockquote>\r\n<hr/>\r\n<h1 class=\"modhead\" data-full=\"들어가며 — 왜 '에이전트를 이해'하는가\" id=\"_1\">들어가며 — 왜 '에이전트를 이해'하는가</h1>\r\n<p>강사가 이 회차를 통째로 '에이전트 이해'에 쓴 이유는 하나다. <strong>도구를 아무리 많이 써봐도, 그 도구가 어떻게 도는지 모르면 결국 남이 만든 걸 클릭만 하게 된다.</strong> 그래서 밑바닥(모델이 말을 배우는 원리)부터 위(에이전트가 협업하는 구조)까지 한 번 훑는다.</p>\r\n<p>프롤로그의 메시지 두 개:</p>\r\n<blockquote class=\"callout callout-key\"><span class=\"callout-badge\">핵심</span>\r\n<p>★ <strong>코딩은 개발자만의 기술이 아니라 현대인의 기본 소양이다.</strong> 코딩을 '배우라'는 게 아니라, <strong>AI가 짜준 코드와 주석을 읽고 \"얘가 뭘 만들어줬구나\"를 파악</strong>할 줄 알라는 것. 안드레이 카파시(전 테슬라 오토파일럿 AI 총괄)조차 \"프로그래밍에서 이렇게 뒤처진다는 느낌은 처음\"이라고 했을 만큼 발전이 빠르다.</p>\r\n<p><strong>보강 — \"따라 하기 벅찬 시대\"의 실체.</strong> 강사 말대로 모델 출시 주기가 급격히 짧아졌다. 이 회차엔 GPT-5.4/5.5/5.5 Pro, Claude Opus 4.8·Sonnet·Fable 5 같은 이름이 쏟아지는데, <strong>뒤에서 이 중 몇 개는 값을 웹으로 검증해 바로잡았다</strong>(모델 가격 파트 참고). 강사가 \"우리나라 통신사 지분 때문에 특정 모델이 막혔다\"류로 언급한 건 강사 스스로 <strong>\"카더라(찌라시)\"라고 못 박은 소문</strong>이므로 노트에서는 사실로 다루지 않는다.</p>\r\n</blockquote>\r\n<hr/>\r\n<h1 class=\"modhead\" data-full=\"1부 · 모델은 어떻게 '말'을 배웠나 (딥러닝 → 트랜스포머)\" id=\"1\">1부 · 모델은 어떻게 '말'을 배웠나 (딥러닝 → 트랜스포머)</h1>\r\n<p>에이전트의 '두뇌'는 결국 LLM이다. 그 LLM이 어떻게 만들어졌는지를 역사 순으로 훑는다. <strong>핵심 한 줄: 다음 단어를 확률로 예측하는 기계</strong>다.</p>\r\n<div class=\"codewrap\"><div class=\"codebar\"><span class=\"codelang\">code</span><button class=\"copybtn\" type=\"button\">복사</button></div><pre class=\"mermaid\">flowchart LR\r\n  P[\"퍼셉트론&lt;br/&gt;(가중치 학습)\"] --&gt; I[\"이미지 학습&lt;br/&gt;(RGB 숫자화)\"]\r\n  I --&gt; E[\"텍스트 임베딩&lt;br/&gt;(단어→벡터)\"]\r\n  E --&gt; N[\"N-gram&lt;br/&gt;(패턴 예측)\"]\r\n  N --&gt; R[\"RNN·LSTM&lt;br/&gt;(시간·기억 추가)\"]\r\n  R --&gt; T[\"트랜스포머&lt;br/&gt;(Attention, 2017)\"]\r\n</pre></div>\r\n<h2 id=\"_2\">퍼셉트론 — 딥러닝의 최소 단위</h2>\r\n<p><strong>퍼셉트론(perceptron)</strong> = 입력에 가중치를 곱해 더한 뒤, 결과를 보고 <strong>가중치를 조금씩 고쳐나가는</strong> 최소 학습 단위. 스위치와 다이얼 비유(웰치랩스 영상)가 딱 이거다 — \"이쪽으로 올리면 양수, 저쪽이면 음수\"를 패턴으로 익히며 다이얼(가중치)을 돌린다. '러닝(학습)'이란 곧 <strong>가중치를 고쳐나가는 것</strong>이다.</p>\r\n<blockquote class=\"callout callout-add\"><span class=\"callout-badge\">보강</span>\r\n<p><strong>보강 — 용어 한 줄씩.</strong> <em>가중치(weight)</em> = 각 입력의 중요도. <em>편향(bias)</em> = 기준선 조정값. <em>손실함수(loss)</em> = 정답과 얼마나 틀렸나. <em>순전파</em> = 입력→출력 계산, <em>역전파</em> = 틀린 만큼 거꾸로 가중치를 고치는 과정. 딥러닝은 이 손실을 줄이는 방향으로 가중치를 반복해서 고친다. NAND/OR/XOR 게이트 학습이 이 원리의 고전 예제다.</p>\r\n</blockquote>\r\n<h2 id=\"_3\">이미지에서 텍스트로 — 임베딩</h2>\r\n<p>이미지는 컴퓨터에서 <strong>RGB 숫자</strong>(0,0,0 ~ 255,255,255)로 표현된다. 비트맵을 잘게 쪼개 각 칸에 색 값을 넣은 것 — 옛날 컴퓨터에서 확대하면 깨지던 건 <strong>하드웨어 한계로 크게 쪼갤 수밖에 없어서</strong>(=해상도 낮음)다.</p>\r\n<p>그럼 텍스트는? <strong>임베딩(embedding) = 단어를 숫자 벡터로 바꾸는 것.</strong> 자주 같이 나오는 단어끼리 가깝게, 안 나오는 단어끼리 멀게 좌표를 찍는다. 2·3차원으론 부족해서 수백~수천 차원으로 늘려 저장한다.</p>\r\n<blockquote class=\"callout callout-warn\"><span class=\"callout-badge\">주의</span>\r\n<p>⚠ <strong>주의 — \"1036차원\"은 예시 숫자.</strong> 강사가 든 \"1036차원\"은 개념 설명용 숫자다. 실제 임베딩 차원은 모델마다 다르지만 <strong>768 / 1024 / 1536 / 4096</strong> 같은 값이 흔하다(\"1036\"이라는 표준 차원은 없다). 요점은 <strong>\"엄청나게 넓은 공간에 점 하나 찍기\"</strong> 이고, 이게 가능해진 건 하드웨어(메모리·연산) 발전 덕이다.</p>\r\n</blockquote>\r\n<h2 id=\"n-gram-rnnlstm\">N-gram → RNN/LSTM — 그리고 그 한계</h2>\r\n<ul>\r\n<li><strong>N-gram</strong>: 앞의 몇 단어 패턴을 보고 다음 단어를 예측. 문장이 길어지면 패턴을 못 잡고, \"안 되잖아 영어는\" ↔ \"영어는 안 되잖아\" 같은 어순 변형에 취약. 리뷰 감성분석(긍/부정)에서 문장이 길어지면 엉뚱하게 판정하던 게 이 한계다.</li>\r\n<li><strong>RNN / LSTM</strong>: 여기에 <strong>시간·기억</strong>을 더해 \"앞의 것을 기억하며 다음을 예측\"하게 만든 것. 하지만 <strong>앞 단어가 많아질수록 맨 처음 단어를 잊는다</strong>(사람이 어제 건 기억해도 1년 전은 흐릿한 것과 같다). 긴 문맥에서 결국 실패에 가까웠다.</li>\r\n</ul>\r\n<h2 id=\"attention-is-all-you-need-2017\">Attention Is All You Need — 트랜스포머 (2017)</h2>\r\n<p>손 놓고 있던 판을 뒤집은 게 <strong>트랜스포머</strong>다.</p>\r\n<blockquote class=\"callout callout-key\"><span class=\"callout-badge\">핵심</span>\r\n<p>★ <strong>핵심 (검색 보강) — 논문 사실 확인.</strong> \"Attention Is All You Need\"는 <strong>2017년, 구글(Google Brain/Research)의 Vaswani 외 8인</strong>이 발표했다(2017년 6월 공개, NeurIPS 2017 게재). 강사가 말한 <strong>\"2017년, 구글\"은 정확하다.</strong> BERT·GPT 등 오늘날 거의 모든 LLM의 뿌리이며, 핵심 메커니즘이 <strong>어텐션(attention)</strong>이다.</p>\r\n</blockquote>\r\n<p><strong>셀프 어텐션(self-attention)</strong>의 QKV를 초보용으로 풀면:</p>\r\n<ul>\r\n<li><strong>Q(쿼리)</strong> = \"나는 누구와 관련 있지?\"라고 묻는 값</li>\r\n<li><strong>K(키)</strong> = 후보 단어들의 '이름표'</li>\r\n<li><strong>V(밸류)</strong> = 실제로 가져올 '내용'</li>\r\n</ul>\r\n<p>예: \"고양이가 매트 위에 앉았다\"에서 \"앉았다\"가 <strong>Q</strong>로 \"누가 앉았나?\"를 물으면, 후보(고양이·매트·위에) 중 <strong>고양이</strong>와의 연관도가 제일 높게 계산된다. 이걸 패턴으로 학습한다.</p>\r\n<div class=\"codewrap\"><div class=\"codebar\"><span class=\"codelang\">code</span><button class=\"copybtn\" type=\"button\">복사</button></div><pre class=\"mermaid\">flowchart LR\r\n  IN[\"입력 문장\"] --&gt; ENC[\"인코딩&lt;br/&gt;(임베딩)\"]\r\n  ENC --&gt; ATT[\"셀프 어텐션&lt;br/&gt;Q·K·V\"]\r\n  ATT --&gt; MLP[\"MLP 여러 층&lt;br/&gt;(퍼셉트론 반복)\"]\r\n  MLP --&gt; LOG[\"로짓(logit)\"]\r\n  LOG --&gt; SM[\"소프트맥스&lt;br/&gt;(0~1 확률)\"]\r\n  SM --&gt; OUT[\"다음 단어 선택\"]\r\n</pre></div>\r\n<p>용어 정리:\r\n- <strong>인코딩/디코딩(LLM 관점)</strong>: 인코더 = 입력을 '읽고 이해'하는 부분, 디코더 = 그 의미로 <strong>다음 단어를 하나씩 생성</strong>하는 부분. (문자 인코딩/디코딩과는 다른 개념.)\r\n- <strong>MLP(멀티레이어 퍼셉트론)</strong>: 어텐션 결과를 앞서 배운 딥러닝(퍼셉트론)으로 수십 층 반복 가공. 파라미터가 70억·80억·800억 개로 커질수록 다양한 패턴을 학습.\r\n- <strong>로짓(logit) → 소프트맥스(softmax)</strong>: 후보 단어별 '점수(로짓)'를 <strong>0~1 사이 확률</strong>로 바꿔, 가장 높은 걸 다음 단어로 뽑는다.</p>\r\n<blockquote class=\"callout callout-add\"><span class=\"callout-badge\">보강</span>\r\n<p><strong>보강 — 왜 지금 되나.</strong> 2017년엔 6→5나노 공정이었는데 지금은 3나노, 2나노까지 왔다. 하드웨어가 기하급수적으로 좋아지며 훨씬 많은 패턴을 학습할 수 있게 된 게 오늘의 모델이다. 구글이 예전 PaLM에서 삐끗했다가 Gemini로 갈아엎은 것도 이 흐름 위에 있다.</p>\r\n</blockquote>\r\n<hr/>\r\n<h1 class=\"modhead\" data-full=\"2부 · AI 에이전트란 무엇인가\" id=\"2-ai\">2부 · AI 에이전트란 무엇인가</h1>\r\n<p>멀티모달(텍스트+이미지)을 지나 지금 화두는 <strong>AI 에이전트</strong>다. 정의부터 못 박는다.</p>\r\n<blockquote class=\"callout callout-key\"><span class=\"callout-badge\">핵심</span>\r\n<p>★ <strong>핵심 — 에이전트 = 자율적으로 도구를 골라 쓰는 AI.</strong> '에이전트'는 원래 있던 말(스포츠 에이전시, 요원)이고, 거기 'AI'를 붙인 것. 규칙대로만 도는 게 아니라 <strong>사람처럼 필요할 때 필요한 도구를 알아서 가져다 쓰는</strong> 게 핵심. 젠슨 황(NVIDIA)이 \"사람 한 명당 수십~수백 개 에이전트가 붙어 일할 것\"이라 한 그 개념이다.</p>\r\n</blockquote>\r\n<h2 id=\"3\">구성 3요소 — 두뇌·도구·기억</h2>\r\n<div class=\"codewrap\"><div class=\"codebar\"><span class=\"codelang\">code</span><button class=\"copybtn\" type=\"button\">복사</button></div><pre class=\"mermaid\">flowchart TD\r\n  A[\"AI 에이전트\"]\r\n  A --&gt; B[\"두뇌&lt;br/&gt;(LLM · 판단 주체)\"]\r\n  A --&gt; C[\"도구&lt;br/&gt;(검색 · 계산 · API)\"]\r\n  A --&gt; D[\"기억&lt;br/&gt;(컨텍스트 · 메모리)\"]\r\n</pre></div>\r\n<ul>\r\n<li><strong>두뇌</strong> = LLM. 어떤 도구를 쓸지 판단하는 주체.</li>\r\n<li><strong>도구</strong> = 계산기·검색·외부 API 등. 두뇌가 못하는 일(예: 정확한 수 계산)을 맡긴다.</li>\r\n<li><strong>기억</strong> = 컨텍스트/메모리. 지금까지의 대화·결과를 담아둔다.</li>\r\n</ul>\r\n<blockquote class=\"callout callout-add\"><span class=\"callout-badge\">보강</span>\r\n<p><strong>보강 (검색 보강) — 강사의 정의는 Anthropic과 일치한다.</strong> Anthropic의 <em>\"Building Effective Agents\"</em>는 에이전트의 기본 블록을 <strong>\"증강된 LLM(augmented LLM) = LLM + 검색(retrieval) + 도구(tools) + 기억(memory)\"</strong>로 정의한다. 강사가 \"Anthropic은 '검색'을 따로 두는데 나는 그걸 '도구'에 포함시켰다\"고 한 대목은 <strong>정확한 대조</strong>다 — 검색도 결국 도구의 하나로 볼 수 있어서다. 강사 말대로 이 분야는 \"아직 정의가 굳지 않은 학문\"이라, 회사·문서마다 구분이 조금씩 다르고 시간이 지나면 또 바뀐다.</p>\r\n</blockquote>\r\n<h2 id=\"_4\">행동·설계·조건 — 그리고 \"왜 기억인가 = 돈\"</h2>\r\n<p>에이전트는 결국 <strong>구조</strong>다. 사용자의 질문을 받아 → 어떤 도구를 쓸지 계획하고 → 넘기고 → 답을 생성하는 <strong>4단계 흐름</strong>으로 돈다. 여기서 강사가 강조한 세 조건:</p>\r\n<ol>\r\n<li><strong>행동</strong> — 실제로 도구를 써서 결과를 만들어내야 에이전트다.</li>\r\n<li><strong>설계</strong> — 어떤 도구를 몇 개 붙일지 정한다(계산기 하나만 있으면 그것만 함).</li>\r\n<li><strong>조건(기억)</strong> — 중간 기억을 반드시 설계해야 한다.</li>\r\n</ol>\r\n<blockquote class=\"callout callout-key\"><span class=\"callout-badge\">핵심</span>\r\n<p>★ <strong>핵심 — 기억을 설계하는 진짜 이유는 '돈'이다.</strong> 기억이 없으면 에이전트는 매번 초기화되는 <strong>\"붕어 같은 존재\"</strong>가 된다. 바로 전 단계 결과를 가져오면 될 걸 똑같은 작업을 반복하고, <strong>그때마다 두뇌(LLM) 호출 = 토큰 = 돈</strong>이 나간다. 일관성·일회성 문제도 있지만, <strong>가장 근본은 비용 효율</strong>이다. \"에이전트를 만들 때 1순위로 생각할 것 = 기억 설계\"라고 강사가 못 박았다.</p>\r\n<p><strong>보강 — RPA와의 차이.</strong> 에이전트 이전의 각광주였던 <strong>RPA(Robotic Process Automation)</strong>는 <strong>룰 베이스(규칙 기반)</strong>라, 예상 밖(튀는) 값이 들어오면 무너진다. '스마트팜/스마트팩토리'가 대개 RPA 기반이었는데 지금은 소리가 쏙 들어갔다. <strong>알고리즘도 규칙 기반이라 그 자체는 'AI 에이전트'가 아니다</strong> — 두뇌(자율 판단)가 있어야 AI 에이전트다. 두뇌가 빠지면 그냥 RPA다.</p>\r\n</blockquote>\r\n<hr/>\r\n<h1 class=\"modhead\" data-full=\"3부 · 에이전트 6종 구조 — 싱글부터 멀티까지\" id=\"3-6\">3부 · 에이전트 6종 구조 — 싱글부터 멀티까지</h1>\r\n<p>강사가 정리한 대표 6종. <strong>위계가 실제로 있는 건 계층형뿐</strong>이니, 나머지를 억지로 \"N계층\"으로 세우지 말 것. (LangChain의 LangGraph 문서가 정리한 멀티 에이전트 구조 — network / supervisor / supervisor(tool-calling) / hierarchical / custom — 와 거의 일치한다. <strong>검색 보강</strong>.)</p>\r\n<div class=\"tablescroll\"><table>\r\n<thead>\r\n<tr>\r\n<th>구조</th>\r\n<th>한 줄 정의</th>\r\n<th>강점</th>\r\n<th>약점</th>\r\n</tr>\r\n</thead>\r\n<tbody>\r\n<tr>\r\n<td><strong>싱글(바닐라)</strong></td>\r\n<td>한 에이전트가 다 함</td>\r\n<td>목적 명확하면 간단(100줄이면 끝)</td>\r\n<td>도구 많아지면 \"뭘 써야 하지\" 판단 부담 폭증</td>\r\n</tr>\r\n<tr>\r\n<td><strong>네트워크</strong></td>\r\n<td>모두가 서로 직접 대화(그물망)</td>\r\n<td>병렬·유연·애자일</td>\r\n<td>리더 없어 헤맴, 이상치 하나에 전체 오염, 코드 수백 줄</td>\r\n</tr>\r\n<tr>\r\n<td><strong>슈퍼바이저(+서브)</strong></td>\r\n<td>팀장 1 + 서브 에이전트 N</td>\r\n<td>조율자 존재, 병렬·유지보수 용이</td>\r\n<td>팀장에 요청 몰리면 <strong>병목</strong>, 팀장 API 비용 급증</td>\r\n</tr>\r\n<tr>\r\n<td><strong>슈퍼바이저 as 툴</strong></td>\r\n<td>서브를 '도구'로만 취급</td>\r\n<td>통제 강함</td>\r\n<td><strong>\"폭군\"</strong> — 서브 의견 무시, 사실상 싱글과 유사</td>\r\n</tr>\r\n<tr>\r\n<td><strong>계층형(hierarchical)</strong></td>\r\n<td>팀장의 팀장의 팀장…</td>\r\n<td>전문성 있게 세밀 운영</td>\r\n<td>비용·시간 큼</td>\r\n</tr>\r\n<tr>\r\n<td><strong>커스텀</strong></td>\r\n<td>내가 흐름을 직접 설계</td>\r\n<td>완전 자유</td>\r\n<td>유지보수 지옥</td>\r\n</tr>\r\n</tbody>\r\n</table></div>\r\n<h2 id=\"_5\">싱글(바닐라) 에이전트</h2>\r\n<p>에이전트 하나가 계획·설계·테스트·검증·유지보수를 다 한다(지금 우리가 Claude 데스크탑 등으로 쓰는 대부분이 이것). 목적이 명확하면 툴 선택도 명확하다. 문제는 <strong>커질수록</strong> 생긴다 — \"나도 써\", \"우리 팀도 연결해줘\"로 도구가 늘면, <strong>같은 질문에도 \"어떤 툴을 써야 하지?\"라는 판단 부담</strong>이 폭증한다. \"팀원 한 명이 회사 일 다 하면 죽어난다\"와 같은 이치.</p>\r\n<blockquote class=\"callout callout-warn\"><span class=\"callout-badge\">주의</span>\r\n<p><strong>보강 — \"그럼 좋은 모델 쓰면 되잖아?\" 의 함정 = 가격.</strong> 여기서 강사가 모델 가격을 예로 들었다. 값 검증 결과는 아래 [정정] 참고.</p>\r\n<p>⚠ <strong>[정정] — Claude Fable 5 가격.</strong> 강사는 Claude Fable 5를 <strong>\"입력 100만 토큰당 $20, 출력 $1,150\"</strong>로 소개했는데, 이는 <strong>사실과 다르다.</strong> Anthropic 공식 기준(2026년) <strong>Claude Fable 5 = 입력 $10 / 출력 $50 (100만 토큰당)</strong> 이다(Fable 5는 Anthropic의 가장 강력한 상용 모델). 출력 $1,150은 실제값($50)의 20배가 넘는 큰 오차다. (검색 보강: platform.claude.com 모델/가격)</p>\r\n<p>★ <strong>핵심 (검색 보강) — GPT-5.5 가격은 강사가 맞다.</strong> 강사가 말한 <strong>\"GPT-5.5 = 입력 $5 / 출력 $30 (100만 토큰당)\"</strong>은 정확하다(2026년 6월 기준, 1M 컨텍스트). 참고로 GPT-5.5 Pro는 $30/$180로 더 비싸다. 요점은 그대로 유효하다 — <strong>고성능 모델은 개인이 감당하기 어렵다.</strong> 그래서 실습에선 값싼 모델을 쓴다(4부).</p>\r\n</blockquote>\r\n<h2 id=\"_6\">멀티 에이전트 — \"바통\"과 핸드오프</h2>\r\n<p>멀티 에이전트 = 팀장·팀원 A·B·C처럼 <strong>컨텍스트가 분리된</strong> 여러 에이전트가 협업. 나눈 이유는 크게 넷:</p>\r\n<ol>\r\n<li><strong>컨텍스트 분리</strong> — 대기업처럼 역할이 명확 → 전문성(좁고 깊게)</li>\r\n<li><strong>병렬 처리</strong> — 한 번에 뿌리고 한 번에 받음</li>\r\n<li><strong>관심사 분리</strong> — 스파게티처럼 얽히지 않음</li>\r\n<li><strong>유지보수</strong> — 문제 있는 에이전트만 쏙 빼서 교체</li>\r\n</ol>\r\n<p>에이전트끼리 결과를 넘기는 걸 강사는 <strong>\"바통\"</strong>이라 불렀다. 전문 용어로 <strong>핸드오프(handoff)</strong> — \"무엇을 / 언제 / 누구 책임으로\" 넘길지의 경계 설정이다.</p>\r\n<blockquote class=\"callout callout-key\"><span class=\"callout-badge\">핵심</span>\r\n<p>★ <strong>핵심 — 핸드오프 vs 델리게이트.</strong> 팀장에게 보고서를 올리고 <strong>손 털면 핸드오프</strong>, 팀장이 \"다시 해\" 해서 <strong>되돌아와 다시 하면 델리게이트(위임)</strong>. 그래서 일반 멀티 에이전트는 \"100% 핸드오프\"가 아니다(돌아올 수 있으니까). <strong>순차(탑다운) 에이전트</strong>만 무조건 아래로만 흐르므로 100% 핸드오프 — 대신 <strong>앞 단계가 잘못 넘기면 뒤가 다 무너진다</strong>는 게 순차의 최대 약점.</p>\r\n</blockquote>\r\n<h2 id=\"_7\">네트워크 에이전트 — \"팀장님 보고 싶어요\"</h2>\r\n<p>모든 에이전트가 서로 직접 대화(카카오톡 친구망 같은 그물망). 병렬로 빠르고 유연하지만, <strong>리더(결정권자)가 없어</strong> 서로 헤맨다. 이상치 하나가 등장하면 옆으로 옆으로 번져 전체가 오염된다. 같은 일을 싱글은 100줄, 네트워크는 수백 줄이 필요할 만큼 복잡해진다.</p>\r\n<div class=\"codewrap\"><div class=\"codebar\"><span class=\"codelang\">code</span><button class=\"copybtn\" type=\"button\">복사</button></div><pre class=\"mermaid\">flowchart LR\r\n  A1[\"에이전트 A\"] &lt;--&gt; A2[\"에이전트 B\"]\r\n  A2 &lt;--&gt; A3[\"에이전트 C\"]\r\n  A3 &lt;--&gt; A1\r\n  A1 &lt;--&gt; A4[\"에이전트 D\"]\r\n  A2 &lt;--&gt; A4\r\n</pre></div>\r\n<blockquote class=\"callout callout-add\"><span class=\"callout-badge\">보강</span>\r\n<p><strong>보강 — 언제 쓰나.</strong> 창의성을 억누르고 <strong>정확한 답</strong>이 필요한 업무(예: <strong>법령 검토</strong> — 계속 검수 필요)에 어울린다. 대신 최적화하려는 개발자는 예외 처리 지옥에 빠지므로, <strong>에이전트 수를 최대한 줄여</strong> 구성하는 게 요령.</p>\r\n</blockquote>\r\n<h2 id=\"as\">슈퍼바이저 &amp; 슈퍼바이저 as 툴 — 오케스트레이션</h2>\r\n<p>네트워크의 \"리더 없음\"을 푸는 게 <strong>오케스트레이션(orchestration)</strong> — 전체를 조율하는 팀장(슈퍼바이저)을 하나 둔다. 뉴스에 나오는 \"서브 에이전트/멀티 에이전트\"가 대개 이 그림이다. (서브 에이전트는 멀티 에이전트의 <strong>하위 개념</strong> — 반대 개념이 아니다.)</p>\r\n<div class=\"codewrap\"><div class=\"codebar\"><span class=\"codelang\">code</span><button class=\"copybtn\" type=\"button\">복사</button></div><pre class=\"mermaid\">flowchart TD\r\n  S[\"슈퍼바이저&lt;br/&gt;(오케스트레이터 · 팀장)\"]\r\n  S --&gt; A[\"서브 A\"]\r\n  S --&gt; B[\"서브 B\"]\r\n  S --&gt; C[\"서브 C\"]\r\n  S --&gt; D[\"서브 D\"]\r\n</pre></div>\r\n<ul>\r\n<li><strong>슈퍼바이저</strong>: 팀장이 요청을 나눠주고 서브와 어느 정도 대화·재요청도 함. 단, <strong>요청이 몰리면 팀장이 병목</strong>에 빠지고, 팀장에 붙인 모델의 <strong>API 비용이 기하급수적으로</strong> 든다.</li>\r\n<li><strong>슈퍼바이저 as 툴</strong>: 서브를 아예 <strong>'도구'로만</strong> 본다. <strong>\"너네는 내 노예야\"</strong> 식 — 서브가 \"이것도 검토하면 좋을 것 같은데요\" 하면 <strong>\"감히 도구가 의견을 내? 시키는 것만 해\"</strong>. 통제는 강하지만 사실상 싱글 에이전트와 비슷해진다(\"폭군\" 비유).</li>\r\n</ul>\r\n<h2 id=\"hierarchical\">계층형(hierarchical) &amp; 커스텀</h2>\r\n<ul>\r\n<li><strong>계층형</strong>: 슈퍼바이저 위에 또 슈퍼바이저. 주간보고가 팀장→과장→그 위로 올라가는 <strong>회사 조직도</strong> 그대로. 전문성 있게 돌지만 <strong>비용·시간</strong>이 크다.</li>\r\n<li><strong>커스텀</strong>: \"둘이 어딨어, 내 맘대로 짤래.\" 내가 흐름을 직접 설계(\"너는 얘한테만 보내\", \"너는 쟤랑 답변하지 마\"). 자유롭지만 <strong>유지보수가 지옥</strong>이다.</li>\r\n</ul>\r\n<div class=\"codewrap\"><div class=\"codebar\"><span class=\"codelang\">code</span><button class=\"copybtn\" type=\"button\">복사</button></div><pre class=\"mermaid\">flowchart TD\r\n  T[\"최상위 슈퍼바이저\"]\r\n  T --&gt; S1[\"팀장 A\"]\r\n  T --&gt; S2[\"팀장 B\"]\r\n  S1 --&gt; W1[\"팀원\"]\r\n  S1 --&gt; W2[\"팀원\"]\r\n  S2 --&gt; W3[\"팀원\"]\r\n  S2 --&gt; W4[\"팀원\"]\r\n</pre></div>\r\n<blockquote class=\"callout callout-warn\"><span class=\"callout-badge\">주의</span>\r\n<p><strong>보강 — 레고 비유(커스텀의 함정).</strong> 탱크 레고는 <strong>설명서</strong>가 있어 쉽다. 그런데 그 부품으로 <strong>공룡</strong>을 만들려면 전부 내 머리로 설계해야 하고, 놀다 보면 부품이 없어져 유지보수가 힘들어진다. 커스텀 구조가 딱 이렇다.</p>\r\n</blockquote>\r\n<hr/>\r\n<h1 class=\"modhead\" data-full=\"4부 · 실습 1 — 민원 초안 생성 멀티 에이전트 (OpenRouter)\" id=\"4-1-openrouter\">4부 · 실습 1 — 민원 초안 생성 멀티 에이전트 (OpenRouter)</h1>\r\n<p>이제 위 구조를 손으로 만든다. 주제는 <strong>\"민원 초안 생성 멀티 에이전트\"</strong>. 입력은 배포된 <strong>민원 예제 40개</strong>(번호·제목·본문, 실제 인사혁신처 민원 기반)이고, 이걸 읽어 <strong>답변 초안</strong>을 만드는 게 목표.</p>\r\n<div class=\"codewrap\"><div class=\"codebar\"><span class=\"codelang\">code</span><button class=\"copybtn\" type=\"button\">복사</button></div><pre class=\"mermaid\">flowchart LR\r\n  M[\"민원 접수&lt;br/&gt;(번호·제목·본문)\"] --&gt; C[\"분류 에이전트\"]\r\n  C --&gt; S[\"검색 에이전트&lt;br/&gt;(법령·과거답변, 예시)\"]\r\n  S --&gt; W[\"작성 에이전트\"]\r\n  W --&gt; R[\"검수 에이전트\"]\r\n  R --&gt; O[\"답변 초안\"]\r\n</pre></div>\r\n<p>각 에이전트는 <strong>페르소나 + 쓸 수 있는 도구</strong>를 함께 줘야 한다.</p>\r\n<blockquote class=\"callout callout-key\"><span class=\"callout-badge\">핵심</span>\r\n<p>★ <strong>핵심 — 페르소나만 주면 '챗봇', 도구까지 줘야 '에이전트'.</strong> \"너는 분류 담당이야\"만 주면 전용 챗봇이고, <strong>도구를 붙여 결과를 만들어내야 에이전트</strong>다. 구조(순차/슈퍼바이저/계층형/커스텀)는 자유롭게 골라도 된다. 실습에선 검색·법령 API는 <strong>\"예시 도구\"로 대체</strong>해도 된다(진짜 API를 붙이면 너무 커진다).</p>\r\n</blockquote>\r\n<h2 id=\"openrouter\">OpenRouter — 키 하나로 수백 개 모델</h2>\r\n<p>강사가 값싼 모델을 쓰라고 한 배경이 <strong>OpenRouter</strong>다.</p>\r\n<blockquote class=\"callout callout-add\"><span class=\"callout-badge\">보강</span>\r\n<p><strong>보강 (검색 보강) — OpenRouter란.</strong> <strong>키 하나로 60여 개 공급자의 400~500+ 개 모델</strong>(OpenAI·Anthropic·Google·Meta·Mistral 등)을 <strong>OpenAI 호환 방식</strong>으로 부르는 통합 게이트웨이다. 공급자별로 인증·결제·SDK를 따로 만들 필요가 없고, 장애 시 다른 모델로 <strong>폴백</strong>도 된다. 실습에선 <strong>한도 2달러/인</strong>이라 <strong>작은(싼) 모델만</strong> 쓰라고 제한했다(어떤 모델을 썼는지 대시보드에 다 뜬다). 중국 모델은 보안 우려로 제외. (출처: openrouter.ai)</p>\r\n<p>★ <strong>핵심 — 작은 모델을 쓰게 한 진짜 의도.</strong> \"기관에 가면 어차피 좋은 모델 못 쓴다. <strong>싼 모델로도 되는지</strong>를 미리 체감하고, '이 정도면 우리 기관에 도입할 만하다'를 테스트해보라\"는 것.</p>\r\n</blockquote>\r\n<h2 id=\"api-env\">실제로 붙이는 법 — API 키와 <code>.env</code></h2>\r\n<p>강사가 \"AI에 잘 얘기하면 다 연결된다\"며 건너뛴 부분을 <strong>동작하는 형태</strong>로 채운다. 핵심: <strong>API 키를 코드에 박지 말고 <code>.env</code>(환경변수)에 둔다.</strong></p>\r\n<p><code>.env</code> 파일 (프로젝트 루트에 두고, <strong>깃에 올리지 않는다</strong>):</p>\r\n<div class=\"codewrap\"><div class=\"codebar\"><span class=\"codelang\">Shell</span><button class=\"copybtn\" type=\"button\">복사</button></div><pre><code class=\"language-bash\">OPENROUTER_API_KEY=sk-or-v1-여기에_본인_키\r\n</code></pre></div>\r\n<p><code>.gitignore</code>에 반드시 추가:</p>\r\n<div class=\"codewrap\"><div class=\"codebar\"><span class=\"codelang\">gitignore</span><button class=\"copybtn\" type=\"button\">복사</button></div><pre><code class=\"language-gitignore\">.env\r\nnode_modules/\r\n</code></pre></div>\r\n<p>파이썬에서 부르기(OpenAI 호환 방식):</p>\r\n<div class=\"codewrap\"><div class=\"codebar\"><span class=\"codelang\">python</span><button class=\"copybtn\" type=\"button\">복사</button></div><pre><code class=\"language-python\"># pip install openai python-dotenv\r\nimport os\r\nfrom dotenv import load_dotenv\r\nfrom openai import OpenAI\r\n\r\nload_dotenv()  # .env 읽어 환경변수로\r\n\r\nclient = OpenAI(\r\n    base_url=\"https://openrouter.ai/api/v1\",     # ← OpenRouter 엔드포인트\r\n    api_key=os.environ[\"OPENROUTER_API_KEY\"],\r\n)\r\n\r\nresp = client.chat.completions.create(\r\n    model=\"openai/gpt-5.5\",                       # ← 싼 모델로 바꿔 쓰기(예시)\r\n    messages=[\r\n        {\"role\": \"system\", \"content\": \"너는 민원 분류 담당이다. 카테고리만 한 단어로 답하라.\"},\r\n        {\"role\": \"user\",   \"content\": \"민원 본문: ...\"},\r\n    ],\r\n)\r\nprint(resp.choices[0].message.content)\r\n</code></pre></div>\r\n<blockquote class=\"callout callout-warn\"><span class=\"callout-badge\">주의</span>\r\n<p>⚠ <strong>주의 — 키는 절대 코드/HTML에 노출하지 마라.</strong> 강사도 \"그건 내 개인 키니 등록하지 말라\"고 했다. <code>.env</code>에 넣고 <code>.gitignore</code>로 깃 추적에서 빼는 게 표준. HTML 프론트에서 직접 키를 부르면 브라우저에 그대로 노출되니, <strong>키를 쓰는 호출은 서버(백엔드)나 로컬 스크립트에서</strong> 해야 한다.</p>\r\n</blockquote>\r\n<p>각 에이전트마다 <strong>다른 모델</strong>을 붙이고 싶으면, 위 <code>create(model=...)</code>의 모델 문자열만 에이전트별로 바꾸면 된다(예: 분류=싼 모델, 검수=조금 더 나은 모델). 웹/파이썬 서버/Node.js 등 <strong>형식은 자유</strong> — \"제대로 돌기만 하면 된다.\"</p>\r\n<blockquote class=\"callout callout-add\"><span class=\"callout-badge\">보강</span>\r\n<p><strong>보강 — 잘 모르겠으면 역공학.</strong> 배포된 <code>.ipynb</code>(주피터) 예제나, 좋아요 많은 오픈 멀티 에이전트(4개 에이전트 제공)를 <strong>하나만 뜯어보며(리버스 엔지니어링)</strong> 어떻게 구성했는지 따라가는 것도 방법. \"모방은 창조의 어머니.\"</p>\r\n</blockquote>\r\n<hr/>\r\n<h1 class=\"modhead\" data-full=\"5부 · 적정 에이전트 수 &amp; 개발 습관 (플랜·기록·Git)\" id=\"5-git\">5부 · 적정 에이전트 수 &amp; 개발 습관 (플랜·기록·Git)</h1>\r\n<p>만들고 나면 \"에이전트가 너무 많나 적나\"가 헷갈린다. 강사의 지침.</p>\r\n<blockquote class=\"callout callout-key\"><span class=\"callout-badge\">핵심</span>\r\n<p>★ <strong>핵심 — \"적정 에이전트 수\"를 정하라.</strong> \"백지장도 맞들면 낫다\"지만, 너무 잘게 쪼개면 <strong>\"사공이 많으면 배가 산으로 간다\"</strong>. 에이전트가 7~8개로 계속 왔다 갔다 하는 건 <strong>각자 일이 명확하지 않아서</strong>다. \"누가 어디까지 하고 넘길지\"를 명확히 하고, <strong>의심스러우면 줄여라(줄이는 게 최고).</strong></p>\r\n<p><strong>보강 — 의사결정나무 depth 비유.</strong> 머신러닝에서 정확도를 가장 크게 좌우하는 게 <strong>의사결정나무의 깊이(depth)</strong> 이듯, 에이전트 수도 너무 적어도·많아도 안 된다. 최적값은 결국 <strong>경험(측정)</strong>으로 찾는다 — 에이전트별 소비 금액을 기록하고, 예컨대 민원 100건을 돌려 구조별 비용·정확도를 비교한다. (게임의 클로즈베타→오픈베타처럼, 최적은 처음부터 못 찾는다.)</p>\r\n</blockquote>\r\n<h2 id=\"_8\">무조건 '플랜' 먼저 — 메타 프롬프트로</h2>\r\n<blockquote class=\"callout callout-key\"><span class=\"callout-badge\">핵심</span>\r\n<p>★ <strong>핵심 — \"뭐 만들어줘\" 금지, 플랜부터.</strong> 바로 만들라고 하지 말고 <strong>① 목표 ② 범위 ③ 단계 ④ 완료 기준</strong>을 먼저 세우게 하라. 오늘 처음 본 멀티 에이전트를 어떻게 다 설명하나? → <strong>메타 프롬프트</strong>로: <em>\"내가 지금 이런 상황이니, 그 프롬프트(플랜)를 더 명확하게 네가 만들어줘.\"</em> 만든 플랜은 <strong>다른 AI에게 교차 검토</strong>시킨다: <em>\"이 플랜에서 가장 크리티컬한 부분이 뭐야? 냉정하게 검토해.\"</em></p>\r\n<p><strong>보강 — \"코딩은 3살 아이 심부름 + 아보카도 사건.\"</strong> 3살짜리에게 \"우유 사와\" 하면 별의별 변수가 다 생긴다. 컴퓨터도 하나하나 다 지정해줘야 한다. 유명한 밈: <em>\"우유 사는데 아보카도 있으면 6개 사와\"</em> → 남자가 아보카도가 있길래 <strong>우유를 6개</strong> 사왔다. 사람 말은 생각보다 안 명확하다. (정가자 포항공대 편 \"개발자 빡치게 하는 법\"이 같은 맥락 — 숟가락 드는 것조차 각도·거리를 다 지정해야 한다.) 그래서 <strong>플랜을 최대한 구체적으로</strong> 먼저 세우는 것이다.</p>\r\n</blockquote>\r\n<h2 id=\"planmd-git\">변경 이유를 남겨라 — <code>plan.md</code>와 Git</h2>\r\n<blockquote class=\"callout callout-key\"><span class=\"callout-badge\">핵심</span>\r\n<p>★ <strong>핵심 — 계획은 변해도 되지만, '바뀐 이유'가 사라지면 안 된다.</strong> 강사가 신입 때 가장 많이 혼난 것도 <em>\"고쳤으면 제발 어딘가에 남겨라\"</em>. 그래서 <strong><code>plan.md</code> 하나를 만들어</strong> \"언제/왜/어디를 바꿨는지\"를 기록하거나, 코드에 <strong>주석</strong>으로 설명을 남긴다.</p>\r\n</blockquote>\r\n<p><code>plan.md</code> 최소 뼈대(그대로 복붙해 시작 가능):</p>\r\n<div class=\"codewrap\"><div class=\"codebar\"><span class=\"codelang\">markdown</span><button class=\"copybtn\" type=\"button\">복사</button></div><pre><code class=\"language-markdown\"># 민원 초안 멀티 에이전트 — plan\r\n\r\n## 목표\r\n- 민원(번호·제목·본문) → 답변 초안 자동 생성\r\n\r\n## 범위\r\n- 분류 → (예시)검색 → 작성 → 검수 (순차 or 슈퍼바이저)\r\n- 모델: OpenRouter의 값싼 모델 (한도 2달러/인)\r\n\r\n## 단계\r\n1. .env 에 OPENROUTER_API_KEY 등록\r\n2. 분류 에이전트 (카테고리 1단어)\r\n3. 작성/검수 에이전트\r\n4. 결과 확인\r\n\r\n## 완료 기준\r\n- 민원 1건 넣으면 답변 초안 1건이 나온다\r\n\r\n## 변경 이력\r\n- 2026-07-01: 검색 에이전트는 API 대신 '예시 도구'로 대체 (이유: 범위 폭증 방지)\r\n</code></pre></div>\r\n<p>Git으로 기록·관리(가장 표준적인 방법):</p>\r\n<div class=\"codewrap\"><div class=\"codebar\"><span class=\"codelang\">Shell</span><button class=\"copybtn\" type=\"button\">복사</button></div><pre><code class=\"language-bash\">git init\r\ngit add plan.md\r\ngit commit -m \"plan: 민원 멀티 에이전트 초기 계획\"\r\n# 이후 변경마다\r\ngit add -A\r\ngit commit -m \"fix: 검색 에이전트를 예시 도구로 대체 (범위 축소)\"\r\n</code></pre></div>\r\n<blockquote class=\"callout callout-add\"><span class=\"callout-badge\">보강</span>\r\n<p><strong>보강 — 커밋(commit) = \"언제 뭘 했다\"의 영구 기록.</strong> 픽셀 에이전트 레포를 보면 원저자가 <strong>커밋을 145개</strong> 남겨놨는데, 그게 다 \"언제 무엇을 고쳤나\"의 이력이다. 개발자가 GitHub를 쓰는 가장 큰 이유가 이 관리 편의성이다.</p>\r\n</blockquote>\r\n<hr/>\r\n<h1 class=\"modhead\" data-full=\"6부 · 실습 2 — 픽셀 에이전트 클론 &amp; 커스텀\" id=\"6-2\">6부 · 실습 2 — 픽셀 에이전트 클론 &amp; 커스텀</h1>\r\n<p>두 번째 실습은 남이 만든 걸 <strong>뜯어고치는</strong> 것. <strong>픽셀 에이전트</strong>를 <code>git clone</code>으로 내 PC에 복제해, 회의 주제(\"다음 달 AI 교육 계획\")로 멀티 에이전트를 돌려본다.</p>\r\n<blockquote class=\"callout callout-add\"><span class=\"callout-badge\">보강</span>\r\n<p><strong>보강 (검색 보강) — 픽셀 에이전트란.</strong> 멀티 에이전트의 활동을 <strong>픽셀아트 '사무실'로 시각화</strong>하는 오픈소스류다(각 에이전트가 캐릭터로 등장해 코딩할 땐 타이핑, 검색할 땐 읽기, 대기 시 물음표 등으로 표현). GitHub에 <code>pixel-agents</code>·<code>pixtuoid</code>·<code>agentroom</code>·<code>claude-office</code> 등 여러 구현이 있고, 대개 <strong>Claude Code(CLI) 훅</strong>에 연동돼 돈다. 강사가 쓴 정확한 레포는 <strong>강의 단톡방에 배포된 링크로 확인</strong>하는 게 안전하다(동명 레포가 여럿). 목적은 하나 — <strong>에이전트가 어떻게 왔다 갔다 하는지 눈으로 보는 것.</strong></p>\r\n</blockquote>\r\n<h2 id=\"git\">Git 설치 확인 → 클론</h2>\r\n<p>먼저 Git이 있는지 확인(강사가 알려준 그 명령):</p>\r\n<div class=\"codewrap\"><div class=\"codebar\"><span class=\"codelang\">Shell</span><button class=\"copybtn\" type=\"button\">복사</button></div><pre><code class=\"language-bash\">git -v\r\n# 예: git version 2.52.0  ← 이렇게 숫자가 나오면 설치됨\r\n</code></pre></div>\r\n<p>없으면 git-scm.com(구글에 <strong>\"Git\"</strong>, GitHub 아님)에서 설치. <strong>이미 있으면 재설치 금지</strong>(충돌 남).</p>\r\n<p>바탕화면에 클론(≈80~90MB):</p>\r\n<div class=\"codewrap\"><div class=\"codebar\"><span class=\"codelang\">Shell</span><button class=\"copybtn\" type=\"button\">복사</button></div><pre><code class=\"language-bash\">cd ~/Desktop            # 윈도우: cd %USERPROFILE%\\Desktop\r\ngit clone &lt;배포된_픽셀에이전트_레포_URL&gt;\r\ncd &lt;클론된_폴더명&gt;\r\n</code></pre></div>\r\n<h2 id=\"nodejs\">의존성 설치 &amp; 실행 (Node.js 프로젝트 기준)</h2>\r\n<p>대부분 이 계열은 Node.js 기반이라, 폴더 안에 <code>package.json</code>이 있으면:</p>\r\n<div class=\"codewrap\"><div class=\"codebar\"><span class=\"codelang\">Shell</span><button class=\"copybtn\" type=\"button\">복사</button></div><pre><code class=\"language-bash\">npm install             # package.json의 의존성 설치 → node_modules/ 생성\r\nnpm run dev             # 또는 npm start (레포의 scripts에 맞춰)\r\n</code></pre></div>\r\n<blockquote class=\"callout callout-warn\"><span class=\"callout-badge\">주의</span>\r\n<p>⚠ <strong>주의 — 어떤 스크립트인지는 <code>package.json</code>에서 확인.</strong> 실행 명령(<code>dev</code>/<code>start</code>/<code>build</code>)은 레포마다 다르다. 폴더에서 <code>package.json</code>의 <code>\"scripts\"</code> 항목을 보거나, README를 따르거나, <strong>막히면 오류 메시지를 그대로 캡처해 AI에 물어보면</strong> 된다(표준 디버깅 루프). 로컬 서버가 뜨면 브라우저로 <code>localhost</code> 주소에 접속해 사무실 화면을 본다.</p>\r\n</blockquote>\r\n<h2 id=\"_9\">뜯어고치기 — 순서와 요령</h2>\r\n<p>강사가 정한 순서:\r\n1. <strong>먼저 파악</strong> — \"이 프로젝트가 뭐 하는 건지\" AI에게 질문(가설 검증)으로 구조를 이해. (계획은 그 다음.)\r\n2. VS Code / Claude Code / Codex 등으로 <strong>해당 폴더 열기</strong> → 대화로 커스텀.\r\n3. <strong>\"Claude Code 없이도 동작하게\"</strong> 고치기 — 원본은 Claude CLI 전용이라, \"터미널 창을 새로 띄우고, 뒷단 모델은 붙이지 말고, 내가 텍스트를 주면 거기 나타나게\" 식으로 요청.\r\n4. <strong>전부 한국어로</strong> 번역 요청(안 그러면 영어로만 답한다).</p>\r\n<blockquote class=\"callout callout-add\"><span class=\"callout-badge\">보강</span>\r\n<p><strong>보강 — \"다 뜯어보라\"의 의미.</strong> 겁먹지 말고(한숨 금지) 구조를 파악한 뒤 플랜을 세우고, <strong>변경을 기록하며</strong> 조금씩 고친다. 에이전트별로 다른 OpenRouter 모델을 붙이고 싶으면 \"추가할 때마다 이 모델로 체결\" 식으로 지시하면 된다.</p>\r\n</blockquote>\r\n<hr/>\r\n<h1 class=\"modhead\" data-full=\"7부 · 멀티 에이전트의 그림자 — 왜 돈이 눈덩이처럼 부나\" id=\"7\">7부 · 멀티 에이전트의 그림자 — 왜 돈이 눈덩이처럼 부나</h1>\r\n<p>멀티 에이전트의 최대 단점은 <strong>비용</strong>이고, 그게 왜 선형이 아니라 눈덩이처럼 커지는지가 이 파트의 핵심.</p>\r\n<h2 id=\"thinking\">Thinking 기본 + 핸드오프는 공짜가 아니다</h2>\r\n<blockquote class=\"callout callout-warn\"><span class=\"callout-badge\">주의</span>\r\n<p>⚠ <strong>주의 — 요즘 모델은 'Thinking(추론)'이 기본.</strong> 질문을 던지면 무조건 추론부터 하는데, <strong>그 추론 과정도 전부 토큰으로 과금</strong>된다. 그래서 입력 대비 출력 가격 차이가 크게는 몇 배까지 벌어진다. (강사가 \"effort: high/medium/low 같은 레벨이 왜 생겼냐\"고 한 게 이 <strong>추론량 조절</strong> 장치다.)</p>\r\n<p><strong>보강 (검색 보강) — 현재 Claude 가격 감각(2026).</strong> 참고로 Anthropic 공식 기준 <strong>Opus 4.8 = 입력 $5 / 출력 $25</strong>, <strong>Sonnet(5·4.6) = $3 / $15</strong> 정도다(100만 토큰당). 강사가 \"Opus 4.8은 비싸니 Sonnet이나 4.6으로 바꿔 써도 충분\"이라 한 방향은 맞다. (강사가 예로 든 \"4.5 시절 $2.5/$10 → Thinking 붙으며 급등\"이라는 <strong>추세 자체는 타당</strong>하나, 세부 숫자는 모델·시점마다 다르니 값이 필요하면 공식 페이지로 재확인.)</p>\r\n</blockquote>\r\n<div class=\"codewrap\"><div class=\"codebar\"><span class=\"codelang\">code</span><button class=\"copybtn\" type=\"button\">복사</button></div><pre class=\"mermaid\">flowchart LR\r\n  A[\"에이전트 A&lt;br/&gt;추론+출력\"] --&gt;|전체 전달| B[\"에이전트 B&lt;br/&gt;입력+추론+출력\"]\r\n  B --&gt;|누적 전달| C[\"에이전트 C&lt;br/&gt;입력+추론+출력\"]\r\n  C --&gt;|또 누적| D[\"…\"]\r\n</pre></div>\r\n<blockquote class=\"callout callout-key\"><span class=\"callout-badge\">핵심</span>\r\n<p>★ <strong>핵심 — 토큰 스노우볼.</strong> A가 \"여기까지 했어\"라며 작업 파일을 넘기면, B는 그걸 <strong>전부 입력 토큰</strong>으로 받고 → 다시 추론(추론 토큰) → 출력(출력 토큰). 이게 다음, 그다음으로 <strong>누적</strong>되며 비용이 <strong>일차함수가 아니라 로그·지수처럼</strong> 불어난다. 왔다 갔다가 잦을수록 더. <strong>에이전트를 너무 많이 만들면 과금 폭탄</strong>이 되는 이유.</p>\r\n</blockquote>\r\n<h2 id=\"latentmas\">연구 최전선 — LatentMAS 논문</h2>\r\n<p>강사가 \"요즘 학자들은 이렇게 접근한다\"며 소개한 신박한 논문.</p>\r\n<blockquote class=\"callout callout-add\"><span class=\"callout-badge\">보강</span>\r\n<p><strong>보강 (검색 보강) — \"Latent Collaboration in Multi-Agent Systems (LatentMAS)\".</strong> arXiv:2511.20639, <strong>2025년 11월 25일</strong> 공개(Gen-Verse/LatentMAS, 학습 불필요 프레임워크). 아이디어: 모델 사이에 굳이 <strong>사람 말(디코딩)로 바꾸지 말고</strong>, 마지막 층 <strong>잠재(latent) 표현을 그대로 넘기자</strong>(공유 잠재 메모리로 무손실 전달). 논문 주장은 9개 벤치마크에서 <strong>토큰 70.8~83.7% 절감, 속도 4~4.3배, 정확도 최대 +14.6%</strong>. 강사가 말한 \"비용 70~80% 절감\"은 이 수치와 정확히 맞다.</p>\r\n<p>⚠ <strong>[정정]·확인 필요 — 날짜와 '정확도' 뉘앙스.</strong> ① 강사가 \"2025년 6월쯤\"이라 했는데 실제는 <strong>2025년 11월</strong>이다(arXiv 2511 = 25년 11월). ② 강사는 \"자기들은 정확도 올렸다지만 실제론 대화가 길어질수록 떨어진다\"고 했는데, <strong>원 논문은 정확도 상승(+14.6%)을 보고</strong>한다. 강사가 지적한 <strong>\"모델마다 토크나이저·임베딩이 달라 여러 홉을 거치면 본래 값을 잃는다\"</strong>는 문제는, <strong>서로 다른 모델(이종, heterogeneous)</strong> 사이 잠재 전달에서 실제로 제기되는 연구 쟁점이다(후속 연구들이 이 열화를 다룬다). 즉 <strong>강사의 직관(이종 모델 간 열화)은 방향이 타당하되, \"이 논문이 정확도를 떨어뜨렸다\"는 단정은 원문과 어긋난다.</strong> 이 대목은 오케스트레이터가 한 번 더 확인하면 좋다.</p>\r\n<p>★ <strong>핵심 — 왜 토크나이저가 문제인가.</strong> 같은 단어라도 GPT계열과 Gemini계열은 <strong>임베딩 값이 다르다</strong>(각자 만든 임베딩·<code>tokenizer.json</code>). 잠재값을 그대로 넘기면 보정을 넣어도 100%는 못 맞추고, <strong>대화가 길어질수록 원래 뜻을 잃는다.</strong> 해결책으로 학생들이 낸 \"어휘(vocabulary) 통일\"이 이론상 최선이지만 — <strong>구글·OpenAI가 서로 표준을 통일해줄 리 없다</strong>(마케팅상). 정답 없는 열린 문제.</p>\r\n</blockquote>\r\n<hr/>\r\n<h1 class=\"modhead\" data-full=\"마무리 &amp; 과제\" id=\"_10\">마무리 &amp; 과제</h1>\r\n<blockquote class=\"callout callout-key\"><span class=\"callout-badge\">핵심</span>\r\n<p>★ 오늘의 한 줄: <strong>에이전트는 결국 '구조'다.</strong> 두뇌·도구·기억으로 이루어지고, 행동·설계·조건(특히 <strong>기억=비용</strong>)으로 돌며, 싱글~멀티 6종의 구조 중 목적에 맞는 걸 고른다. 도구는 쉽고, <strong>어디에·어떻게 나눌지가 어렵다.</strong></p>\r\n</blockquote>\r\n<p><strong>과제</strong> — 실습에서 만든 걸 <strong>GitHub에 업로드하고 그 주소를 제출</strong>한다.\r\n- 에이전트 하나만 만들었으면 싱글 에이전트를 구현한 것(강사가 \"멀티로 만들라\"고 강제하진 않았다 — 픽셀 에이전트를 <strong>고쳐서 구현</strong>해보는 게 핵심).\r\n- 완벽할 필요는 없고 <strong>어느 정도 성공한 상태</strong>로 올리면 된다.</p>\r\n<p><strong>다음 주(7회차) 예고</strong> — <strong>RAG</strong>를 직접 구축한다. RAG가 무엇인지, <strong>청크(chunk) 사이즈</strong>를 어떻게 나눌지, 그리고 RAG의 역사(<strong>Naive → Advanced → Modular → GraphRAG</strong>)까지 훑고 하나씩 구현해본다.</p>\r\n<hr/>\r\n<h1 class=\"modhead\" data-full=\"부록 — 용어 사전 · 출처\" id=\"_11\">부록 — 용어 사전 · 출처</h1>\r\n<h2 id=\"_12\">용어 빠른 사전</h2>\r\n<div class=\"tablescroll\"><table>\r\n<thead>\r\n<tr>\r\n<th>용어</th>\r\n<th>한 줄 정의</th>\r\n</tr>\r\n</thead>\r\n<tbody>\r\n<tr>\r\n<td>퍼셉트론</td>\r\n<td>가중치를 고쳐가며 학습하는 딥러닝 최소 단위</td>\r\n</tr>\r\n<tr>\r\n<td>임베딩</td>\r\n<td>단어·이미지를 숫자 벡터(좌표)로 바꾸는 것</td>\r\n</tr>\r\n<tr>\r\n<td>N-gram</td>\r\n<td>앞 몇 단어 패턴으로 다음 단어를 예측(구식)</td>\r\n</tr>\r\n<tr>\r\n<td>RNN / LSTM</td>\r\n<td>시간·기억을 더한 예측 모델(긴 문맥엔 약함)</td>\r\n</tr>\r\n<tr>\r\n<td>트랜스포머 / 어텐션</td>\r\n<td>\"Attention Is All You Need\"(2017, 구글)의 구조 / 연관도 계산 메커니즘</td>\r\n</tr>\r\n<tr>\r\n<td>QKV(셀프 어텐션)</td>\r\n<td>쿼리·키·밸류로 \"누구와 관련 있나\"를 계산</td>\r\n</tr>\r\n<tr>\r\n<td>MLP</td>\r\n<td>멀티레이어 퍼셉트론, 어텐션 결과를 여러 층 가공</td>\r\n</tr>\r\n<tr>\r\n<td>로짓 / 소프트맥스</td>\r\n<td>후보 단어 점수 / 이를 0~1 확률로 변환</td>\r\n</tr>\r\n<tr>\r\n<td>인코딩 / 디코딩(LLM)</td>\r\n<td>입력을 이해하는 부분 / 다음 단어를 생성하는 부분</td>\r\n</tr>\r\n<tr>\r\n<td>에이전트 3요소</td>\r\n<td>두뇌(LLM) · 도구 · 기억(컨텍스트)</td>\r\n</tr>\r\n<tr>\r\n<td>RPA</td>\r\n<td>룰(규칙) 기반 자동화 — 튀는 값에 약함, 두뇌 없음</td>\r\n</tr>\r\n<tr>\r\n<td>핸드오프 / 델리게이트</td>\r\n<td>손 털고 넘김 / 되돌아와 다시 함(위임)</td>\r\n</tr>\r\n<tr>\r\n<td>오케스트레이션</td>\r\n<td>전체를 조율하는 팀장(슈퍼바이저)을 두는 것</td>\r\n</tr>\r\n<tr>\r\n<td>슈퍼바이저 / as 툴</td>\r\n<td>팀장+서브 / 서브를 '도구'로만 취급(\"폭군\")</td>\r\n</tr>\r\n<tr>\r\n<td>계층형 / 커스텀</td>\r\n<td>슈퍼바이저의 슈퍼바이저 / 내가 흐름 직접 설계</td>\r\n</tr>\r\n<tr>\r\n<td>순차 에이전트</td>\r\n<td>위→아래 일방향(100% 핸드오프, 앞이 틀리면 다 무너짐)</td>\r\n</tr>\r\n<tr>\r\n<td>OpenRouter</td>\r\n<td>키 하나로 수백 개 모델을 부르는 통합 게이트웨이</td>\r\n</tr>\r\n<tr>\r\n<td><code>.env</code></td>\r\n<td>API 키 등 비밀값을 담는 환경변수 파일(깃 제외)</td>\r\n</tr>\r\n<tr>\r\n<td><code>git clone</code> / commit</td>\r\n<td>레포를 내 PC로 복제 / \"언제 뭘 했다\" 기록</td>\r\n</tr>\r\n<tr>\r\n<td>plan.md</td>\r\n<td>목표·범위·단계·완료기준·변경이력을 남기는 계획 문서</td>\r\n</tr>\r\n<tr>\r\n<td>Thinking(추론) 토큰</td>\r\n<td>답 전 추론 과정도 과금되는 토큰</td>\r\n</tr>\r\n<tr>\r\n<td>토큰 스노우볼</td>\r\n<td>핸드오프마다 입력·추론·출력이 누적돼 비용 급증</td>\r\n</tr>\r\n<tr>\r\n<td>LatentMAS</td>\r\n<td>사람 말 대신 잠재(latent) 표현을 넘기는 멀티 에이전트 연구</td>\r\n</tr>\r\n</tbody>\r\n</table></div>\r\n<h2 id=\"_13\">검색으로 확인·보강한 출처</h2>\r\n<ul>\r\n<li><strong>Attention Is All You Need</strong> (2017, Vaswani 외 8인, 구글; 2017-06 공개 / NeurIPS 2017): <a href=\"https://en.wikipedia.org/wiki/Attention_Is_All_You_Need\">Wikipedia</a></li>\r\n<li><strong>GPT-5.5 가격</strong> ($5/$30 per 1M, 2026): <a href=\"https://openrouter.ai/openai/gpt-5.5\">OpenRouter — GPT-5.5</a>, <a href=\"https://www.morphllm.com/openai-api-pricing\">Morph — OpenAI API Pricing 2026</a></li>\r\n<li><strong>Claude Fable 5 가격</strong> ($10/$50 per 1M; 강사값 $20/$1150 정정): Anthropic 공식 모델/가격(platform.claude.com) — claude-api 스킬 캐시 기준(2026)</li>\r\n<li><strong>OpenRouter</strong> (키 하나·400~500+ 모델·60+ 공급자·OpenAI 호환): <a href=\"https://openrouter.ai/\">openrouter.ai</a>, <a href=\"https://openrouter.ai/docs/guides/overview/models\">OpenRouter Docs</a></li>\r\n<li><strong>Anthropic \"Building Effective Agents\"</strong> (augmented LLM = retrieval+tools+memory): <a href=\"https://www.anthropic.com/research/building-effective-agents\">anthropic.com/research/building-effective-agents</a></li>\r\n<li><strong>LangGraph 멀티 에이전트 구조</strong> (network/supervisor/hierarchical/custom): <a href=\"https://reference.langchain.com/python/langgraph-supervisor\">LangGraph Supervisor</a>, <a href=\"https://github.com/langchain-ai/langgraph-supervisor-py\">langgraph-supervisor-py</a></li>\r\n<li><strong>LatentMAS 논문</strong> (arXiv:2511.20639, 2025-11-25 공개; 토큰 70.8~83.7%↓, 속도 4~4.3배, 정확도 최대 +14.6%): <a href=\"https://arxiv.org/abs/2511.20639\">arXiv</a>, <a href=\"https://github.com/Gen-Verse/LatentMAS\">GitHub Gen-Verse/LatentMAS</a></li>\r\n<li><strong>픽셀 에이전트류</strong> (멀티 에이전트를 픽셀아트 사무실로 시각화, Claude Code 연동): <a href=\"https://github.com/pixel-agents-hq/pixel-agents\">pixel-agents-hq/pixel-agents</a>, <a href=\"https://github.com/paulrobello/claude-office\">paulrobello/claude-office</a> — <em>정확한 레포는 강의 배포 링크로 확인 필요</em></li>\r\n</ul>\r\n  </main>\r\n</div>\r\n\r\n<script src=\"https://cdnjs.cloudflare.com/ajax/libs/highlight.js/11.9.0/highlight.min.js\"><\/script>\r\n<script src=\"https://cdnjs.cloudflare.com/ajax/libs/highlight.js/11.9.0/languages/powershell.min.js\"><\/script>\r\n<script src=\"https://cdnjs.cloudflare.com/ajax/libs/highlight.js/11.9.0/languages/vbscript.min.js\"><\/script>\r\n<script src=\"https://cdnjs.cloudflare.com/ajax/libs/mermaid/10.9.1/mermaid.min.js\"><\/script>\r\n<script>\r\n// 주제 헤더 raw 텍스트를 data-full로 옮겨 ::after 표시\r\ndocument.querySelectorAll('h1.modhead').forEach(function(h){\r\n  h.setAttribute('data-full', h.textContent);\r\n});\r\n\r\n// highlight.js\r\nif(window.hljs){\r\n  document.querySelectorAll('.codewrap pre code').forEach(function(b){\r\n    try{hljs.highlightElement(b);}catch(e){}\r\n  });\r\n}\r\n\r\n// mermaid\r\nif(window.mermaid){\r\n  mermaid.initialize({\r\n    startOnLoad:true, theme:'base',\r\n    htmlLabels:false,\r\n    themeVariables:{\r\n      fontFamily:'-apple-system,Pretendard,\"Malgun Gothic\",sans-serif',\r\n      fontSize:'13px',\r\n      primaryColor:'#e6f4f1', primaryBorderColor:'#127c71', primaryTextColor:'#0c5249',\r\n      lineColor:'#9aa0a8', secondaryColor:'#f4f1ea', tertiaryColor:'#fbf1e4',\r\n      clusterBkg:'#f6f6f0', clusterBorder:'#cfd3cb'\r\n    },\r\n    flowchart:{curve:'basis', useMaxWidth:true, htmlLabels:false},\r\n    sequence:{useMaxWidth:true}\r\n  });\r\n}\r\n\r\n// 복사 버튼\r\ndocument.querySelectorAll('.copybtn').forEach(function(btn){\r\n  btn.addEventListener('click', function(){\r\n    var code = btn.closest('.codewrap').querySelector('pre code');\r\n    var txt = code ? code.innerText : '';\r\n    navigator.clipboard.writeText(txt).then(function(){\r\n      btn.textContent='복사됨'; btn.classList.add('ok');\r\n      setTimeout(function(){btn.textContent='복사'; btn.classList.remove('ok');},1400);\r\n    });\r\n  });\r\n});\r\n\r\n// 스크롤 스파이\r\nvar links = Array.from(document.querySelectorAll('#nav a'));\r\nvar map = {};\r\nlinks.forEach(function(a){ map[a.getAttribute('href').slice(1)] = a; });\r\nvar heads = Array.from(document.querySelectorAll('.main h1[id], .main h2[id]'));\r\nvar spy = new IntersectionObserver(function(entries){\r\n  entries.forEach(function(en){\r\n    if(en.isIntersecting){\r\n      links.forEach(function(l){l.classList.remove('active');});\r\n      var act = map[en.target.id];\r\n      if(act){act.classList.add('active');\r\n        act.scrollIntoView({block:'nearest'});}\r\n    }\r\n  });\r\n}, {rootMargin:'-10% 0px -75% 0px', threshold:0});\r\nheads.forEach(function(h){spy.observe(h);});\r\n\r\n// 모바일 사이드바\r\nvar side=document.getElementById('side'), scrim=document.getElementById('scrim'),\r\n    mb=document.getElementById('menubtn');\r\nfunction toggle(open){side.classList.toggle('open',open);scrim.classList.toggle('show',open);}\r\nif(mb){mb.addEventListener('click',function(){toggle(!side.classList.contains('open'));});}\r\nif(scrim){scrim.addEventListener('click',function(){toggle(false);});}\r\nlinks.forEach(function(a){a.addEventListener('click',function(){if(window.innerWidth<=880)toggle(false);});});\r\n<\/script>\r\n</body>\r\n</html>\r\n"};
